!srv 15.02.26
SUBROUTINE B2STBC_PHYS_NODIFF(ncv, nfc, nvx, ns, ismain, ismain0, switch&
& , geo, mpg, pl, dv, co, rt, st_ext, srw, wrong_flow, main_call, &
& praverage, bc_for_equations)
  USE B2MOD_TYPES
  USE B2MOD_MATH_DIFF
  USE B2MOD_BOUNDARY_NAMELIST_DIFF
  USE B2MOD_NEUTRALS_NAMELIST_DIFF
  USE B2MOD_CONSTANTS
  USE B2MOD_TIME
  USE B2MOD_DIAG_DIFF
  USE B2MOD_B2CMPA
  USE B2MOD_B2CMPB
!srv 26.02.18
  USE B2MOD_BOUNDARY_SOURCES_DIFF
  USE B2MOD_SWITCHES_DIFF
!srv 15.02.26
  USE B2MOD_CONVERGENCE
  USE B2US_GEO_DIFF
  USE B2US_MAP_DIFF
  USE B2US_PLASMA_DIFF
!srv 28.07.11
  USE B2MOD_ASTRA_TO_B2_DIFF
  USE B2MOD_AD_DIFF, ONLY : ncall_b2stbc_phys, sconpar, senepar, senipar&
& , scurpar, coeff_16, prev_cur_delta, cur_delta, po_step, po_prev, &
& po_curr, ubig, vbig, pbig, up00, epslon, ne00, us, vs, nas, nivs, tes,&
& tis, pos
! csc The following are not necessary for computation but are needed
!     for adjoint AD to avoid side-effect variables
  USE B2MOD_AD_DIFF, ONLY : prev_cur_delta, cur_delta, po_step, po_prev,&
& po_curr, coeff_16, nueout, fs, ffac, dfs, s2
  USE B2MOD_SUBSYS
  USE B2MOD_DIMENSIONS
  IMPLICIT NONE
!   ..input arguments (unchanged on exit)
  INTEGER, INTENT(IN) :: ncv, nfc, nvx, ns, ismain, ismain0
  REAL(kind=r8) :: praverage(2)
  TYPE(SWITCHES), INTENT(IN) :: switch
  TYPE(GEOMETRY), INTENT(IN) :: geo
  TYPE(MAPPING), INTENT(IN) :: mpg
  TYPE(B2PLASMA), INTENT(IN) :: pl
  TYPE(B2DERIVATIVES), INTENT(INOUT) :: dv
  TYPE(B2RATES), INTENT(IN) :: rt
  TYPE(B2COEFF), INTENT(INOUT) :: co
  TYPE(B2STATEEXT), INTENT(IN) :: st_ext
!xpb
  LOGICAL :: main_call
!srv 15.02.26
  CHARACTER(len=3) :: bc_for_equations
!   ..output arguments (unspecified on entry)
  TYPE(B2SOURCEWORK), INTENT(INOUT) :: srw
!xpb
  LOGICAL :: wrong_flow
!   ..common blocks
!-----------------------------------------------------------------------
!.documentation
!
!  1. purpose
!
!     B2STBC_PHYS provides linearised expressions for the sources of
!     density, parallel momentum, electron heat, atom heat, and charge,
!     due to the boundary conditions.
!     Here the boundary conditions are expressed by use of the old B2
!     namelist format.
!
!-----------------------------------------------------------------------
!.declarations
!
!   ..local variables
  INTEGER :: icv1, ifc, is, ib, ibc, k
!Solovyev 23.05.14 !srv 29.09.15 }
  INTEGER, SAVE :: bcpot_16_step=50
  INTEGER, SAVE :: bccon_flux_fb_style=0
!srv 19.04.13
  INTEGER, SAVE :: bcene_15_style=1
!srv 19.04.13
  INTEGER, SAVE :: bceni_15_style=0
!srv 19.04.13
  INTEGER, SAVE :: bcpot_12_style=0
  INTEGER, SAVE :: bcenk_17_style=0
  INTEGER, SAVE :: bc_type16_kinetic_energy=0
!srv 16.02.12 12.02.15 29.09.15
  LOGICAL :: once_bccon(0:ns-1), once_bcene, once_bceni, once_bcpot
  REAL(kind=r8) :: naua2sum(0:ns-1), naua2average(0:ns-1), pzaverage, &
& pzsum, volsum, vbc(ncv, 0:ns-1), csbc(ncv, 0:ns-1)
!lk 20.11.07
  REAL(kind=r8) :: bzsum, bzaverage
!sxhz(-1:nx,-1:ny),                                    !srv 24.08.08
  REAL(kind=r8) :: wdia(ncv), wrk0(ncv), wrkf(nfc), pz(ncv), gonedbsq(&
& nfc, 0:1), sna0_no_mdf(ncv, 0:1, 0:ns-1)
!srv 23.09.08
  REAL(kind=r8), SAVE :: cor9=0.0_R8
  REAL(kind=r8) :: fac_he_anom, fac_he_anom_bc
!srv 11.07.05
  CHARACTER :: chns*3, chk*1
!srv 01.02.09
  REAL(kind=r8) :: rz(ncv)
  CHARACTER(len=26) :: boundary_location(nbcd)
!   ..procedures
  INTRINSIC ABS, SQRT
  EXTERNAL IPGETR, B2XVSG, B2XVPS_NODIFF, INTFACE_S
!srv 24.08.08
  REAL(kind=r8) :: sy, INTFACE_S
  EXTERNAL XERTST, IPGETI, ESEEC0_NODIFF
  INTRINSIC MINVAL
  EXTERNAL XERRAB
  REAL(r8) :: result1
  REAL(r8) :: result2
  INTEGER :: arg1
  CHARACTER(len=15) :: arg10
!   ..initialisation
!-----------------------------------------------------------------------
!.computation
!
! ..preliminaries
!   ..subprogram start-up calls
  CALL SUBINI('b2stbc_phys')
!   ..set internal parameters on first call
  IF (ncall_b2stbc_phys .EQ. 0) THEN
    CALL IPGETI('b2stbc_bccon_flux_fb_style', bccon_flux_fb_style)
    CALL IPGETI('b2stbc_bcene_15_style', bcene_15_style)
    CALL IPGETI('b2stbc_bceni_15_style', bceni_15_style)
    CALL IPGETI('b2stbc_bcpot_12_style', bcpot_12_style)
    CALL IPGETI('b2stbc_bcenk_17_style', bcenk_17_style)
! The following switches are only used in 'WG-TODO' blocks, i.e. not yet converted to wide grid functionality
!       call ipgeti ('b2tfhe_conduction_only', conduction_only)
!       call ipgeti ('b2stbc_iform_corr_dia', iform_corr_dia)        !srv 25.07.05
!       call ipgeti ('b2stbc_coreregno', coreregno)
!       call xertst (cbirso.le.coreregno.and.
!     1   coreregno.le.cbirso+cbnrso-1,
!     2   'faulty internal parameter coreregno')
!       if (nncut.ge.2) then
!         call ipgeti ('b2stbc_coreregn2', coreregn2)
!         call xertst (cbirso.le.coreregn2.and.
!     1     coreregn2.le.cbirso+cbnrso-1,
!     2     'faulty internal parameter coreregn2')
!       endif
!       call ipgeti ('b2tfhe_no_hybr', no_hybr_e)
!       call ipgeti ('b2tfhi_no_hybr', no_hybr_i)
!       call ipgeti ('b2stbc_type16_ref', bc_type16_ref)
!       call ipgeti ('b2stbc_type20_ref', bc_type20_ref)
!       call ipgeti ('b2stbc_type21_ref', bc_type21_ref)
!       call ipgeti ('b2stbc_fix_fch_in_fhe_sheath',
!     1  fix_fch_in_fhe_sheath)
!       call ipgeti ('b2stbc_fix_sx_in_fhe_sheath',
!     1  fix_sx_in_fhe_sheath)                                       !srv 08.05.09
!       call ipgeti ('b2stbc_istyle_fchi', istyle_fchi)              !srv 14.02.05
!       call ipgeti ('b2stbc_bcpot_16_step', bcpot_16_step)          !Solovyev 23.05.14 !srv 29.09.15
!       call ipgeti ('b2stbc_type16_kinetic_energy',
!     1  bc_type16_kinetic_energy)
!       call ipgeti ('b2stbc_average_pr', istyle_average_pr)         !srv 08.08.02
  END IF
!   ..test nCv, nFc, ns
  CALL XERTST(0 .LT. ncv .AND. 0 .LT. nfc, 'faulty argument nCv, nFc')
  CALL XERTST(1 .LE. ns, 'faulty argument ns')
  CALL XERTST(0 .LE. ismain .AND. ismain .LT. ns, &
&       'invalid main plasma species index ismain')
  CALL XERTST(.NOT.is_neutral(ismain), &
&       'invalid main plasma species ismain; must not be neutral')
  CALL XERTST(0 .LE. ismain0 .AND. ismain0 .LT. ns, &
&       'invalid main neutral species index ismain0')
  CALL XERTST(is_neutral(ismain0) .OR. ismain .EQ. ismain0, &
&       'invalid main neutral species ismain0; must be neutral')
!   ..test facdrift (not on first call)                              !xpb
!xpb
  IF (ncall_b2stbc_phys .GT. 0) THEN
    result1 = MINVAL(dv%facdrift)
    result2 = MAXVAL(dv%facdrift)
    CALL XERTST(0.0_R8 .LE. result1 .AND. 1.0_R8 .GE. result2, &
&         'faulty argument facdrift')
  END IF
!   ..extensive tests on first few calls
  IF (ncall_b2stbc_phys .LT. 3) THEN
!    ..test sign of vol
    CALL B2XVSG(ncv, geo%cvvol, 1, 'vol', '.gt.')
    arg1 = nfc*2
    CALL B2XVSG(arg1, geo%fcvol, 1, 'vol', '.gt.')
!    ..test state
    CALL B2XVPS_NODIFF(ncv, nfc, ns, pl, dv)
!    ..test sign of chce, chci
    wrkf(:) = co%chce(:, 0)*geo%fcqalf(:, 0)
    CALL B2XVSG(nfc, wrkf, 1, 'chce0', '.ge.')
    wrkf(:) = co%chce(:, 1)*geo%fcqalf(:, 1)
    CALL B2XVSG(nfc, wrkf, 1, 'chce1', '.ge.')
    wrkf(:) = co%chci(:, 0)*geo%fcqalf(:, 0)
    CALL B2XVSG(nfc, wrkf, 1, 'chci0', '.ge.')
    wrkf(:) = co%chci(:, 1)*geo%fcqalf(:, 1)
    CALL B2XVSG(nfc, wrkf, 1, 'chci1', '.ge.')
  END IF
!   ..set cutll, cutlo
  IF (.NOT.b2mod_math_initialised) CALL B2MOD_MATH_INIT()
!
!  -- INITIALISE CERTAIN CONSTANTS --
  epslon = 1.e-10_R8
!  -- SET NE00, UP00, UBIG, VBIG --
  ne00 = 1.0e20_R8
  up00 = SQRT(100*ev/mp)
  ubig = up00/epslon
  vbig = 1.0e-2_R8*ubig
  pbig = up00
!
  sna0_no_mdf = 0.0_R8
!
  cor9 = switch%b2stbc_cor9
!
  IF (switch%keps_anom_he_model .EQ. 0) THEN
! Default model. Apply factor 5/2 for anomalous terms in heat equations
! Default model. No correction for imposed heat fluxes at boundaries
    fac_he_anom = 2.5_R8
    fac_he_anom_bc = 1.0_R8
  ELSE IF (switch%keps_anom_he_model .EQ. 1) THEN
! keps model. Apply factor 3/2 for anomalous terms in heat equations
! Assume physical heat flux with factor 3/2.
! No correction for imposed heat fluxes at boundaries.
    fac_he_anom = 1.5_R8
    fac_he_anom_bc = 1.0_R8
  ELSE IF (switch%keps_anom_he_model .EQ. 2) THEN
! keps model. Apply factor 3/2 for anomalous terms in heat equations
! Assume physical heat flux is still with factor 5/2.
! Correct imposed heat fluxes at boundaries.
    fac_he_anom = 1.5_R8
    fac_he_anom_bc = 3.0_R8/5.0_R8
  END IF
!
!srv 18.01.02
  CALL B2XPPZ_NODIFF(ncv, ns, dv%ne, pl%na, pl%te, pl%ti, pz, st_ext)
!
!   ..pre-compute some quantities for core BCs with drifts
  CALL GRAD_NODIFF(ncv, nfc, nvx, 1, geo, mpg, geo%cvonedbsq, geo%&
&            vxonedbsq, gonedbsq)
  pzsum = 0.0_R8
  naua2sum = 0.0_R8
  volsum = 0.0_R8
  bzsum = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
  DO ib=1,nbc
    icv1 = mpg%bccv(mpg%bccvp(ib, 1), 1)
    IF (mpg%cvonclosedsurface(icv1)) THEN
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
!      ..accumulate the average pressure for inner flux surface
        pzsum = pzsum + geo%fcs(ifc)*pz(icv1)
        volsum = volsum + geo%fcs(ifc)
!      ..accumulate the average na*ua**2, na for inner flux surface
        DO is=0,ns-1
          naua2sum(is) = naua2sum(is) + geo%fcs(ifc)*pl%na(icv1, is)*pl%&
&           ua(icv1, is)**2
        END DO
!      ..accumulate the average fcBb(:,2) for inner flux surface
        bzsum = bzsum + geo%fcs(ifc)*geo%fcbb(ifc, 2)
      END DO
    END IF
  END DO
  IF (volsum .GT. 0.0_R8) THEN
    pzaverage = pzsum/volsum
    naua2average = naua2sum/volsum
    bzaverage = bzsum/volsum
  END IF
!
!wdk  ro and pr based on charged particles only!
!wdk  no neutral contribution to sound speed definition
!srv 01.02.09
  CALL B2XPRZ_NODIFF(ncv, ns, mp, am, pl%na, rz, st_ext)
!      call b2xppz (nCv, ns, dv%ne, pl%na, pl%te, pl%ti, pz, st_ext)
  wdia = (dv%ne*pl%te+dv%ni(:, 1)*pl%ti)*geo%cvbb(:, 2)
  DO is=0,st_ext%ns-1
    IF (.NOT.st_ext%is_neutral(is)) wdia = wdia + st_ext%na(:, is)*&
&       st_ext%ta(:, is)*geo%cvbb(:, 2)
  END DO
  IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, *) 'Doing B2-style bc'
!
!srv 16.02.12 {
  once_bccon = .false.
  once_bcene = .false.
!srv 16.02.12 }
  once_bceni = .false.
!Solovyev 13.05.14 !srv 29.09.15
  once_bcpot = .false.
! -- Prepare boundary_location array in advance                       !srv 05.08.22 {
  DO ib=1,nbc
    IF (bcpos(ib) .EQ. -2) THEN
      WRITE(boundary_location(ib), '(a23,i2)') ' on boundary cell list '&
&     , ib
    ELSE
      WRITE(boundary_location(ib), '(a4,i4,a6,i4,a4,i4)') ' at ', bcpos(&
&     ib), ' from ', bcstart(ib), ' to ', bcend(ib)
    END IF
!srv 05.08.22 }

  END DO
!
! -- LOOP OVER ALL BOUNDARIES
  DO ib=1,nbc
!srv 15.02.26 }
!
    SELECT CASE  (bc_for_equations) 
    CASE ('all') 
!srv 15.02.26 {
      CALL B2STBC_PHYS_SPECIES(ib)
      CALL B2STBC_PHYS_ENE(ib)
      CALL B2STBC_PHYS_ENI(ib)
      CALL B2STBC_PHYS_POT(ib)
      CALL B2STBC_PHYS_ENK(ib)
      CALL B2STBC_PHYS_ENZ(ib)
    CASE ('spc') 
      CALL B2STBC_PHYS_SPECIES(ib)
    CASE ('ene') 
      CALL B2STBC_PHYS_ENE(ib)
    CASE ('eni') 
      CALL B2STBC_PHYS_ENI(ib)
    CASE ('pot') 
      CALL B2STBC_PHYS_POT(ib)
    CASE ('enk') 
      CALL B2STBC_PHYS_ENK(ib)
    CASE ('enz') 
      CALL B2STBC_PHYS_ENZ(ib)
    CASE DEFAULT
      CALL XERRAB('B2STBC -- incorrect value of bc_for_equations')
    END SELECT
!

  END DO
!
! -- Moving core tally according to B.C.
! -- Must be done only once!
!
!
  IF (switch%b2npmo_iout .EQ. 1 .OR. switch%iout_b2wdat .EQ. 4) THEN
!srv 11.09.09 {
    DO is=0,ns-1
      WRITE(chns, '(i3.3)') is
      wrk0 = srw%smo0(:, 0, is) + srw%smo0(:, 1, is)*pl%ua(:, is) + srw%&
&       smo0(:, 2, is)*pl%na(:, is)*mp*am(is) + srw%smo0(:, 3, is)*pl%ua&
&       (:, is)*pl%na(:, is)*mp*am(is)
      arg10 = 'b2stbc_phys_smo'//chns
      CALL MY_OUT_US(70, ncv, 0, wrk0, arg10)
    END DO
  END IF
  IF (switch%b2npco_iout .EQ. 1 .OR. switch%iout_b2wdat .EQ. 4) THEN
    DO is=0,ns-1
      WRITE(chns, '(i3.3)') is
      wrk0 = srw%sna0(:, 0, is) + srw%sna0(:, 1, is)*pl%na(:, is)
      arg10 = 'b2stbc_phys_sna'//chns
      CALL MY_OUT_US(70, ncv, 0, wrk0, arg10)
    END DO
  END IF
  IF (switch%b2npht_iout .EQ. 1 .OR. switch%iout_b2wdat .EQ. 4) THEN
    wrk0 = srw%she0(:, 0) + srw%she0(:, 1)*pl%te + srw%she0(:, 2)*dv%ne &
&     + srw%she0(:, 3)*pl%te*dv%ne
    CALL MY_OUT_US(70, ncv, 0, wrk0, 'b2stbc_phys_she')
    wrk0 = srw%shi0(:, 0) + srw%shi0(:, 1)*pl%ti + srw%shi0(:, 2)*dv%ni(&
&     :, 0) + srw%shi0(:, 3)*pl%ti*dv%ni(:, 0)
    CALL MY_OUT_US(70, ncv, 0, wrk0, 'b2stbc_phys_shi')
  END IF
  IF ((switch%b2npp7_iout .EQ. 1 .OR. switch%b2nppo_iout .EQ. 1) .OR. &
&     switch%iout_b2wdat .EQ. 4) THEN
    wrk0 = srw%sch0(:, 0) + srw%sch0(:, 1)*pl%po + srw%sch0(:, 2)*dv%ne &
&     + srw%sch0(:, 3)*pl%po*dv%ne
    CALL MY_OUT_US(70, ncv, 0, wrk0, 'b2stbc_phys_sch')
  END IF
!srv 11.09.09 }
!
  IF (switch%b2stbc_iout .EQ. 1) THEN
    DO is=0,ns-1
      WRITE(chns, '(i3.3)') is
      DO k=0,3
        WRITE(chk, '(i1)') k
        arg10 = 'b2stbc_phys_smo'//chk//chns
        CALL MY_OUT_US(70, ncv, 0, srw%smo0(1, k, is), arg10)
      END DO
      DO k=0,1
        WRITE(chk, '(i1)') k
        arg10 = 'b2stbc_phys_sna'//chk//chns
        CALL MY_OUT_US(70, ncv, 0, srw%sna0(1, k, is), arg10)
      END DO
    END DO
    DO k=0,3
      WRITE(chk, '(i1)') k
      arg10 = 'b2stbc_phys_sch'//chk
      CALL MY_OUT_US(70, ncv, 0, srw%sch0(1, k), arg10)
      arg10 = 'b2stbc_phys_she'//chk
      CALL MY_OUT_US(70, ncv, 0, srw%she0(1, k), arg10)
      arg10 = 'b2stbc_phys_shi'//chk
      CALL MY_OUT_US(70, ncv, 0, srw%shi0(1, k), arg10)
    END DO
  END IF
!
! ..return
  IF (ncall_b2stbc_phys .EQ. 0 .OR. main_call) ncall_b2stbc_phys = &
&     ncall_b2stbc_phys + 1
  CALL SUBEND()
  RETURN
!
!-----------------------------------------------------------------------
!.end b2stbc_phys
