    REAL(kind=r8) :: x3
    REAL(kind=r8) :: y7
    REAL(kind=r8) :: x4
    REAL(kind=r8) :: x4b
    REAL(kind=r8) :: y8
    REAL(kind=r8) :: y8b
    REAL(kind=r8) :: x5
