              t3 = switch%b2stbc_bc_ref
              CALL PUSHCONTROL1B(0)
            ELSE
              CALL PUSHCONTROL1B(1)
            END IF
            IF (totflux .GE. 0.) THEN
              x9 = totflux
            ELSE
              x9 = -totflux
            END IF
            IF (sconpar(is) .GE. 0.) THEN
              y12 = sconpar(is)
            ELSE
              y12 = -sconpar(is)
            END IF
            IF (x9 .LT. y12) THEN
              max16 = y12
            ELSE
              max16 = x9
            END IF
            IF (max16 .GT. 0.0_R8) THEN
              IF (totflux .GE. 0.) THEN
                x10 = totflux
                CALL PUSHCONTROL1B(0)
              ELSE
                x10 = -totflux
                CALL PUSHCONTROL1B(1)
              END IF
              IF (sconpar(is) .GE. 0.) THEN
                y13 = sconpar(is)
                CALL PUSHCONTROL1B(0)
              ELSE
                y13 = -sconpar(is)
                CALL PUSHCONTROL1B(1)
              END IF
              IF (x10 .LT. y13) THEN
                CALL PUSHREAL8(max17, r8/8)
                max17 = y13
                CALL PUSHCONTROL1B(0)
              ELSE
                CALL PUSHREAL8(max17, r8/8)
                max17 = x10
                CALL PUSHCONTROL1B(1)
              END IF
              CALL PUSHREAL8(nas, r8/8)
              nas = nas*(1.0_R8-t3*(totflux-sconpar(is))/max17)
              CALL PUSHCONTROL1B(0)
            ELSE
              CALL PUSHCONTROL1B(1)
            END IF
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  CALL PUSHINTEGER4(icv1)
                  icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  CALL PUSHINTEGER4(icv2)
                  icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                  CALL PUSHINTEGER4(ifc)
                  ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                  CALL PUSHREAL8(srw%sna0(icv1, 0, is), r8/8)
                  srw%sna0(icv1, 0, is) = vbig*(nas+pl%na(icv2, is)-t1)*&
&                   geo%fcs(ifc)
                  CALL PUSHREAL8(srw%sna0(icv1, 1, is), r8/8)
                  srw%sna0(icv1, 1, is) = -(vbig*geo%fcs(ifc))
                  CALL PUSHREAL8(sna0_no_mdf(icv1, 0, is), r8/8)
                  sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
                  CALL PUSHREAL8(sna0_no_mdf(icv1, 1, is), r8/8)
                  sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
                END DO
                CALL PUSHINTEGER4(ibc - 1)
                CALL PUSHCONTROL1B(1)
              ELSE
                CALL PUSHCONTROL1B(0)
              END IF
            END DO
            once_bccon(is) = .true.
            CALL PUSHCONTROL6B(30)
          ELSE
            CALL PUSHCONTROL6B(31)
          END IF
        ELSE
          CALL PUSHCONTROL6B(32)
        END IF
      CASE (27) 
!IYS 04.03.2013 }
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
!srv 16.02.12 }
          IF (.NOT.once_bccon(is)) THEN
            IF (switch%use_astra .NE. 0) THEN
              CALL PUSHCONTROL1B(0)
            ELSE
              CALL PUSHREAL8(sconpar(is), r8/8)
              sconpar(is) = 0.0_R8
              DO ibw=ib,nbc
                IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') &
&                   .AND. bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                  CALL PUSHREAL8(sconpar(is), r8/8)
                  sconpar(is) = sconpar(is) + conpar(is, ibw, 1)
                  CALL PUSHCONTROL1B(1)
                ELSE
                  CALL PUSHCONTROL1B(0)
                END IF
              END DO
              CALL PUSHCONTROL1B(1)
            END IF
            CALL PUSHREAL8(totfluxn, r8/8)
            totfluxn = 0.0_R8
            CALL PUSHREAL8(totfluxi, r8/8)
            totfluxi = 0.0_R8
! Volume between two surfaces              !lk 12.12.12 {
            CALL PUSHREAL8(t0, r8/8)
            t0 = 0.0_R8
! Volume-averaged on neighbouring surface
            CALL PUSHREAL8(t1, r8/8)
            t1 = 0.0_R8
            CALL PUSHREAL8(nas, r8/8)
            nas = 0.0_R8
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  CALL PUSHINTEGER4(icv1)
                  icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  CALL PUSHINTEGER4(icv2)
                  icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                  CALL PUSHINTEGER4(ifc)
                  ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                  CALL PUSHINTEGER4(isb)
! totfluxn here means the sum of fluxes over all ions (including fluid
! neutrals) of this isotope except for the highest ionisation stage.
! For coupled runs, both fna and fna_mdf are rescaled for neutrals
! Note that for neutrals fna = fna_mdf
                  DO isb=0,ns-1
                    IF (b2espcr(is) .EQ. b2espcr(isb) .AND. is .NE. isb&
&                   ) THEN
                      IF ((.NOT.is_neutral(isb)) .OR. switch%use_eirene &
&                         .EQ. 0) THEN
                        IF (switch%mdf_fnb .NE. 0) THEN
                          totfluxn = totfluxn - mpg%bcfcor(mpg%bccvp(ibw&
&                           , 1)+ibc-1)*(dv%fna_mdf(ifc, 0, isb)+dv%&
&                           fna_mdf(ifc, 1, isb))
                          CALL PUSHCONTROL2B(3)
                        ELSE
                          totfluxn = totfluxn - mpg%bcfcor(mpg%bccvp(ibw&
&                           , 1)+ibc-1)*(dv%fna(ifc, 0, isb)+dv%fna(ifc&
&                           , 1, isb))
                          CALL PUSHCONTROL2B(2)
                        END IF
                      ELSE
                        CALL PUSHCONTROL2B(1)
                      END IF
                    ELSE
                      CALL PUSHCONTROL2B(0)
                    END IF
                  END DO
! totfluxi here means the flux of the ion in the highest ionisation stage.
                  IF (switch%mdf_fnb .NE. 0) THEN
                    totfluxi = totfluxi - mpg%bcfcor(mpg%bccvp(ibw, 1)+&
&                     ibc-1)*(dv%fna_mdf(ifc, 0, is)+dv%fna_mdf(ifc, 1, &
&                     is))
                    CALL PUSHCONTROL1B(0)
                  ELSE
                    totfluxi = totfluxi - mpg%bcfcor(mpg%bccvp(ibw, 1)+&
&                     ibc-1)*(dv%fna(ifc, 0, is)+dv%fna(ifc, 1, is))
                    CALL PUSHCONTROL1B(1)
                  END IF
                  t0 = t0 + geo%cvvol(icv2)
                  t1 = t1 + pl%na(icv2, is)*geo%cvvol(icv2)
                  nas = nas + pl%na(icv1, is)*geo%cvvol(icv2)
                END DO
                CALL PUSHINTEGER4(ibc - 1)
                CALL PUSHCONTROL1B(1)
              ELSE
                CALL PUSHCONTROL1B(0)
              END IF
            END DO
!
            t1 = t1/t0
! Volume-averaged density
            nas = nas/t0
            IF (conpar(is, ib, 2) .GT. 0.0_R8) THEN
              CALL PUSHREAL8(t3, r8/8)
              t3 = conpar(is, ib, 2)
              CALL PUSHCONTROL1B(0)
            ELSE
              CALL PUSHCONTROL1B(1)
            END IF
            IF (conpar(is, ib, 2) .LE. 0.0_R8) THEN
              CALL PUSHREAL8(t3, r8/8)
              t3 = switch%b2stbc_bc_ref
              CALL PUSHCONTROL1B(1)
            ELSE
              CALL PUSHCONTROL1B(0)
            END IF
            IF (totfluxn .GE. 0.) THEN
              abs3 = totfluxn
            ELSE
              abs3 = -totfluxn
            END IF
            IF (totfluxi .GE. 0.) THEN
              abs9 = totfluxi
            ELSE
              abs9 = -totfluxi
            END IF
            IF (sconpar(is) .GE. 0.) THEN
              abs13 = sconpar(is)
            ELSE
              abs13 = -sconpar(is)
            END IF
            IF (abs3 + abs9 + abs13 .GT. 0.0_R8) THEN
              IF (totfluxn .GE. 0.) THEN
                CALL PUSHREAL8(abs4, r8/8)
                abs4 = totfluxn
                CALL PUSHCONTROL1B(1)
              ELSE
                CALL PUSHREAL8(abs4, r8/8)
                abs4 = -totfluxn
                CALL PUSHCONTROL1B(0)
              END IF
              IF (totfluxi .GE. 0.) THEN
                CALL PUSHREAL8(abs10, r8/8)
                abs10 = totfluxi
                CALL PUSHCONTROL1B(1)
              ELSE
                CALL PUSHREAL8(abs10, r8/8)
                abs10 = -totfluxi
                CALL PUSHCONTROL1B(0)
              END IF
              IF (sconpar(is) .GE. 0.) THEN
                CALL PUSHREAL8(abs14, r8/8)
                abs14 = sconpar(is)
                CALL PUSHCONTROL1B(0)
              ELSE
                CALL PUSHREAL8(abs14, r8/8)
                abs14 = -sconpar(is)
                CALL PUSHCONTROL1B(1)
              END IF
              CALL PUSHREAL8(nas, r8/8)
              nas = nas*(1.0_R8-t3*(totfluxn+totfluxi-sconpar(is))/(abs4&
&               +abs10+abs14))
              CALL PUSHCONTROL1B(0)
            ELSE
              CALL PUSHCONTROL1B(1)
            END IF
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  CALL PUSHINTEGER4(icv1)
                  icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  CALL PUSHINTEGER4(icv2)
                  icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                  CALL PUSHINTEGER4(ifc)
                  ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                  CALL PUSHREAL8(srw%sna0(icv1, 0, is), r8/8)
                  srw%sna0(icv1, 0, is) = vbig*(nas+pl%na(icv2, is)-t1)*&
&                   geo%fcs(ifc)
                  CALL PUSHREAL8(srw%sna0(icv1, 1, is), r8/8)
                  srw%sna0(icv1, 1, is) = -(vbig*geo%fcs(ifc))
                  CALL PUSHREAL8(sna0_no_mdf(icv1, 0, is), r8/8)
                  sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
                  CALL PUSHREAL8(sna0_no_mdf(icv1, 1, is), r8/8)
                  sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
                END DO
                CALL PUSHINTEGER4(ibc - 1)
                CALL PUSHCONTROL1B(1)
              ELSE
                CALL PUSHCONTROL1B(0)
              END IF
            END DO
            once_bccon(is) = .true.
            CALL PUSHCONTROL6B(33)
          ELSE
            CALL PUSHCONTROL6B(34)
          END IF
        ELSE
          CALL PUSHCONTROL6B(35)
        END IF
      CASE (28) 
!
! -- BCCON=28  Prescribe the flux surface averaged density, with poloidal
!              perturbation taken from flux tube just inside domain
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          IF (is .EQ. ismain .AND. switch%use_astra .NE. 0) THEN
!srv 28.07.11
            CALL PUSHREAL8(conpar(is, ib, 1), r8/8)
            conpar(is, ib, 1) = neb_astra
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHCONTROL1B(1)
          END IF
          IF (conpar(is, ib, 1) .EQ. 0.0_R8) THEN
            CALL PUSHREAL8(conpar(is, ib, 1), r8/8)
            conpar(is, ib, 1) = switch%b2mndr_na_min
            CALL PUSHCONTROL2B(0)
          ELSE
            CALL PUSHCONTROL2B(1)
          END IF
        ELSE
          CALL PUSHCONTROL2B(2)
        END IF
!       ..compute average density on core boundary
        CALL PUSHREAL8(t0, r8/8)
        t0 = 0.0_R8
        CALL PUSHREAL8(t1, r8/8)
        t1 = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
        DO ib0=1,nbc
          CALL PUSHINTEGER4(icv1)
          icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
          IF (mpg%cvonclosedsurface(icv1)) THEN
! loop over number of cells in the boundary
            DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
! number of the domain cell
              CALL PUSHINTEGER4(icv2)
              icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
              t0 = t0 + geo%cvvol(icv2)
              t1 = t1 + geo%cvvol(icv2)*pl%na(icv2, is)
            END DO
            CALL PUSHINTEGER4(ibc0 - 1)
            CALL PUSHCONTROL1B(1)
          ELSE
            CALL PUSHCONTROL1B(0)
          END IF
        END DO
        t1 = t1/t0
!       ..impose density with perturbation
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          CALL PUSHINTEGER4(icv1)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
          CALL PUSHINTEGER4(icv2)
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          CALL PUSHINTEGER4(ifc)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          CALL PUSHREAL8(srw%sna0(icv1, 0, is), r8/8)
          srw%sna0(icv1, 0, is) = vbig*geo%fcs(ifc)*(pl%na(icv2, is)+&
&           conpar(is, ib, 1)-t1)
          CALL PUSHREAL8(srw%sna0(icv1, 1, is), r8/8)
          srw%sna0(icv1, 1, is) = -(vbig*geo%fcs(ifc))
          CALL PUSHREAL8(sna0_no_mdf(icv1, 0, is), r8/8)
          sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
          CALL PUSHREAL8(sna0_no_mdf(icv1, 1, is), r8/8)
          sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
        END DO
        CALL PUSHCONTROL6B(36)
      CASE (29) 
!       ..compute average density on core boundary
        CALL PUSHREAL8(t0, r8/8)
        t0 = 0.0_R8
        CALL PUSHREAL8(t1, r8/8)
        t1 = 0.0_R8
        CALL PUSHREAL8(t2, r8/8)
        t2 = 0.0_R8
        CALL PUSHREAL8(totflux, r8/8)
        totflux = 0.0_R8
        CALL PUSHREAL8(totpar, r8/8)
        totpar = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
        DO ib0=1,nbc
          CALL PUSHINTEGER4(icv1)
          icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
          IF (mpg%cvonclosedsurface(icv1)) THEN
! loop over number of cells in the boundary
            DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
              icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
              CALL PUSHINTEGER4(icv2)
              icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
              CALL PUSHINTEGER4(ifc)
              ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
              t0 = t0 + geo%cvvol(icv2)
              t1 = t1 + geo%cvvol(icv2)*pl%na(icv1, is)
              t2 = t2 + geo%cvvol(icv2)*pl%na(icv2, is)
              IF (bccon_flux_fb_style .EQ. 0) THEN
                totflux = totflux - mpg%bcfcor(mpg%bccvp(ib0, 1)+ibc0-1)&
&                 *(dv%fna(ifc, 0, is)+dv%fna(ifc, 1, is))
                CALL PUSHCONTROL1B(1)
              ELSE
                totflux = totflux - mpg%bcfcor(mpg%bccvp(ib0, 1)+ibc0-1)&
&                 *(dv%fna_eir(ifc, 0, is)+dv%fna_eir(ifc, 1, is))
                CALL PUSHCONTROL1B(0)
              END IF
            END DO
            CALL PUSHINTEGER4(ibc0 - 1)
!nh conpar(is,ib0,3) contains the contribution from the ionized neutrals
!   (ionising_core option)
            totpar = totpar + conpar(is, ib0, 1) + conpar(is, ib0, 3)
            CALL PUSHCONTROL1B(1)
          ELSE
            CALL PUSHCONTROL1B(0)
          END IF
        END DO
        t1 = t1/t0
        t2 = t2/t0
        IF (conpar(is, ib, 2) .GT. 0.0_R8) THEN
          CALL PUSHREAL8(t3, r8/8)
          t3 = conpar(is, ib, 2)
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        IF (conpar(is, ib, 2) .LE. 0.0_R8) THEN
          CALL PUSHREAL8(t3, r8/8)
          t3 = switch%b2stbc_bc_ref
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        IF (totflux .GE. 0.) THEN
          x11 = totflux
          CALL PUSHCONTROL1B(0)
        ELSE
          x11 = -totflux
          CALL PUSHCONTROL1B(1)
        END IF
        IF (totpar .GE. 0.) THEN
          y14 = totpar
          CALL PUSHCONTROL1B(0)
        ELSE
          y14 = -totpar
          CALL PUSHCONTROL1B(1)
        END IF
        IF (x11 .LT. y14) THEN
          IF (y14 .LT. 1.0e10_R8) THEN
            CALL PUSHREAL8(max18, r8/8)
            max18 = 1.0e10_R8
            CALL PUSHCONTROL2B(0)
          ELSE
            CALL PUSHREAL8(max18, r8/8)
            max18 = y14
            CALL PUSHCONTROL2B(1)
          END IF
        ELSE IF (x11 .LT. 1.0e10_R8) THEN
          CALL PUSHREAL8(max18, r8/8)
          max18 = 1.0e10_R8
          CALL PUSHCONTROL2B(2)
        ELSE
          CALL PUSHREAL8(max18, r8/8)
          max18 = x11
          CALL PUSHCONTROL2B(3)
        END IF
        t4 = (1.0_R8-t3*(totflux-totpar)/max18)*t1
!       ..impose density with perturbation
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          CALL PUSHINTEGER4(icv1)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
          CALL PUSHINTEGER4(icv2)
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          CALL PUSHINTEGER4(ifc)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          CALL PUSHREAL8(srw%sna0(icv1, 0, is), r8/8)
          srw%sna0(icv1, 0, is) = vbig*geo%fcs(ifc)*(pl%na(icv2, is)+t4-&
&           t2)
          CALL PUSHREAL8(srw%sna0(icv1, 1, is), r8/8)
          srw%sna0(icv1, 1, is) = -(vbig*geo%fcs(ifc))
          CALL PUSHREAL8(sna0_no_mdf(icv1, 0, is), r8/8)
          sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
          CALL PUSHREAL8(sna0_no_mdf(icv1, 1, is), r8/8)
          sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
        END DO
        CALL PUSHCONTROL6B(37)
      CASE DEFAULT
        CALL PUSHCONTROL6B(38)
      END SELECT
!
! -- BOUNDARY CONDITIONS FOR PARALLEL MOMENTUM EQUATIONS --
!
      SELECT CASE  (bcmom(is, ib)) 
      CASE (0) 
        CALL PUSHCONTROL4B(14)
      CASE (1) 
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          CALL PUSHINTEGER4(icv1)
! number of the guard cell face
          CALL PUSHINTEGER4(ifc)
        END DO
        CALL PUSHCONTROL4B(0)
      CASE (2) 
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          CALL PUSHINTEGER4(icv1)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
          CALL PUSHINTEGER4(icv2)
! number of the guard cell face
          CALL PUSHINTEGER4(ifc)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          ivx1 = mpg%fcvx(ifc, 1)
          ivx2 = mpg%fcvx(ifc, 2)
          CALL PUSHREAL8(t1, r8/8)
          t1 = INTVERTEX_S_NODIFF(ivx1, ncv, nvx, mpg, geo%vxvol, pl%ua(&
&           :, is))
          CALL PUSHREAL8(t2, r8/8)
          t2 = INTVERTEX_S_NODIFF(ivx2, ncv, nvx, mpg, geo%vxvol, pl%ua(&
&           :, is))
        END DO
        CALL PUSHCONTROL4B(1)
      CASE (3) 
        CALL PUSHCONTROL4B(14)
      CASE (4) 
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          CALL PUSHINTEGER4(icv1)
! number of the guard cell face
          CALL PUSHINTEGER4(ifc)
        END DO
        CALL PUSHCONTROL4B(2)
      CASE (5) 
!wdk      Possible backwards-compatibility issue:
!wdk      In the unstructured solver, we impose flux per unit area normal
!wdk      to the surface/boundary.
!wdk      In the original code, the flux per unit area in the poloidal
!wdk      direction was imposed at E/W boundaries (and normal to the
!wdk      radial direction at N/S - unchanged for aligned grids)
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          CALL PUSHINTEGER4(icv1)
! number of the guard cell face
          CALL PUSHINTEGER4(ifc)
        END DO
        CALL PUSHCONTROL4B(3)
      CASE (6) 
        CALL PUSHCONTROL4B(14)
      CASE (7) 
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          CALL PUSHINTEGER4(icv1)
! number of the guard cell face
        END DO
        CALL PUSHCONTROL4B(4)
      CASE (8) 
        DO ibc=1,mpg%bccvp(ib, 2)
          CALL PUSHINTEGER4(icv1)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          CALL PUSHINTEGER4(icv2)
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          CALL PUSHINTEGER4(ifc)
          y15 = SQRT(pl%ti(icv1)/pl%ti(icv2))
          IF (1.0_R8 .GT. y15) THEN
            CALL PUSHREAL8(a, r8/8)
            a = y15
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHREAL8(a, r8/8)
            a = 1.0_R8
            CALL PUSHCONTROL1B(1)
          END IF
        END DO
        CALL PUSHCONTROL4B(5)
      CASE (9) 
        CALL PUSHREAL8(us, r8/8)
        us = 0.0_R8
        DO ibc=1,mpg%bccvp(ib, 2)
          CALL PUSHINTEGER4(icv)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          CALL PUSHINTEGER4(ifc)
          ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
          us = us + geo%fcs(ifc)*geo%fchz(ifc)
        END DO
        DO ibc=1,mpg%bccvp(ib, 2)
          CALL PUSHINTEGER4(icv)
          CALL PUSHINTEGER4(ifc)
        END DO
        CALL PUSHCONTROL4B(6)
      CASE (10) 
        DO ibc=1,mpg%bccvp(ib, 2)
          CALL PUSHINTEGER4(icv)
          CALL PUSHINTEGER4(ifc)
        END DO
        CALL PUSHCONTROL4B(7)
      CASE (11) 
        CALL PUSHCONTROL4B(14)
      CASE (12) 
        DO ibc=1,mpg%bccvp(ib, 2)
          CALL PUSHINTEGER4(icv)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          CALL PUSHINTEGER4(ifc)
          ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
          IF (0.0_R8 .LT. mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*dv%fna_fcor&
&             (ifc, 1, is)) THEN
            CALL PUSHREAL8(max19, r8/8)
            max19 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*dv%fna_fcor(ifc, &
&             1, is)
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHREAL8(max19, r8/8)
            max19 = 0.0_R8
            CALL PUSHCONTROL1B(1)
          END IF
        END DO
        CALL PUSHCONTROL4B(8)
      CASE (13) 
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          CALL PUSHINTEGER4(icv1)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the internal cell
          CALL PUSHINTEGER4(icv2)
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          CALL PUSHINTEGER4(ifc)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          ivx1 = mpg%fcvx(ifc, 1)
          ivx2 = mpg%fcvx(ifc, 2)
          CALL PUSHREAL8(t1, r8/8)
          t1 = INTVERTEX_S_NODIFF(ivx1, ncv, nvx, mpg, geo%vxvol, pl%ua(&
&           :, is))
          CALL PUSHREAL8(t2, r8/8)
          t2 = INTVERTEX_S_NODIFF(ivx2, ncv, nvx, mpg, geo%vxvol, pl%ua(&
&           :, is))
          IF (geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3) .GE. &
&             0.) THEN
            CALL PUSHREAL8(wrk, r8/8)
            wrk = geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3)
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHREAL8(wrk, r8/8)
            wrk = -(geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3)&
&             )
            CALL PUSHCONTROL1B(1)
          END IF
          IF (wrk .LT. geo%qalfmin) THEN
            CALL PUSHCONTROL1B(0)
          ELSE
!srv 15.02.26
            CALL PUSHREAL8ARRAY(vbc, r8*ncv*ns/8)
            CALL VBC_IS(ib, is, ibc, icv1, icv2, ifc, csbc(icv1, is), &
&                 wrk)
!srv 07.05.09 {
            IF (geo%fcpbshz(ifc) .GE. 0.) THEN
              CALL PUSHREAL8(abs5, r8/8)
              abs5 = geo%fcpbshz(ifc)
              CALL PUSHCONTROL1B(0)
            ELSE
              CALL PUSHREAL8(abs5, r8/8)
              abs5 = -geo%fcpbshz(ifc)
              CALL PUSHCONTROL1B(1)
            END IF
            CALL PUSHCONTROL1B(1)
          END IF
        END DO
        CALL PUSHCONTROL4B(9)
      CASE (14) 
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          CALL PUSHINTEGER4(icv1)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          CALL PUSHINTEGER4(ifc)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
!TODO: drift contributions!
          IF (0.0_R8 .LT. mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*dv%fna_fcor&
&             (ifc, 1, is)) THEN
            CALL PUSHREAL8(max20, r8/8)
            max20 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*dv%fna_fcor(ifc, &
&             1, is)
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHREAL8(max20, r8/8)
            max20 = 0.0_R8
            CALL PUSHCONTROL1B(1)
          END IF
        END DO
        CALL PUSHCONTROL4B(10)
      CASE (15) 
        CALL PUSHCONTROL4B(14)
      CASE (16) 
!       ..compute average parallel velocity on core boundary
        CALL PUSHREAL8(t0, r8/8)
        t0 = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
        DO ib0=1,nbc
          CALL PUSHINTEGER4(icv)
          icv = mpg%bccv(mpg%bccvp(ib0, 1), 2)
          IF (mpg%cvonclosedsurface(icv)) THEN
! loop over number of cells in the boundary
            DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
! number of the domain cell
              CALL PUSHINTEGER4(icv2)
              icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
              t0 = t0 + geo%cvvol(icv2)
            END DO
            CALL PUSHINTEGER4(ibc0 - 1)
            CALL PUSHCONTROL1B(1)
          ELSE
            CALL PUSHCONTROL1B(0)
          END IF
        END DO
!       ..impose velocity
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          CALL PUSHINTEGER4(icv1)
! number of the domain cell
          CALL PUSHINTEGER4(icv2)
! number of the guard cell face
          CALL PUSHINTEGER4(ifc)
        END DO
        CALL PUSHCONTROL4B(11)
      CASE (17) 
!wdk      Possible backwards-compatibility issue:
!wdk      In the unstructured solver, we impose flux per unit area normal
!wdk      to the surface/boundary.
!wdk      In the original code, the flux per unit area in the poloidal
!wdk      direction was imposed at E/W boundaries (and normal to the
!wdk      radial direction at N/S - unchanged for aligned grids)
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          CALL PUSHINTEGER4(icv1)
! number of the guard cell face
          CALL PUSHINTEGER4(ifc)
        END DO
        CALL PUSHCONTROL4B(12)
      CASE (18) 
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          CALL PUSHINTEGER4(icv)
        END DO
        CALL PUSHCONTROL4B(13)
      CASE DEFAULT
        CALL PUSHCONTROL4B(14)
      END SELECT
    END DO
    t3b = 0.D0
    DO 110 is=ns-1,0,-1
      CALL POPCONTROL4B(branch)
      IF (branch .LT. 7) THEN
        IF (branch .LT. 3) THEN
          IF (branch .EQ. 0) THEN
            DO ibc=mpg%bccvp(ib, 2),1,-1
              icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
              srwb%smo0(icv1, 1, is) = 0.D0
              ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
              momparb(is, ib, 1) = momparb(is, ib, 1) + am(is)*geo%fcs(&
&               ifc)*vbig*ne00*geo%fchz(ifc)*srwb%smo0(icv1, 0, is)
              srwb%smo0(icv1, 0, is) = 0.D0
              CALL POPINTEGER4(ifc)
              CALL POPINTEGER4(icv1)
            END DO
          ELSE IF (branch .EQ. 1) THEN
            DO ibc=mpg%bccvp(ib, 2),1,-1
              icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
              ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
              plb%na(icv1, is) = plb%na(icv1, is) - vbig*am(is)*geo%fcs(&
&               ifc)*geo%fchz(ifc)*srwb%smo0(icv1, 1, is)
              srwb%smo0(icv1, 1, is) = 0.D0
              icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
              temp4 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
              temp2 = cor9*geo%fcqgam(ifc, 1)*(geo%fchc(ifc, 1)+geo%fchc&
&               (ifc, 2))
              temp0 = geo%fchc(ifc, 1) + geo%fchc(ifc, 2)
              tempb5 = vbig*am(is)*geo%fcs(ifc)*geo%fchz(ifc)*srwb%smo0(&
&               icv1, 0, is)
              srwb%smo0(icv1, 0, is) = 0.D0
              plb%na(icv1, is) = plb%na(icv1, is) + (temp0*(geo%fcqgam(&
&               ifc, 0)*mompar(is, ib, 1))-temp2*(temp4*((t2-t1)/geo%&
&               fcht(ifc)))+pl%ua(icv2, is))*tempb5
              tempb = pl%na(icv1, is)*tempb5
              momparb(is, ib, 1) = momparb(is, ib, 1) + geo%fcqgam(ifc, &
&               0)*temp0*tempb
              tempb6 = -(temp4*temp2*tempb/geo%fcht(ifc))
              plb%ua(icv2, is) = plb%ua(icv2, is) + tempb
              t2b = tempb6
              t1b = -tempb6
              ivx2 = mpg%fcvx(ifc, 2)
              CALL POPREAL8(t2, r8/8)
              CALL INTVERTEX_S_B(ivx2, ncv, nvx, mpg, geo%vxvol, pl%ua(:&
&                          , is), plb%ua(:, is), t2b)
              ivx1 = mpg%fcvx(ifc, 1)
              CALL POPREAL8(t1, r8/8)
              CALL INTVERTEX_S_B(ivx1, ncv, nvx, mpg, geo%vxvol, pl%ua(:&
&                          , is), plb%ua(:, is), t1b)
              CALL POPINTEGER4(ifc)
              CALL POPINTEGER4(icv2)
              CALL POPINTEGER4(icv1)
            END DO
          ELSE
            DO ibc=mpg%bccvp(ib, 2),1,-1
              icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
              ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
              momparb(is, ib, 2) = momparb(is, ib, 2) - geo%fcs(ifc)*geo&
&               %fchz(ifc)*srwb%smo0(icv1, 1, is)
              srwb%smo0(icv1, 1, is) = 0.D0
              tempb6 = geo%fcs(ifc)*geo%fchz(ifc)*srwb%smo0(icv1, 0, is)
              srwb%smo0(icv1, 0, is) = 0.D0
              momparb(is, ib, 2) = momparb(is, ib, 2) + mompar(is, ib, 1&
&               )*tempb6
              momparb(is, ib, 1) = momparb(is, ib, 1) + mompar(is, ib, 2&
&               )*tempb6
              CALL POPINTEGER4(ifc)
              CALL POPINTEGER4(icv1)
            END DO
          END IF
        ELSE IF (branch .LT. 5) THEN
          IF (branch .EQ. 3) THEN
            DO ibc=mpg%bccvp(ib, 2),1,-1
              icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
              srwb%smo0(icv1, 1, is) = 0.D0
              ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
              momparb(is, ib, 1) = momparb(is, ib, 1) + geo%fcs(ifc)*geo&
&               %fchz(ifc)*srwb%smo0(icv1, 0, is)
              srwb%smo0(icv1, 0, is) = 0.D0
              CALL POPINTEGER4(ifc)
              CALL POPINTEGER4(icv1)
            END DO
          ELSE
            DO ibc=mpg%bccvp(ib, 2),1,-1
              icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
              srwb%smo0(icv1, 1, is) = 0.D0
              srwb%smo0(icv1, 0, is) = 0.D0
              CALL POPINTEGER4(icv1)
            END DO
          END IF
        ELSE IF (branch .EQ. 5) THEN
          DO ibc=mpg%bccvp(ib, 2),1,-1
            icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            plb%na(icv1, is) = plb%na(icv1, is) - vbig*am(is)*geo%fcs(&
&             ifc)*geo%fchz(ifc)*srwb%smo0(icv1, 0, is)
            srwb%smo0(icv1, 0, is) = 0.D0
            icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
            tempb5 = geo%fcs(ifc)*geo%fchz(ifc)*vbig*am(is)*srwb%smo0(&
&             icv1, 0, is)
            srwb%smo0(icv1, 0, is) = 0.D0
            tempb2 = pl%ua(icv2, is)*tempb5
            plb%ua(icv2, is) = plb%ua(icv2, is) + pl%na(icv1, is)*a*&
&             tempb5
            plb%na(icv1, is) = plb%na(icv1, is) + a*tempb2
            ab = pl%na(icv1, is)*tempb2
            CALL POPCONTROL1B(branch)
            IF (branch .EQ. 0) THEN
              CALL POPREAL8(a, r8/8)
              y15b = ab
            ELSE
              CALL POPREAL8(a, r8/8)
              y15b = 0.D0
            END IF
            temp5 = pl%ti(icv1)/pl%ti(icv2)
            IF (temp5 .EQ. 0.D0) THEN
              tempb5 = 0.D0
            ELSE
              tempb5 = y15b/(pl%ti(icv2)*2.0*SQRT(temp5))
            END IF
            plb%ti(icv1) = plb%ti(icv1) + tempb5
            plb%ti(icv2) = plb%ti(icv2) - temp5*tempb5
            CALL POPINTEGER4(ifc)
            CALL POPINTEGER4(icv2)
            CALL POPINTEGER4(icv1)
          END DO
        ELSE
          DO ibc=mpg%bccvp(ib, 2),1,-1
            icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
            srwb%smo0(icv, 1, is) = 0.D0
            ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
            momparb(is, ib, 1) = momparb(is, ib, 1) + geo%fcs(ifc)*geo%&
&             fchz(ifc)*srwb%smo0(icv, 0, is)/us
            srwb%smo0(icv, 0, is) = 0.D0
            CALL POPINTEGER4(ifc)
            CALL POPINTEGER4(icv)
          END DO
          DO ibc=mpg%bccvp(ib, 2),1,-1
            CALL POPINTEGER4(ifc)
            CALL POPINTEGER4(icv)
          END DO
          CALL POPREAL8(us, r8/8)
        END IF
      ELSE IF (branch .LT. 11) THEN
        IF (branch .LT. 9) THEN
          IF (branch .EQ. 7) THEN
            DO ibc=mpg%bccvp(ib, 2),1,-1
              icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
              ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
              tempb6 = am(is)*mp*srwb%smo0(icv, 1, is)
              tempb5 = -(geo%fcs(ifc)*geo%fchz(ifc)*srwb%smo0(icv, 1, is&
&               )/mompar(is, ib, 1))
              srwb%smo0(icv, 1, is) = 0.D0
              cob%vsa0(icv, is) = cob%vsa0(icv, is) + tempb5
              momparb(is, ib, 1) = momparb(is, ib, 1) - co%vsa0(icv, is)&
&               *tempb5/mompar(is, ib, 1)
              sna0_no_mdfb(icv, 1, is) = sna0_no_mdfb(icv, 1, is) + pl%&
&               na(icv, is)*tempb6
              plb%na(icv, is) = plb%na(icv, is) + sna0_no_mdf(icv, 1, is&
&               )*tempb6
              tempb5 = am(is)*mp*srwb%smo0(icv, 0, is)
              srwb%smo0(icv, 0, is) = 0.D0
              plb%ua(icv, is) = plb%ua(icv, is) + sna0_no_mdf(icv, 0, is&
&               )*tempb5
              sna0_no_mdfb(icv, 0, is) = sna0_no_mdfb(icv, 0, is) + pl%&
&               ua(icv, is)*tempb5
              CALL POPINTEGER4(ifc)
              CALL POPINTEGER4(icv)
            END DO
          ELSE
            DO ibc=mpg%bccvp(ib, 2),1,-1
              icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
              ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
              momparb(is, ib, 2) = momparb(is, ib, 2) + geo%fcs(ifc)*geo&
&               %fchz(ifc)*srwb%smo0(icv, 3, is)
              tempb6 = srwb%smo0(icv, 3, is)/pl%na(icv, is)
              momparb(is, ib, 1) = momparb(is, ib, 1) + max19*tempb6
              max19b = mompar(is, ib, 1)*tempb6
              plb%na(icv, is) = plb%na(icv, is) - mompar(is, ib, 1)*&
&               max19*tempb6/pl%na(icv, is)
              CALL POPCONTROL1B(branch)
              IF (branch .EQ. 0) THEN
                CALL POPREAL8(max19, r8/8)
                dvb%fna_fcor(ifc, 1, is) = dvb%fna_fcor(ifc, 1, is) + &
&                 mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*max19b
              ELSE
                CALL POPREAL8(max19, r8/8)
              END IF
              srwb%smo0(icv, 2, is) = 0.D0
              srwb%smo0(icv, 1, is) = 0.D0
              srwb%smo0(icv, 0, is) = 0.D0
              CALL POPINTEGER4(ifc)
              CALL POPINTEGER4(icv)
            END DO
          END IF
        ELSE IF (branch .EQ. 9) THEN
          DO ibc=mpg%bccvp(ib, 2),1,-1
            CALL POPCONTROL1B(branch)
            IF (branch .EQ. 0) THEN
              icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
              ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
              plb%na(icv1, is) = plb%na(icv1, is) - vbig*am(is)*geo%fcs(&
&               ifc)*geo%fchz(ifc)*srwb%smo0(icv1, 1, is)
              srwb%smo0(icv1, 1, is) = 0.D0
              icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
              temp6 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
              temp4 = cor9*geo%fcqgam(ifc, 1)*(geo%fchc(ifc, 1)+geo%fchc&
&               (ifc, 2))
              tempb5 = vbig*am(is)*geo%fcs(ifc)*geo%fchz(ifc)*srwb%smo0(&
&               icv1, 0, is)
              srwb%smo0(icv1, 0, is) = 0.D0
              plb%na(icv1, is) = plb%na(icv1, is) + (pl%ua(icv2, is)-&
&               temp4*(temp6*((t2-t1)/geo%fcht(ifc))))*tempb5
              tempb2 = pl%na(icv1, is)*tempb5
              plb%ua(icv2, is) = plb%ua(icv2, is) + tempb2
              tempb3 = -(temp6*temp4*tempb2/geo%fcht(ifc))
              t2b = tempb3
              t1b = -tempb3
            ELSE
              icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
              plb%na(icv1, is) = plb%na(icv1, is) - am(is)*abs5*ubig*mp*&
&               srwb%smo0(icv1, 1, is)/epslon**2
              ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
              CALL POPCONTROL1B(branch)
              IF (branch .EQ. 0) THEN
                CALL POPREAL8(abs5, r8/8)
              ELSE
                CALL POPREAL8(abs5, r8/8)
              END IF
              tempb5 = ubig*mp*geo%fchz(ifc)*am(is)*geo%fcs(ifc)*srwb%&
&               smo0(icv1, 0, is)
              tempb2 = vbc(icv1, is)*tempb5/epslon**2
              vbcb(icv1, is) = vbcb(icv1, is) + pl%na(icv1, is)*mompar(&
&               is, ib, 1)*tempb5/epslon**2
              plb%na(icv1, is) = plb%na(icv1, is) + mompar(is, ib, 1)*&
&               tempb2
              momparb(is, ib, 1) = momparb(is, ib, 1) + pl%na(icv1, is)*&
&               tempb2
              icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
              CALL POPREAL8ARRAY(vbc, r8*ncv*ns/8)
              CALL VBC_IS_B(ib, is, ibc, icv1, icv2, ifc, csbc(icv1, is)&
&                     , csbcb(icv1, is), wrk)
              t1b = 0.D0
              t2b = 0.D0
            END IF
            CALL POPCONTROL1B(branch)
            IF (branch .EQ. 0) THEN
              CALL POPREAL8(wrk, r8/8)
            ELSE
              CALL POPREAL8(wrk, r8/8)
            END IF
            ivx2 = mpg%fcvx(ifc, 2)
            CALL POPREAL8(t2, r8/8)
            CALL INTVERTEX_S_B(ivx2, ncv, nvx, mpg, geo%vxvol, pl%ua(:, &
&                        is), plb%ua(:, is), t2b)
            ivx1 = mpg%fcvx(ifc, 1)
            CALL POPREAL8(t1, r8/8)
            CALL INTVERTEX_S_B(ivx1, ncv, nvx, mpg, geo%vxvol, pl%ua(:, &
