                tempb3 = -(mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*0.5_R8*t1b&
&                 )
                tempb0 = (pl%na(icv1, is)+pl%na(icv2, is))*tempb3
                tempb2 = (temp*dv%vaecrb(ifc, 0, is)+temp4*dv%vaecrb(ifc&
&                 , 1, is))*tempb3
                plb%na(icv1, is) = plb%na(icv1, is) + tempb2
                plb%na(icv2, is) = plb%na(icv2, is) + tempb2
                dvb%vaecrb(ifc, 0, is) = dvb%vaecrb(ifc, 0, is) + temp*&
&                 tempb0
                dvb%vaecrb(ifc, 1, is) = dvb%vaecrb(ifc, 1, is) + temp4*&
&                 tempb0
                CALL POPCONTROL1B(branch)
                IF (branch .EQ. 0) THEN
                  CALL POPREAL8(srw%sna0(icv1, 0, is), r8/8)
                  t0b = srwb%sna0(icv1, 0, is)
                ELSE
                  CALL POPREAL8(srw%sna0(icv1, 1, is), r8/8)
                  tempb3 = srwb%sna0(icv1, 1, is)/pl%na(icv1, is)
                  t0b = tempb3
                  plb%na(icv1, is) = plb%na(icv1, is) - t0*tempb3/pl%na(&
&                   icv1, is)
                END IF
                CALL POPREAL8(t0, r8/8)
                tempb2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*t0b
                dvb%fnapsch(ifc, 0, is) = dvb%fnapsch(ifc, 0, is) + &
&                 tempb2
                dvb%fnapsch(ifc, 1, is) = dvb%fnapsch(ifc, 1, is) + &
&                 tempb2
              END IF
              CALL POPREAL8(sna0_no_mdf(icv1, 1, is), r8/8)
              srwb%sna0(icv1, 1, is) = srwb%sna0(icv1, 1, is) + &
&               sna0_no_mdfb(icv1, 1, is)
              sna0_no_mdfb(icv1, 1, is) = 0.D0
              CALL POPREAL8(sna0_no_mdf(icv1, 0, is), r8/8)
              srwb%sna0(icv1, 0, is) = srwb%sna0(icv1, 0, is) + &
&               sna0_no_mdfb(icv1, 0, is)
              sna0_no_mdfb(icv1, 0, is) = 0.D0
              sy = geo%fcs(ifc)
              CALL POPREAL8(srw%sna0(icv1, 1, is), r8/8)
              temp1 = rt%rza(icv1, is)*pl%te(icv1) + pl%ti(icv1)
              tempb2 = -(sy*srwb%sna0(icv1, 1, is)/conpar(is, ib, 1))
              srwb%sna0(icv1, 1, is) = 0.D0
              cob%dna0(icv1, is) = cob%dna0(icv1, is) + tempb2
              cob%dpa0(icv1, is) = cob%dpa0(icv1, is) + temp1*tempb2
              tempb1 = co%dpa0(icv1, is)*tempb2
              conparb(is, ib, 1) = conparb(is, ib, 1) - (co%dna0(icv1, &
&               is)+co%dpa0(icv1, is)*temp1)*tempb2/conpar(is, ib, 1)
              rtb%rza(icv1, is) = rtb%rza(icv1, is) + pl%te(icv1)*tempb1
              plb%te(icv1) = plb%te(icv1) + rt%rza(icv1, is)*tempb1
              plb%ti(icv1) = plb%ti(icv1) + tempb1
              CALL POPREAL8(srw%sna0(icv1, 0, is), r8/8)
              srwb%sna0(icv1, 0, is) = 0.D0
              CALL POPINTEGER4(ifc)
              CALL POPINTEGER4(icv2)
              CALL POPINTEGER4(icv1)
            END DO
          ELSE
            DO ibc=mpg%bccvp(ib, 2),1,-1
              CALL POPCONTROL1B(branch)
              IF (branch .EQ. 0) THEN
                icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
                CALL POPREAL8(srw%sna0(icv1, 1, is), r8/8)
                t0b = pl%na(icv1, is)*srwb%sna0(icv1, 0, is) - srwb%sna0&
&                 (icv1, 1, is)
                CALL POPREAL8(srw%sna0(icv1, 0, is), r8/8)
                plb%na(icv1, is) = plb%na(icv1, is) + t0*srwb%sna0(icv1&
&                 , 0, is)
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                CALL POPREAL8(t0, r8/8)
                temp3 = (rt%rza(icv1, is)*pl%te(icv1)+pl%ti(icv1))/(am(&
&                 is)*mp)
                temp1 = SQRT(temp3)
                tempb5 = geo%fcs(ifc)*t0b
                IF (temp3 .EQ. 0.D0) THEN
                  tempb2 = 0.D0
                ELSE
                  tempb2 = conpar(is, ib, 2)*tempb5/(am(is)*mp*2.0*temp1&
&                   )
                END IF
                conparb(is, ib, 2) = conparb(is, ib, 2) + temp1*tempb5
                rtb%rza(icv1, is) = rtb%rza(icv1, is) + pl%te(icv1)*&
&                 tempb2
                plb%te(icv1) = plb%te(icv1) + rt%rza(icv1, is)*tempb2
                plb%ti(icv1) = plb%ti(icv1) + tempb2
                CALL POPCONTROL1B(branch)
                IF (branch .EQ. 0) THEN
                  CALL POPREAL8(srw%sna0(icv1, 0, is), r8/8)
                  t0b = srwb%sna0(icv1, 0, is)
                ELSE
                  CALL POPREAL8(srw%sna0(icv1, 1, is), r8/8)
                  tempb4 = srwb%sna0(icv1, 1, is)/pl%na(icv1, is)
                  t0b = tempb4
                  plb%na(icv1, is) = plb%na(icv1, is) - t0*tempb4/pl%na(&
&                   icv1, is)
                END IF
                CALL POPREAL8(t0, r8/8)
                tempb5 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*t0b
                dvb%fnapsch(ifc, 0, is) = dvb%fnapsch(ifc, 0, is) + &
&                 tempb5
                dvb%fnapsch(ifc, 1, is) = dvb%fnapsch(ifc, 1, is) + &
&                 tempb5
                CALL POPREAL8(srw%sna0(icv1, 1, is), r8/8)
                max4b = -srwb%sna0(icv1, 1, is)
                CALL POPCONTROL1B(branch)
                IF (branch .EQ. 0) THEN
                  y2b = max4b
                ELSE
                  y2b = 0.D0
                END IF
                icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
                temp5 = (pl%na(icv1, is)+pl%na(icv2, is))/pl%na(icv1, is&
&                 )
                temp2 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
                temp0 = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
                tempb4 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*0.5_R8*y2b
                dvb%vaecrb(ifc, 0, is) = dvb%vaecrb(ifc, 0, is) + temp2*&
&                 temp5*tempb4
                dvb%vaecrb(ifc, 1, is) = dvb%vaecrb(ifc, 1, is) + temp0*&
&                 temp5*tempb4
                tempb5 = (temp2*dv%vaecrb(ifc, 0, is)+temp0*dv%vaecrb(&
&                 ifc, 1, is))*tempb4/pl%na(icv1, is)
                plb%na(icv1, is) = plb%na(icv1, is) + tempb5
                plb%na(icv2, is) = plb%na(icv2, is) + tempb5
                plb%na(icv1, is) = plb%na(icv1, is) - temp5*tempb5
              ELSE
                icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
                CALL POPREAL8(srw%sna0(icv1, 1, is), r8/8)
                max3b = -srwb%sna0(icv1, 1, is)
                CALL POPCONTROL1B(branch)
                IF (branch .EQ. 0) THEN
                  y1b = max3b
                ELSE
                  y1b = 0.D0
                END IF
                icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                temp5 = (pl%na(icv1, is)+pl%na(icv2, is))/pl%na(icv1, is&
&                 )
                temp0 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
                temp = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
                tempb4 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*0.5_R8*y1b
                tempb3 = temp5*tempb4
                tempb5 = (temp0*(dv%vadia(ifc, 0, is)+dv%vaecrb(ifc, 0, &
&                 is))+temp*(dv%vadia(ifc, 1, is)+dv%vaecrb(ifc, 1, is))&
&                 )*tempb4/pl%na(icv1, is)
                plb%na(icv1, is) = plb%na(icv1, is) + tempb5
                plb%na(icv2, is) = plb%na(icv2, is) + tempb5
                plb%na(icv1, is) = plb%na(icv1, is) - temp5*tempb5
                dvb%vadia(ifc, 0, is) = dvb%vadia(ifc, 0, is) + temp0*&
&                 tempb3
                dvb%vaecrb(ifc, 0, is) = dvb%vaecrb(ifc, 0, is) + temp0*&
&                 tempb3
                dvb%vadia(ifc, 1, is) = dvb%vadia(ifc, 1, is) + temp*&
&                 tempb3
                dvb%vaecrb(ifc, 1, is) = dvb%vaecrb(ifc, 1, is) + temp*&
&                 tempb3
              END IF
              CALL POPREAL8ARRAY(sna0_no_mdf(icv1, :, is), r8*2/8)
              srwb%sna0(icv1, :, is) = srwb%sna0(icv1, :, is) + &
&               sna0_no_mdfb(icv1, :, is)
              CALL POPREAL8(srw%sna0(icv1, 1, is), r8/8)
              temp1 = (rt%rza(icv1, is)*pl%te(icv1)+pl%ti(icv1))/(am(is)&
&               *mp)
              temp5 = SQRT(temp1)
              tempb2 = geo%fcs(ifc)*srwb%sna0(icv1, 1, is)
              srwb%sna0(icv1, 1, is) = 0.D0
              IF (temp1 .EQ. 0.D0) THEN
                tempb1 = 0.D0
              ELSE
                tempb1 = conpar(is, ib, 1)*tempb2/(am(is)*mp*2.0*temp5)
              END IF
              conparb(is, ib, 1) = conparb(is, ib, 1) + temp5*tempb2
              rtb%rza(icv1, is) = rtb%rza(icv1, is) + pl%te(icv1)*tempb1
              plb%te(icv1) = plb%te(icv1) + rt%rza(icv1, is)*tempb1
              plb%ti(icv1) = plb%ti(icv1) + tempb1
              CALL POPREAL8(srw%sna0(icv1, 0, is), r8/8)
              srwb%sna0(icv1, 0, is) = 0.D0
              CALL POPINTEGER4(ifc)
              CALL POPINTEGER4(icv2)
              CALL POPINTEGER4(icv1)
