          END IF
        ELSE IF (branch .LT. 14) THEN
          IF (branch .LT. 11) THEN
            IF (branch .EQ. 9) THEN
              t2b = 0.D0
              DO ibc=mpg%bccvp(ib, 2),1,-1
                icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
                CALL POPREAL8(sna0_no_mdf(icv1, 1, is), r8/8)
                srwb%sna0(icv1, 1, is) = srwb%sna0(icv1, 1, is) + &
&                 sna0_no_mdfb(icv1, 1, is)
                sna0_no_mdfb(icv1, 1, is) = 0.D0
                CALL POPREAL8(sna0_no_mdf(icv1, 0, is), r8/8)
                srwb%sna0(icv1, 0, is) = srwb%sna0(icv1, 0, is) + &
&                 sna0_no_mdfb(icv1, 0, is)
                sna0_no_mdfb(icv1, 0, is) = 0.D0
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                CALL POPREAL8(srw%sna0(icv1, 1, is), r8/8)
                srwb%sna0(icv1, 1, is) = 0.D0
                CALL POPREAL8(srw%sna0(icv1, 0, is), r8/8)
                t2b = t2b + vbig*geo%fcs(ifc)*srwb%sna0(icv1, 0, is)
                srwb%sna0(icv1, 0, is) = 0.D0
                CALL POPINTEGER4(ifc)
                CALL POPINTEGER4(icv1)
              END DO
              CALL POPREAL8(t2, r8/8)
              temp4 = t3/max5
              tempb5 = t1*t2b
              t1b = (1.0_R8-(totflux-totpar)*temp4)*t2b
              totfluxb = -(temp4*tempb5)
              totparb = temp4*tempb5
              tempb4 = -((totflux-totpar)*tempb5/max5)
              t3b = t3b + tempb4
              max5b = -(temp4*tempb4)
              CALL POPCONTROL2B(branch)
              IF (branch .LT. 2) THEN
                IF (branch .EQ. 0) THEN
                  CALL POPREAL8(max5, r8/8)
                  y3b = 0.D0
                ELSE
                  CALL POPREAL8(max5, r8/8)
                  y3b = max5b
                END IF
                x1b = 0.D0
              ELSE
                IF (branch .EQ. 2) THEN
                  CALL POPREAL8(max5, r8/8)
                  x1b = 0.D0
                ELSE
                  CALL POPREAL8(max5, r8/8)
                  x1b = max5b
                END IF
                y3b = 0.D0
              END IF
              CALL POPCONTROL1B(branch)
              IF (branch .EQ. 0) THEN
                totparb = totparb + y3b
              ELSE
                totparb = totparb - y3b
              END IF
              CALL POPCONTROL1B(branch)
              IF (branch .EQ. 0) THEN
                totfluxb = totfluxb + x1b
              ELSE
                totfluxb = totfluxb - x1b
              END IF
              CALL POPCONTROL1B(branch)
              IF (branch .EQ. 0) THEN
                CALL POPREAL8(t3, r8/8)
                t3b = 0.D0
              END IF
              CALL POPCONTROL1B(branch)
              IF (branch .EQ. 0) THEN
                CALL POPREAL8(t3, r8/8)
                conparb(is, ib, 2) = conparb(is, ib, 2) + t3b
                t3b = 0.D0
              END IF
              CALL POPREAL8(totpar, r8/8)
              conparb(is, ib, 1) = conparb(is, ib, 1) + totparb
              conparb(is, ib, 3) = conparb(is, ib, 3) + totparb
              t1b = t1b/t0
              DO ibc=mpg%bccvp(ib, 2),1,-1
                CALL POPCONTROL1B(branch)
                IF (branch .EQ. 0) THEN
                  icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                  tempb5 = -(mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*totfluxb&
&                   )
                  dvb%fna_eir(ifc, 0, is) = dvb%fna_eir(ifc, 0, is) + &
&                   tempb5
                  dvb%fna_eir(ifc, 1, is) = dvb%fna_eir(ifc, 1, is) + &
&                   tempb5
                ELSE
                  icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                  tempb5 = -(mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*totfluxb&
&                   )
                  dvb%fna(ifc, 0, is) = dvb%fna(ifc, 0, is) + tempb5
                  dvb%fna(ifc, 1, is) = dvb%fna(ifc, 1, is) + tempb5
                END IF
                plb%na(icv1, is) = plb%na(icv1, is) + geo%fcs(ifc)*t1b
                CALL POPINTEGER4(ifc)
                CALL POPINTEGER4(icv1)
              END DO
              CALL POPREAL8(totflux, r8/8)
              CALL POPREAL8(t1, r8/8)
              CALL POPREAL8(t0, r8/8)
            ELSE
              DO ibc=mpg%bccvp(ib, 2),1,-1
                CALL POPCONTROL3B(branch)
                IF (branch .LT. 2) THEN
                  IF (branch .NE. 0) THEN
                    CALL POPREAL8(srw%sna0(icv1, 1, is), r8/8)
