                    max9b = srwb%sna0(icv1, 0, is)
                    CALL POPCONTROL1B(branch)
                    IF (branch .EQ. 0) t0b = t0b + max9b
                    icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
                    ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                    CALL POPREAL8(t0, r8/8)
                    temp2 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
                    temp0 = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
                    tempb5 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*t0b
                    dvb%fnapsch(ifc, 0, is) = dvb%fnapsch(ifc, 0, is) + &
&                     tempb5
                    dvb%fnapsch(ifc, 1, is) = dvb%fnapsch(ifc, 1, is) + &
&                     tempb5
                    tempb4 = (pl%na(icv1, is)+pl%na(icv2, is))*0.5_R8*&
&                     tempb5
                    tempb2 = (temp2*dv%vadia(ifc, 0, is)+temp0*dv%vadia(&
&                     ifc, 1, is))*0.5_R8*tempb5
                    plb%na(icv1, is) = plb%na(icv1, is) + tempb2
                    plb%na(icv2, is) = plb%na(icv2, is) + tempb2
                    dvb%vadia(ifc, 0, is) = dvb%vadia(ifc, 0, is) + &
&                     temp2*tempb4
                    dvb%vadia(ifc, 1, is) = dvb%vadia(ifc, 1, is) + &
&                     temp0*tempb4
                  END IF
                  CALL POPREAL8ARRAY(sna0_no_mdf(icv1, :, is), r8*2/8)
                  srwb%sna0(icv1, :, is) = srwb%sna0(icv1, :, is) + &
&                   sna0_no_mdfb(icv1, :, is)
                  sna0_no_mdfb(icv1, :, is) = 0.D0
                  CALL POPCONTROL1B(branch)
                  IF (branch .EQ. 0) THEN
                    CALL POPREAL8(srw%sna0(icv1, 1, is), r8/8)
                    tempb5 = -(geo%fcs(ifc)*srwb%sna0(icv1, 1, is)/&
&                     conpar(is, ib, 2))
                    cob%dna0(icv1, is) = cob%dna0(icv1, is) + tempb5
                    conparb(is, ib, 2) = conparb(is, ib, 2) - co%dna0(&
&                     icv1, is)*tempb5/conpar(is, ib, 2)
                  END IF
                  CALL POPREAL8(srw%sna0(icv1, 1, is), r8/8)
                  tempb4 = -(geo%fcs(ifc)*srwb%sna0(icv1, 1, is))
                  srwb%sna0(icv1, 1, is) = 0.D0
                  momparb(is, ib, 1) = momparb(is, ib, 1) + max8*tempb4
                  max8b = mompar(is, ib, 1)*tempb4
                  CALL POPCONTROL1B(branch)
                  IF (branch .EQ. 0) THEN
                    CALL POPREAL8(max8, r8/8)
                    y6b = max8b
                    x2b = 0.D0
                  ELSE
                    CALL POPREAL8(max8, r8/8)
                    x2b = max8b
                    y6b = 0.D0
                  END IF
                  vbcb(icv1, is) = vbcb(icv1, is) + SIGN(1.0_R8, wrk)*&
&                   y6b
                  vbndb = y6b
                  csbcb(icv1, is) = csbcb(icv1, is) + abs6*x2b
                  CALL POPCONTROL1B(branch)
                  IF (branch .EQ. 0) THEN
                    CALL POPREAL8(abs6, r8/8)
                  ELSE
                    CALL POPREAL8(abs6, r8/8)
                  END IF
                  CALL POPREAL8(srw%sna0(icv1, 0, is), r8/8)
                  srwb%sna0(icv1, 0, is) = 0.D0
                  tempb4 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*vbndb
                  dvb%vaecrb(ifc, 0, is) = dvb%vaecrb(ifc, 0, is) + geo%&
&                   fcqalf(ifc, 0)*tempb4
                  dvb%vaecrb(ifc, 1, is) = dvb%vaecrb(ifc, 1, is) + geo%&
&                   fcqalf(ifc, 1)*tempb4
                  csb0 = 0.D0
                ELSE
                  IF (branch .EQ. 2) THEN
                    icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
                    CALL POPREAL8(srw%sna0(icv1, 1, is), r8/8)
                    tempb4 = srwb%sna0(icv1, 1, is)/pl%na(icv1, is)
                    t0b = tempb4
                    plb%na(icv1, is) = plb%na(icv1, is) - t0*tempb4/pl%&
&                     na(icv1, is)
                  ELSE IF (branch .EQ. 3) THEN
                    icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
                    CALL POPREAL8(srw%sna0(icv1, 0, is), r8/8)
                    t0b = srwb%sna0(icv1, 0, is)
                  ELSE
                    icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
                    CALL POPREAL8(srw%sna0(icv1, 1, is), r8/8)
                    max6b = -srwb%sna0(icv1, 1, is)
                    CALL POPCONTROL1B(branch)
                    IF (branch .EQ. 0) THEN
                      y4b = max6b
                    ELSE
                      y4b = 0.D0
                    END IF
                    icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
                    ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                    temp5 = (pl%na(icv1, is)+pl%na(icv2, is))/pl%na(icv1&
&                     , is)
                    temp2 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
                    temp0 = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
