                  srwb%sna0(icv1, 0, is) = srwb%sna0(icv1, 0, is) + &
&                   sna0_no_mdfb(icv1, 0, is)
                  sna0_no_mdfb(icv1, 0, is) = 0.D0
                  ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                  CALL POPREAL8(srw%sna0(icv1, 1, is), r8/8)
                  srwb%sna0(icv1, 1, is) = 0.D0
                  icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                  CALL POPREAL8(srw%sna0(icv1, 0, is), r8/8)
                  tempb4 = vbig*geo%fcs(ifc)*srwb%sna0(icv1, 0, is)
                  srwb%sna0(icv1, 0, is) = 0.D0
                  nasb = nasb + tempb4
                  plb%na(icv2, is) = plb%na(icv2, is) + tempb4
                  t1b = t1b - tempb4
                  CALL POPINTEGER4(ifc)
                  CALL POPINTEGER4(icv2)
                  CALL POPINTEGER4(icv1)
                END DO
              END IF
            END DO
            CALL POPCONTROL1B(branch)
            IF (branch .EQ. 0) THEN
              CALL POPREAL8(nas, r8/8)
              temp4 = t3/(abs4+abs10+abs14)
              tempb3 = -(temp4*nas*nasb)
              tempb4 = -((totfluxn+totfluxi-sconpar(is))*nas*nasb/(abs4+&
&               abs10+abs14))
              nasb = (1.0_R8-(totfluxn+totfluxi-sconpar(is))*temp4)*nasb
              t3b = t3b + tempb4
              tempb0 = -(temp4*tempb4)
              abs4b = tempb0
              abs10b = tempb0
              abs14b = tempb0
              totfluxnb = tempb3
              totfluxib = tempb3
              sconparb(is) = sconparb(is) - tempb3
              CALL POPCONTROL1B(branch)
              IF (branch .EQ. 0) THEN
                CALL POPREAL8(abs14, r8/8)
                sconparb(is) = sconparb(is) + abs14b
              ELSE
                CALL POPREAL8(abs14, r8/8)
                sconparb(is) = sconparb(is) - abs14b
              END IF
              CALL POPCONTROL1B(branch)
              IF (branch .EQ. 0) THEN
                CALL POPREAL8(abs10, r8/8)
                totfluxib = totfluxib - abs10b
              ELSE
                CALL POPREAL8(abs10, r8/8)
                totfluxib = totfluxib + abs10b
              END IF
              CALL POPCONTROL1B(branch)
              IF (branch .EQ. 0) THEN
                CALL POPREAL8(abs4, r8/8)
                totfluxnb = totfluxnb - abs4b
              ELSE
                CALL POPREAL8(abs4, r8/8)
                totfluxnb = totfluxnb + abs4b
              END IF
            ELSE
              totfluxib = 0.D0
              totfluxnb = 0.D0
            END IF
            CALL POPCONTROL1B(branch)
            IF (branch .NE. 0) THEN
              CALL POPREAL8(t3, r8/8)
              t3b = 0.D0
            END IF
            CALL POPCONTROL1B(branch)
            IF (branch .EQ. 0) THEN
              CALL POPREAL8(t3, r8/8)
              conparb(is, ib, 2) = conparb(is, ib, 2) + t3b
              t3b = 0.D0
            END IF
            nasb = nasb/t0
            t1b = t1b/t0
            DO ibw=nbc,ib,-1
              CALL POPCONTROL1B(branch)
              IF (branch .NE. 0) THEN
                CALL POPINTEGER4(ad_to16)
                DO ibc=ad_to16,1,-1
                  icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                  plb%na(icv1, is) = plb%na(icv1, is) + geo%cvvol(icv2)*&
&                   nasb
                  plb%na(icv2, is) = plb%na(icv2, is) + geo%cvvol(icv2)*&
&                   t1b
                  CALL POPCONTROL1B(branch)
                  IF (branch .EQ. 0) THEN
                    ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                    tempb5 = -(mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)*&
&                     totfluxib)
                    dvb%fna_mdf(ifc, 0, is) = dvb%fna_mdf(ifc, 0, is) + &
&                     tempb5
                    dvb%fna_mdf(ifc, 1, is) = dvb%fna_mdf(ifc, 1, is) + &
&                     tempb5
                  ELSE
                    ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                    tempb5 = -(mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)*&
&                     totfluxib)
                    dvb%fna(ifc, 0, is) = dvb%fna(ifc, 0, is) + tempb5
                    dvb%fna(ifc, 1, is) = dvb%fna(ifc, 1, is) + tempb5
                  END IF
                  DO isb=ns-1,0,-1
                    CALL POPCONTROL2B(branch)
                    IF (branch .GE. 2) THEN
                      IF (branch .EQ. 2) THEN
                        tempb5 = -(mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)*&
&                         totfluxnb)
                        dvb%fna(ifc, 0, isb) = dvb%fna(ifc, 0, isb) + &
&                         tempb5
                        dvb%fna(ifc, 1, isb) = dvb%fna(ifc, 1, isb) + &
&                         tempb5
                      ELSE
                        tempb5 = -(mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)*&
&                         totfluxnb)
                        dvb%fna_mdf(ifc, 0, isb) = dvb%fna_mdf(ifc, 0, &
&                         isb) + tempb5
                        dvb%fna_mdf(ifc, 1, isb) = dvb%fna_mdf(ifc, 1, &
&                         isb) + tempb5
                      END IF
                    END IF
                  END DO
                  CALL POPINTEGER4(isb)
                  CALL POPINTEGER4(ifc)
                  CALL POPINTEGER4(icv2)
                  CALL POPINTEGER4(icv1)
                END DO
              END IF
            END DO
            CALL POPREAL8(nas, r8/8)
            CALL POPREAL8(t1, r8/8)
            CALL POPREAL8(t0, r8/8)
            CALL POPREAL8(totfluxi, r8/8)
            CALL POPREAL8(totfluxn, r8/8)
            CALL POPCONTROL1B(branch)
            IF (branch .NE. 0) THEN
              DO ibw=nbc,ib,-1
                CALL POPCONTROL1B(branch)
                IF (branch .NE. 0) THEN
                  CALL POPREAL8(sconpar(is), r8/8)
                  conparb(is, ibw, 1) = conparb(is, ibw, 1) + sconparb(&
&                   is)
                END IF
              END DO
              CALL POPREAL8(sconpar(is), r8/8)
              sconparb(is) = 0.D0
            END IF
          END IF
        END IF
      ELSE IF (branch .GE. 36) THEN
        IF (branch .EQ. 36) THEN
          t1b = 0.D0
          DO ibc=mpg%bccvp(ib, 2),1,-1
            icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
            CALL POPREAL8(sna0_no_mdf(icv1, 1, is), r8/8)
            srwb%sna0(icv1, 1, is) = srwb%sna0(icv1, 1, is) + &
&             sna0_no_mdfb(icv1, 1, is)
            sna0_no_mdfb(icv1, 1, is) = 0.D0
            CALL POPREAL8(sna0_no_mdf(icv1, 0, is), r8/8)
            srwb%sna0(icv1, 0, is) = srwb%sna0(icv1, 0, is) + &
&             sna0_no_mdfb(icv1, 0, is)
            sna0_no_mdfb(icv1, 0, is) = 0.D0
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            CALL POPREAL8(srw%sna0(icv1, 1, is), r8/8)
            srwb%sna0(icv1, 1, is) = 0.D0
            icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
            CALL POPREAL8(srw%sna0(icv1, 0, is), r8/8)
            tempb5 = vbig*geo%fcs(ifc)*srwb%sna0(icv1, 0, is)
            srwb%sna0(icv1, 0, is) = 0.D0
            plb%na(icv2, is) = plb%na(icv2, is) + tempb5
            conparb(is, ib, 1) = conparb(is, ib, 1) + tempb5
            t1b = t1b - tempb5
            CALL POPINTEGER4(ifc)
            CALL POPINTEGER4(icv2)
            CALL POPINTEGER4(icv1)
          END DO
          t1b = t1b/t0
          DO ib0=nbc,1,-1
            CALL POPCONTROL1B(branch)
            IF (branch .NE. 0) THEN
              CALL POPINTEGER4(ad_to18)
              DO ibc0=ad_to18,1,-1
                icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
                plb%na(icv2, is) = plb%na(icv2, is) + geo%cvvol(icv2)*&
&                 t1b
                CALL POPINTEGER4(icv2)
              END DO
            END IF
            CALL POPINTEGER4(icv1)
          END DO
          CALL POPREAL8(t1, r8/8)
          CALL POPREAL8(t0, r8/8)
          CALL POPCONTROL2B(branch)
          IF (branch .EQ. 0) THEN
            CALL POPREAL8(conpar(is, ib, 1), r8/8)
            conparb(is, ib, 1) = 0.D0
          ELSE IF (branch .NE. 1) THEN
            GOTO 110
          END IF
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            CALL POPREAL8(conpar(is, ib, 1), r8/8)
            conparb(is, ib, 1) = 0.D0
          END IF
        ELSE IF (branch .EQ. 37) THEN
          t2b = 0.D0
          t4b = 0.D0
          DO ibc=mpg%bccvp(ib, 2),1,-1
            icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
            CALL POPREAL8(sna0_no_mdf(icv1, 1, is), r8/8)
            srwb%sna0(icv1, 1, is) = srwb%sna0(icv1, 1, is) + &
&             sna0_no_mdfb(icv1, 1, is)
            sna0_no_mdfb(icv1, 1, is) = 0.D0
            CALL POPREAL8(sna0_no_mdf(icv1, 0, is), r8/8)
            srwb%sna0(icv1, 0, is) = srwb%sna0(icv1, 0, is) + &
&             sna0_no_mdfb(icv1, 0, is)
            sna0_no_mdfb(icv1, 0, is) = 0.D0
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            CALL POPREAL8(srw%sna0(icv1, 1, is), r8/8)
            srwb%sna0(icv1, 1, is) = 0.D0
            icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
            CALL POPREAL8(srw%sna0(icv1, 0, is), r8/8)
            tempb5 = vbig*geo%fcs(ifc)*srwb%sna0(icv1, 0, is)
            srwb%sna0(icv1, 0, is) = 0.D0
            plb%na(icv2, is) = plb%na(icv2, is) + tempb5
            t4b = t4b + tempb5
            t2b = t2b - tempb5
            CALL POPINTEGER4(ifc)
            CALL POPINTEGER4(icv2)
            CALL POPINTEGER4(icv1)
          END DO
          temp4 = t3/max18
          tempb5 = t1*t4b
          t1b = (1.0_R8-(totflux-totpar)*temp4)*t4b
          totfluxb = -(temp4*tempb5)
          totparb = temp4*tempb5
          tempb4 = -((totflux-totpar)*tempb5/max18)
          t3b = t3b + tempb4
          max18b = -(temp4*tempb4)
          CALL POPCONTROL2B(branch)
          IF (branch .LT. 2) THEN
            IF (branch .EQ. 0) THEN
              CALL POPREAL8(max18, r8/8)
              y14b = 0.D0
            ELSE
              CALL POPREAL8(max18, r8/8)
              y14b = max18b
            END IF
            x11b = 0.D0
          ELSE
            IF (branch .EQ. 2) THEN
              CALL POPREAL8(max18, r8/8)
              x11b = 0.D0
            ELSE
              CALL POPREAL8(max18, r8/8)
              x11b = max18b
            END IF
            y14b = 0.D0
          END IF
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            totparb = totparb + y14b
          ELSE
            totparb = totparb - y14b
          END IF
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            totfluxb = totfluxb + x11b
          ELSE
            totfluxb = totfluxb - x11b
          END IF
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            CALL POPREAL8(t3, r8/8)
            t3b = 0.D0
          END IF
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            CALL POPREAL8(t3, r8/8)
            conparb(is, ib, 2) = conparb(is, ib, 2) + t3b
            t3b = 0.D0
          END IF
          t2b = t2b/t0
          t1b = t1b/t0
          DO ib0=nbc,1,-1
            CALL POPCONTROL1B(branch)
            IF (branch .NE. 0) THEN
              conparb(is, ib0, 1) = conparb(is, ib0, 1) + totparb
              conparb(is, ib0, 3) = conparb(is, ib0, 3) + totparb
              CALL POPINTEGER4(ad_to19)
              DO ibc0=ad_to19,1,-1
                CALL POPCONTROL1B(branch)
                IF (branch .EQ. 0) THEN
                  icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                  tempb5 = -(mpg%bcfcor(mpg%bccvp(ib0, 1)+ibc0-1)*&
&                   totfluxb)
                  dvb%fna_eir(ifc, 0, is) = dvb%fna_eir(ifc, 0, is) + &
&                   tempb5
                  dvb%fna_eir(ifc, 1, is) = dvb%fna_eir(ifc, 1, is) + &
&                   tempb5
                ELSE
                  icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                  tempb5 = -(mpg%bcfcor(mpg%bccvp(ib0, 1)+ibc0-1)*&
&                   totfluxb)
                  dvb%fna(ifc, 0, is) = dvb%fna(ifc, 0, is) + tempb5
                  dvb%fna(ifc, 1, is) = dvb%fna(ifc, 1, is) + tempb5
                END IF
                icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
                plb%na(icv2, is) = plb%na(icv2, is) + geo%cvvol(icv2)*&
&                 t2b
                plb%na(icv1, is) = plb%na(icv1, is) + geo%cvvol(icv2)*&
&                 t1b
                CALL POPINTEGER4(ifc)
                CALL POPINTEGER4(icv2)
              END DO
            END IF
            CALL POPINTEGER4(icv1)
          END DO
          CALL POPREAL8(totpar, r8/8)
          CALL POPREAL8(totflux, r8/8)
          CALL POPREAL8(t2, r8/8)
          CALL POPREAL8(t1, r8/8)
          CALL POPREAL8(t0, r8/8)
        END IF
      END IF
 110 CONTINUE
  END SUBROUTINE B2STBC_PHYS_SPECIES_B

!srv 15.02.26 }
!
  SUBROUTINE B2STBC_PHYS_SPECIES(ib)
    IMPLICIT NONE
    INTEGER :: is, ib, ibc, ib0, ibc0, ibw, isb
    INTEGER :: icv, icv1, icv2, ifc, ivx1, ivx2
    REAL(kind=r8) :: s1, t0, t1, t2, t3, t4, vbnd, totpar, totflux, &
&   totfluxn, totfluxi, a, cs, csb, wrk
    REAL(kind=r8), EXTERNAL :: INTVERTEX_S_NODIFF
    LOGICAL :: ishigh
    EXTERNAL XERRAB
    INTRINSIC MIN
    INTRINSIC SQRT
    INTRINSIC ABS
    INTRINSIC SIGN
    REAL(r8) :: y1
    REAL(r8) :: y2
    REAL(kind=r8) :: x1
    REAL(kind=r8) :: y3
    REAL(r8) :: y4
    REAL(r8) :: y5
    REAL(kind=r8) :: x2
    REAL(kind=r8) :: y6
    REAL(kind=r8) :: x3
    REAL(kind=r8) :: y7
    REAL(kind=r8) :: x4
    REAL(kind=r8) :: y8
    REAL(kind=r8) :: x5
    REAL(kind=r8) :: y9
    REAL(kind=r8) :: x6
    REAL(kind=r8) :: x7
    REAL(kind=r8) :: y10
    REAL(kind=r8) :: x8
    REAL(kind=r8) :: y11
    REAL(kind=r8) :: x9
    REAL(kind=r8) :: y12
    REAL(kind=r8) :: x10
    REAL(kind=r8) :: y13
    REAL(kind=r8) :: x11
    REAL(kind=r8) :: y14
    REAL(r8) :: y15
    REAL(r8) :: max1
    REAL(r8) :: min1
    REAL(r8) :: max2
    REAL(r8) :: min2
    REAL(r8) :: max3
    REAL(r8) :: max4
    REAL(kind=r8) :: max5
    REAL(kind=r8) :: abs0
    REAL(r8) :: max6
    REAL(r8) :: max7
    REAL(kind=r8) :: max8
    REAL(r8) :: max9
    REAL(r8) :: min3
    REAL(kind=r8) :: max10
    REAL(kind=r8) :: max11
    REAL(kind=r8) :: max12
    REAL(kind=r8) :: max13
    REAL(kind=r8) :: max14
    REAL(kind=r8) :: max15
    REAL(kind=r8) :: abs1
    REAL(kind=r8) :: abs2
    REAL(kind=r8) :: max16
    REAL(kind=r8) :: max17
    REAL(kind=r8) :: abs3
    REAL(kind=r8) :: abs4
    REAL(kind=r8) :: max18
    REAL(r8) :: max19
    REAL(kind=r8) :: abs5
    REAL(r8) :: max20
    REAL(kind=r8) :: abs6
    REAL(kind=r8) :: abs7
    REAL(kind=r8) :: abs8
    REAL(kind=r8) :: abs9
    REAL(kind=r8) :: abs10
    REAL(kind=r8) :: abs11
    REAL(kind=r8) :: abs12
    REAL(kind=r8) :: abs13
    REAL(kind=r8) :: abs14
    LOGICAL :: result10
!
    DO is=0,ns-1
      IF (is .EQ. ns - 1) THEN
        ishigh = .true.
      ELSE
        ishigh = .NOT.LNEXT(is, is + 1)
      END IF
!
! -- BOUNDARY CONDITIONS FOR CONTINUITY EQUATIONS --
      SELECT CASE  (bccon(is, ib)) 
      CASE (0) 

      CASE (1) 
!
!
! -- BCCON=1 -- PRESCRIBE THE VALUE OF THE DENSITY
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          IF (conpar(is, ib, 1) .EQ. 0.0_R8) THEN
            conpar(is, ib, 1) = switch%b2mndr_na_min
            WRITE(*, *) 'Zero density B.C. no longer allowed!'
            WRITE(*, *) 'Changed to na_min.'
          END IF
          WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)') &
&         'BCCON =  1 : constant density ', conpar(is, ib, 1), ' on ', &
&         bcchar(ib), boundary_location(ib), ' for species ', is
          CALL XERTST(conpar(is, ib, 1) .GT. 0.0_R8, &
&               'BCCON = 1, CONPAR(,,1) !> 0')
          icv = mpg%bccv(mpg%bccvp(ib, 1), 2)
          IF (mpg%cvonclosedsurface(icv)) THEN
            IF (is .EQ. ismain .AND. switch%use_astra .NE. 0) CALL &
&             XERRAB('Compile with -DASTRA option to couple to ASTRA!')
            IF (ishigh) CALL XERTST(switch%ionising_core .EQ. 0, &
&               'ionising_core switch usage inconsistent with BCCON = 1'&
&                            )
          END IF
        END IF
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%sna0(icv1, 0, is) = vbig*geo%fcs(ifc)*conpar(is, ib, 1)
          srw%sna0(icv1, 1, is) = -(vbig*geo%fcs(ifc))
          sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
          sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
        END DO
      CASE (2) 
!
! -- BCCON=2 -- PRESCRIBE THE GRADIENT OF THE DENSITY
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)') &
&         'BCCON =  2 : density gradient ', conpar(is, ib, 1), ' on ', &
&         bcchar(ib), boundary_location(ib), ' for species ', is
          icv = mpg%bccv(mpg%bccvp(ib, 1), 1)
          IF (mpg%cvonclosedsurface(icv) .AND. ishigh) CALL XERTST(&
&                                                            switch%&
&                                                          ionising_core&
&                                                            .EQ. 0, &
&               'ionising_core switch usage inconsistent with BCCON = 2'&
&                                                           )
        END IF
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          ivx1 = mpg%fcvx(ifc, 1)
          ivx2 = mpg%fcvx(ifc, 2)
          t1 = INTVERTEX_S_NODIFF(ivx1, ncv, nvx, mpg, geo%vxvol, pl%na(&
&           :, is))
          t2 = INTVERTEX_S_NODIFF(ivx2, ncv, nvx, mpg, geo%vxvol, pl%na(&
&           :, is))
          srw%sna0(icv1, 0, is) = vbig*geo%fcs(ifc)*(conpar(is, ib, 1)*(&
&           geo%fchc(ifc, 1)+geo%fchc(ifc, 2))*geo%fcqgam(ifc, 0)-cor9*(&
&           t2-t1)*geo%fcqgam(ifc, 1)*(geo%fchc(ifc, 1)+geo%fchc(ifc, 2)&
&           )/geo%fcht(ifc)*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)+pl%na(&
&           icv2, is))
          srw%sna0(icv1, 1, is) = -(vbig*geo%fcs(ifc))
          sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
          sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
        END DO
      CASE (3) 
!
! -- BCCON=3 -- SHEATH CONDITIONS
!
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,a,a,a,i3)') &
&                                   'BCCON =  3 : sheath density bc on '&
&                                     , bcchar(ib), boundary_location(ib&
&                                     ), ' for species ', is
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%sna0(icv1, 0, is) = ubig*geo%fcs(ifc)*pl%na(icv2, is)
          srw%sna0(icv1, 1, is) = -(ubig*geo%fcs(ifc))
          sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
          sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
        END DO
      CASE (4) 
!
! -- BCCON=4 -- PRESCRIBE THE VALUE OF THE DENSITY, WEAKLY
!                 A MIXED BOUNDARY CONDITION
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          IF (conpar(is, ib, 1) .EQ. 0.0_R8) THEN
            conpar(is, ib, 1) = switch%b2mndr_na_min
            WRITE(*, *) 'Zero density B.C. no longer allowed!'
            WRITE(*, *) 'Changed to na_min.'
          END IF
          WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)') &
&         'BCCON =  4 : weak density ', conpar(is, ib, 1), ' on ', &
&         bcchar(ib), boundary_location(ib), ' for species ', is
          CALL XERTST(conpar(is, ib, 1) .GT. 0.0_R8, &
&               'BCCON = 4, CONPAR(,,1) !> 0')
          CALL XERTST(conpar(is, ib, 2) .GT. 0.0_R8, &
&               'BCCON = 4, CONPAR(,,2) !> 0')
          icv = mpg%bccv(mpg%bccvp(ib, 1), 1)
          IF (mpg%cvonclosedsurface(icv) .AND. ishigh) CALL XERTST(&
&                                                            switch%&
&                                                          ionising_core&
&                                                            .EQ. 0, &
&               'ionising_core switch usage inconsistent with BCCON = 4'&
&                                                           )
        END IF
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%sna0(icv1, 0, is) = conpar(is, ib, 2)*geo%fcs(ifc)*conpar(&
&           is, ib, 1)
          srw%sna0(icv1, 1, is) = -(conpar(is, ib, 2)*geo%fcs(ifc))
          sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
          sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
        END DO
      CASE (5) 
!
! -- BCCON=5 -- PRESCRIBE THE PARTICLE FLUX PER UNIT AREA
!
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)'&
&                                    ) &
&                                 'BCCON =  5 : particle flux per area '&
&                                     , conpar(is, ib, 1), ' on ', &
&                                     bcchar(ib), boundary_location(ib)&
&                                     , ' for species ', is
!wdk      Possible backwards-compatibility issue:
!wdk      In the unstructured solver, we impose flux per unit area normal
!wdk      to the surface/boundary.
!wdk      In the original code, the flux per unit area in the poloidal
!wdk      direction was imposed at E/W boundaries (and normal to the
!wdk      radial direction at N/S - unchanged for aligned grids)
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%sna0(icv1, 0, is) = conpar(is, ib, 1)*geo%fcs(ifc)
          srw%sna0(icv1, 1, is) = 0.0_R8
          sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
          sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
          IF (switch%mdf_fnb .NE. 0) THEN
!wdk Added correction to make mdf_fnb options equivalent
            t0 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%fnapsch(ifc, 0, &
&             is)+dv%fnapsch(ifc, 1, is)+(geo%fcs(ifc)*geo%fcqalf(ifc, 0&
&             )*dv%vadia(ifc, 0, is)+geo%fcs(ifc)*geo%fcqalf(ifc, 1)*dv%&
&             vadia(ifc, 1, is))*0.5_R8*(pl%na(icv1, is)+pl%na(icv2, is)&
&             ))
            IF (0.0_R8 .LT. t0) THEN
              max1 = t0
            ELSE
              max1 = 0.0_R8
            END IF
            srw%sna0(icv1, 0, is) = srw%sna0(icv1, 0, is) + max1
            IF (0.0_R8 .GT. t0) THEN
              min1 = t0
            ELSE
              min1 = 0.0_R8
            END IF
            srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) + min1/pl%na(&
&             icv1, is)
          END IF
        END DO
      CASE (6) 
!
! -- BCCON=6 -- PRESCRIBE THE TOTAL PARTICLE FLUX FOR A
!                 CONSTANT DENSITY
!
        CALL XERRAB('b2stbc_phys -- BCCON = 6 not adapted for WG')
!
! -- BCCON=7 -- PRESCRIBE THE GIVEN PROFILE OF DENSITY
!
      CASE (7) 
        IF (ncall_b2stbc_phys .EQ. 0) THEN
!srv 26.02.18 {
          WRITE(*, '(4a,i3)') 'BCCON = 7 : specified density on ', &
&         bcchar(ib), boundary_location(ib), ' for species ', is
        END IF
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%sna0(icv1, 0, is) = vbig*geo%fcs(ifc)*bv_na(icv1, is)
          srw%sna0(icv1, 1, is) = -(vbig*geo%fcs(ifc))
          sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
          sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
        END DO
      CASE (8) 
!
! -- BCCON=8 -- PRESCRIBE THE TOTAL PARTICLE FLUX WITH
!                 CONSTANT FLUX DENSITY
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          IF (is .EQ. ismain .AND. bcchar(ib) .EQ. 'S' .AND. switch%&
&             use_astra .NE. 0) THEN
            CALL XERRAB(&
&                 'Compile with -DASTRA option to couple to ASTRA!')
!
          END IF
          WRITE(*, '(a,1p,g14.7,a4,a1,a,a13,i3)') &
&         'BCCON =  8 : total particle flux ', conpar(is, ib, 1), ' on '&
&         , bcchar(ib), boundary_location(ib), ' for species ', is
        END IF
!wdk      Note: take full area for face, whether "poloidal" or "radial" or mixed
!wdk      Backwards compatibility issue for E/W and 5-pt stencil?
!wdk      Total flux will be fine, possibly distributed somewhat differently...
        us = 0.0_R8
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          us = us + geo%fcs(ifc)
        END DO
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%sna0(icv1, 0, is) = srw%sna0(icv1, 0, is) + conpar(is, ib&
&           , 1)/us*geo%fcs(ifc)
          srw%sna0(icv1, 1, is) = 0.0_R8
          sna0_no_mdf(icv1, 0, is) = sna0_no_mdf(icv1, 0, is) + srw%sna0&
&           (icv1, 0, is)
          sna0_no_mdf(icv1, 1, is) = sna0_no_mdf(icv1, 1, is) + srw%sna0&
&           (icv1, 1, is)
          IF (switch%mdf_fnb .NE. 0) THEN
!wdk Correction now involves vadia instead of ExB velocity
!wdk This makes implementation equivalent to mdf_fnb = 0 option
            t0 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%fnapsch(ifc, 0, &
&             is)+dv%fnapsch(ifc, 1, is)+(geo%fcs(ifc)*geo%fcqalf(ifc, 0&
&             )*dv%vadia(ifc, 0, is)+geo%fcs(ifc)*geo%fcqalf(ifc, 1)*dv%&
&             vadia(ifc, 1, is))*0.5_R8*(pl%na(icv1, is)+pl%na(icv2, is)&
&             ))
            IF (0.0_R8 .LT. t0) THEN
              max2 = t0
            ELSE
              max2 = 0.0_R8
            END IF
            srw%sna0(icv1, 0, is) = srw%sna0(icv1, 0, is) + max2
            IF (0.0_R8 .GT. t0) THEN
              min2 = t0
            ELSE
              min2 = 0.0_R8
            END IF
            srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) + min2/pl%na(&
&             icv1, is)
          END IF
        END DO
      CASE (9) 
!
! -- BCCON=9 -- PRESCRIBE THE DECAY LENGTH FOR THE DENSITY
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)') &
&         'BCCON =  9 : density decay length ', conpar(is, ib, 1), &
&         ' on ', bcchar(ib), boundary_location(ib), ' for species ', is
          CALL XERTST(conpar(is, ib, 1) .NE. 0.0_R8, &
&               'B2STBC -- BCCON=9, CONPAR(,,1) = 0')
          icv = mpg%bccv(mpg%bccvp(ib, 1), 1)
          IF (mpg%cvonclosedsurface(icv) .AND. ishigh) CALL XERTST(&
&                                                            switch%&
&                                                          ionising_core&
&                                                            .EQ. 0, &
&               'ionising_core switch usage inconsistent with BCCON = 9'&
&                                                           )
        END IF
!
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          sy = geo%fcs(ifc)
!
          srw%sna0(icv1, 0, is) = 0.0_R8
          srw%sna0(icv1, 1, is) = -((co%dna0(icv1, is)+co%dpa0(icv1, is)&
&           *(rt%rza(icv1, is)*pl%te(icv1)+pl%ti(icv1)))/conpar(is, ib, &
&           1)*sy)
          sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
          sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
          IF (switch%mdf_fnb .EQ. 1) THEN
            t0 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%fnapsch(ifc, 0, &
&             is)+dv%fnapsch(ifc, 1, is))
            IF (t0 .GE. 0.0_R8) THEN
              srw%sna0(icv1, 0, is) = srw%sna0(icv1, 0, is) + t0
            ELSE
              srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) + t0/pl%na(&
&               icv1, is)
            END IF
            t1 = -(mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(geo%fcs(ifc)*geo%&
&             fcqalf(ifc, 0)*dv%vaecrb(ifc, 0, is)+geo%fcs(ifc)*geo%&
&             fcqalf(ifc, 1)*dv%vaecrb(ifc, 1, is))*0.5_R8*(pl%na(icv1, &
&             is)+pl%na(icv2, is)))
            IF (t1 .GE. 0.0_R8) THEN
              srw%sna0(icv1, 0, is) = srw%sna0(icv1, 0, is) + t1
            ELSE
              srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) + t1/pl%na(&
&               icv1, is)
            END IF
          END IF
        END DO
      CASE (10) 
!
! -- BCCON=10 -- leakage option for density, recommended for cases with drifts
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)') 'BCCON = 10 : leakage ', &
&         conpar(is, ib, 1), ' on ', bcchar(ib), boundary_location(ib), &
&         ' for species ', is
          icv = mpg%bccv(mpg%bccvp(ib, 1), 1)
          IF (mpg%cvonclosedsurface(icv) .AND. ishigh) CALL XERTST(&
&                                                            switch%&
&                                                          ionising_core&
&                                                            .EQ. 0, &
&              'ionising_core switch usage inconsistent with BCCON = 10'&
&                                                           )
!lkw 30.06.2022
          CALL XERTST(conpar(is, ib, 2) .GE. 0.0_R8, &
&               'For BCCON = 10, CONPAR(,,2) should not be negative')
        END IF
!wdk      Note: now total face area taken. Need to check backwards
!wdk      compatibility for E/W boundaries
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the plasma cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%sna0(icv1, 0, is) = 0.0_R8
          srw%sna0(icv1, 1, is) = geo%fcs(ifc)*SQRT((rt%rza(icv1, is)*pl&
&           %te(icv1)+pl%ti(icv1))/(am(is)*mp))*conpar(is, ib, 1)
          sna0_no_mdf(icv1, :, is) = sna0_no_mdf(icv1, :, is) + srw%sna0&
&           (icv1, :, is)
          IF (switch%mdf_fnb .EQ. 0) THEN
            y1 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(geo%fcs(ifc)*geo%&
&             fcqalf(ifc, 0)*(dv%vadia(ifc, 0, is)+dv%vaecrb(ifc, 0, is)&
&             )+geo%fcs(ifc)*geo%fcqalf(ifc, 1)*(dv%vadia(ifc, 1, is)+dv&
&             %vaecrb(ifc, 1, is)))*0.5_R8*(pl%na(icv1, is)+pl%na(icv2, &
&             is))/pl%na(icv1, is)
            IF (0.0_R8 .LT. y1) THEN
              max3 = y1
            ELSE
              max3 = 0.0_R8
            END IF
            srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) - max3
          ELSE
            y2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(geo%fcs(ifc)*geo%&
&             fcqalf(ifc, 0)*dv%vaecrb(ifc, 0, is)+geo%fcs(ifc)*geo%&
&             fcqalf(ifc, 1)*dv%vaecrb(ifc, 1, is))*0.5_R8*(pl%na(icv1, &
&             is)+pl%na(icv2, is))/pl%na(icv1, is)
            IF (0.0_R8 .LT. y2) THEN
              max4 = y2
            ELSE
              max4 = 0.0_R8
            END IF
            srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) - max4
            t0 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%fnapsch(ifc, 0, &
&             is)+dv%fnapsch(ifc, 1, is))
            IF (t0 .GE. 0.0_R8) THEN
              srw%sna0(icv1, 0, is) = srw%sna0(icv1, 0, is) + t0
            ELSE
              srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) + t0/pl%na(&
&               icv1, is)
            END IF
!lkw 30.06.2022{
            t0 = geo%fcs(ifc)*SQRT((rt%rza(icv1, is)*pl%te(icv1)+pl%ti(&
&             icv1))/(am(is)*mp))*conpar(is, ib, 2)
            srw%sna0(icv1, 0, is) = srw%sna0(icv1, 0, is) + t0*pl%na(&
&             icv1, is)
!lkw 30.06.2022}
            srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) - t0
          END IF
        END DO
      CASE (11) 
!
! -- BCCON=11 -- particle flux feedback boundary condition
!
        CALL XERRAB('b2stbc_phys -- BCCON = 11 not adapted for WG')
!
! -- BCCON=12 -- particle density feedback boundary condition
!
      CASE (12) 
        CALL XERRAB('b2stbc_phys -- BCCON = 12 not adapted for WG')
!
! -- BCCON=13 -- Feedback constant density for a given particle flux
!
      CASE (13) 
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,a,a,a,i3,a,1p,2g14.7)') &
&         'BCCON = 13 : particle density to achieve '//&
&         'specified total flux on ', bcchar(ib), boundary_location(ib)&
&         , ' for species ', is, ' with parameters ', conpar(is, ib, 1)&
&         , conpar(is, ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1), 1)
          IF (switch%ionising_core .GT. 0) WRITE(*, *) &
&               'imposed flux adapted due to ionising_core switch usage'
        END IF
!       ..compute average density on boundary
        t0 = 0.0_R8
        t1 = 0.0_R8
!wdk Note on backwards compatibility: feedback now always on
!wdk flux through the boundary itself (no offset)
        totflux = 0.0_R8
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          t0 = t0 + geo%fcs(ifc)
          t1 = t1 + geo%fcs(ifc)*pl%na(icv1, is)
          IF (bccon_flux_fb_style .EQ. 0) THEN
            totflux = totflux - mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%&
&             fna(ifc, 0, is)+dv%fna(ifc, 1, is))
          ELSE
            totflux = totflux - mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%&
&             fna_eir(ifc, 0, is)+dv%fna_eir(ifc, 1, is))
          END IF
        END DO
        t1 = t1/t0
!nh conpar(is,ib,3) contains the contribution from the ionized neutrals
!   (ionising_core option)
        totpar = conpar(is, ib, 1) + conpar(is, ib, 3)
        IF (conpar(is, ib, 2) .GT. 0.0_R8) t3 = conpar(is, ib, 2)
        IF (conpar(is, ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref
        IF (totflux .GE. 0.) THEN
          x1 = totflux
        ELSE
          x1 = -totflux
        END IF
        IF (totpar .GE. 0.) THEN
          y3 = totpar
        ELSE
          y3 = -totpar
        END IF
        IF (x1 .LT. y3) THEN
          IF (y3 .LT. 1.0e10_R8) THEN
            max5 = 1.0e10_R8
          ELSE
            max5 = y3
          END IF
        ELSE IF (x1 .LT. 1.0e10_R8) THEN
          max5 = 1.0e10_R8
        ELSE
          max5 = x1
        END IF
        t2 = (1.0_R8-t3*(totflux-totpar)/max5)*t1
        IF (switch%b2stbc_diagno .GE. 2) WRITE(*, &
&                                        '(a,i3,1p,4(1x,e15.6))') &
&             'bccon=13: is, curr_flux, desired_flux, old/new density, '&
&                                        , is, totflux, totpar, t1, t2
!       ..impose density
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%sna0(icv1, 0, is) = vbig*geo%fcs(ifc)*t2
          srw%sna0(icv1, 1, is) = -(vbig*geo%fcs(ifc))
          sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
          sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
        END DO
      CASE (14) 
!
! -- BCCON=14 -- Sound speed flux
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          IF (mompar(is, ib, 2) .LT. 0.5_R8) THEN
            WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)') &
&           'BCCON = 14 : sound speed flux ', mompar(is, ib, 1), ' on '&
&           , bcchar(ib), boundary_location(ib), ' for species ', is
          ELSE
            WRITE(*, '(a,a,1p,g14.7,a,a,a,a,i3)') &
&           'BCCON = 14 with MOMPAR(:,:,2) > 0.5 : non-marginal ', &
&           'sheath BC, with MOMPAR(:,:,1) = ', mompar(is, ib, 1), &
&           ' on boundary ', bcchar(ib), boundary_location(ib), &
&           ' for species ', is
          END IF
          CALL XERTST(conpar(is, ib, 2) .GE. 0.0_R8, &
&               'BCCON = 14, CONPAR(,,2) < 0 not allowed!')
        END IF
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          IF (geo%fcpbs(ifc) .GE. 0.) THEN
            s1 = geo%fcpbs(ifc)
          ELSE
            s1 = -geo%fcpbs(ifc)
          END IF
!srv 15.02.26
          CALL CSBC_IS(icv1, ib, is, cs)
!srv 15.02.26
          CALL VBC_IS(ib, is, ibc, icv1, icv2, ifc, csbc(icv1, is), wrk)
          IF (wrk .GE. 0.) THEN
            abs0 = wrk
          ELSE
            abs0 = -wrk
          END IF
          IF (abs0 .LT. geo%qalfmin) THEN
            srw%sna0(icv1, 0, is) = 0.0_R8
            srw%sna0(icv1, 1, is) = -(geo%fcs(ifc)*mompar(is, ib, 1)*cs*&
&             geo%qalfmax)
            sna0_no_mdf(icv1, :, is) = sna0_no_mdf(icv1, :, is) + srw%&
&             sna0(icv1, :, is)
            IF (switch%mdf_fnb .EQ. 0) THEN
              y4 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(geo%fcs(ifc)*geo%&
&               fcqalf(ifc, 0)*dv%vaecrb(ifc, 0, is)+geo%fcs(ifc)*geo%&
&               fcqalf(ifc, 1)*dv%vaecrb(ifc, 1, is))*0.5_R8*(pl%na(icv1&
&               , is)+pl%na(icv2, is))/pl%na(icv1, is)
              IF (0.0_R8 .LT. y4) THEN
                max6 = y4
              ELSE
                max6 = 0.0_R8
              END IF
              srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) - max6
            ELSE
              y5 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(geo%fcs(ifc)*geo%&
&               fcqalf(ifc, 0)*(dv%vaecrb(ifc, 0, is)+dv%vadia(ifc, 0, &
&               is))+geo%fcs(ifc)*geo%fcqalf(ifc, 1)*(dv%vaecrb(ifc, 1, &
&               is)+dv%vadia(ifc, 1, is)))*0.5_R8*(pl%na(icv1, is)+pl%na&
&               (icv2, is))/pl%na(icv1, is)
              IF (0.0_R8 .LT. y5) THEN
                max7 = y5
              ELSE
                max7 = 0.0_R8
              END IF
              srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) - max7
              t0 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%fnapsch(ifc, 0&
&               , is)+dv%fnapsch(ifc, 1, is))
              IF (t0 .GE. 0.0_R8) THEN
                srw%sna0(icv1, 0, is) = srw%sna0(icv1, 0, is) + t0
              ELSE
                srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) + t0/pl%na&
&                 (icv1, is)
              END IF
            END IF
          ELSE
            vbnd = (dv%vaecrb(ifc, 0, is)*geo%fcqalf(ifc, 0)+dv%vaecrb(&
&             ifc, 1, is)*geo%fcqalf(ifc, 1))*mpg%bcfcor(mpg%bccvp(ib, 1&
&             )+ibc-1)
            srw%sna0(icv1, 0, is) = 0.0_R8
            IF (wrk .GE. 0.) THEN
              abs6 = wrk
            ELSE
              abs6 = -wrk
            END IF
            x2 = csbc(icv1, is)*abs6
            y6 = vbc(icv1, is)*SIGN(1.0_R8, wrk) + vbnd
            IF (x2 .LT. y6) THEN
              max8 = y6
            ELSE
              max8 = x2
            END IF
            srw%sna0(icv1, 1, is) = -(geo%fcs(ifc)*mompar(is, ib, 1)*&
&             max8)
            IF (conpar(is, ib, 2) .GT. 0.0_R8) srw%sna0(icv1, 1, is) = &
&               srw%sna0(icv1, 1, is) - co%dna0(icv1, is)/conpar(is, ib&
&               , 2)*geo%fcs(ifc)
            sna0_no_mdf(icv1, :, is) = srw%sna0(icv1, :, is)
            IF (switch%mdf_fnb .NE. 0) THEN
              t0 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%fnapsch(ifc, 0&
&               , is)+dv%fnapsch(ifc, 1, is)+(geo%fcs(ifc)*geo%fcqalf(&
&               ifc, 0)*dv%vadia(ifc, 0, is)+geo%fcs(ifc)*geo%fcqalf(ifc&
&               , 1)*dv%vadia(ifc, 1, is))*0.5_R8*(pl%na(icv1, is)+pl%na&
&               (icv2, is)))
              IF (0.0_R8 .LT. t0) THEN
                max9 = t0
              ELSE
                max9 = 0.0_R8
              END IF
              srw%sna0(icv1, 0, is) = srw%sna0(icv1, 0, is) + max9
              IF (0.0_R8 .GT. t0) THEN
                min3 = t0
              ELSE
                min3 = 0.0_R8
              END IF
              srw%sna0(icv1, 1, is) = srw%sna0(icv1, 1, is) + min3/pl%na&
&               (icv1, is)
            END IF
          END IF
        END DO
      CASE (15) 
!
! -- BCCON=15 -- prescribe a radial leakage velocity, as a multiplier to the local thermal velocity
!
!srv 25.09.09 16.02.12
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(2a,1p,g14.7,a,a,a,a,i3)') &
&         'BCCON = 15 : prescribe the decay length for the density', &
&         ' for drifs switched on ', conpar(is, ib, 1), ' on ', bcchar(&
&         ib), boundary_location(ib), ' for species ', is
          icv = mpg%bccv(mpg%bccvp(ib, 1), 1)
          IF (mpg%cvonclosedsurface(icv) .AND. ishigh) CALL XERTST(&
&                                                            switch%&
&                                                          ionising_core&
&                                                            .EQ. 0, &
&              'ionising_core switch usage inconsistent with BCCON = 15'&
&                                                           )
        END IF
!wdk      Notes:
!wdk       * need correction for misaligned grids -> t1
!wdk       * need to correct this BC for hybrid scheme
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          csb = SQRT((rt%rza(icv1, is)*pl%te(icv1)+pl%ti(icv1))/(am(is)*&
&           mp))
          t0 = geo%fcqalf(ifc, 1)
          t1 = (geo%fchc(ifc, 1)+geo%fchc(ifc, 2))/geo%fcht(ifc)*geo%&
&           fcqbet(ifc, 0)
          srw%sna0(icv1, 0, is) = vbig*co%cdna(ifc, 1, is)*(t0*pl%na(&
&           icv2, is)-mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*t1*(pl%na(mpg%&
&           fcvx(ifc, 2), is)-pl%na(mpg%fcvx(ifc, 1), is)))
          srw%sna0(icv1, 1, is) = -(vbig*(co%cdna(ifc, 1, is)*t0-conpar(&
&           is, ib, 1)*geo%fcs(ifc)*csb))
          sna0_no_mdf(icv1, :, is) = srw%sna0(icv1, :, is)
!srv 25.09.09 }
        END DO
      CASE (16) 
!
! -- BCCON=16 -- Feedback boundary condition: given total particle flux with constant density  !srv 16.02.12 {
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,a,i3)') &
&         'BCCON = 16 : given total particle flux with constant', &
&         ' density for ion is =', is
!           write all boundaries with this type of boundary condition
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bccon(is, ibw) .EQ. bccon(is, ib)) THEN
              WRITE(*, '(a,a,a,a,i3)') ' on ', bcchar(ibw), &
&             boundary_location(ibw), ' for species ', is
              icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
              CALL XERTST(mpg%cvonclosedsurface(icv), &
&                   'BCCON = 16 only applicable to core boundaries !')
            END IF
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (&
&               (((((bccon(is, ibw) .EQ. 19 .OR. bccon(is, ibw) .EQ. 21)&
&               .OR. bccon(is, ibw) .EQ. 22) .OR. bccon(is, ibw) .EQ. 23&
&               ) .OR. bccon(is, ibw) .EQ. 25) .OR. bccon(is, ibw) .EQ. &
&               26) .OR. bccon(is, ibw) .EQ. 27)) THEN
! IYS 22.01.2016 added BCCON = 25,26 and 27
              CALL XERRAB(&
&       'BCCON types 16, 19, 21, 22, 23, 25, 26 and 27 cannot be mixed!'&
&                  )
            END IF
          END DO
          IF (ishigh) CALL XERTST(switch%ionising_core .EQ. 0, &
&              'ionising_core switch usage inconsistent with BCCON = 16'&
&                          )
        END IF
!srv 16.02.12 }
        IF (.NOT.once_bccon(is)) THEN
          IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
            IF (switch%use_astra .NE. 0) THEN
              CALL XERRAB(&
&                   'Compile with -DASTRA option to couple to ASTRA!')
            ELSE
              sconpar(is) = 0.0_R8
              DO ibw=ib,nbc
                IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') &
&                   .AND. bccon(is, ibw) .EQ. bccon(is, ib)) sconpar(is)&
&                  = sconpar(is) + conpar(is, ibw, 1)
              END DO
            END IF
            WRITE(*, *) 'BCCON=16: Summed value is ', sconpar(is)
            nas = 0.0_R8
            vs = 0.0_R8
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  nas = nas + pl%na(icv, is)*geo%cvvol(icv)
                  vs = vs + geo%cvvol(icv)
                END DO
              END IF
            END DO
            nas = nas/vs
            totflux = 0.0_R8
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                IF (switch%mdf_fnb .NE. 0) THEN
                  DO ibc=1,mpg%bccvp(ibw, 2)
                    icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                    ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                    totflux = totflux - mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc&
&                     -1)*(dv%fna_mdf(ifc, 0, is)+dv%fna_mdf(ifc, 1, is)&
&                     )
                  END DO
                ELSE
                  DO ibc=1,mpg%bccvp(ibw, 2)
                    icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                    ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                    totflux = totflux - mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc&
&                     -1)*(dv%fna(ifc, 0, is)+dv%fna(ifc, 1, is))
                  END DO
                END IF
              END IF
            END DO
            IF (conpar(is, ib, 2) .GT. 0.0_R8) t3 = conpar(is, ib, 2)
            IF (conpar(is, ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref
            IF (totflux .GE. 0.) THEN
              x3 = totflux
            ELSE
              x3 = -totflux
            END IF
            IF (sconpar(is) .GE. 0.) THEN
              y7 = sconpar(is)
            ELSE
              y7 = -sconpar(is)
            END IF
            IF (x3 .LT. y7) THEN
              max10 = y7
            ELSE
              max10 = x3
            END IF
            IF (max10 .GT. 0.0_R8) THEN
              IF (totflux .GE. 0.) THEN
                x4 = totflux
              ELSE
                x4 = -totflux
              END IF
              IF (sconpar(is) .GE. 0.) THEN
                y8 = sconpar(is)
              ELSE
                y8 = -sconpar(is)
              END IF
              IF (x4 .LT. y8) THEN
                max11 = y8
              ELSE
                max11 = x4
              END IF
              nas = nas*(1.0_R8-t3*(totflux-sconpar(is))/max11)
            END IF
            WRITE(*, '(a,es14.7,a,es14.7,a,es14.7,a,i3)') ' NAS=', nas, &
&           ' totflux=', totflux, ' SCONPAR=', sconpar(is), ' IS=', is
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                  srw%sna0(icv, 0, is) = vbig*nas*geo%fcs(ifc)
                  srw%sna0(icv, 1, is) = -(vbig*geo%fcs(ifc))
                  sna0_no_mdf(icv, 0, is) = srw%sna0(icv, 0, is)
                  sna0_no_mdf(icv, 1, is) = srw%sna0(icv, 1, is)
                END DO
              END IF
            END DO
            once_bccon(is) = .true.
          ELSE
!srv 16.02.12 }
            CALL XERRAB('B2STBC -- BCCON=16, NOT AVAILABLE FOR N,W,E')
          END IF
        END IF
      CASE (17) 
!
! -- BCCON=17 -- FILLER
!
        CALL XERRAB('B2STBC -- BCCON=17, NOT YET AVAILABLE')
!
! -- BCCON=18 -- FILLER
!
      CASE (18) 
        CALL XERRAB('B2STBC -- BCCON=18, NOT YET AVAILABLE')
!
! -- BCCON=19 -- Feedback boundary condition: given sum of integrated neutrals and
!                main ion particle fluxes with constant ion density.
!
      CASE (19) 
        IF (switch%spatial_hybrid .NE. 0) CALL XERRAB(&
&                          'BCCON = 19 not compatible with spatial hybr'&
&                                              )
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, *) 'BCCON = 19 : given sum of particle flux '//&
&         'for isonuclear sequence with constant '//&
&         'highest ionisation stage density '
!             write all boundaries with this type of boundary condition
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bccon(is, ibw) .EQ. bccon(is, ib)) THEN
              WRITE(*, '(a,a,a,a,i3)') ' on ', bcchar(ibw), &
&             boundary_location(ibw), ' for species ', is
              icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
              CALL XERTST(mpg%cvonclosedsurface(icv), &
&                   'BCCON = 19 only applicable to core boundaries !')
            END IF
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (&
&               (((((bccon(is, ibw) .EQ. 16 .OR. bccon(is, ibw) .EQ. 21)&
&               .OR. bccon(is, ibw) .EQ. 22) .OR. bccon(is, ibw) .EQ. 23&
&               ) .OR. bccon(is, ibw) .EQ. 25) .OR. bccon(is, ibw) .EQ. &
&               26) .OR. bccon(is, ibw) .EQ. 27)) THEN
! IYS 22.01.2016 added BCCON = 25,26 and 27
              CALL XERRAB('BCCON types 16, 19, 21, 22, 23, 25, '//&
&                   '26 and 27 cannot be mixed!')
            END IF
          END DO
          IF (is .LT. ns - 1) THEN
            result10 = LNEXT(is, is + 1)
            CALL XERTST(.NOT.result10, &
&                 'BCCON = 19 can only be applied to ions in their '//&
&                 'highest ionisation stage')
          END IF
          IF (ishigh) CALL XERTST(switch%ionising_core .EQ. 0, &
&              'ionising_core switch usage inconsistent with BCCON = 19'&
&                          )
        END IF
!srv 16.02.12 }
        IF (.NOT.once_bccon(is)) THEN
          IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
            IF (switch%use_astra .NE. 0) THEN
              CALL XERRAB(&
&                   'Compile with -DASTRA option to couple to ASTRA!')
            ELSE
              sconpar(is) = 0.0_R8
              DO ibw=ib,nbc
                IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') &
&                   .AND. bccon(is, ibw) .EQ. bccon(is, ib)) sconpar(is)&
&                  = sconpar(is) + conpar(is, ibw, 1)
              END DO
            END IF
            WRITE(*, *) 'BCCON=19: Summed value is ', sconpar(is)
            nas = 0.0_R8
            vs = 0.0_R8
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  nas = nas + pl%na(icv, is)*geo%cvvol(icv)
                  vs = vs + geo%cvvol(icv)
                END DO
              END IF
            END DO
            nas = nas/vs
            totfluxn = 0.0_R8
            totfluxi = 0.0_R8
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
! totfluxn here means the sum of fluxes over all ions (including fluid
! neutrals) of this isotope except for the highest ionisation stage.
! For coupled runs, both fna and fna_mdf are rescaled for neutrals
! Note that for neutrals fna = fna_mdf
                  DO isb=0,ns-1
                    IF (b2espcr(is) .EQ. b2espcr(isb) .AND. is .NE. isb&
&                   ) THEN
                      IF ((.NOT.is_neutral(isb)) .OR. switch%use_eirene &
&                         .EQ. 0) THEN
                        IF (switch%mdf_fnb .NE. 0) THEN
                          totfluxn = totfluxn - mpg%bcfcor(mpg%bccvp(ibw&
&                           , 1)+ibc-1)*(dv%fna_mdf(ifc, 0, is)+dv%&
&                           fna_mdf(ifc, 1, is))
                        ELSE
                          totfluxn = totfluxn - mpg%bcfcor(mpg%bccvp(ibw&
&                           , 1)+ibc-1)*(dv%fna(ifc, 0, is)+dv%fna(ifc, &
&                           1, is))
                        END IF
                      END IF
                    END IF
                  END DO
! totfluxi here means the flux of the ion in the highest ionisation stage.
                  IF (switch%mdf_fnb .NE. 0) THEN
                    totfluxi = totfluxi - mpg%bcfcor(mpg%bccvp(ibw, 1)+&
&                     ibc-1)*(dv%fna_mdf(ifc, 0, is)+dv%fna_mdf(ifc, 1, &
&                     is))
                  ELSE
                    totfluxi = totfluxi - mpg%bcfcor(mpg%bccvp(ibw, 1)+&
&                     ibc-1)*(dv%fna(ifc, 0, is)+dv%fna(ifc, 1, is))
                  END IF
                END DO
              END IF
            END DO
            IF (conpar(is, ib, 2) .GT. 0.0_R8) t3 = conpar(is, ib, 2)
            IF (conpar(is, ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref
            IF (totfluxn + totfluxi .GE. 0.) THEN
              x5 = totfluxn + totfluxi
            ELSE
              x5 = -(totfluxn+totfluxi)
            END IF
            IF (sconpar(is) .GE. 0.) THEN
              y9 = sconpar(is)
            ELSE
              y9 = -sconpar(is)
            END IF
            IF (x5 .LT. y9) THEN
              max12 = y9
            ELSE
              max12 = x5
            END IF
            IF (max12 .GT. 0.0_R8) THEN
              IF (totfluxn + totfluxi .GE. 0.) THEN
                x6 = totfluxn + totfluxi
              ELSE
                x6 = -(totfluxn+totfluxi)
              END IF
              IF (x6 .LT. sconpar(is)) THEN
                max13 = sconpar(is)
              ELSE
                max13 = x6
              END IF
              nas = nas*(1.0_R8-t3*(totfluxn+totfluxi-sconpar(is))/max13&
&               )
            END IF
            WRITE(*, '(a,es14.7,a,es14.7,a,es14.7,a,es14.7,a,es14.7)') &
&           ' NAS=', nas, ' totfluxn=', totfluxn, ' totfluxi=', totfluxi&
&           , ' SCONPAR=', sconpar(is), ' totfluxn+totfluxi=', totfluxn &
&           + totfluxi
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                  srw%sna0(icv, 0, is) = vbig*nas*geo%fcs(ifc)
                  srw%sna0(icv, 1, is) = -(vbig*geo%fcs(ifc))
                  sna0_no_mdf(icv, 0, is) = srw%sna0(icv, 0, is)
                  sna0_no_mdf(icv, 1, is) = srw%sna0(icv, 1, is)
                END DO
              END IF
            END DO
            once_bccon(is) = .true.
          ELSE
!srv 16.02.12 }
            CALL XERRAB('B2STBC -- BCCON=19, NOT AVAILABLE FOR N,W,E')
          END IF
        END IF
      CASE (20) 
!
! -- BCCON=20 -- constant density feedback condition
!
        CALL XERRAB('b2stbc_phys -- BCCON = 20 not adapted for WG')
!
!    -- BCCON=21 -- PRESCRIBE THE VALUE OF THE DENSITY !lk and IYS 01.03.2013
!                   AND ADD A POLOIDAL DENSITY VARIATION TO GET A SOLUTION
!                   WHICH IS AS CLOSE AS POSSIBLE TO NEOCLASSICAL THEORY
!                   DERIVED FOR PURE H/D/T PLASMA ONLY.
!
! IT IS RECOMMENDED TO USE THIS BOUNDARY CONDITION TOGETHER WITH
! CORRESPONDING CONDITION ON ION TEMPERATURE (BCENI=23,24)
!
      CASE (21) 
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,1p,g14.7)') 'BCCON = 21 : constant density', &
&         conpar(is, ib, 1)
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bccon(is, ibw) .EQ. bccon(is, ib)) THEN
              WRITE(*, '(a,a,a,a,i3)') ' on ', bcchar(ibw), &
&             boundary_location(ibw), ' for species ', is
              icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
              CALL XERTST(mpg%cvonclosedsurface(icv), &
&                   'BCCON = 21 only applicable to core boundaries !')
              CALL XERTST(conpar(is, ib, 1) .GT. 0.0_R8, &
&                   'BCCON = 21, CONPAR(,,1) !> 0')
! IYS 22.01.2015
              CALL XERTST(conpar(is, ib, 1) .EQ. conpar(is, ibw, 1), &
&                   'BCCON = 21, Average density on all parts '//&
&                   'of the surface should be the same')
              IF (bceni(ibw) .NE. 23 .AND. bceni(ibw) .NE. 24) THEN
                WRITE(0, *) 'Should use BCCON(IS,IB).EQ.21 '//&
&               'together with BCENI=23 or 24'
                WRITE(*, *) 'Should use BCCON(IS,IB).EQ.21 '//&
&               'together with BCENI=23 or 24'
!srv 21.09.12
                WRITE(*, '(a)') &
&               'Please ensure that this boundary condition '//&
&               'is consistent with the '//&
&               'ion energy boundary condition'
              END IF
            END IF
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (&
&               (((((bccon(is, ibw) .EQ. 16 .OR. bccon(is, ibw) .EQ. 19)&
&               .OR. bccon(is, ibw) .EQ. 22) .OR. bccon(is, ibw) .EQ. 23&
&               ) .OR. bccon(is, ibw) .EQ. 25) .OR. bccon(is, ibw) .EQ. &
&               26) .OR. bccon(is, ibw) .EQ. 27)) THEN
! IYS 22.01.2016 added BCCON = 25,26 and 27
              CALL XERRAB('BCCON types 16, 19, 21, 22, 23, 25, '//&
&                   '26 and 27 cannot be mixed!')
            END IF
          END DO
          CALL XERTST(is .EQ. ismain, &
&               'BCCON = 21 is applied for main ion only ')
          IF (.NOT.(ns .EQ. 1 .OR. (ns .EQ. 2 .AND. is_neutral(0)))) &
&         THEN
            WRITE(0, *) &
&           'Use of BCCON=21 only meant for single-fluid runs!'
            WRITE(0, *) 'Use BCCON=25 instead!'
            WRITE(6, *) &
&           'Use of BCCON=21 only meant for single-fluid runs!'
            WRITE(6, *) 'Use BCCON=25 instead!'
          END IF
          IF (ishigh) CALL XERTST(switch%ionising_core .EQ. 0, &
&              'ionising_core switch usage inconsistent with BCCON = 21'&
&                          )
        END IF
!lk and IYS 01.03.2013}
        IF ((bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') .AND. mpg%&
&           cvonclosedsurface(mpg%bccv(mpg%bccvp(ibw, 1), 2))) THEN
          IF (.NOT.once_bccon(is)) THEN
            IF (is .EQ. ismain .AND. switch%use_astra .NE. 0) CALL &
&             XERRAB('Compile with -DASTRA option to couple to ASTRA!')
! Volume between two surfaces               !lk 12.12.12 {
            t0 = 0.0_R8
! Sum of volume-averaged electron and ion temperatures
            t1 = 0.0_R8
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                  t0 = t0 + geo%cvvol(icv2)
                  t1 = t1 + (pl%ti(icv1)+pl%te(icv1))*geo%cvvol(icv2)
                END DO
              END IF
            END DO
! Sum of volume-averaged electron and ion temperatures
            IF (t0 .GT. 0.0_R8) t1 = t1/t0
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                  srw%sna0(icv, 0, is) = vbig*conpar(is, ibw, 1)*t1/(pl%&
&                   ti(icv)+pl%te(icv))*geo%fcs(ifc)
                  srw%sna0(icv, 1, is) = -(vbig*geo%fcs(ifc))
                  sna0_no_mdf(icv, 0, is) = srw%sna0(icv, 0, is)
                  sna0_no_mdf(icv, 1, is) = srw%sna0(icv, 1, is)
                END DO
              END IF
            END DO
            once_bccon(is) = .true.
          END IF
        ELSE
          CALL XERRAB('B2STBC -- BCCON=21, VALID FOR CORE ONLY')
        END IF
      CASE (22) 
!
! -- BCCON=22 -- Feedback boundary condition: given total particle flux with
!    constant average density. The poloidal density variation is added to make
!    the solution as close as possible to the neoclassical value derived for
!    pure H/D/T plasma.
!    It is recommended to use this boundary condition
!    together with corresponding boundary condition on ion temperature
!    (BCENI=23,24) !srv 16.02.12, IYS 01.03.2013 {
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,a,i3)') &
&         'BCCON = 22 : given total particle flux with constant', &
&         ' density for ion is =', is
!           write all boundaries with this type of boundary condition
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bccon(is, ibw) .EQ. bccon(is, ib)) THEN
              WRITE(*, '(a,a,a,a,i3)') ' on ', bcchar(ibw), &
&             boundary_location(ibw), ' for species ', is
              icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
              CALL XERTST(mpg%cvonclosedsurface(icv), &
&                   'BCCON = 22 only applicable to core boundaries !')
              IF (bceni(ibw) .NE. 23 .AND. bceni(ibw) .NE. 24) THEN
                WRITE(0, *) 'Should use BCCON(IS,IB).EQ.22 '//&
&               'together with BCENI=23 or 24'
                WRITE(*, *) 'Should use BCCON(IS,IB).EQ.22 '//&
&               'together with BCENI=23 or 24'
!srv 21.09.12
                WRITE(*, '(a)') &
&               'Please ensure that this boundary condition '//&
&               'is consistent with the '//&
&               'ion energy boundary condition'
              END IF
            END IF
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (&
&               (((((bccon(is, ibw) .EQ. 16 .OR. bccon(is, ibw) .EQ. 19)&
&               .OR. bccon(is, ibw) .EQ. 21) .OR. bccon(is, ibw) .EQ. 23&
&               ) .OR. bccon(is, ibw) .EQ. 25) .OR. bccon(is, ibw) .EQ. &
&               26) .OR. bccon(is, ibw) .EQ. 27)) THEN
! IYS 22.01.2016 added BCCON = 25,26 and 27
              CALL XERRAB('BCCON types 16, 19, 21, 22, 23, 25, '//&
&                   '26 and 27 cannot be mixed!')
            END IF
          END DO
          CALL XERTST(is .EQ. ismain, &
&               'BCCON = 22 is applied for main ion only ')
          IF (.NOT.(ns .EQ. 1 .OR. (ns .EQ. 2 .AND. is_neutral(0)))) &
&         THEN
            WRITE(0, *) &
&           'Use of BCCON=22 only meant for single-fluid runs!'
            WRITE(0, *) 'Use BCCON=26 instead!'
            WRITE(6, *) &
&           'Use of BCCON=22 only meant for single-fluid runs!'
            WRITE(6, *) 'Use BCCON=26 instead!'
          END IF
          IF (ishigh) CALL XERTST(switch%ionising_core .EQ. 0, &
&              'ionising_core switch usage inconsistent with BCCON = 22'&
&                          )
        END IF
!iys 01.03.13 }
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
!srv 16.02.12 }
          IF (.NOT.once_bccon(is)) THEN
            IF (switch%use_astra .NE. 0) THEN
              CALL XERRAB(&
&                   'Compile with -DASTRA option to couple to ASTRA!')
            ELSE
              sconpar(is) = 0.0_R8
              DO ibw=ib,nbc
                IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') &
&                   .AND. bccon(is, ibw) .EQ. bccon(is, ib)) sconpar(is)&
&                  = sconpar(is) + conpar(is, ibw, 1)
              END DO
            END IF
            WRITE(*, *) 'BCCON=22: Summed value is ', sconpar(is)
            totflux = 0.0_R8
! Volume between two surfaces             !lk 12.12.12 {
            t0 = 0.0_R8
! Sum of volume-averaged electron and ion temperatures
            t1 = 0.0_R8
            nas = 0.0_R8
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                  ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                  t0 = t0 + geo%cvvol(icv2)
                  t1 = t1 + (pl%ti(icv1)+pl%te(icv1))*geo%cvvol(icv2)
                  nas = nas + pl%na(icv1, is)*geo%cvvol(icv2)
                  IF (switch%mdf_fnb .NE. 0) THEN
                    totflux = totflux - mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc&
&                     -1)*(dv%fna_mdf(ifc, 0, is)+dv%fna_mdf(ifc, 1, is)&
&                     )
                  ELSE
                    totflux = totflux - mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc&
&                     -1)*(dv%fna(ifc, 0, is)+dv%fna(ifc, 1, is))
                  END IF
                END DO
              END IF
            END DO
! Sum of volume-averaged electron and ion temperatures
            t1 = t1/t0
! Volume-averaged density
            nas = nas/t0
            IF (conpar(is, ib, 2) .GT. 0.0_R8) t3 = conpar(is, ib, 2)
            IF (conpar(is, ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref
            IF (totflux .GE. 0.) THEN
              x7 = totflux
            ELSE
              x7 = -totflux
            END IF
            IF (sconpar(is) .GE. 0.) THEN
              y10 = sconpar(is)
            ELSE
              y10 = -sconpar(is)
            END IF
            IF (x7 .LT. y10) THEN
              max14 = y10
            ELSE
              max14 = x7
            END IF
            IF (max14 .GT. 0.0_R8) THEN
              IF (totflux .GE. 0.) THEN
                x8 = totflux
              ELSE
                x8 = -totflux
              END IF
              IF (sconpar(is) .GE. 0.) THEN
                y11 = sconpar(is)
              ELSE
                y11 = -sconpar(is)
              END IF
              IF (x8 .LT. y11) THEN
                max15 = y11
              ELSE
                max15 = x8
              END IF
              nas = nas*(1.0_R8-t3*(totflux-sconpar(is))/max15)
            END IF
            WRITE(*, '(a,es14.7,a,es14.7,a,es14.7,a,i3)') ' NAS=', nas, &
&           ' totflux=', totflux, ' SCONPAR=', sconpar(is), ' IS=', is
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                  srw%sna0(icv, 0, is) = vbig*nas*t1*geo%fcs(ifc)/(pl%ti&
&                   (icv)+pl%te(icv))
                  srw%sna0(icv, 1, is) = -(vbig*geo%fcs(ifc))
                  sna0_no_mdf(icv, 0, is) = srw%sna0(icv, 0, is)
                  sna0_no_mdf(icv, 1, is) = srw%sna0(icv, 1, is)
                END DO
              END IF
            END DO
            once_bccon(is) = .true.
          END IF
        ELSE
!srv 16.02.12 }
          CALL XERRAB('B2STBC -- BCCON=22 IS AVAILABLE FOR CORE ONLY')
        END IF
      CASE (23) 
!
! -- BCCON=23 -- Feedback boundary condition: given sum of integrated neutrals and
!    main ion particle fluxes with constant average density.
!    The poloidal density variation is added to make the solution
!    as close as possible to the neoclassical value derived for pure H/D/T plasma.
!    It is recommended to use this boundary condition with corresponding
!    boundary condition on ion temperature (BCENI=23,24) !srv 16.02.12, IYS 04.03.2013 {
!    Use this boundary condition for pure H/D/T plasma only,
!    If a minor impurity is present, please use the BCCON=27 instead. ! IYS 21.01.2016
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,a,i3)') &
&         'BCCON = 23 : given total particle flux with constant', &
&         ' density for main ion is =', ismain
!          write all boundaries with this type of boundary condition
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bccon(is, ibw) .EQ. bccon(is, ib)) THEN
              WRITE(*, '(a,a,a,a,i3)') ' on ', bcchar(ibw), &
&             boundary_location(ibw), ' for species ', is
              icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
              CALL XERTST(mpg%cvonclosedsurface(icv), &
&                   'BCCON = 23 only applicable to core boundaries !')
              CALL XERTST(conpar(is, ibw, 1) .GE. 0.0_R8, &
&                   'BCCON = 23, CONPAR(,,1) < 0')
              IF (bceni(ibw) .NE. 23 .AND. bceni(ibw) .NE. 24) THEN
                WRITE(0, *) 'Should use BCCON(IS,IB).EQ.23 '//&
&               'together with BCENI=23 or 24'
                WRITE(*, *) 'Should use BCCON(IS,IB).EQ.23 '//&
&               'together with BCENI=23 or 24'
!srv 21.09.12
                WRITE(*, '(a)') &
&               'Please ensure that this boundary condition '//&
&               'is consistent with the '//&
&               'ion energy boundary condition'
              END IF
            END IF
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (&
&               (((((bccon(is, ibw) .EQ. 16 .OR. bccon(is, ibw) .EQ. 19)&
&               .OR. bccon(is, ibw) .EQ. 21) .OR. bccon(is, ibw) .EQ. 22&
&               ) .OR. bccon(is, ibw) .EQ. 25) .OR. bccon(is, ibw) .EQ. &
&               26) .OR. bccon(is, ibw) .EQ. 27)) THEN
! IYS 22.01.2016 added BCCON = 25,26 and 27
              CALL XERRAB('BCCON types 16, 19, 21, 22, 23, 25, '//&
&                   '26 and 27 cannot be mixed!')
            END IF
          END DO
          IF (.NOT.(ns .EQ. 1 .OR. (ns .EQ. 2 .AND. is_neutral(0)))) &
&         THEN
            WRITE(0, *) &
&           'Use of BCCON=23 only meant for single-fluid runs!'
            WRITE(0, *) 'Use BCCON=27 instead!'
            WRITE(6, *) &
&           'Use of BCCON=23 only meant for single-fluid runs!'
            WRITE(0, *) 'Use BCCON=27 instead!'
          END IF
          CALL XERTST(is .EQ. ismain, &
&               'BCCON = 23 is applied for main ion only ')
          IF (ishigh) CALL XERTST(switch%ionising_core .EQ. 0, &
&              'ionising_core switch usage inconsistent with BCCON = 23'&
&                          )
        END IF
!IYS 04.03.2013 }
!
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
!srv 16.02.12 }
          IF (.NOT.once_bccon(is)) THEN
            IF (switch%use_astra .NE. 0) THEN
              CALL XERRAB(&
&                   'Compile with -DASTRA option to couple to ASTRA!')
            ELSE
              sconpar(is) = 0.0_R8
              DO ibw=ib,nbc
                IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') &
&                   .AND. bccon(is, ibw) .EQ. bccon(is, ib)) sconpar(is)&
&                  = sconpar(is) + conpar(is, ibw, 1)
              END DO
            END IF
            WRITE(*, *) 'BCCON=23: Summed value is ', sconpar(is)
            totfluxn = 0.0_R8
            totfluxi = 0.0_R8
! Volume between two surfaces               !lk 12.12.12 {
            t0 = 0.0_R8
! Sum of volume-averaged electron and ion temperatures
            t1 = 0.0_R8
            nas = 0.0_R8
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                  ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                  isb = ismain0
                  IF (is_neutral(isb)) totfluxn = totfluxn - mpg%bcfcor(&
&                     mpg%bccvp(ibw, 1)+ibc-1)*(dv%fna(ifc, 0, isb)+dv%&
&                     fna(ifc, 1, isb))
                  isb = ismain
                  IF (switch%mdf_fnb .NE. 0) THEN
                    totfluxi = totfluxi - mpg%bcfcor(mpg%bccvp(ibw, 1)+&
&                     ibc-1)*(dv%fna_mdf(ifc, 0, isb)+dv%fna_mdf(ifc, 1&
&                     , isb))
                  ELSE
                    totfluxi = totfluxi - mpg%bcfcor(mpg%bccvp(ibw, 1)+&
&                     ibc-1)*(dv%fna(ifc, 0, isb)+dv%fna(ifc, 1, isb))
                  END IF
                  t0 = t0 + geo%cvvol(icv2)
                  t1 = t1 + (pl%ti(icv1)+pl%te(icv1))*geo%cvvol(icv2)
                  nas = nas + pl%na(icv1, is)*geo%cvvol(icv2)
                END DO
              END IF
            END DO
! Sum of volume-averaged electron and ion temperatures
            t1 = t1/t0
! Volume-averaged density
            nas = nas/t0
            IF (conpar(is, ib, 2) .GT. 0.0_R8) t3 = conpar(is, ib, 2)
            IF (conpar(is, ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref
            IF (totfluxn .GE. 0.) THEN
              abs1 = totfluxn
            ELSE
              abs1 = -totfluxn
            END IF
            IF (totfluxi .GE. 0.) THEN
              abs7 = totfluxi
            ELSE
              abs7 = -totfluxi
            END IF
            IF (sconpar(is) .GE. 0.) THEN
              abs11 = sconpar(is)
            ELSE
              abs11 = -sconpar(is)
            END IF
            IF (abs1 + abs7 + abs11 .GT. 0.0_R8) THEN
              IF (totfluxn .GE. 0.) THEN
                abs2 = totfluxn
              ELSE
                abs2 = -totfluxn
              END IF
              IF (totfluxi .GE. 0.) THEN
                abs8 = totfluxi
              ELSE
                abs8 = -totfluxi
              END IF
              IF (sconpar(is) .GE. 0.) THEN
                abs12 = sconpar(is)
              ELSE
                abs12 = -sconpar(is)
              END IF
              nas = nas*(1.0_R8-t3*(totfluxn+totfluxi-sconpar(is))/(abs2&
&               +abs8+abs12))
            END IF
            WRITE(*, '(5(a,es14.7))') ' NAS=', nas, ' totfluxn=', &
&           totfluxn, ' totfluxi=', totfluxi, ' SCONPAR=', sconpar(is), &
&           ' totfluxn+totfluxi=', totfluxn + totfluxi
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                  srw%sna0(icv, 0, is) = vbig*nas*t1/(pl%ti(icv)+pl%te(&
&                   icv))*geo%fcs(ifc)
                  srw%sna0(icv, 1, is) = -(vbig*geo%fcs(ifc))
                  sna0_no_mdf(icv, 0, is) = srw%sna0(icv, 0, is)
                  sna0_no_mdf(icv, 1, is) = srw%sna0(icv, 1, is)
                END DO
              END IF
            END DO
            once_bccon(is) = .true.
          END IF
        ELSE
!srv 16.02.12 }
          CALL XERRAB('B2STBC -- BCCON=23 IS AVAILABLE FOR CORE ONLY')
        END IF
      CASE (24) 
!
! -- BCCON=24 -- constant density scaled by density on the ring bc_type21_ref away
!
        CALL XERRAB('b2stbc_phys -- BCCON = 24 not adapted for WG')
!
! -- BCCON=25  Feedback boundary condition: PRESCRIBE THE AVERAGE VALUE OF THE DENSITY  !lk and IYS 01.03.2013{
!              AND ADD A POLOIDAL DENSITY VARIATION FROM NEIGHBOURING RADIAL CELL.
!              THIS BOUNDARY CONDITION IS SUITABLE FOR ANY SPECIES OF
!              MULTI-SPECIES PLASMA (I.E. IN THE CASE WHEN THE CONDITION USED
!              IN BCCON=21 FAILS)
!              IT IS RECOMMENDED TO USE THIS BOUNDARY CONDITION TOGETHER WITH
!              CORRESPONDING CONDITION ON ION TEMPERATURE (BCENI=26,27)
!
      CASE (25) 
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,1p,g14.7)') &
&         'BCCON = 25 : constant average density', conpar(is, ib, 1)
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bccon(is, ibw) .EQ. bccon(is, ib)) THEN
              WRITE(*, '(a,a,a,a,i3)') ' on ', bcchar(ibw), &
&             boundary_location(ibw), ' for species ', is
              icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
              CALL XERTST(mpg%cvonclosedsurface(icv), &
&                   'BCCON = 25 only applicable to core boundaries !')
              CALL XERTST(conpar(is, ibw, 1) .GT. 0.0_R8, &
&                   'BCCON = 25, CONPAR(,,1) !> 0')
! IYS 22.01.2015
              CALL XERTST(conpar(is, ib, 1) .EQ. conpar(is, ibw, 1), &
&                   'BCCON = 25, Average density on all parts '//&
&                   'of the surface should be the same')
              IF (bceni(ibw) .NE. 26 .AND. bceni(ibw) .NE. 27) THEN
                WRITE(0, *) 'Should use BCCON(IS,IB).EQ.25 '//&
&               'together with BCENI=26 or 27'
                WRITE(*, *) 'Should use BCCON(IS,IB).EQ.25 '//&
&               'together with BCENI=26 or 27'
!srv 21.09.12
                WRITE(*, '(a)') &
&               'Please ensure that this boundary condition '//&
&               'is consistent with the '//&
&               'ion energy boundary condition'
              END IF
            END IF
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (&
&               (((((bccon(is, ibw) .EQ. 16 .OR. bccon(is, ibw) .EQ. 19)&
&               .OR. bccon(is, ibw) .EQ. 21) .OR. bccon(is, ibw) .EQ. 22&
&               ) .OR. bccon(is, ibw) .EQ. 23) .OR. bccon(is, ibw) .EQ. &
&               26) .OR. bccon(is, ibw) .EQ. 27)) THEN
! IYS 22.01.2016 added BCCON = 25,26 and 27
              CALL XERRAB('BCCON types 16, 19, 21, 22, 23, 25, '//&
&                   '26 and 27 cannot be mixed!')
            END IF
          END DO
          IF (ishigh) CALL XERTST(switch%ionising_core .EQ. 0, &
&              'ionising_core switch usage inconsistent with BCCON = 25'&
&                          )
        END IF
!lk and IYS 01.03.2013}
!
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
          IF (.NOT.once_bccon(is)) THEN
            IF (is .EQ. ismain .AND. switch%use_astra .NE. 0) CALL &
&             XERRAB('Compile with -DASTRA option to couple to ASTRA!')
! Volume between two surfaces              !lk 12.12.12 {
            t0 = 0.0_R8
! Sum of volume-averaged density
            t1 = 0.0_R8
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                  t0 = t0 + geo%cvvol(icv)
                  t1 = t1 + pl%na(icv, is)*geo%cvvol(icv)
                END DO
              END IF
            END DO
            t1 = t1/t0
            DO ibw=ib,nbc
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                srw%sna0(icv1, 0, is) = vbig*geo%fcs(ifc)*(conpar(is, &
&                 ibw, 1)+pl%na(icv2, is)-t1)
                srw%sna0(icv1, 1, is) = -(vbig*geo%fcs(ifc))
                sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
                sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
              END DO
            END DO
            once_bccon(is) = .true.
          END IF
        ELSE
          CALL XERRAB('B2STBC -- BCCON=25, VALID FOR CORE ONLY')
        END IF
      CASE (26) 
!
! -- BCCON=26  Feedback boundary condition: PRESCRIBE THE TOTAL ION FLUX AND
!              FIND THE AVERAGE DENSITY.  !lk and IYS 01.03.2013
!              THE POLOIDAL DENSITY VARIATION FROM THE NEIGHBOURING RADIAL
!              RING IS APPLIED ON TOP OF THE AVERAGE DENSITY.
!              THIS BOUNDARY CONDITION IS SUITABLE FOR ANY SPECIES OF
!              MULTI-SPECIES PLASMA (I.E. IN THE CASE WHEN THE CONDITION USED
!              IN BCCON=22 FAILS)
!              IT IS RECOMMENDED TO USE THIS BOUNDARY CONDITION TOGETHER WITH
!              A CORRESPONDING CONDITION ON THE ION TEMPERATURE (BCENI=26,27)
!
! ncall_b2stbc_phys == 0
        IF (ncall_b2stbc_phys .EQ. 0) THEN
!IYS 21.01.2016
!IYS 21.01.2016
!IYS 21.01.2016
          WRITE(*, '(a,a,i3)') &
&         'BCCON = 26 : given total particle flux with ', &
&         'constant average density for ion is =', is
!           write all boundaries with this type of boundary condition
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bccon(is, ibw) .EQ. bccon(is, ib)) THEN
              WRITE(*, '(a,a,a,a,i3)') ' on ', bcchar(ibw), &
&             boundary_location(ibw), ' for species ', is
              icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
              CALL XERTST(mpg%cvonclosedsurface(icv), &
&                   'BCCON = 26 only applicable to core boundaries !')
              IF (bceni(ibw) .NE. 26 .AND. bceni(ibw) .NE. 27) THEN
                WRITE(0, *) 'Should use BCCON(IS,IB).EQ.26 '//&
&               'together with BCENI=26 or 27'
                WRITE(*, *) 'Should use BCCON(IS,IB).EQ.26 '//&
&               'together with BCENI=26 or 27'
!srv 21.09.12
                WRITE(*, '(a)') &
&               'Please ensure that this boundary condition '//&
&               'is consistent with the '//&
&               'ion energy boundary condition'
              END IF
            END IF
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (&
&               (((((bccon(is, ibw) .EQ. 16 .OR. bccon(is, ibw) .EQ. 19)&
&               .OR. bccon(is, ibw) .EQ. 21) .OR. bccon(is, ibw) .EQ. 22&
&               ) .OR. bccon(is, ibw) .EQ. 23) .OR. bccon(is, ibw) .EQ. &
&               25) .OR. bccon(is, ibw) .EQ. 27)) THEN
! IYS 22.01.2016 added BCCON = 25,26 and 27
              CALL XERRAB('BCCON types 16, 19, 21, 22, 23, 25, '//&
&                   '26 and 27 cannot be mixed!')
            END IF
          END DO
          IF (ishigh) CALL XERTST(switch%ionising_core .EQ. 0, &
&              'ionising_core switch usage inconsistent with BCCON = 26'&
&                          )
        END IF
!IYS 01.03.2013 }
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
!srv 16.02.12 }
          IF (.NOT.once_bccon(is)) THEN
            IF (switch%use_astra .NE. 0) THEN
              CALL XERRAB(&
&                   'Compile with -DASTRA option to couple to ASTRA!')
            ELSE
              sconpar(is) = 0.0_R8
              DO ibw=ib,nbc
                IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') &
&                   .AND. bccon(is, ibw) .EQ. bccon(is, ib)) sconpar(is)&
&                  = sconpar(is) + conpar(is, ibw, 1)
              END DO
            END IF
            WRITE(*, *) 'BCCON=26: Summed value is ', sconpar(is)
            totflux = 0.0_R8
! Volume between two surfaces               !lk 12.12.12 {
            t0 = 0.0_R8
! Volume-averaged density on previous surface
            t1 = 0.0_R8
            nas = 0.0_R8
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                  ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                  t0 = t0 + geo%cvvol(icv2)
                  t1 = t1 + pl%na(icv2, is)*geo%cvvol(icv2)
                  nas = nas + pl%na(icv1, is)*geo%cvvol(icv2)
                  IF (switch%mdf_fnb .NE. 0) THEN
                    totflux = totflux - mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc&
&                     -1)*(dv%fna_mdf(ifc, 0, is)+dv%fna_mdf(ifc, 1, is)&
&                     )
                  ELSE
                    totflux = totflux - mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc&
&                     -1)*(dv%fna(ifc, 0, is)+dv%fna(ifc, 1, is))
                  END IF
                END DO
              END IF
            END DO
! Sum of volume-averaged electron and ion temperatures
            t1 = t1/t0
! Volume-averaged density
            nas = nas/t0
            IF (conpar(is, ib, 2) .GT. 0.0_R8) t3 = conpar(is, ib, 2)
            IF (conpar(is, ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref
            IF (totflux .GE. 0.) THEN
              x9 = totflux
            ELSE
              x9 = -totflux
            END IF
            IF (sconpar(is) .GE. 0.) THEN
              y12 = sconpar(is)
            ELSE
              y12 = -sconpar(is)
            END IF
            IF (x9 .LT. y12) THEN
              max16 = y12
            ELSE
              max16 = x9
            END IF
            IF (max16 .GT. 0.0_R8) THEN
              IF (totflux .GE. 0.) THEN
                x10 = totflux
              ELSE
                x10 = -totflux
              END IF
              IF (sconpar(is) .GE. 0.) THEN
                y13 = sconpar(is)
              ELSE
                y13 = -sconpar(is)
              END IF
              IF (x10 .LT. y13) THEN
                max17 = y13
              ELSE
                max17 = x10
              END IF
              nas = nas*(1.0_R8-t3*(totflux-sconpar(is))/max17)
            END IF
            WRITE(*, '(a,es14.7,a,es14.7,a,es14.7,a,i3)') ' NAS=', nas, &
&           ' totflux=', totflux, ' SCONPAR=', sconpar(is), ' IS=', is
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                  ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                  srw%sna0(icv1, 0, is) = vbig*(nas+pl%na(icv2, is)-t1)*&
&                   geo%fcs(ifc)
                  srw%sna0(icv1, 1, is) = -(vbig*geo%fcs(ifc))
                  sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
                  sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
                END DO
              END IF
            END DO
            once_bccon(is) = .true.
          END IF
        ELSE
!srv 16.02.12 }
          CALL XERRAB('B2STBC -- BCCON=26 IS AVAILABLE FOR CORE ONLY')
        END IF
      CASE (27) 
!
! -- BCCON=27  Feedback boundary condition: prescribe the particle flux sum
!              for all neutrals and ions belonging to a given isonuclear sequence
!              and find the average density of the highest ionisation state.
!              THE POLOIDAL DENSITY VARIATION FROM THE NEIGHBOURING RADIAL
!              CELL IS ADDED TO THE AVERAGE DENSITY.
!              IT IS RECOMMENDED TO USE THIS BOUNDARY CONDITION TOGETHER WITH
!              A CORRESPONDING CONDITION ON THE ION TEMPERATURE (BCENI=26,27)
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,a,i3)') &
&         'BCCON = 27 : given total particle flux with constant', &
&         ' density for highest ionisation stage ion is =', is
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bccon(is, ibw) .EQ. bccon(is, ib)) THEN
              WRITE(*, '(a,a,a,a,i3)') ' on ', bcchar(ibw), &
&             boundary_location(ibw), ' for species ', is
              icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
              CALL XERTST(mpg%cvonclosedsurface(icv), &
&                   'BCCON = 27 only applicable to core boundaries !')
              CALL XERTST(conpar(is, ibw, 1) .GE. 0.0_R8, &
&                   'BCCON = 27, CONPAR(,,1) < 0')
              IF (bceni(ibw) .NE. 26 .AND. bceni(ibw) .NE. 27) THEN
                WRITE(0, *) 'Should use BCCON(IS,IB).EQ.27 '//&
&               'together with BCENI=26 or 27'
                WRITE(*, *) 'Should use BCCON(IS,IB).EQ.27 '//&
&               'together with BCENI=26 or 27'
!srv 21.09.12
                WRITE(*, '(a)') &
&               'Please ensure that this boundary condition '//&
&               'is consistent with the '//&
&               'ion energy boundary condition'
              END IF
            END IF
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (&
&               (((((bccon(is, ibw) .EQ. 16 .OR. bccon(is, ibw) .EQ. 19)&
&               .OR. bccon(is, ibw) .EQ. 21) .OR. bccon(is, ibw) .EQ. 22&
&               ) .OR. bccon(is, ibw) .EQ. 23) .OR. bccon(is, ibw) .EQ. &
&               25) .OR. bccon(is, ibw) .EQ. 26)) THEN
!IYS 22.01.2016 added BCCON = 25,26 and 27
              CALL XERRAB('BCCON types 16, 19, 21, 22, 23, 25, '//&
&                   '26 and 27 cannot be mixed!')
            END IF
          END DO
        END IF
!IYS 04.03.2013 }
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
!srv 16.02.12 }
          IF (.NOT.once_bccon(is)) THEN
            IF (switch%use_astra .NE. 0) THEN
              CALL XERRAB(&
&                   'Compile with -DASTRA option to couple to ASTRA!')
            ELSE
              sconpar(is) = 0.0_R8
              DO ibw=ib,nbc
                IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') &
&                   .AND. bccon(is, ibw) .EQ. bccon(is, ib)) sconpar(is)&
&                  = sconpar(is) + conpar(is, ibw, 1)
              END DO
            END IF
            WRITE(*, *) 'BCCON=27: Summed value is ', sconpar(is)
            totfluxn = 0.0_R8
            totfluxi = 0.0_R8
! Volume between two surfaces              !lk 12.12.12 {
            t0 = 0.0_R8
! Volume-averaged on neighbouring surface
            t1 = 0.0_R8
            nas = 0.0_R8
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                  ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
! totfluxn here means the sum of fluxes over all ions (including fluid
! neutrals) of this isotope except for the highest ionisation stage.
! For coupled runs, both fna and fna_mdf are rescaled for neutrals
! Note that for neutrals fna = fna_mdf
                  DO isb=0,ns-1
                    IF (b2espcr(is) .EQ. b2espcr(isb) .AND. is .NE. isb&
&                   ) THEN
                      IF ((.NOT.is_neutral(isb)) .OR. switch%use_eirene &
&                         .EQ. 0) THEN
                        IF (switch%mdf_fnb .NE. 0) THEN
                          totfluxn = totfluxn - mpg%bcfcor(mpg%bccvp(ibw&
&                           , 1)+ibc-1)*(dv%fna_mdf(ifc, 0, isb)+dv%&
&                           fna_mdf(ifc, 1, isb))
                        ELSE
                          totfluxn = totfluxn - mpg%bcfcor(mpg%bccvp(ibw&
&                           , 1)+ibc-1)*(dv%fna(ifc, 0, isb)+dv%fna(ifc&
&                           , 1, isb))
                        END IF
                      END IF
                    END IF
                  END DO
! totfluxi here means the flux of the ion in the highest ionisation stage.
                  IF (switch%mdf_fnb .NE. 0) THEN
                    totfluxi = totfluxi - mpg%bcfcor(mpg%bccvp(ibw, 1)+&
&                     ibc-1)*(dv%fna_mdf(ifc, 0, is)+dv%fna_mdf(ifc, 1, &
&                     is))
                  ELSE
                    totfluxi = totfluxi - mpg%bcfcor(mpg%bccvp(ibw, 1)+&
&                     ibc-1)*(dv%fna(ifc, 0, is)+dv%fna(ifc, 1, is))
                  END IF
                  t0 = t0 + geo%cvvol(icv2)
                  t1 = t1 + pl%na(icv2, is)*geo%cvvol(icv2)
                  nas = nas + pl%na(icv1, is)*geo%cvvol(icv2)
                END DO
              END IF
            END DO
!
            t1 = t1/t0
! Volume-averaged density
            nas = nas/t0
            IF (conpar(is, ib, 2) .GT. 0.0_R8) t3 = conpar(is, ib, 2)
            IF (conpar(is, ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref
            IF (totfluxn .GE. 0.) THEN
              abs3 = totfluxn
            ELSE
              abs3 = -totfluxn
            END IF
            IF (totfluxi .GE. 0.) THEN
              abs9 = totfluxi
            ELSE
              abs9 = -totfluxi
            END IF
            IF (sconpar(is) .GE. 0.) THEN
              abs13 = sconpar(is)
            ELSE
              abs13 = -sconpar(is)
            END IF
            IF (abs3 + abs9 + abs13 .GT. 0.0_R8) THEN
              IF (totfluxn .GE. 0.) THEN
                abs4 = totfluxn
              ELSE
                abs4 = -totfluxn
              END IF
              IF (totfluxi .GE. 0.) THEN
                abs10 = totfluxi
              ELSE
                abs10 = -totfluxi
              END IF
              IF (sconpar(is) .GE. 0.) THEN
                abs14 = sconpar(is)
              ELSE
                abs14 = -sconpar(is)
              END IF
              nas = nas*(1.0_R8-t3*(totfluxn+totfluxi-sconpar(is))/(abs4&
&               +abs10+abs14))
            END IF
            WRITE(*, '(5(a,es14.7))') ' NAS=', nas, ' totfluxn=', &
&           totfluxn, ' totfluxi=', totfluxi, ' SCONPAR=', sconpar(is), &
&           ' totfluxn+totfluxi=', totfluxn + totfluxi
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bccon(is, ibw) .EQ. bccon(is, ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                  ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                  srw%sna0(icv1, 0, is) = vbig*(nas+pl%na(icv2, is)-t1)*&
&                   geo%fcs(ifc)
                  srw%sna0(icv1, 1, is) = -(vbig*geo%fcs(ifc))
                  sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
                  sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
                END DO
              END IF
            END DO
            once_bccon(is) = .true.
          END IF
        ELSE
!srv 16.02.12 }
          CALL XERRAB('B2STBC -- BCCON=27 IS AVAILABLE FOR CORE ONLY')
        END IF
      CASE (28) 
!
! -- BCCON=28  Prescribe the flux surface averaged density, with poloidal
!              perturbation taken from flux tube just inside domain
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          DO ibc=1,mpg%bccvp(ib, 2)
            icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
            CALL XERTST(mpg%cvonclosedsurface(icv), &
&                 'BCCON=28 intended for core boundaries only!')
          END DO
          IF (is .EQ. ismain .AND. switch%use_astra .NE. 0) THEN
!srv 28.07.11
            conpar(is, ib, 1) = neb_astra
          END IF
          IF (conpar(is, ib, 1) .EQ. 0.0_R8) THEN
            conpar(is, ib, 1) = switch%b2mndr_na_min
            WRITE(*, *) 'Zero density B.C. no longer allowed!'
            WRITE(*, *) 'Changed to na_min.'
          END IF
          WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)') &
&         'constant density + perturbation', conpar(is, ib, 1), ' on ', &
&         bcchar(ib), boundary_location(ib), ' for species ', is
          CALL XERTST(conpar(is, ib, 1) .GT. 0.0_R8, &
&               'BCCON = 28, conpar(,,1) !> 0')
        END IF
!       ..compute average density on core boundary
        t0 = 0.0_R8
        t1 = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
        DO ib0=1,nbc
          icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
          IF (mpg%cvonclosedsurface(icv1)) THEN
! loop over number of cells in the boundary
            DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
              icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
              icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
              ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
              t0 = t0 + geo%cvvol(icv2)
              t1 = t1 + geo%cvvol(icv2)*pl%na(icv2, is)
            END DO
          END IF
        END DO
        t1 = t1/t0
!       ..impose density with perturbation
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%sna0(icv1, 0, is) = vbig*geo%fcs(ifc)*(pl%na(icv2, is)+&
&           conpar(is, ib, 1)-t1)
          srw%sna0(icv1, 1, is) = -(vbig*geo%fcs(ifc))
          sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
          sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
        END DO
      CASE (29) 
!
! -- BCCON=29  Feedback on the total particle flux, by imposing a flux surface
!              averaged density, with poloidal perturbation taken from flux
!              tube just inside domain
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          DO ibc=1,mpg%bccvp(ib, 2)
            icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
            CALL XERTST(mpg%cvonclosedsurface(icv), &
&                 'BCCON=29 intended for core boundaries only!')
          END DO
        END IF
!       ..compute average density on core boundary
        t0 = 0.0_R8
        t1 = 0.0_R8
        t2 = 0.0_R8
        totflux = 0.0_R8
        totpar = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
        DO ib0=1,nbc
          icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
          IF (mpg%cvonclosedsurface(icv1)) THEN
            IF (bccon(is, ib0) .NE. 29) CALL XERRAB(&
&                                      'BCCON=29: incompatible core BCs'&
&                                            )
! loop over number of cells in the boundary
            DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
              icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
              icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
              ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
              t0 = t0 + geo%cvvol(icv2)
              t1 = t1 + geo%cvvol(icv2)*pl%na(icv1, is)
              t2 = t2 + geo%cvvol(icv2)*pl%na(icv2, is)
              IF (bccon_flux_fb_style .EQ. 0) THEN
                totflux = totflux - mpg%bcfcor(mpg%bccvp(ib0, 1)+ibc0-1)&
&                 *(dv%fna(ifc, 0, is)+dv%fna(ifc, 1, is))
              ELSE
                totflux = totflux - mpg%bcfcor(mpg%bccvp(ib0, 1)+ibc0-1)&
&                 *(dv%fna_eir(ifc, 0, is)+dv%fna_eir(ifc, 1, is))
              END IF
            END DO
!nh conpar(is,ib0,3) contains the contribution from the ionized neutrals
!   (ionising_core option)
            totpar = totpar + conpar(is, ib0, 1) + conpar(is, ib0, 3)
          END IF
        END DO
        t1 = t1/t0
        t2 = t2/t0
        IF (conpar(is, ib, 2) .GT. 0.0_R8) t3 = conpar(is, ib, 2)
        IF (conpar(is, ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref
        IF (totflux .GE. 0.) THEN
          x11 = totflux
        ELSE
          x11 = -totflux
        END IF
        IF (totpar .GE. 0.) THEN
          y14 = totpar
        ELSE
          y14 = -totpar
        END IF
        IF (x11 .LT. y14) THEN
          IF (y14 .LT. 1.0e10_R8) THEN
            max18 = 1.0e10_R8
          ELSE
            max18 = y14
          END IF
        ELSE IF (x11 .LT. 1.0e10_R8) THEN
          max18 = 1.0e10_R8
        ELSE
          max18 = x11
        END IF
        t4 = (1.0_R8-t3*(totflux-totpar)/max18)*t1
!       ..impose density with perturbation
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%sna0(icv1, 0, is) = vbig*geo%fcs(ifc)*(pl%na(icv2, is)+t4-&
&           t2)
          srw%sna0(icv1, 1, is) = -(vbig*geo%fcs(ifc))
          sna0_no_mdf(icv1, 0, is) = srw%sna0(icv1, 0, is)
          sna0_no_mdf(icv1, 1, is) = srw%sna0(icv1, 1, is)
        END DO
      CASE DEFAULT
!
        WRITE(*, *) bccon(is, ib)
        CALL XERRAB('BCCON out of bounds')
      END SELECT
!
! -- BOUNDARY CONDITIONS FOR PARALLEL MOMENTUM EQUATIONS --
!
      SELECT CASE  (bcmom(is, ib)) 
      CASE (0) 

      CASE (1) 
!
! -- BCMOM=1 -- PRESCRIBE THE VALUE OF THE PARALLEL VELOCITY
!
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)'&
&                                    ) &
&                            'BCMOM =  1 : specified parallel velocity '&
&                                     , mompar(is, ib, 1), ' on ', &
&                                     bcchar(ib), boundary_location(ib)&
&                                     , ' for species ', is
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%smo0(icv1, 0, is) = vbig*ne00*am(is)*mompar(is, ib, 1)*geo&
&           %fcs(ifc)*geo%fchz(ifc)
          srw%smo0(icv1, 1, is) = -(vbig*ne00*am(is)*geo%fcs(ifc)*geo%&
&           fchz(ifc))
        END DO
      CASE (2) 
!
! -- BCMOM=2 -- PRESCRIBE THE GRADIENT OF THE PARALLEL VELOCITY
!
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)'&
&                                    ) &
&                             'BCMOM =  2 : parallel velocity gradient '&
&                                     , mompar(is, ib, 1), ' on ', &
&                                     bcchar(ib), boundary_location(ib)&
&                                     , ' for species ', is
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          ivx1 = mpg%fcvx(ifc, 1)
          ivx2 = mpg%fcvx(ifc, 2)
          t1 = INTVERTEX_S_NODIFF(ivx1, ncv, nvx, mpg, geo%vxvol, pl%ua(&
&           :, is))
          t2 = INTVERTEX_S_NODIFF(ivx2, ncv, nvx, mpg, geo%vxvol, pl%ua(&
&           :, is))
          srw%smo0(icv1, 0, is) = vbig*am(is)*pl%na(icv1, is)*geo%fcs(&
&           ifc)*geo%fchz(ifc)*(mompar(is, ib, 1)*(geo%fchc(ifc, 1)+geo%&
&           fchc(ifc, 2))*geo%fcqgam(ifc, 0)-cor9*(t2-t1)*geo%fcqgam(ifc&
&           , 1)*(geo%fchc(ifc, 1)+geo%fchc(ifc, 2))/geo%fcht(ifc)*mpg%&
&           bcfcor(mpg%bccvp(ib, 1)+ibc-1)+pl%ua(icv2, is))
          srw%smo0(icv1, 1, is) = -(vbig*am(is)*pl%na(icv1, is)*geo%fcs(&
&           ifc)*geo%fchz(ifc))
        END DO
      CASE (3) 
!
! -- BCMOM=3 -- SHEATH CONDITIONS, MACH NUMBER AS INPUT
!
        CALL XERRAB('b2stbc_phys -- BCMOM = 3 not adapted for WG.'//&
&             ' Replace with drift-compatible BCMOM = 13')
! -- BCMOM=4 -- PRESCRIBE THE VALUE OF THE VELOCITY, WEAKLY
!                 A MIXED BOUNDARY CONDITION
!
      CASE (4) 
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)') &
&         'BCMOM =  4 : weak velocity ', mompar(is, ib, 1), ' on ', &
&         bcchar(ib), boundary_location(ib), ' for species ', is
          CALL XERTST(mompar(is, ib, 2) .GT. 0.0_R8, &
&               'BCMOM = 4, MOMPAR(,,2) !> 0')
        END IF
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%smo0(icv1, 0, is) = mompar(is, ib, 2)*mompar(is, ib, 1)*&
&           geo%fcs(ifc)*geo%fchz(ifc)
          srw%smo0(icv1, 1, is) = -(mompar(is, ib, 2)*geo%fcs(ifc)*geo%&
&           fchz(ifc))
        END DO
      CASE (5) 
!
! -- BCMOM=5 -- PRESCRIBE THE PARALLEL MOMENTUM FLUX PER UNIT AREA
!
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)'&
&                                    ) &
&                   'BCMOM =  5 : parallel momentum flux per unit area '&
&                                     , mompar(is, ib, 1), ' on ', &
&                                     bcchar(ib), boundary_location(ib)&
&                                     , ' for species ', is
!wdk      Possible backwards-compatibility issue:
!wdk      In the unstructured solver, we impose flux per unit area normal
!wdk      to the surface/boundary.
!wdk      In the original code, the flux per unit area in the poloidal
!wdk      direction was imposed at E/W boundaries (and normal to the
!wdk      radial direction at N/S - unchanged for aligned grids)
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%smo0(icv1, 0, is) = mompar(is, ib, 1)*geo%fcs(ifc)*geo%&
&           fchz(ifc)
          srw%smo0(icv1, 1, is) = 0.0_R8
        END DO
      CASE (6) 
!
! -- BCMOM=6 -- PRESCRIBE THE TOTAL PARALLEL MOMENTUM FLUX FOR A
!                 CONSTANT PARALLEL VELOCITY
!
        CALL XERRAB('B2STBC -- BCMOM=6, NOT YET AVAILABLE')
!
! -- BCMOM=7 -- PRESCRIBE THE GIVEN PROFILE OF VELOCITY
!
      CASE (7) 
        IF (ncall_b2stbc_phys .EQ. 0) THEN
!srv 26.02.18 {
          WRITE(*, '(4a,i3)') &
&         'BCMOM = 7 : specified parallel velocity on ', bcchar(ib), &
&         boundary_location(ib), ' for species ', is
        END IF
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%smo0(icv1, 0, is) = vbig*ne00*am(is)*bv_ua(icv1, is)*geo%&
&           fcs(ifc)*geo%fchz(ifc)
          srw%smo0(icv1, 1, is) = -(vbig*ne00*am(is)*geo%fcs(ifc)*geo%&
&           fchz(ifc))
        END DO
      CASE (8) 
!
! -- BCMOM=8 -- SPECIAL : LIMITED SHEAR
!
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,a,a,a,i3)') &
&                              'BCMOM =  8 : limited shear velocity on '&
&                                     , bcchar(ib), boundary_location(ib&
&                                     ), ' for species ', is
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          y15 = SQRT(pl%ti(icv1)/pl%ti(icv2))
          IF (1.0_R8 .GT. y15) THEN
            a = y15
          ELSE
            a = 1.0_R8
          END IF
          srw%smo0(icv1, 0, is) = vbig*geo%fcs(ifc)*geo%fchz(ifc)*am(is)&
&           *pl%na(icv1, is)*a*pl%ua(icv2, is)
          srw%smo0(icv1, 0, is) = -(vbig*geo%fcs(ifc)*geo%fchz(ifc)*am(&
&           is)*pl%na(icv1, is))
        END DO
      CASE (9) 
!
! -- BCMOM=9 -- PRESCRIBE THE TOTAL PARALLEL MOMENTUM FLUX WITH
!                 CONSTANT FLUX DENSITY
!
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)'&
&                                    ) &
&                           'BCMOM =  9 : total parallel momentum flux '&
&                                     , mompar(is, ib, 1), ' on ', &
&                                     bcchar(ib), boundary_location(ib)&
&                                     , ' for species ', is
        us = 0.0_R8
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
          us = us + geo%fcs(ifc)*geo%fchz(ifc)
        END DO
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
          srw%smo0(icv, 0, is) = mompar(is, ib, 1)/us*geo%fcs(ifc)*geo%&
&           fchz(ifc)
          srw%smo0(icv, 1, is) = 0.0_R8
        END DO
      CASE (10) 
!
! -- BCMOM=10 -- PRESCRIBE THE DECAY LENGTH FOR THE PARALLEL MOMENTUM
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)') &
&         'BCMOM = 10 : parallel momentum decay length ', mompar(is, ib&
&         , 1), ' on ', bcchar(ib), boundary_location(ib), &
&         ' for species ', is
          CALL XERTST(mompar(is, ib, 1) .NE. 0.0_R8, &
&               'BCMOM = 10, MOMPAR(,,1) = 0')
          IF (bccon(is, ib) .NE. 9) THEN
            WRITE(0, *) &
&           'Should use BCCON(IS,IB).EQ.9 together with BCMOM=10'
            WRITE(*, *) &
&           'Should use BCCON(IS,IB).EQ.9 together with BCMOM=10'
            WRITE(*, '(1x,a)') &
&           'Please ensure that this boundary condition '//&
&           'is consistent with '//'the density boundary condition'
          END IF
        END IF
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
          srw%smo0(icv, 0, is) = am(is)*mp*pl%ua(icv, is)*sna0_no_mdf(&
&           icv, 0, is)
          srw%smo0(icv, 1, is) = -(co%vsa0(icv, is)/mompar(is, ib, 1)*&
&           geo%fcs(ifc)*geo%fchz(ifc)) + am(is)*mp*sna0_no_mdf(icv, 1, &
&           is)*pl%na(icv, is)
        END DO
      CASE (11) 
!
! -- BCMOM=11 -- ROZHANSKY VISCOSITY CONDITION FOR THE PARALLEL MOMENTUM
!
        CALL XERRAB('b2stbc_phys -- BCMOM = 11 not adapted for WG')
!
! -- BCMOM=12 -- CONDITION from b2stbc_spb FOR THE PARALLEL MOMENTUM   !srv 01.02.09 {
!srv added accumulation in order to account twice b.c. for corner cells
      CASE (12) 
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, &
&                                     '(a,1p,g14.7,a,g14.7,a,a,a,a,i3)')&
&                   'BCMOM = 12 : from b2stbc_spb parallel momentum bc '&
&                                     //'with mompar1 =', mompar(is, ib&
&                                     , 1), ' and mompar2 =', mompar(is&
&                                     , ib, 2), ' on ', bcchar(ib), &
&                                     boundary_location(ib), &
&                                     ' for species ', is
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
          srw%smo0(icv, 0, is) = 0.0_R8
          srw%smo0(icv, 1, is) = 0.0_R8
          srw%smo0(icv, 2, is) = 0.0_R8
          IF (0.0_R8 .LT. mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*dv%fna_fcor&
&             (ifc, 1, is)) THEN
            max19 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*dv%fna_fcor(ifc, &
&             1, is)
          ELSE
            max19 = 0.0_R8
          END IF
          srw%smo0(icv, 3, is) = srw%smo0(icv, 3, is) + mompar(is, ib, 2&
&           )*geo%fcs(ifc)*geo%fchz(ifc) + mompar(is, ib, 1)*max19/pl%na&
&           (icv, is)
        END DO
      CASE (13) 
!
! -- BCMOM=13 -- DRIFT-COMPATIBLE SHEATH CONDITION FOR THE PARALLEL MOMENTUM
!srv added accumulation in order to account twice b.c. for corner cells
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          IF (mompar(is, ib, 2) .LT. 0.5_R8) THEN
            WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a,a,i3)') &
&           'BCMOM = 13 : from b2stbc_spb parallel momentum bc '//&
&           'with mompar1 =', mompar(is, ib, 1), ' and mompar2 =', &
&           mompar(is, ib, 2), ' on ', bcchar(ib), boundary_location(ib)&
&           , ' for species ', is
          ELSE
            WRITE(*, '(a,a,1p,g14.7,a,a,a,a,i3)') &
&           'BCMOM = 13 with MOMPAR(:,:,2) > 0.5 : non-marginal ', &
&           'sheath BC, with MOMPAR(:,:,1) = ', mompar(is, ib, 1), &
&           ' on boundary ', bcchar(ib), boundary_location(ib), &
&           ' for species ', is
          END IF
          CALL XERTST(bccon(is, ib) .EQ. 14, &
&               'BCCON = 14 must be used in conjunction '//&
&               'with BCMOM = 13!')
        END IF
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the internal cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          ivx1 = mpg%fcvx(ifc, 1)
          ivx2 = mpg%fcvx(ifc, 2)
          t1 = INTVERTEX_S_NODIFF(ivx1, ncv, nvx, mpg, geo%vxvol, pl%ua(&
&           :, is))
          t2 = INTVERTEX_S_NODIFF(ivx2, ncv, nvx, mpg, geo%vxvol, pl%ua(&
&           :, is))
          IF (geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3) .GE. &
&             0.) THEN
            wrk = geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3)
          ELSE
            wrk = -(geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3)&
&             )
          END IF
          IF (wrk .LT. geo%qalfmin) THEN
            srw%smo0(icv1, 0, is) = vbig*am(is)*pl%na(icv1, is)*geo%fcs(&
&             ifc)*geo%fchz(ifc)*(-(cor9*(t2-t1)*geo%fcqgam(ifc, 1)*(geo&
&             %fchc(ifc, 1)+geo%fchc(ifc, 2))/geo%fcht(ifc)*mpg%bcfcor(&
&             mpg%bccvp(ib, 1)+ibc-1))+pl%ua(icv2, is))
            srw%smo0(icv1, 1, is) = -(vbig*am(is)*pl%na(icv1, is)*geo%&
&             fcs(ifc)*geo%fchz(ifc))
          ELSE
!srv 15.02.26
            CALL VBC_IS(ib, is, ibc, icv1, icv2, ifc, csbc(icv1, is), &
&                 wrk)
!srv 07.05.09 {
            srw%smo0(icv1, 0, is) = srw%smo0(icv1, 0, is) + ubig/epslon&
&             **2*am(is)*mp*pl%na(icv1, is)*mompar(is, ib, 1)*vbc(icv1, &
&             is)*geo%fcs(ifc)*geo%fchz(ifc)
            IF (geo%fcpbshz(ifc) .GE. 0.) THEN
              abs5 = geo%fcpbshz(ifc)
            ELSE
              abs5 = -geo%fcpbshz(ifc)
            END IF
!srv 07.05.09 }
            srw%smo0(icv1, 1, is) = srw%smo0(icv1, 1, is) - ubig/epslon&
&             **2*am(is)*mp*pl%na(icv1, is)*abs5
          END IF
!srv 01.02.09 }

        END DO
      CASE (14) 
!
! -- BCMOM=14 -- CONDITION from b2stbc_spb FOR THE PARALLEL MOMENTUM    !srv 01.02.09 {
!srv added accumulation in order to account twice b.c. for corner cells
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, &
&                                     '(a,1p,g14.7,a,g14.7,a,a,a,a,i3)')&
&              'BCMOM = 14 : from b2stbc_spb momentum bc with mompar1 ='&
&                                     , mompar(is, ib, 1), &
&                                     ' and mompar2 =', mompar(is, ib, 2&
&                                     ), ' on ', bcchar(ib), &
&                                     boundary_location(ib), &
&                                     ' for species ', is
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
!TODO: drift contributions!
          srw%smo0(icv1, 0, is) = 0.0_R8
          srw%smo0(icv1, 1, is) = 0.0_R8
          srw%smo0(icv1, 2, is) = 0.0_R8
          IF (0.0_R8 .LT. mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*dv%fna_fcor&
&             (ifc, 1, is)) THEN
            max20 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*dv%fna_fcor(ifc, &
&             1, is)
          ELSE
            max20 = 0.0_R8
          END IF
          srw%smo0(icv1, 3, is) = srw%smo0(icv1, 3, is) + mompar(is, ib&
&           , 2)*geo%fcs(ifc)*geo%fchz(ifc) + mompar(is, ib, 1)*max20/pl&
&           %na(icv1, is)
        END DO
      CASE (15) 
!
!
! -- BCMOM=15 -- PRESCRIBE THE VALUE OF THE PARALLEL VELOCITY, SCALED WITH
!                B_average/B_local
!
        CALL XERRAB('b2stbc_phys -- BCMOM = 15 not adapted for WG')
!
! -- BCMOM=16 -- PRESCRIBE THE AVERAGE VALUE OF THE PARALLEL VELOCITY   !lk 12.12.12 {
!
      CASE (16) 
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)') &
&         'BCMOM = 16 : specified average parallel velocity ', mompar(is&
&         , ib, 1), ' on ', bcchar(ib), boundary_location(ib), &
&         ' for species ', is
          DO ibc=1,mpg%bccvp(ib, 2)
            icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
            CALL XERTST(mpg%cvonclosedsurface(icv), &
&                 'BCMOM=16 intended for core boundaries only!')
          END DO
        END IF
!       ..compute average parallel velocity on core boundary
        t0 = 0.0_R8
        t1 = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
        DO ib0=1,nbc
          icv = mpg%bccv(mpg%bccvp(ib0, 1), 2)
          IF (mpg%cvonclosedsurface(icv)) THEN
! loop over number of cells in the boundary
            DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
              icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
              icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
              ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
              t0 = t0 + geo%cvvol(icv2)
              t1 = t1 + geo%cvvol(icv2)*pl%ua(icv2, is)
            END DO
          END IF
        END DO
        t1 = t1/t0
!       ..impose velocity
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%smo0(icv1, 0, is) = vbig*ne00*am(is)*geo%fcs(ifc)*geo%fchz&
&           (ifc)*(mompar(is, ib, 1)+pl%ua(icv2, is)-t1)
          srw%smo0(icv1, 1, is) = -(vbig*ne00*am(is)*geo%fcs(ifc)*geo%&
&           fchz(ifc))
        END DO
      CASE (17) 
!
! -- BCMOM=17 -- leakage option for parallel momentum
!
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a,a,i3)'&
&                                    ) &
&                              'BCMOM = 17 : parallel momentum leakage '&
&                                     , mompar(is, ib, 1), ' on ', &
&                                     bcchar(ib), boundary_location(ib)&
&                                     , ' for species ', is
!wdk      Possible backwards-compatibility issue:
!wdk      In the unstructured solver, we impose flux per unit area normal
!wdk      to the surface/boundary.
!wdk      In the original code, the flux per unit area in the poloidal
!wdk      direction was imposed at E/W boundaries (and normal to the
!wdk      radial direction at N/S - unchanged for aligned grids)
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%smo0(icv1, 0, is) = 0.0_R8
          srw%smo0(icv1, 1, is) = geo%fcs(ifc)*geo%fchz(ifc)*SQRT((rt%&
&           rza(icv1, is)*pl%te(icv1)+pl%ti(icv1))/(am(is)*mp))*(am(is)*&
&           mp)*mompar(is, ib, 1)*pl%na(icv1, is)
        END DO
      CASE (18) 
!
! -- BCMOM=18 -- PRESCRIBE ZERO SOURCE TERMS (-> no flux)
!
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,a,a,a,i3)') &
&               'BCMOM = 18 : specified zero source terms (no flux) on '&
&                                     , bcchar(ib), boundary_location(ib&
&                                     ), ' for species ', is
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          srw%smo0(icv, 0, is) = 0.0_R8
          srw%smo0(icv, 1, is) = 0.0_R8
        END DO
      CASE DEFAULT
!
        WRITE(*, *) bcmom(is, ib)
        CALL XERRAB('BCMOM out of bounds')
!
      END SELECT
! -- END LOOP OVER SPECIES

    END DO
!
    RETURN
  END SUBROUTINE B2STBC_PHYS_SPECIES

!  Differentiation of b2stbc_phys_ene in reverse (adjoint) mode (with options context noISIZE r8):
!   gradient     of useful results: conpar enepar enipar potpar
!                senepar *(dv.fch_p) *(dv.fna) *(dv.fne) *(dv.fhe)
!                *(dv.fhe_mdf) *(dv.fhepsch) *(dv.fhi) *(dv.kinrgy)
!                *(dv.ne) *(dv.ni) *(dv.vaecrb) *(dv.vedia) *(dv.veecrb)
!                *(rt.rza) *(srw.she0) *(srw.shi0) *(srw.sna0)
!                *(co.chce) *(co.hce0) *(co.dna0) *(pl.na) *(pl.po)
!                *(pl.te) *(pl.ti) rz pz
!   with respect to varying inputs: conpar enepar enipar potpar
!                senepar *(dv.fch_p) *(dv.fna) *(dv.fne) *(dv.fhe)
!                *(dv.fhe_mdf) *(dv.fhepsch) *(dv.fhi) *(dv.kinrgy)
!                *(dv.ne) *(dv.ni) *(dv.vaecrb) *(dv.vedia) *(dv.veecrb)
!                *(rt.rza) *(srw.she0) *(srw.shi0) *(srw.sna0)
!                *(co.chce) *(co.hce0) *(co.dna0) *(pl.na) *(pl.po)
!                *(pl.te) *(pl.ti) rz pz
!   Plus diff mem management of: dv.fch_p:in dv.fna:in dv.fne:in
!                dv.fhe:in dv.fhe_mdf:in dv.fhepsch:in dv.fhi:in
!                dv.kinrgy:in dv.ne:in dv.ni:in dv.vaecrb:in dv.vedia:in
!                dv.veecrb:in mpg.bcfcor:in geo.fcs:in geo.vxvol:in
!                st_ext.ua:in rt.rza:in srw.she0:in srw.shi0:in
!                srw.sna0:in co.chce:in co.hce0:in co.dna0:in pl.na:in
!                pl.po:in pl.te:in pl.ti:in
!
  SUBROUTINE B2STBC_PHYS_ENE_B(ib)
    IMPLICIT NONE
    INTEGER :: ib, ibw, ibc, ibc0, ib0, is, ism
    INTEGER :: icv, icv1, icv2, ifc, ivx1, ivx2
    REAL(kind=r8) :: cs, vte, s1, t0, t1, t2, t3, t4, neave, totpar, &
&   totflux, teave, weight, wrk
    REAL(kind=r8) :: csb, vteb, t0b, t1b, t2b, t3b, t4b, neaveb, totparb&
&   , totfluxb, teaveb, weightb
    REAL(kind=r8), EXTERNAL :: INTVERTEX_S_NODIFF
    EXTERNAL XERRAB
    INTRINSIC MIN
    INTRINSIC SQRT
    INTRINSIC ABS
    REAL(r8) :: y1
    REAL(r8) :: y1b
    REAL(r8) :: y2
    REAL(r8) :: y2b
    REAL(kind=r8) :: x1
    REAL(kind=r8) :: x1b
    REAL(kind=r8) :: y3
    REAL(kind=r8) :: y3b
    REAL(kind=r8) :: x2
    REAL(kind=r8) :: x2b
    REAL(kind=r8) :: x3
    REAL(kind=r8) :: x3b
    REAL(kind=r8) :: y4
    REAL(kind=r8) :: y4b
    REAL(r8) :: max1
    REAL(r8) :: max1b
    REAL(r8) :: min1
    REAL(r8) :: min1b
    REAL(r8) :: max2
    REAL(r8) :: max2b
    REAL(r8) :: min2
    REAL(r8) :: min2b
    REAL(r8) :: max3
    REAL(r8) :: max3b
    REAL(r8) :: max4
    REAL(r8) :: max4b
    REAL(r8) :: min3
    REAL(r8) :: min3b
    REAL(r8) :: max5
    REAL(r8) :: max5b
    REAL(r8) :: min4
    REAL(r8) :: min4b
    REAL(kind=r8) :: abs0
    REAL(r8) :: min5
    REAL(r8) :: min5b
    REAL(r8) :: max6
    REAL(r8) :: max6b
    REAL(r8) :: min6
    REAL(r8) :: min6b
    REAL(kind=r8) :: max7
    REAL(kind=r8) :: max7b
    REAL(kind=r8) :: max8
    REAL(kind=r8) :: max8b
    REAL(kind=r8) :: max9
    REAL(kind=r8) :: max9b
    REAL(kind=r8) :: abs1
    REAL(kind=r8) :: result10
    REAL(kind=r8) :: result10b
    REAL(kind=r8) :: temp
    REAL(kind=r8) :: tempb
    REAL(kind=r8) :: temp0
    REAL(kind=r8) :: tempb0
    REAL(r8) :: temp1
    REAL(r8) :: tempb1
    REAL(r8) :: temp2
    REAL(kind=r8) :: temp3
    REAL(kind=r8) :: temp4
    REAL(r8) :: temp5
    REAL(r8) :: tempb2
    REAL(kind=r8) :: tempb3
    REAL(kind=r8) :: tempb4
    REAL(r8) :: tempb5
    REAL(kind=r8) :: temp6
    REAL(kind=r8) :: temp7
    REAL(kind=r8) :: tempb6
    REAL(kind=r8) :: tempb7
    INTEGER*4 :: branch
    INTEGER :: ad_to
    INTEGER :: ad_to0
    INTEGER :: ad_to1
    INTEGER :: ad_to2
    INTEGER :: ad_to3
!
! -- BOUNDARY CONDITIONS FOR ELECTRON ENERGY EQUATION --
!
    SELECT CASE  (bcene(ib)) 
    CASE (0) 

    CASE (1) 
!
!
! -- BCENE=1 -- PRESCRIBE THE VALUE OF THE ELECTRON TEMPERATURE
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        IF (bcchar(ib) .EQ. 'S' .AND. switch%use_astra .NE. 0) THEN
          CALL PUSHCONTROL2B(1)
        ELSE
          CALL PUSHCONTROL2B(2)
        END IF
      ELSE
        CALL PUSHCONTROL2B(0)
      END IF
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        srwb%she0(icv, 1) = 0.D0
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        eneparb(ib, 1) = eneparb(ib, 1) + vbig*ne00*geo%fcs(ifc)*ev*srwb&
&         %she0(icv, 0)
        srwb%she0(icv, 0) = 0.D0
      END DO
      CALL POPCONTROL2B(branch)
      IF (branch .NE. 0) THEN
        IF (branch .EQ. 1) eneparb(ib, 1) = 0.D0
      END IF
    CASE (2) 
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        srwb%she0(icv1, 1) = 0.D0
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        tempb = vbig*ne00*geo%fcs(ifc)*srwb%she0(icv1, 0)
        srwb%she0(icv1, 0) = 0.D0
        eneparb(ib, 1) = eneparb(ib, 1) + ev*geo%fcqgam(ifc, 0)*(geo%&
&         fchc(ifc, 1)+geo%fchc(ifc, 2))*tempb
        tempb0 = -(mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*cor9*geo%fcqgam(&
&         ifc, 1)*(geo%fchc(ifc, 1)+geo%fchc(ifc, 2))*tempb/geo%fcht(ifc&
&         ))
        plb%te(icv2) = plb%te(icv2) + tempb
        t2b = tempb0
        t1b = -tempb0
        ivx2 = mpg%fcvx(ifc, 2)
        CALL INTVERTEX_S_B(ivx2, ncv, nvx, mpg, geo%vxvol, pl%te, plb%te&
&                    , t2b)
        ivx1 = mpg%fcvx(ifc, 1)
        CALL INTVERTEX_S_B(ivx1, ncv, nvx, mpg, geo%vxvol, pl%te, plb%te&
&                    , t1b)
      END DO
    CASE (3) 

    CASE (4) 
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        eneparb(ib, 2) = eneparb(ib, 2) - geo%fcs(ifc)*srwb%she0(icv, 1)&
&         /ev
        srwb%she0(icv, 1) = 0.D0
        tempb0 = geo%fcs(ifc)*srwb%she0(icv, 0)
        srwb%she0(icv, 0) = 0.D0
        eneparb(ib, 2) = eneparb(ib, 2) + enepar(ib, 1)*tempb0
        eneparb(ib, 1) = eneparb(ib, 1) + enepar(ib, 2)*tempb0
      END DO
    CASE (5) 
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        srwb%she0(icv, 1) = 0.D0
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        eneparb(ib, 1) = eneparb(ib, 1) + geo%fcs(ifc)*srwb%she0(icv, 0)
        srwb%she0(icv, 0) = 0.D0
      END DO
    CASE (6) 

    CASE (7) 
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        srwb%she0(icv1, 1) = 0.D0
        srwb%she0(icv1, 0) = 0.D0
      END DO
    CASE (8) 
      us = 0.0_R8
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        us = us + geo%fcs(ifc)
      END DO
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        CALL PUSHINTEGER4(icv1)
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        CALL PUSHINTEGER4(ifc)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        IF (switch%mdf_fhe .NE. 0) THEN
!wdk Correction now involves vedia instead of ExB velocity
!wdk This makes implementation equivalent to mdf_f = 0 option
          t0 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*2.5_R8*(geo%fcs(ifc)*&
&           geo%fcqalf(ifc, 0)*dv%vedia(ifc, 0)+geo%fcs(ifc)*geo%fcqalf(&
&           ifc, 1)*dv%vedia(ifc, 1))*0.5_R8*(dv%ne(icv1)+dv%ne(icv2))*&
&           0.5_R8*(pl%te(icv1)+pl%te(icv2))
          IF (0.0_R8 .LT. t0) THEN
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHCONTROL1B(1)
          END IF
          IF (0.0_R8 .GT. t0) THEN
            CALL PUSHREAL8(min1, r8/8)
            min1 = t0
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHREAL8(min1, r8/8)
            min1 = 0.0_R8
            CALL PUSHCONTROL1B(1)
          END IF
          CALL PUSHCONTROL1B(1)
        ELSE
          CALL PUSHCONTROL1B(0)
        END IF
      END DO
      DO ibc=mpg%bccvp(ib, 2),1,-1
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) THEN
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          tempb2 = srwb%she0(icv1, 1)/pl%te(icv1)
          min1b = tempb2
          plb%te(icv1) = plb%te(icv1) - min1*tempb2/pl%te(icv1)
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            CALL POPREAL8(min1, r8/8)
            t0b = min1b
          ELSE
            CALL POPREAL8(min1, r8/8)
            t0b = 0.D0
          END IF
          max1b = srwb%she0(icv1, 0)
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) t0b = t0b + max1b
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          temp1 = pl%te(icv1) + pl%te(icv2)
          temp2 = dv%ne(icv1) + dv%ne(icv2)
          temp3 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
          temp4 = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
          tempb0 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*0.5_R8**2*2.5_R8*&
&           t0b
          tempb = temp2*temp1*tempb0
          tempb2 = (temp3*dv%vedia(ifc, 0)+temp4*dv%vedia(ifc, 1))*&
&           tempb0
          dvb%ne(icv1) = dvb%ne(icv1) + temp1*tempb2
          dvb%ne(icv2) = dvb%ne(icv2) + temp1*tempb2
          plb%te(icv1) = plb%te(icv1) + temp2*tempb2
          plb%te(icv2) = plb%te(icv2) + temp2*tempb2
          dvb%vedia(ifc, 0) = dvb%vedia(ifc, 0) + temp3*tempb
          dvb%vedia(ifc, 1) = dvb%vedia(ifc, 1) + temp4*tempb
          tempb1 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*srwb%she0(icv1, 0)
          dvb%fhepsch(ifc, 0) = dvb%fhepsch(ifc, 0) + tempb1
          dvb%fhepsch(ifc, 1) = dvb%fhepsch(ifc, 1) + tempb1
        END IF
        srwb%she0(icv1, 1) = 0.D0
        eneparb(ib, 1) = eneparb(ib, 1) + fac_he_anom_bc*geo%fcs(ifc)*&
&         srwb%she0(icv1, 0)/us
        srwb%she0(icv1, 0) = 0.D0
        CALL POPINTEGER4(ifc)
        CALL POPINTEGER4(icv1)
      END DO
    CASE (9) 
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        CALL PUSHINTEGER4(icv1)
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        CALL PUSHINTEGER4(ifc)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        IF (switch%mdf_fhe .NE. 0) THEN
          t0 = -(mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*1.5_R8*(geo%fcs(ifc)&
&           *geo%fcqalf(ifc, 0)*dv%veecrb(ifc, 0)+geo%fcs(ifc)*geo%&
&           fcqalf(ifc, 1)*dv%veecrb(ifc, 1))*0.5_R8*(dv%ne(icv1)+dv%ne(&
&           icv2))*0.5_R8*(pl%te(icv1)+pl%te(icv2)))
          IF (0.0_R8 .LT. t0) THEN
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHCONTROL1B(1)
          END IF
          IF (0.0_R8 .GT. t0) THEN
            CALL PUSHREAL8(min2, r8/8)
            min2 = t0
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHREAL8(min2, r8/8)
            min2 = 0.0_R8
            CALL PUSHCONTROL1B(1)
          END IF
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
      END DO
      DO ibc=mpg%bccvp(ib, 2),1,-1
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          tempb2 = srwb%she0(icv1, 1)/pl%te(icv1)
          min2b = tempb2
          plb%te(icv1) = plb%te(icv1) - min2*tempb2/pl%te(icv1)
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            CALL POPREAL8(min2, r8/8)
            t0b = min2b
          ELSE
            CALL POPREAL8(min2, r8/8)
            t0b = 0.D0
          END IF
          max2b = srwb%she0(icv1, 0)
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) t0b = t0b + max2b
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          temp5 = pl%te(icv1) + pl%te(icv2)
          temp2 = dv%ne(icv1) + dv%ne(icv2)
          temp0 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
          temp = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
          tempb3 = -(mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*0.5_R8**2*1.5_R8&
&           *t0b)
          tempb4 = temp2*temp5*tempb3
          tempb1 = (temp0*dv%veecrb(ifc, 0)+temp*dv%veecrb(ifc, 1))*&
&           tempb3
          dvb%ne(icv1) = dvb%ne(icv1) + temp5*tempb1
          dvb%ne(icv2) = dvb%ne(icv2) + temp5*tempb1
          plb%te(icv1) = plb%te(icv1) + temp2*tempb1
          plb%te(icv2) = plb%te(icv2) + temp2*tempb1
          dvb%veecrb(ifc, 0) = dvb%veecrb(ifc, 0) + temp0*tempb4
          dvb%veecrb(ifc, 1) = dvb%veecrb(ifc, 1) + temp*tempb4
          tempb2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*srwb%she0(icv1, 0)
          dvb%fhepsch(ifc, 0) = dvb%fhepsch(ifc, 0) + tempb2
          dvb%fhepsch(ifc, 1) = dvb%fhepsch(ifc, 1) + tempb2
        END IF
        DO is=ns-1,0,-1
          srwb%sna0(icv1, 1, is) = srwb%sna0(icv1, 1, is) + rt%rza(icv1&
&           , is)*pl%na(icv1, is)*fac_he_anom*srwb%she0(icv1, 1)
          tempb2 = srw%sna0(icv1, 1, is)*fac_he_anom*srwb%she0(icv1, 1)
          rtb%rza(icv1, is) = rtb%rza(icv1, is) + pl%na(icv1, is)*tempb2
          plb%na(icv1, is) = plb%na(icv1, is) + rt%rza(icv1, is)*tempb2
          tempb2 = srw%sna0(icv1, 0, is)*fac_he_anom*srwb%she0(icv1, 0)
          srwb%sna0(icv1, 0, is) = srwb%sna0(icv1, 0, is) + rt%rza(icv1&
&           , is)*pl%te(icv1)*fac_he_anom*srwb%she0(icv1, 0)
          rtb%rza(icv1, is) = rtb%rza(icv1, is) + pl%te(icv1)*tempb2
          plb%te(icv1) = plb%te(icv1) + rt%rza(icv1, is)*tempb2
        END DO
        sy = geo%fcs(ifc)
        tempb2 = -(sy*srwb%she0(icv1, 1)/enepar(ib, 1))
        srwb%she0(icv1, 1) = 0.D0
        cob%hce0(icv1) = cob%hce0(icv1) + tempb2
        eneparb(ib, 1) = eneparb(ib, 1) - co%hce0(icv1)*tempb2/enepar(ib&
&         , 1)
        srwb%she0(icv1, 0) = 0.D0
        CALL POPINTEGER4(ifc)
        CALL POPINTEGER4(icv1)
      END DO
    CASE (11, 10) 

    CASE (12) 
      DO ibc=1,mpg%bccvp(ib, 2)
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        IF (0.0_R8 .LT. mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%fne(ifc, &
&           0)+dv%fne(ifc, 1))) THEN
          CALL PUSHREAL8(max3, r8/8)
          max3 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%fne(ifc, 0)+dv%&
&           fne(ifc, 1))
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHREAL8(max3, r8/8)
          max3 = 0.0_R8
          CALL PUSHCONTROL1B(1)
        END IF
      END DO
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        tempb3 = -(srwb%she0(icv, 3)/dv%ne(icv))
        eneparb(ib, 1) = eneparb(ib, 1) + max3*tempb3
        max3b = enepar(ib, 1)*tempb3
        dvb%ne(icv) = dvb%ne(icv) - enepar(ib, 1)*max3*tempb3/dv%ne(icv)
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          CALL POPREAL8(max3, r8/8)
          tempb2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*max3b
          dvb%fne(ifc, 0) = dvb%fne(ifc, 0) + tempb2
          dvb%fne(ifc, 1) = dvb%fne(ifc, 1) + tempb2
        ELSE
          CALL POPREAL8(max3, r8/8)
        END IF
      END DO
    CASE (13) 
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        srwb%she0(icv, 1) = 0.D0
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        tempb3 = geo%fcs(ifc)*srwb%she0(icv, 0)
        srwb%she0(icv, 0) = 0.D0
        eneparb(ib, 1) = eneparb(ib, 1) + pl%te(icv)*tempb3
        plb%te(icv) = plb%te(icv) + enepar(ib, 1)*tempb3
      END DO
    CASE (14) 
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        CALL PUSHINTEGER4(icv1)
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        CALL PUSHINTEGER4(ifc)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        CALL PUSHREAL8(cs, r8/8)
        cs = SQRT(pz(icv1)/rz(icv1))
        IF (switch%mdf_fhe .NE. 0) THEN
          t0 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*2.5_R8*(geo%fcs(ifc)*&
&           geo%fcqalf(ifc, 0)*dv%vedia(ifc, 0)+geo%fcs(ifc)*geo%fcqalf(&
&           ifc, 1)*dv%vedia(ifc, 1))*0.5_R8*(dv%ne(icv1)+dv%ne(icv2))*&
&           0.5_R8*(pl%te(icv1)+pl%te(icv2))
          IF (0.0_R8 .LT. t0) THEN
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHCONTROL1B(1)
          END IF
          IF (0.0_R8 .GT. t0) THEN
            CALL PUSHREAL8(min3, r8/8)
            min3 = t0
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHREAL8(min3, r8/8)
            min3 = 0.0_R8
            CALL PUSHCONTROL1B(1)
          END IF
          CALL PUSHCONTROL1B(1)
        ELSE
          CALL PUSHCONTROL1B(0)
        END IF
      END DO
      DO ibc=mpg%bccvp(ib, 2),1,-1
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) THEN
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          tempb2 = srwb%she0(icv1, 1)/pl%te(icv1)
          min3b = tempb2
          plb%te(icv1) = plb%te(icv1) - min3*tempb2/pl%te(icv1)
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            CALL POPREAL8(min3, r8/8)
            t0b = min3b
          ELSE
            CALL POPREAL8(min3, r8/8)
            t0b = 0.D0
          END IF
          max4b = srwb%she0(icv1, 0)
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) t0b = t0b + max4b
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          temp5 = pl%te(icv1) + pl%te(icv2)
          temp2 = dv%ne(icv1) + dv%ne(icv2)
          temp0 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
          temp = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
          tempb3 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*0.5_R8**2*2.5_R8*&
&           t0b
          tempb4 = temp2*temp5*tempb3
          tempb1 = (temp0*dv%vedia(ifc, 0)+temp*dv%vedia(ifc, 1))*tempb3
          dvb%ne(icv1) = dvb%ne(icv1) + temp5*tempb1
          dvb%ne(icv2) = dvb%ne(icv2) + temp5*tempb1
          plb%te(icv1) = plb%te(icv1) + temp2*tempb1
          plb%te(icv2) = plb%te(icv2) + temp2*tempb1
          dvb%vedia(ifc, 0) = dvb%vedia(ifc, 0) + temp0*tempb4
          dvb%vedia(ifc, 1) = dvb%vedia(ifc, 1) + temp*tempb4
          tempb2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*srwb%she0(icv1, 0)
          dvb%fhepsch(ifc, 0) = dvb%fhepsch(ifc, 0) + tempb2
          dvb%fhepsch(ifc, 1) = dvb%fhepsch(ifc, 1) + tempb2
        END IF
        tempb3 = geo%fcs(ifc)*fac_he_anom_bc*srwb%she0(icv1, 3)
        srwb%she0(icv1, 3) = 0.D0
        csb = enepar(ib, 1)*tempb3
        eneparb(ib, 1) = eneparb(ib, 1) + cs*tempb3
        temp0 = cs*dv%ne(icv1)
        tempb3 = geo%fcs(ifc)*fac_he_anom_bc*qe*srwb%she0(icv1, 0)
        srwb%she0(icv1, 0) = 0.D0
        tempb4 = enepar(ib, 1)*enepar(ib, 2)*tempb3
        tempb = temp0*pl%po(icv1)*tempb3
        eneparb(ib, 1) = eneparb(ib, 1) + enepar(ib, 2)*tempb
        eneparb(ib, 2) = eneparb(ib, 2) + enepar(ib, 1)*tempb
        tempb0 = pl%po(icv1)*tempb4
        plb%po(icv1) = plb%po(icv1) + temp0*tempb4
        csb = csb + dv%ne(icv1)*tempb0
        dvb%ne(icv1) = dvb%ne(icv1) + cs*tempb0
        CALL POPREAL8(cs, r8/8)
        temp4 = pz(icv1)/rz(icv1)
        IF (temp4 .EQ. 0.D0) THEN
          tempb3 = 0.D0
        ELSE
          tempb3 = csb/(rz(icv1)*2.0*SQRT(temp4))
        END IF
        pzb(icv1) = pzb(icv1) + tempb3
        rzb(icv1) = rzb(icv1) - temp4*tempb3
        CALL POPINTEGER4(ifc)
        CALL POPINTEGER4(icv1)
      END DO
    CASE (15) 
!srv 01.02.09 }
!srv added accumulation in order to account twice b.c. for corner cells
      IF (bcene_15_style .EQ. 0) THEN
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          CALL PUSHINTEGER4(icv1)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          CALL PUSHINTEGER4(ifc)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          CALL PUSHREAL8(cs, r8/8)
          cs = SQRT(pz(icv1)/rz(icv1))
          CALL PUSHREAL8(t0, r8/8)
          t0 = dv%ne(icv1)
          CALL PUSHREAL8(t1, r8/8)
          t1 = 0.0_R8
          DO is=0,ns-1
            IF (.NOT.is_neutral(is) .AND. conpar(is, ib, 2) .GT. 0.0_R8&
&           ) THEN
              t1 = t1 + co%dna0(icv1, is)/conpar(is, ib, 2)*rt%rza(icv1&
&               , is)*pl%na(icv1, is)
              CALL PUSHCONTROL1B(1)
            ELSE
              CALL PUSHCONTROL1B(0)
            END IF
          END DO
          IF (geo%fcpbs(ifc) .GE. 0.) THEN
            CALL PUSHREAL8(abs1, r8/8)
            abs1 = geo%fcpbs(ifc)
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHREAL8(abs1, r8/8)
            abs1 = -geo%fcpbs(ifc)
            CALL PUSHCONTROL1B(1)
          END IF
          y1 = abs1*t0*cs - dv%fch_p(ifc, 0)*mpg%bcfcor(mpg%bccvp(ib, 1)&
&           +ibc-1)/qe
          IF (0.0_R8 .LT. y1) THEN
            t0 = y1
            CALL PUSHCONTROL1B(0)
          ELSE
            t0 = 0.0_R8
            CALL PUSHCONTROL1B(1)
          END IF
          t1 = t1*geo%fcs(ifc)
!srv 27.02.13 }
          IF (switch%pot_eq .EQ. 1) THEN
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHCONTROL1B(1)
          END IF
          IF (switch%mdf_fhe .NE. 0) THEN
            CALL PUSHREAL8(t0, r8/8)
            t0 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*2.5_R8*(geo%fcs(ifc)&
&             *geo%fcqalf(ifc, 0)*dv%vedia(ifc, 0)+geo%fcs(ifc)*geo%&
&             fcqalf(ifc, 1)*dv%vedia(ifc, 1))*0.5_R8*(dv%ne(icv1)+dv%ne&
&             (icv2))*0.5_R8*(pl%te(icv1)+pl%te(icv2))
            IF (0.0_R8 .LT. t0) THEN
              CALL PUSHCONTROL1B(0)
            ELSE
              CALL PUSHCONTROL1B(1)
            END IF
            IF (0.0_R8 .GT. t0) THEN
              CALL PUSHREAL8(min4, r8/8)
              min4 = t0
              CALL PUSHCONTROL1B(0)
            ELSE
              CALL PUSHREAL8(min4, r8/8)
              min4 = 0.0_R8
              CALL PUSHCONTROL1B(1)
            END IF
            CALL PUSHCONTROL1B(1)
          ELSE
            CALL PUSHCONTROL1B(0)
          END IF
        END DO
        DO ibc=mpg%bccvp(ib, 2),1,-1
          CALL POPCONTROL1B(branch)
          IF (branch .NE. 0) THEN
            icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
            tempb2 = srwb%she0(icv1, 1)/pl%te(icv1)
            min4b = tempb2
            plb%te(icv1) = plb%te(icv1) - min4*tempb2/pl%te(icv1)
            CALL POPCONTROL1B(branch)
            IF (branch .EQ. 0) THEN
              CALL POPREAL8(min4, r8/8)
              t0b = min4b
            ELSE
              CALL POPREAL8(min4, r8/8)
              t0b = 0.D0
            END IF
            max5b = srwb%she0(icv1, 0)
            CALL POPCONTROL1B(branch)
            IF (branch .EQ. 0) t0b = t0b + max5b
            icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            CALL POPREAL8(t0, r8/8)
            temp5 = pl%te(icv1) + pl%te(icv2)
            temp2 = dv%ne(icv1) + dv%ne(icv2)
            temp0 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
            temp = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
            tempb3 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*0.5_R8**2*2.5_R8&
&             *t0b
            tempb4 = temp2*temp5*tempb3
            tempb1 = (temp0*dv%vedia(ifc, 0)+temp*dv%vedia(ifc, 1))*&
&             tempb3
            dvb%ne(icv1) = dvb%ne(icv1) + temp5*tempb1
            dvb%ne(icv2) = dvb%ne(icv2) + temp5*tempb1
            plb%te(icv1) = plb%te(icv1) + temp2*tempb1
            plb%te(icv2) = plb%te(icv2) + temp2*tempb1
            dvb%vedia(ifc, 0) = dvb%vedia(ifc, 0) + temp0*tempb4
            dvb%vedia(ifc, 1) = dvb%vedia(ifc, 1) + temp*tempb4
            tempb2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*srwb%she0(icv1, &
&             0)
            dvb%fhepsch(ifc, 0) = dvb%fhepsch(ifc, 0) + tempb2
            dvb%fhepsch(ifc, 1) = dvb%fhepsch(ifc, 1) + tempb2
          END IF
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            tempb2 = -((t0+t1)*qe*srwb%she0(icv1, 0))
            tempb3 = -((pl%po(icv1)-potpar(ib, 2))*qe*srwb%she0(icv1, 0)&
&             )
            t0b = tempb3 - (gammae+1.0_R8)*srwb%she0(icv1, 1)/(1.0_R8-&
&             gammae)
            t1b = tempb3 - enepar(ib, 2)*fac_he_anom_bc*srwb%she0(icv1, &
&             1)
            plb%po(icv1) = plb%po(icv1) + tempb2
            potparb(ib, 2) = potparb(ib, 2) - tempb2
            eneparb(ib, 2) = eneparb(ib, 2) - t1*fac_he_anom_bc*srwb%&
&             she0(icv1, 1)
          ELSE
            t0b = -(((gammae+1.0_R8)/(1.0_R8-gammae)+switch%delpo)*srwb%&
&             she0(icv1, 1))
            eneparb(ib, 2) = eneparb(ib, 2) - fac_he_anom_bc*t1*srwb%&
&             she0(icv1, 1)
            t1b = -((switch%delpo+fac_he_anom_bc*enepar(ib, 2))*srwb%&
&             she0(icv1, 1))
          END IF
          t1b = geo%fcs(ifc)*t1b
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            y1b = t0b
          ELSE
            y1b = 0.D0
          END IF
          t0 = dv%ne(icv1)
          t0b = cs*abs1*y1b
          csb = t0*abs1*y1b
          dvb%fch_p(ifc, 0) = dvb%fch_p(ifc, 0) - mpg%bcfcor(mpg%bccvp(&
&           ib, 1)+ibc-1)*y1b/qe
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            CALL POPREAL8(abs1, r8/8)
          ELSE
            CALL POPREAL8(abs1, r8/8)
          END IF
          DO is=ns-1,0,-1
            CALL POPCONTROL1B(branch)
            IF (branch .NE. 0) THEN
              temp5 = pl%na(icv1, is)/conpar(is, ib, 2)
              cob%dna0(icv1, is) = cob%dna0(icv1, is) + rt%rza(icv1, is)&
&               *temp5*t1b
              rtb%rza(icv1, is) = rtb%rza(icv1, is) + co%dna0(icv1, is)*&
&               temp5*t1b
              tempb2 = co%dna0(icv1, is)*rt%rza(icv1, is)*t1b/conpar(is&
&               , ib, 2)
              plb%na(icv1, is) = plb%na(icv1, is) + tempb2
              conparb(is, ib, 2) = conparb(is, ib, 2) - temp5*tempb2
            END IF
          END DO
          CALL POPREAL8(t1, r8/8)
          CALL POPREAL8(t0, r8/8)
          dvb%ne(icv1) = dvb%ne(icv1) + t0b
          CALL POPREAL8(cs, r8/8)
          temp4 = pz(icv1)/rz(icv1)
          IF (temp4 .EQ. 0.D0) THEN
            tempb3 = 0.D0
          ELSE
            tempb3 = csb/(rz(icv1)*2.0*SQRT(temp4))
          END IF
          pzb(icv1) = pzb(icv1) + tempb3
          rzb(icv1) = rzb(icv1) - temp4*tempb3
          CALL POPINTEGER4(ifc)
          CALL POPINTEGER4(icv1)
        END DO
      ELSE IF (bcene_15_style .EQ. 1) THEN
!wdk    Todo: corrections for BCCON.ne.14
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          CALL PUSHINTEGER4(icv1)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          CALL PUSHINTEGER4(ifc)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          CALL PUSHREAL8(vte, r8/8)
          vte = SQRT(pl%te(icv1)/me)
          IF (geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3) .GE. &
&             0.) THEN
            wrk = geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3)
          ELSE
            wrk = -(geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3)&
&             )
          END IF
          IF (wrk .LT. geo%qalfmin) THEN
            IF (geo%fcs(ifc) .GE. 0.) THEN
              abs0 = geo%fcs(ifc)
            ELSE
              abs0 = -geo%fcs(ifc)
            END IF
            CALL PUSHREAL8(s1, r8/8)
            s1 = abs0*geo%qalfmax
            CALL PUSHCONTROL2B(0)
          ELSE IF (geo%fcpbs(ifc) .GE. 0.) THEN
            CALL PUSHREAL8(s1, r8/8)
            s1 = geo%fcpbs(ifc)
            CALL PUSHCONTROL2B(2)
          ELSE
            CALL PUSHREAL8(s1, r8/8)
            s1 = -geo%fcpbs(ifc)
            CALL PUSHCONTROL2B(1)
          END IF
          CALL PUSHREAL8(t0, r8/8)
          t0 = dv%ne(icv1)
          CALL PUSHREAL8(t1, r8/8)
          t1 = 0.0_R8
          DO is=0,ns-1
            IF (.NOT.is_neutral(is) .AND. conpar(is, ib, 2) .GT. 0.0_R8&
&           ) THEN
              t1 = t1 + co%dna0(icv1, is)/conpar(is, ib, 2)*rt%rza(icv1&
&               , is)*pl%na(icv1, is)
              CALL PUSHCONTROL1B(1)
            ELSE
              CALL PUSHCONTROL1B(0)
            END IF
          END DO
          IF (-50.0_R8 .LT. -(qe*(pl%po(icv1)-potpar(ib, 2))/pl%te(icv1)&
&             )) THEN
            y2 = -(qe*(pl%po(icv1)-potpar(ib, 2))/pl%te(icv1))
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHCONTROL1B(1)
            y2 = -50.0_R8
          END IF
          IF (0.0_R8 .GT. y2) THEN
            CALL PUSHREAL8(min5, r8/8)
            min5 = y2
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHREAL8(min5, r8/8)
            min5 = 0.0_R8
            CALL PUSHCONTROL1B(1)
          END IF
!lkw 31.03.2023
          CALL PUSHBOOLEAN(b2mod_math_initialised)
          CALL PUSHREAL8(cutlo, r8/8)
          CALL PUSHREAL8(cutll, r8/8)
          CALL PUSHREAL8(result10, r8/8)
          result10 = EXPU2(min5)
          CALL PUSHREAL8(t0, r8/8)
          t0 = s1*t0*SQRT(1.0_R8/(2.0_R8*pi))*vte*result10
          t1 = t1*geo%fcs(ifc)
          IF (switch%pot_eq .EQ. 1) THEN
!wdk to check: correct 2nd term for gammae?
            CALL PUSHREAL8(srw%she0(icv1, 1), r8/8)
            srw%she0(icv1, 1) = srw%she0(icv1, 1) - (1.0_R8+gammae+&
&             enepar(ib, 1)+switch%stab_coeff_sheath_te)*t0 - &
&             fac_he_anom_bc*enepar(ib, 2)*t1
!lkw 31.03.2023
!wdk to check: correct 2nd term for gammae?
            CALL PUSHREAL8(srw%she0(icv1, 0), r8/8)
            srw%she0(icv1, 0) = srw%she0(icv1, 0) - ((1.0_R8-gammae)*qe*&
&             (pl%po(icv1)-potpar(ib, 2))-switch%stab_coeff_sheath_te*pl&
&             %te(icv1))*t0 - qe*(pl%po(icv1)-potpar(ib, 2))*t1
            IF (switch%b2nppo_restr_po .NE. 0.0_R8 .AND. srw%she0(icv1, &
&               0) + srw%she0(icv1, 1)*pl%te(icv1) .GT. 0.0_R8) THEN
              CALL PUSHREAL8ARRAY(srw%she0(icv1, :), r8*SIZE(srw%she0, 2&
&                           )/8)
              srw%she0(icv1, :) = 0.0_R8
              CALL PUSHCONTROL2B(0)
            ELSE
              CALL PUSHCONTROL2B(1)
            END IF
          ELSE
            CALL PUSHREAL8(cs, r8/8)
            cs = SQRT(pz(icv1)/rz(icv1))
!srv 11.03.09 {
!wdk to check: correct for gammae?
            CALL PUSHREAL8(srw%she0(icv1, 1), r8/8)
            srw%she0(icv1, 1) = srw%she0(icv1, 1) - s1*dv%ne(icv1)*cs*(&
&             1.0_R8+gammae+enepar(ib, 1)+(1.0_R8-gammae)*switch%delpo) &
&             - (fac_he_anom_bc*enepar(ib, 2)+switch%delpo)*t1
            CALL PUSHCONTROL2B(2)
          END IF
          IF (switch%mdf_fhe .NE. 0) THEN
            CALL PUSHREAL8(srw%she0(icv1, 0), r8/8)
            srw%she0(icv1, 0) = srw%she0(icv1, 0) + mpg%bcfcor(mpg%bccvp&
&             (ib, 1)+ibc-1)*(dv%fhepsch(ifc, 0)+dv%fhepsch(ifc, 1))
            CALL PUSHREAL8(t0, r8/8)
            t0 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*2.5_R8*(geo%fcs(ifc)&
&             *geo%fcqalf(ifc, 0)*dv%vedia(ifc, 0)+geo%fcs(ifc)*geo%&
&             fcqalf(ifc, 1)*dv%vedia(ifc, 1))*0.5_R8*(dv%ne(icv1)+dv%ne&
&             (icv2))*0.5_R8*(pl%te(icv1)+pl%te(icv2))
            IF (0.0_R8 .LT. t0) THEN
              max6 = t0
              CALL PUSHCONTROL1B(0)
            ELSE
              CALL PUSHCONTROL1B(1)
              max6 = 0.0_R8
            END IF
            CALL PUSHREAL8(srw%she0(icv1, 0), r8/8)
            srw%she0(icv1, 0) = srw%she0(icv1, 0) + max6
            IF (0.0_R8 .GT. t0) THEN
              CALL PUSHREAL8(min6, r8/8)
              min6 = t0
              CALL PUSHCONTROL1B(0)
            ELSE
              CALL PUSHREAL8(min6, r8/8)
              min6 = 0.0_R8
              CALL PUSHCONTROL1B(1)
            END IF
            CALL PUSHREAL8(srw%she0(icv1, 1), r8/8)
            srw%she0(icv1, 1) = srw%she0(icv1, 1) + min6/pl%te(icv1)
            CALL PUSHCONTROL1B(1)
          ELSE
            CALL PUSHCONTROL1B(0)
          END IF
        END DO
        DO ibc=mpg%bccvp(ib, 2),1,-1
          CALL POPCONTROL1B(branch)
          IF (branch .NE. 0) THEN
            icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
            CALL POPREAL8(srw%she0(icv1, 1), r8/8)
            tempb2 = srwb%she0(icv1, 1)/pl%te(icv1)
            min6b = tempb2
            plb%te(icv1) = plb%te(icv1) - min6*tempb2/pl%te(icv1)
            CALL POPCONTROL1B(branch)
            IF (branch .EQ. 0) THEN
              CALL POPREAL8(min6, r8/8)
              t0b = min6b
            ELSE
              CALL POPREAL8(min6, r8/8)
              t0b = 0.D0
            END IF
            CALL POPREAL8(srw%she0(icv1, 0), r8/8)
            max6b = srwb%she0(icv1, 0)
            CALL POPCONTROL1B(branch)
            IF (branch .EQ. 0) t0b = t0b + max6b
            icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            CALL POPREAL8(t0, r8/8)
            temp5 = pl%te(icv1) + pl%te(icv2)
            temp2 = dv%ne(icv1) + dv%ne(icv2)
            temp0 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
            temp = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
            tempb3 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*0.5_R8**2*2.5_R8&
&             *t0b
            tempb4 = temp2*temp5*tempb3
            tempb1 = (temp0*dv%vedia(ifc, 0)+temp*dv%vedia(ifc, 1))*&
&             tempb3
            dvb%ne(icv1) = dvb%ne(icv1) + temp5*tempb1
            dvb%ne(icv2) = dvb%ne(icv2) + temp5*tempb1
            plb%te(icv1) = plb%te(icv1) + temp2*tempb1
            plb%te(icv2) = plb%te(icv2) + temp2*tempb1
            dvb%vedia(ifc, 0) = dvb%vedia(ifc, 0) + temp0*tempb4
            dvb%vedia(ifc, 1) = dvb%vedia(ifc, 1) + temp*tempb4
            CALL POPREAL8(srw%she0(icv1, 0), r8/8)
            tempb2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*srwb%she0(icv1, &
&             0)
            dvb%fhepsch(ifc, 0) = dvb%fhepsch(ifc, 0) + tempb2
            dvb%fhepsch(ifc, 1) = dvb%fhepsch(ifc, 1) + tempb2
          END IF
          CALL POPCONTROL2B(branch)
          IF (branch .EQ. 0) THEN
            CALL POPREAL8ARRAY(srw%she0(icv1, :), r8*SIZE(srw%she0, 2)/8&
&                       )
            srwb%she0(icv1, :) = 0.D0
          ELSE IF (branch .NE. 1) THEN
            CALL POPREAL8(srw%she0(icv1, 1), r8/8)
            tempb2 = -((gammae+(1.0_R8-gammae)*switch%delpo+enepar(ib, 1&
&             )+1.0_R8)*s1*srwb%she0(icv1, 1))
            eneparb(ib, 1) = eneparb(ib, 1) - dv%ne(icv1)*cs*s1*srwb%&
&             she0(icv1, 1)
            eneparb(ib, 2) = eneparb(ib, 2) - fac_he_anom_bc*t1*srwb%&
&             she0(icv1, 1)
            t1b = -((switch%delpo+fac_he_anom_bc*enepar(ib, 2))*srwb%&
&             she0(icv1, 1))
            dvb%ne(icv1) = dvb%ne(icv1) + cs*tempb2
            csb = dv%ne(icv1)*tempb2
            CALL POPREAL8(cs, r8/8)
            temp4 = pz(icv1)/rz(icv1)
            IF (temp4 .EQ. 0.D0) THEN
              tempb3 = 0.D0
            ELSE
              tempb3 = csb/(rz(icv1)*2.0*SQRT(temp4))
            END IF
            pzb(icv1) = pzb(icv1) + tempb3
            rzb(icv1) = rzb(icv1) - temp4*tempb3
            t0b = 0.D0
            GOTO 100
          END IF
          CALL POPREAL8(srw%she0(icv1, 0), r8/8)
          tempb2 = -((1.0_R8-gammae)*qe*t0*srwb%she0(icv1, 0))
          plb%te(icv1) = plb%te(icv1) + switch%stab_coeff_sheath_te*t0*&
&           srwb%she0(icv1, 0)
          t0b = -(((1.0_R8-gammae)*qe*(pl%po(icv1)-potpar(ib, 2))-switch&
&           %stab_coeff_sheath_te*pl%te(icv1))*srwb%she0(icv1, 0)) - (&
&           gammae+switch%stab_coeff_sheath_te+enepar(ib, 1)+1.0_R8)*&
&           srwb%she0(icv1, 1)
          tempb5 = -(qe*srwb%she0(icv1, 0))
          plb%po(icv1) = plb%po(icv1) + t1*tempb5 + tempb2
          potparb(ib, 2) = potparb(ib, 2) - t1*tempb5 - tempb2
          t1b = (pl%po(icv1)-potpar(ib, 2))*tempb5 - enepar(ib, 2)*&
&           fac_he_anom_bc*srwb%she0(icv1, 1)
          CALL POPREAL8(srw%she0(icv1, 1), r8/8)
          eneparb(ib, 1) = eneparb(ib, 1) - t0*srwb%she0(icv1, 1)
          eneparb(ib, 2) = eneparb(ib, 2) - t1*fac_he_anom_bc*srwb%she0(&
&           icv1, 1)
 100      t1b = geo%fcs(ifc)*t1b
          CALL POPREAL8(t0, r8/8)
          tempb3 = s1*SQRT(1.0/(2.0_R8*pi))*t0b
          t0b = vte*result10*tempb3
          vteb = t0*result10*tempb3
          result10b = t0*vte*tempb3
          CALL POPREAL8(result10, r8/8)
          CALL POPREAL8(cutll, r8/8)
          CALL POPREAL8(cutlo, r8/8)
          CALL POPBOOLEAN(b2mod_math_initialised)
          CALL EXPU2_B(min5, min5b, result10b)
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            CALL POPREAL8(min5, r8/8)
            y2b = min5b
          ELSE
            CALL POPREAL8(min5, r8/8)
            y2b = 0.D0
          END IF
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            tempb2 = -(qe*y2b/pl%te(icv1))
            plb%po(icv1) = plb%po(icv1) + tempb2
            potparb(ib, 2) = potparb(ib, 2) - tempb2
            plb%te(icv1) = plb%te(icv1) - (pl%po(icv1)-potpar(ib, 2))*&
&             tempb2/pl%te(icv1)
          END IF
          DO is=ns-1,0,-1
            CALL POPCONTROL1B(branch)
            IF (branch .NE. 0) THEN
              temp5 = pl%na(icv1, is)/conpar(is, ib, 2)
              cob%dna0(icv1, is) = cob%dna0(icv1, is) + rt%rza(icv1, is)&
&               *temp5*t1b
              rtb%rza(icv1, is) = rtb%rza(icv1, is) + co%dna0(icv1, is)*&
&               temp5*t1b
              tempb2 = co%dna0(icv1, is)*rt%rza(icv1, is)*t1b/conpar(is&
&               , ib, 2)
              plb%na(icv1, is) = plb%na(icv1, is) + tempb2
              conparb(is, ib, 2) = conparb(is, ib, 2) - temp5*tempb2
            END IF
          END DO
          CALL POPREAL8(t1, r8/8)
          CALL POPREAL8(t0, r8/8)
          dvb%ne(icv1) = dvb%ne(icv1) + t0b
          CALL POPCONTROL2B(branch)
          IF (branch .EQ. 0) THEN
            CALL POPREAL8(s1, r8/8)
          ELSE IF (branch .EQ. 1) THEN
            CALL POPREAL8(s1, r8/8)
          ELSE
            CALL POPREAL8(s1, r8/8)
          END IF
          CALL POPREAL8(vte, r8/8)
          IF (.NOT.pl%te(icv1)/me .EQ. 0.D0) plb%te(icv1) = plb%te(icv1)&
&             + vteb/(me*2.0*SQRT(pl%te(icv1)/me))
          CALL POPINTEGER4(ifc)
          CALL POPINTEGER4(icv1)
        END DO
      END IF
    CASE (16) 
!
! -- BCENE=16 -- Feedback boundary condition with constant temperature
!
!
      IF (switch%bcene_16_style .EQ. 0) THEN
!       ..compute average temperature on boundary
        t0 = 0.0_R8
        t1 = 0.0_R8
!wdk Note on backwards compatibility: feedback now always on
!wdk flux through the boundary itself (no offset)
        totflux = 0.0_R8
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          t0 = t0 + geo%fcs(ifc)*dv%ne(icv1)
          t1 = t1 + geo%fcs(ifc)*dv%ne(icv1)*pl%te(icv1)
          totflux = totflux - (dv%fhe(ifc, 0)+dv%fhe(ifc, 1))*mpg%bcfcor&
&           (mpg%bccvp(ib, 1)+ibc-1)
        END DO
        CALL PUSHREAL8(t1, r8/8)
        t1 = t1/t0
        totpar = fac_he_anom_bc*enepar(ib, 1)
        IF (enepar(ib, 2) .GT. 0.0_R8) THEN
          t3 = enepar(ib, 2)
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        IF (enepar(ib, 2) .LE. 0.0_R8) THEN
          t3 = switch%b2stbc_bc_ref_te
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        IF (totflux .GE. 0.) THEN
          x1 = totflux
          CALL PUSHCONTROL1B(0)
        ELSE
          x1 = -totflux
          CALL PUSHCONTROL1B(1)
        END IF
        IF (totpar .GE. 0.) THEN
          y3 = totpar
          CALL PUSHCONTROL1B(0)
        ELSE
          y3 = -totpar
          CALL PUSHCONTROL1B(1)
        END IF
        IF (x1 .LT. y3) THEN
          max7 = y3
          CALL PUSHCONTROL1B(0)
        ELSE
          max7 = x1
          CALL PUSHCONTROL1B(1)
        END IF
        t2b = 0.D0
        DO ibc=mpg%bccvp(ib, 2),1,-1
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          srwb%she0(icv1, 1) = 0.D0
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          t2b = t2b + geo%fcs(ifc)*vbig*ne00*srwb%she0(icv1, 0)
          srwb%she0(icv1, 0) = 0.D0
        END DO
        temp4 = t3/max7
        tempb2 = t1*t2b
        t1b = (1.0_R8-(totflux-totpar)*temp4)*t2b
        totfluxb = -(temp4*tempb2)
        totparb = temp4*tempb2
        tempb3 = -((totflux-totpar)*tempb2/max7)
        t3b = tempb3
        max7b = -(temp4*tempb3)
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          y3b = max7b
          x1b = 0.D0
        ELSE
          x1b = max7b
          y3b = 0.D0
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          totparb = totparb + y3b
        ELSE
          totparb = totparb - y3b
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          totfluxb = totfluxb + x1b
        ELSE
          totfluxb = totfluxb - x1b
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) t3b = 0.D0
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) eneparb(ib, 2) = eneparb(ib, 2) + t3b
        eneparb(ib, 1) = eneparb(ib, 1) + fac_he_anom_bc*totparb
        CALL POPREAL8(t1, r8/8)
        t0b = -(t1*t1b/t0**2)
        t1b = t1b/t0
        DO ibc=mpg%bccvp(ib, 2),1,-1
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          tempb2 = -(mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*totfluxb)
          dvb%fhe(ifc, 0) = dvb%fhe(ifc, 0) + tempb2
          dvb%fhe(ifc, 1) = dvb%fhe(ifc, 1) + tempb2
          tempb2 = geo%fcs(ifc)*t1b
          dvb%ne(icv1) = dvb%ne(icv1) + pl%te(icv1)*tempb2 + geo%fcs(ifc&
&           )*t0b
          plb%te(icv1) = plb%te(icv1) + dv%ne(icv1)*tempb2
        END DO
      ELSE IF (switch%bcene_16_style .EQ. 1) THEN
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
!srv 16.02.12 }
          IF (.NOT.once_bcene) THEN
            IF (switch%use_astra .NE. 0) THEN
              CALL PUSHCONTROL1B(0)
            ELSE
              senepar = 0.0_R8
              DO ibw=ib,nbc
                IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') &
&                   .AND. bcene(ibw) .EQ. bcene(ib)) THEN
                  senepar = senepar + enepar(ibw, 1)
                  CALL PUSHCONTROL1B(1)
                ELSE
                  CALL PUSHCONTROL1B(0)
                END IF
              END DO
              CALL PUSHCONTROL1B(1)
            END IF
            tes = 0.0_R8
            CALL PUSHREAL8(volsum, r8/8)
            volsum = 0.0_R8
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bcene(ibw) .EQ. bcene(ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  CALL PUSHINTEGER4(icv)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  tes = tes + pl%te(icv)*geo%cvvol(icv)
                  volsum = volsum + geo%cvvol(icv)
                END DO
                CALL PUSHINTEGER4(ibc - 1)
                CALL PUSHCONTROL1B(1)
              ELSE
                CALL PUSHCONTROL1B(0)
              END IF
            END DO
            tes = tes/volsum
            totflux = 0.0_R8
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bcene(ibw) .EQ. bcene(ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  CALL PUSHINTEGER4(icv)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                  IF (switch%mdf_fhe .NE. 0) THEN
                    totflux = totflux - mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc&
&                     -1)*(dv%fhe_mdf(ifc, 0)+dv%fhe_mdf(ifc, 1))
                    totflux = totflux - pl%te(icv)*dv%ne(icv)*geo%fcs(&
&                     ifc)*mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)*(dv%&
&                     vaecrb(ifc, 0, ns-1)*geo%fcqalf(ifc, 0)+dv%vaecrb(&
&                     ifc, 1, ns-1)*geo%fcqalf(ifc, 1))
                    CALL PUSHCONTROL1B(1)
                  ELSE
                    totflux = totflux - mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc&
&                     -1)*(dv%fhe(ifc, 0)+dv%fhe(ifc, 1))
                    CALL PUSHCONTROL1B(0)
                  END IF
                END DO
                CALL PUSHINTEGER4(ibc - 1)
                CALL PUSHCONTROL1B(1)
              ELSE
                CALL PUSHCONTROL1B(0)
              END IF
            END DO
            IF (enepar(ib, 2) .GT. 0.0_R8) THEN
              t3 = enepar(ib, 2)
              CALL PUSHCONTROL1B(0)
            ELSE
              CALL PUSHCONTROL1B(1)
            END IF
            IF (enepar(ib, 2) .LE. 0.0_R8) THEN
              t3 = switch%b2stbc_bc_ref_te
              CALL PUSHCONTROL1B(0)
            ELSE
              CALL PUSHCONTROL1B(1)
            END IF
            IF (totflux .GE. 0.) THEN
              x2 = totflux
              CALL PUSHCONTROL1B(0)
            ELSE
              x2 = -totflux
              CALL PUSHCONTROL1B(1)
            END IF
            IF (x2 .LT. senepar) THEN
              max8 = senepar
              CALL PUSHCONTROL1B(0)
            ELSE
              max8 = x2
              CALL PUSHCONTROL1B(1)
            END IF
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bcene(ibw) .EQ. bcene(ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  CALL PUSHINTEGER4(icv)
                END DO
                CALL PUSHINTEGER4(ibc - 1)
                CALL PUSHCONTROL1B(1)
              ELSE
                CALL PUSHCONTROL1B(0)
              END IF
            END DO
            tesb = 0.D0
            DO ibw=nbc,ib,-1
              CALL POPCONTROL1B(branch)
              IF (branch .NE. 0) THEN
                CALL POPINTEGER4(ad_to1)
                DO ibc=ad_to1,1,-1
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  srwb%she0(icv, 1) = 0.D0
                  ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                  tesb = tesb + geo%fcs(ifc)*vbig*ne00*srwb%she0(icv, 0)
                  srwb%she0(icv, 0) = 0.D0
                  CALL POPINTEGER4(icv)
                END DO
              END IF
            END DO
            temp4 = t3/max8
            tempb2 = tes*tesb
            tesb = (1.0_R8-(totflux-senepar)*temp4)*tesb
            totfluxb = -(temp4*tempb2)
            seneparb = seneparb + temp4*tempb2
            tempb3 = -((totflux-senepar)*tempb2/max8)
            t3b = tempb3
            max8b = -(temp4*tempb3)
            CALL POPCONTROL1B(branch)
            IF (branch .EQ. 0) THEN
              seneparb = seneparb + max8b
              x2b = 0.D0
            ELSE
              x2b = max8b
            END IF
            CALL POPCONTROL1B(branch)
            IF (branch .EQ. 0) THEN
              totfluxb = totfluxb + x2b
            ELSE
              totfluxb = totfluxb - x2b
            END IF
            CALL POPCONTROL1B(branch)
            IF (branch .EQ. 0) t3b = 0.D0
            CALL POPCONTROL1B(branch)
            IF (branch .EQ. 0) eneparb(ib, 2) = eneparb(ib, 2) + t3b
            DO ibw=nbc,ib,-1
              CALL POPCONTROL1B(branch)
              IF (branch .NE. 0) THEN
                CALL POPINTEGER4(ad_to0)
                DO ibc=ad_to0,1,-1
                  CALL POPCONTROL1B(branch)
                  IF (branch .EQ. 0) THEN
                    icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                    ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                    tempb2 = -(mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)*&
&                     totfluxb)
                    dvb%fhe(ifc, 0) = dvb%fhe(ifc, 0) + tempb2
                    dvb%fhe(ifc, 1) = dvb%fhe(ifc, 1) + tempb2
                  ELSE
                    icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                    ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                    tempb2 = -(geo%fcs(ifc)*mpg%bcfcor(mpg%bccvp(ibw, 1)&
&                     +ibc-1)*totfluxb)
                    tempb5 = (geo%fcqalf(ifc, 0)*dv%vaecrb(ifc, 0, ns-1)&
&                     +geo%fcqalf(ifc, 1)*dv%vaecrb(ifc, 1, ns-1))*&
&                     tempb2
                    tempb3 = pl%te(icv)*dv%ne(icv)*tempb2
                    dvb%vaecrb(ifc, 0, ns-1) = dvb%vaecrb(ifc, 0, ns-1) &
&                     + geo%fcqalf(ifc, 0)*tempb3
                    dvb%vaecrb(ifc, 1, ns-1) = dvb%vaecrb(ifc, 1, ns-1) &
&                     + geo%fcqalf(ifc, 1)*tempb3
                    plb%te(icv) = plb%te(icv) + dv%ne(icv)*tempb5
                    dvb%ne(icv) = dvb%ne(icv) + pl%te(icv)*tempb5
                    tempb2 = -(mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)*&
&                     totfluxb)
                    dvb%fhe_mdf(ifc, 0) = dvb%fhe_mdf(ifc, 0) + tempb2
                    dvb%fhe_mdf(ifc, 1) = dvb%fhe_mdf(ifc, 1) + tempb2
                  END IF
                  CALL POPINTEGER4(icv)
                END DO
              END IF
            END DO
            tesb = tesb/volsum
            DO ibw=nbc,ib,-1
              CALL POPCONTROL1B(branch)
              IF (branch .NE. 0) THEN
                CALL POPINTEGER4(ad_to)
                DO ibc=ad_to,1,-1
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  plb%te(icv) = plb%te(icv) + geo%cvvol(icv)*tesb
                  CALL POPINTEGER4(icv)
                END DO
              END IF
            END DO
            CALL POPREAL8(volsum, r8/8)
            CALL POPCONTROL1B(branch)
            IF (branch .NE. 0) THEN
              DO ibw=nbc,ib,-1
                CALL POPCONTROL1B(branch)
                IF (branch .NE. 0) eneparb(ibw, 1) = eneparb(ibw, 1) + &
&                   seneparb
              END DO
              seneparb = 0.D0
            END IF
          END IF
        END IF
      END IF
    CASE (17) 
      IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
        totflux = 0.0_R8
        t0 = 0.0_R8
        weight = 0.0_R8
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
          totflux = totflux - (dv%fhe(ifc, 0)+dv%fhe(ifc, 1)+dv%fhi(ifc&
&           , 0)+dv%fhi(ifc, 1)+st_ext%fhi(ifc, 0)+st_ext%fhi(ifc, 1))*&
&           mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          IF (bc_type16_kinetic_energy .EQ. 1) THEN
            DO is=0,ns-1
              CALL PUSHREAL8(result10, r8/8)
              result10 = INTFACE_S(ifc, ncv, nfc, mpg%fccv, geo%fcvol, &
&               dv%kinrgy(1, is))
              totflux = totflux - (1.0_R8-switch%boris)*mpg%bcfcor(mpg%&
&               bccvp(ib, 1)+ibc-1)*(dv%fna(ifc, 0, is)+dv%fna(ifc, 1, &
&               is))*result10
            END DO
            DO is=0,st_ext%ns-1
              CALL PUSHREAL8(result10, r8/8)
              result10 = INTFACE_S(ifc, ncv, nfc, mpg%fccv, geo%fcvol, &
&               st_ext%ua(1, is))
              totflux = totflux - (1.0_R8-switch%boris)*mpg%bcfcor(mpg%&
&               bccvp(ib, 1)+ibc-1)*(st_ext%fa(ifc, 0, is)+st_ext%fa(ifc&
&               , 1, is))*0.5_R8*st_ext%am(is)*mp*result10**2
            END DO
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHCONTROL1B(1)
          END IF
          t0 = t0 + (pl%te(icv)*dv%ne(icv)+pl%ti(icv)*dv%ni(icv, 0))*geo&
&           %cvvol(icv)
          weight = weight + (dv%ne(icv)+dv%ni(icv, 0))*geo%cvvol(icv)
        END DO
        CALL PUSHREAL8(t0, r8/8)
        t0 = t0/weight
        t1b = 0.D0
        DO ibc=mpg%bccvp(ib, 2),1,-1
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          srwb%shi0(icv, 1) = 0.D0
          ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
          srwb%she0(icv, 1) = 0.D0
          t1b = t1b + geo%fcs(ifc)*vbig*ne00*srwb%shi0(icv, 0) + geo%fcs&
&           (ifc)*vbig*ne00*srwb%she0(icv, 0)
          srwb%shi0(icv, 0) = 0.D0
          srwb%she0(icv, 0) = 0.D0
        END DO
        temp4 = enipar(ib, 2)/enipar(ib, 1)
        temp3 = enepar(ib, 1) + enipar(ib, 1)
        temp0 = totflux*enipar(ib, 1)/temp3
        temp = enepar(ib, 2)/enepar(ib, 1)
        temp6 = enepar(ib, 1) + enipar(ib, 1)
        temp7 = totflux*enepar(ib, 1)/temp6
        tempb2 = t0*t1b
        t0b = (1.0_R8-(temp0-enipar(ib, 1))*temp4-(temp7-enepar(ib, 1))*&
&         temp)*t1b
        tempb0 = -(temp4*tempb2/temp3)
        tempb3 = -((temp0-enipar(ib, 1))*tempb2/enipar(ib, 1))
        tempb6 = -(temp*tempb2/temp6)
        tempb = -((temp7-enepar(ib, 1))*tempb2/enepar(ib, 1))
        eneparb(ib, 2) = eneparb(ib, 2) + tempb
        totfluxb = enepar(ib, 1)*tempb6 + enipar(ib, 1)*tempb0
        tempb7 = -(temp7*tempb6)
        eniparb(ib, 2) = eniparb(ib, 2) + tempb3
        tempb4 = -(temp0*tempb0)
        eniparb(ib, 1) = eniparb(ib, 1) + temp4*tempb2 + tempb7 + &
&         totflux*tempb0 - temp4*tempb3 + tempb4
        eneparb(ib, 1) = eneparb(ib, 1) + temp*tempb2 + totflux*tempb6 -&
&         temp*tempb + tempb7 + tempb4
        CALL POPREAL8(t0, r8/8)
        weightb = -(t0*t0b/weight**2)
        t0b = t0b/weight
        DO ibc=mpg%bccvp(ib, 2),1,-1
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          tempb2 = geo%cvvol(icv)*weightb
          dvb%ne(icv) = dvb%ne(icv) + tempb2
          dvb%ni(icv, 0) = dvb%ni(icv, 0) + tempb2
          tempb2 = geo%cvvol(icv)*t0b
          plb%te(icv) = plb%te(icv) + dv%ne(icv)*tempb2
          dvb%ne(icv) = dvb%ne(icv) + pl%te(icv)*tempb2
          plb%ti(icv) = plb%ti(icv) + dv%ni(icv, 0)*tempb2
          dvb%ni(icv, 0) = dvb%ni(icv, 0) + pl%ti(icv)*tempb2
          ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            DO is=st_ext%ns-1,0,-1
              CALL POPREAL8(result10, r8/8)
            END DO
            DO is=ns-1,0,-1
              tempb2 = -((1.0_R8-switch%boris)*mpg%bcfcor(mpg%bccvp(ib, &
&               1)+ibc-1)*totfluxb)
              dvb%fna(ifc, 0, is) = dvb%fna(ifc, 0, is) + result10*&
&               tempb2
              dvb%fna(ifc, 1, is) = dvb%fna(ifc, 1, is) + result10*&
&               tempb2
              result10b = (dv%fna(ifc, 0, is)+dv%fna(ifc, 1, is))*tempb2
              CALL POPREAL8(result10, r8/8)
              CALL INTFACE_S_B(ifc, ncv, nfc, mpg%fccv, geo%fcvol, dv%&
&                        kinrgy(1, is), dvb%kinrgy(1, is), result10b)
            END DO
          END IF
          tempb2 = -(mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*totfluxb)
          dvb%fhe(ifc, 0) = dvb%fhe(ifc, 0) + tempb2
          dvb%fhe(ifc, 1) = dvb%fhe(ifc, 1) + tempb2
          dvb%fhi(ifc, 0) = dvb%fhi(ifc, 0) + tempb2
          dvb%fhi(ifc, 1) = dvb%fhi(ifc, 1) + tempb2
        END DO
      END IF
    CASE (18) 
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        srwb%she0(icv1, 1) = 0.D0
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        t1b = geo%fcs(ifc)*vbig*ne00*srwb%she0(icv1, 0)
        srwb%she0(icv1, 0) = 0.D0
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
        eneparb(ib, 1) = eneparb(ib, 1) - pl%te(icv2)*t1b
        plb%te(icv2) = plb%te(icv2) + (1.0_R8-enepar(ib, 1))*t1b
      END DO
    CASE (19) 

    CASE (20) 
      IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
        totflux = 0.0_R8
        t0 = 0.0_R8
        weight = 0.0_R8
        teave = 0.0_R8
        neave = 0.0_R8
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          totflux = totflux - mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%fhe&
&           (ifc, 0)+dv%fhe(ifc, 1))
          t0 = t0 + pl%te(icv1)*dv%ne(icv1)*geo%cvvol(icv1)
          weight = weight + dv%ne(icv1)*geo%cvvol(icv1)
          teave = teave + pl%te(icv2)*dv%ne(icv2)*geo%cvvol(icv2)
          neave = neave + dv%ne(icv2)*geo%cvvol(icv2)
        END DO
        CALL PUSHREAL8(t0, r8/8)
        t0 = t0/weight
        CALL PUSHREAL8(teave, r8/8)
        teave = teave/neave
        IF (enepar(ib, 2) .GT. 0.0_R8) THEN
          t3 = enepar(ib, 2)
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        IF (enepar(ib, 2) .LE. 0.0_R8) THEN
          t3 = switch%b2stbc_bc_ref_te
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        t1 = (1.0_R8-t3*(totflux-enepar(ib, 1))/enepar(ib, 1))*t0
        teaveb = 0.D0
        t1b = 0.D0
        DO ibc=mpg%bccvp(ib, 2),1,-1
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          srwb%she0(icv1, 1) = 0.D0
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          tempb2 = vbig*ne00*geo%fcs(ifc)*srwb%she0(icv1, 0)
          srwb%she0(icv1, 0) = 0.D0
          plb%te(icv2) = plb%te(icv2) + t1*tempb2/teave
          tempb6 = pl%te(icv2)*tempb2/teave
          t1b = t1b + tempb6
          teaveb = teaveb - t1*tempb6/teave
        END DO
        temp7 = t3/enepar(ib, 1)
        tempb2 = t0*t1b
        t0b = (1.0_R8-(totflux-enepar(ib, 1))*temp7)*t1b
        totfluxb = -(temp7*tempb2)
        tempb6 = -((totflux-enepar(ib, 1))*tempb2/enepar(ib, 1))
        eneparb(ib, 1) = eneparb(ib, 1) + temp7*tempb2 - temp7*tempb6
        t3b = tempb6
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) t3b = 0.D0
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) eneparb(ib, 2) = eneparb(ib, 2) + t3b
        CALL POPREAL8(teave, r8/8)
        neaveb = -(teave*teaveb/neave**2)
        teaveb = teaveb/neave
        CALL POPREAL8(t0, r8/8)
        weightb = -(t0*t0b/weight**2)
        t0b = t0b/weight
        DO ibc=mpg%bccvp(ib, 2),1,-1
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          tempb2 = geo%cvvol(icv2)*teaveb
          dvb%ne(icv2) = dvb%ne(icv2) + geo%cvvol(icv2)*neaveb + pl%te(&
&           icv2)*tempb2
          plb%te(icv2) = plb%te(icv2) + dv%ne(icv2)*tempb2
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          tempb2 = geo%cvvol(icv1)*t0b
          dvb%ne(icv1) = dvb%ne(icv1) + geo%cvvol(icv1)*weightb + pl%te(&
&           icv1)*tempb2
          plb%te(icv1) = plb%te(icv1) + dv%ne(icv1)*tempb2
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          tempb2 = -(mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*totfluxb)
          dvb%fhe(ifc, 0) = dvb%fhe(ifc, 0) + tempb2
          dvb%fhe(ifc, 1) = dvb%fhe(ifc, 1) + tempb2
        END DO
      END IF
    CASE (21) 
      IF ((bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'N') .OR. bcchar(ib)&
&         .EQ. 'A') THEN
        teave = 0.0_R8
        neave = 0.0_R8
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          teave = teave + pl%te(icv)*dv%ne(icv)*geo%cvvol(icv)
          neave = neave + dv%ne(icv)*geo%cvvol(icv)
        END DO
        CALL PUSHREAL8(teave, r8/8)
        teave = teave/neave
        IF (enepar(ib, 2) .GT. 0.0_R8) THEN
          t3 = enepar(ib, 2)
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        IF (enepar(ib, 2) .LE. 0.0_R8) THEN
          t3 = switch%b2stbc_bc_ref_te
          CALL PUSHCONTROL1B(1)
        ELSE
          CALL PUSHCONTROL1B(0)
        END IF
        teaveb = 0.D0
        t3b = 0.D0
        DO ibc=mpg%bccvp(ib, 2),1,-1
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          srwb%she0(icv1, 1) = 0.D0
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          temp6 = t3/teave
          tempb6 = vbig*ne00*ev*geo%fcs(ifc)*srwb%she0(icv1, 0)
          srwb%she0(icv1, 0) = 0.D0
          eneparb(ib, 1) = eneparb(ib, 1) + (pl%te(icv2)*temp6-t3+1.0_R8&
&           )*tempb6
          tempb2 = enepar(ib, 1)*tempb6
          plb%te(icv2) = plb%te(icv2) + temp6*tempb2
          tempb7 = pl%te(icv2)*tempb2/teave
          t3b = t3b + tempb7 - tempb2
          teaveb = teaveb - temp6*tempb7
        END DO
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) t3b = 0.D0
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) eneparb(ib, 2) = eneparb(ib, 2) + t3b
        CALL POPREAL8(teave, r8/8)
        neaveb = -(teave*teaveb/neave**2)
        teaveb = teaveb/neave
        DO ibc=mpg%bccvp(ib, 2),1,-1
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          tempb2 = geo%cvvol(icv)*teaveb
          dvb%ne(icv) = dvb%ne(icv) + geo%cvvol(icv)*neaveb + pl%te(icv)&
&           *tempb2
          plb%te(icv) = plb%te(icv) + dv%ne(icv)*tempb2
        END DO
      END IF
    CASE (22) 
!wdk    Notes:
!wdk     * need correction for misaligned grids -> t1
!wdk     * need to correct this BC for hybrid scheme
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
! number of the guard cell face
        CALL PUSHREAL8(vte, r8/8)
        vte = SQRT(pl%te(icv1)/me)
      END DO
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        t0 = geo%fcqalf(ifc, 1)
        tempb6 = -(vbig*ne00*ev*srwb%she0(icv1, 1))
        srwb%she0(icv1, 1) = 0.D0
        tempb7 = -(geo%fcs(ifc)*tempb6)
        tempb3 = dv%ne(icv1)*tempb7
        dvb%ne(icv1) = dvb%ne(icv1) + enepar(ib, 1)*vte*tempb7
        eneparb(ib, 1) = eneparb(ib, 1) + vte*tempb3
        vteb = enepar(ib, 1)*tempb3
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
        t1 = (geo%fchc(ifc, 1)+geo%fchc(ifc, 2))/geo%fcht(ifc)*geo%&
&         fcqbet(ifc, 0)
        temp7 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*t1
        tempb2 = vbig*ne00*ev*srwb%she0(icv1, 0)
        cob%chce(ifc, 1) = cob%chce(ifc, 1) + t0*tempb6 + (t0*pl%te(icv2&
&         )-temp7*(pl%te(mpg%fcvx(ifc, 2))-pl%te(mpg%fcvx(ifc, 1))))*&
&         tempb2
        srwb%she0(icv1, 0) = 0.D0
        tempb7 = co%chce(ifc, 1)*tempb2
        plb%te(icv2) = plb%te(icv2) + t0*tempb7
        plb%te(mpg%fcvx(ifc, 2)) = plb%te(mpg%fcvx(ifc, 2)) - temp7*&
&         tempb7
        plb%te(mpg%fcvx(ifc, 1)) = plb%te(mpg%fcvx(ifc, 1)) + temp7*&
&         tempb7
        CALL POPREAL8(vte, r8/8)
        IF (.NOT.pl%te(icv1)/me .EQ. 0.D0) plb%te(icv1) = plb%te(icv1) +&
&           vteb/(me*2.0*SQRT(pl%te(icv1)/me))
      END DO
    CASE (23) 
!
!
! -- BCENE=23 -- Prescribe the value of the electron temperature, with poloidal
!                perturbation taken from flux tube just inside domain
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        IF (switch%use_astra .NE. 0) THEN
          CALL PUSHCONTROL2B(0)
        ELSE
          CALL PUSHCONTROL2B(1)
        END IF
      ELSE
        CALL PUSHCONTROL2B(2)
      END IF
!     ..compute average temperature on core boundary
      t0 = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
        IF (mpg%cvonclosedsurface(icv1)) THEN
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            t0 = t0 + geo%cvvol(icv2)
          END DO
          CALL PUSHINTEGER4(ibc0 - 1)
          CALL PUSHCONTROL1B(1)
        ELSE
          CALL PUSHCONTROL1B(0)
        END IF
      END DO
      t1b = 0.D0
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        srwb%she0(icv1, 1) = 0.D0
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        tempb2 = vbig*ne00*geo%fcs(ifc)*srwb%she0(icv1, 0)
        srwb%she0(icv1, 0) = 0.D0
        plb%te(icv2) = plb%te(icv2) + tempb2
        eneparb(ib, 1) = eneparb(ib, 1) + ev*tempb2
        t1b = t1b - tempb2
      END DO
      t1b = t1b/t0
      DO ib0=nbc,1,-1
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) THEN
          CALL POPINTEGER4(ad_to2)
          DO ibc0=ad_to2,1,-1
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
            plb%te(icv2) = plb%te(icv2) + geo%cvvol(icv2)*t1b
          END DO
        END IF
      END DO
      CALL POPCONTROL2B(branch)
      IF (branch .EQ. 0) eneparb(ib, 1) = 0.D0
    CASE (24) 
!     ..compute average temperature on core boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
      totflux = 0.0_R8
      totpar = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        CALL PUSHINTEGER4(icv1)
        icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
        IF (mpg%cvonclosedsurface(icv1)) THEN
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            t0 = t0 + geo%cvvol(icv2)
            t1 = t1 + geo%cvvol(icv2)*pl%te(icv1)
            totflux = totflux - (dv%fhe(ifc, 0)+dv%fhe(ifc, 1))*mpg%&
&             bcfcor(mpg%bccvp(ib0, 1)+ibc0-1)
          END DO
          CALL PUSHINTEGER4(ibc0 - 1)
          totpar = totpar + enepar(ib0, 1)
          CALL PUSHCONTROL1B(1)
        ELSE
          CALL PUSHCONTROL1B(0)
        END IF
      END DO
      totpar = fac_he_anom_bc*totpar
      t1 = t1/t0
      IF (enepar(ib, 2) .GT. 0.0_R8) THEN
        t3 = enepar(ib, 2)
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHCONTROL1B(1)
      END IF
      IF (enepar(ib, 2) .LE. 0.0_R8) THEN
        t3 = switch%b2stbc_bc_ref_te
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHCONTROL1B(1)
      END IF
      IF (totflux .GE. 0.) THEN
        x3 = totflux
        CALL PUSHCONTROL1B(0)
      ELSE
        x3 = -totflux
        CALL PUSHCONTROL1B(1)
      END IF
      IF (totpar .GE. 0.) THEN
        y4 = totpar
        CALL PUSHCONTROL1B(0)
      ELSE
        y4 = -totpar
        CALL PUSHCONTROL1B(1)
      END IF
      IF (x3 .LT. y4) THEN
        max9 = y4
        CALL PUSHCONTROL1B(0)
      ELSE
        max9 = x3
        CALL PUSHCONTROL1B(1)
      END IF
!     ..impose temperature with perturbation
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        CALL PUSHINTEGER4(icv1)
! number of the domain cell
! number of the guard cell face
      END DO
      t2b = 0.D0
      t4b = 0.D0
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        srwb%she0(icv1, 1) = 0.D0
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        tempb2 = vbig*ne00*geo%fcs(ifc)*srwb%she0(icv1, 0)
        srwb%she0(icv1, 0) = 0.D0
        plb%te(icv2) = plb%te(icv2) + tempb2
        t4b = t4b + tempb2
        t2b = t2b - tempb2
        CALL POPINTEGER4(icv1)
      END DO
      temp7 = t3/max9
      tempb2 = t1*t4b
      t1b = (1.0_R8-(totflux-totpar)*temp7)*t4b
      totfluxb = -(temp7*tempb2)
      totparb = temp7*tempb2
      tempb6 = -((totflux-totpar)*tempb2/max9)
      t3b = tempb6
      max9b = -(temp7*tempb6)
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        y4b = max9b
        x3b = 0.D0
      ELSE
        x3b = max9b
        y4b = 0.D0
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        totparb = totparb + y4b
      ELSE
        totparb = totparb - y4b
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        totfluxb = totfluxb + x3b
      ELSE
        totfluxb = totfluxb - x3b
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) t3b = 0.D0
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) eneparb(ib, 2) = eneparb(ib, 2) + t3b
      t2b = t2b/t0
      t1b = t1b/t0
      totparb = fac_he_anom_bc*totparb
      DO ib0=nbc,1,-1
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) THEN
          eneparb(ib0, 1) = eneparb(ib0, 1) + totparb
          CALL POPINTEGER4(ad_to3)
          DO ibc0=ad_to3,1,-1
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            tempb2 = -(mpg%bcfcor(mpg%bccvp(ib0, 1)+ibc0-1)*totfluxb)
            dvb%fhe(ifc, 0) = dvb%fhe(ifc, 0) + tempb2
            dvb%fhe(ifc, 1) = dvb%fhe(ifc, 1) + tempb2
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
            plb%te(icv2) = plb%te(icv2) + geo%cvvol(icv2)*t2b
            plb%te(icv1) = plb%te(icv1) + geo%cvvol(icv2)*t1b
          END DO
        END IF
        CALL POPINTEGER4(icv1)
      END DO
    END SELECT
  END SUBROUTINE B2STBC_PHYS_ENE_B

!
  SUBROUTINE B2STBC_PHYS_ENE(ib)
    IMPLICIT NONE
    INTEGER :: ib, ibw, ibc, ibc0, ib0, is, ism
    INTEGER :: icv, icv1, icv2, ifc, ivx1, ivx2
    REAL(kind=r8) :: cs, vte, s1, t0, t1, t2, t3, t4, neave, totpar, &
&   totflux, teave, weight, wrk
    REAL(kind=r8), EXTERNAL :: INTVERTEX_S_NODIFF
    EXTERNAL XERRAB
    INTRINSIC MIN
    INTRINSIC SQRT
    INTRINSIC ABS
    REAL(r8) :: y1
    REAL(r8) :: y2
    REAL(kind=r8) :: x1
    REAL(kind=r8) :: y3
    REAL(kind=r8) :: x2
    REAL(kind=r8) :: x3
    REAL(kind=r8) :: y4
    REAL(r8) :: max1
    REAL(r8) :: min1
    REAL(r8) :: max2
    REAL(r8) :: min2
    REAL(r8) :: max3
    REAL(r8) :: max4
    REAL(r8) :: min3
    REAL(r8) :: max5
    REAL(r8) :: min4
    REAL(kind=r8) :: abs0
    REAL(r8) :: min5
    REAL(r8) :: max6
    REAL(r8) :: min6
    REAL(kind=r8) :: max7
    REAL(kind=r8) :: max8
    REAL(kind=r8) :: max9
    REAL(kind=r8) :: abs1
    REAL(kind=r8) :: result10
!
! -- BOUNDARY CONDITIONS FOR ELECTRON ENERGY EQUATION --
!
    SELECT CASE  (bcene(ib)) 
    CASE (0) 

    CASE (1) 
!
!
! -- BCENE=1 -- PRESCRIBE THE VALUE OF THE ELECTRON TEMPERATURE
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        IF (bcchar(ib) .EQ. 'S' .AND. switch%use_astra .NE. 0) THEN
!srv 14.06.12
          enepar(ib, 1) = teb_astra*1.0e3_R8
        END IF
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENE =  1 : specified electron temperature ', enepar(ib, 1), &
&       ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enepar(ib, 1) .GT. 0.0_R8, &
&             'BCENE = 1, ENEPAR(,1) !> 0')
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        srw%she0(icv, 0) = vbig*ne00*geo%fcs(ifc)*enepar(ib, 1)*ev
        srw%she0(icv, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (2) 
!
! -- BCENE=2 -- PRESCRIBE THE GRADIENT OF THE ELECTRON TEMPERATURE
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                          'BCENE =  2 : electron temperature gradient '&
&                                   , enepar(ib, 1), ' on ', bcchar(ib)&
&                                   , boundary_location(ib)
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        ivx1 = mpg%fcvx(ifc, 1)
        ivx2 = mpg%fcvx(ifc, 2)
        t1 = INTVERTEX_S_NODIFF(ivx1, ncv, nvx, mpg, geo%vxvol, pl%te)
        t2 = INTVERTEX_S_NODIFF(ivx2, ncv, nvx, mpg, geo%vxvol, pl%te)
        srw%she0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*(ev*enepar(ib, 1)*(&
&         geo%fchc(ifc, 1)+geo%fchc(ifc, 2))*geo%fcqgam(ifc, 0)-cor9*(t2&
&         -t1)*geo%fcqgam(ifc, 1)*(geo%fchc(ifc, 1)+geo%fchc(ifc, 2))/&
&         geo%fcht(ifc)*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)+pl%te(icv2))
        srw%she0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (3) 
!
! -- BCENE=3 -- SHEATH CONDITIONS, ELECTRON ENERGY TRANSMISSION
!
      CALL XERRAB('b2stbc_phys -- BCENE = 3 not adapted for WG.'//&
&           ' Replace with drift-compatible BCENE = 15')
!
! -- BCENE=4 -- PRESCRIBE THE VALUE OF THE ELECTRON TEMPERATURE,
!                 WEAKLY A MIXED BOUNDARY CONDITION
!
    CASE (4) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENE =  4 : weak electron temperature ', enepar(ib, 1), ' on '&
&       , bcchar(ib), boundary_location(ib)
        CALL XERTST(enepar(ib, 1) .GT. 0.0_R8, &
&             'BCENE = 4, ENEPAR(,1) !> 0')
        CALL XERTST(enepar(ib, 2) .GT. 0.0_R8, &
&             'BCENE = 4, ENEPAR(,2) !> 0')
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        srw%she0(icv, 0) = enepar(ib, 2)*geo%fcs(ifc)*enepar(ib, 1)
        srw%she0(icv, 1) = -(enepar(ib, 2)/ev*geo%fcs(ifc))
      END DO
    CASE (5) 
!
! -- BCENE=5 -- PRESCRIBE THE ELECTRON ENERGY FLUX PER UNIT AREA
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                          'BCENE =  5 : electron energy flux per area '&
&                                   , enepar(ib, 1), ' on ', bcchar(ib)&
&                                   , boundary_location(ib)
      DO ibc=1,mpg%bccvp(ib, 2)
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        srw%she0(icv, 0) = enepar(ib, 1)*geo%fcs(ifc)
        srw%she0(icv, 1) = 0.0_R8
      END DO
    CASE (6) 
!
! -- BCENE=6 -- PRESCRIBE THE TOTAL ELECTRON ENERGY FLUX FOR A
!                 CONSTANT ELECTRON TEMPERATURE
!
      CALL XERRAB('b2stbc_phys -- BCENE = 6 not adapted for WG')
!
! -- BCENE=7 -- PRESCRIBE THE ELECTRON TEMPERATURE PROFILE
!
    CASE (7) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
!srv 26.02.18 {
        WRITE(*, '(3a)') &
&       'BCENE = 7 : specified electron temperature on ', bcchar(ib), &
&       boundary_location(ib)
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%she0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*bv_te(icv1)*ev
        srw%she0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (8) 
!
! -- BCENE=8 -- PRESCRIBE THE TOTAL ELECTRON HEAT FLUX WITH CONSTANT
!                 FLUX DENSITY
!wdk BC not recommended for drifts!
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        IF (switch%use_astra .NE. 0) CALL XERRAB(&
&                      'Compile with -DASTRA option to couple to ASTRA!'&
&                                         )
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENE =  8 : total electron energy flux ', enepar(ib, 1), &
&       ' on ', bcchar(ib), boundary_location(ib)
      END IF
      us = 0.0_R8
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        us = us + geo%fcs(ifc)
      END DO
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%she0(icv1, 0) = fac_he_anom_bc*enepar(ib, 1)/us*geo%fcs(ifc)
        srw%she0(icv1, 1) = 0.0_R8
        IF (switch%mdf_fhe .NE. 0) THEN
!wdk Correction now involves vedia instead of ExB velocity
!wdk This makes implementation equivalent to mdf_f = 0 option
          srw%she0(icv1, 0) = srw%she0(icv1, 0) + mpg%bcfcor(mpg%bccvp(&
&           ib, 1)+ibc-1)*(dv%fhepsch(ifc, 0)+dv%fhepsch(ifc, 1))
          t0 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*2.5_R8*(geo%fcs(ifc)*&
&           geo%fcqalf(ifc, 0)*dv%vedia(ifc, 0)+geo%fcs(ifc)*geo%fcqalf(&
&           ifc, 1)*dv%vedia(ifc, 1))*0.5_R8*(dv%ne(icv1)+dv%ne(icv2))*&
&           0.5_R8*(pl%te(icv1)+pl%te(icv2))
          IF (0.0_R8 .LT. t0) THEN
            max1 = t0
          ELSE
            max1 = 0.0_R8
          END IF
          srw%she0(icv1, 0) = srw%she0(icv1, 0) + max1
          IF (0.0_R8 .GT. t0) THEN
            min1 = t0
          ELSE
            min1 = 0.0_R8
          END IF
          srw%she0(icv1, 1) = srw%she0(icv1, 1) + min1/pl%te(icv1)
        END IF
      END DO
    CASE (9) 
!
! -- BCENE=9 -- PRESCRIBE THE DECAY LENGTH FOR THE ELECTRON TEMPERATURE
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENE =  9 : electron temperature decay length ', enepar(ib, 1)&
&       , ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enepar(ib, 1) .NE. 0.0_R8, &
&             'BCENE = 9, ENEPAR(,1) = 0')
        ism = 0
        DO is=0,ns-1
          IF (bccon(is, ib) .NE. 9 .AND. (.NOT.is_neutral(is))) THEN
            ism = ism + 1
            WRITE(0, *) &
&           'Should use BCCON(IS,IB).EQ.9 together with BCENE=9'
            WRITE(*, *) &
&           'Should use BCCON(IS,IB).EQ.9 together with BCENE=9'
          END IF
          IF (bccon(is, ib) .EQ. 1) WRITE(0, *) &
&                      'Should use BCENE=19 in conjunction with BCCON=1'
          IF (ism .GT. 0) THEN
!srv 21.09.12
            WRITE(*, '(1x,a)') &
&           'Please ensure that this boundary condition '//&
&           'is consistent with the density boundary conditions'
          END IF
        END DO
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        sy = geo%fcs(ifc)
        srw%she0(icv1, 0) = 0.0_R8
        srw%she0(icv1, 1) = -(co%hce0(icv1)/enepar(ib, 1)*sy)
        DO is=0,ns-1
          srw%she0(icv1, 0) = srw%she0(icv1, 0) + rt%rza(icv1, is)*&
&           fac_he_anom*pl%te(icv1)*srw%sna0(icv1, 0, is)
          srw%she0(icv1, 1) = srw%she0(icv1, 1) + rt%rza(icv1, is)*&
&           fac_he_anom*srw%sna0(icv1, 1, is)*pl%na(icv1, is)
!! end species loop
        END DO
        IF (switch%mdf_fhe .NE. 0) THEN
          srw%she0(icv1, 0) = srw%she0(icv1, 0) + mpg%bcfcor(mpg%bccvp(&
&           ib, 1)+ibc-1)*(dv%fhepsch(ifc, 0)+dv%fhepsch(ifc, 1))
          t0 = -(mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*1.5_R8*(geo%fcs(ifc)&
&           *geo%fcqalf(ifc, 0)*dv%veecrb(ifc, 0)+geo%fcs(ifc)*geo%&
&           fcqalf(ifc, 1)*dv%veecrb(ifc, 1))*0.5_R8*(dv%ne(icv1)+dv%ne(&
&           icv2))*0.5_R8*(pl%te(icv1)+pl%te(icv2)))
          IF (0.0_R8 .LT. t0) THEN
            max2 = t0
          ELSE
            max2 = 0.0_R8
          END IF
          srw%she0(icv1, 0) = srw%she0(icv1, 0) + max2
          IF (0.0_R8 .GT. t0) THEN
            min2 = t0
          ELSE
            min2 = 0.0_R8
          END IF
          srw%she0(icv1, 1) = srw%she0(icv1, 1) + min2/pl%te(icv1)
        END IF
!! end loop over cells

      END DO
    CASE (10) 
!
! -- BCENE=10 -- Feedback option for core
!
      CALL XERRAB('b2stbc_phys -- BCENE = 10 not adapted for WG')
!
! -- BCENE=11 -- FROM B2STBC_SPB                                       !srv 01.02.09 {
!srv added accumulation in order to account twice b.c. for corner cells
    CASE (11) 
      CALL XERRAB('b2stbc_phys -- BCENE = 11 not adapted for WG')
!
! -- BCENE=12 -- SHEATH CONDITIONS, EL ENERGY TRANSMISSION COEFFICIENT
!
    CASE (12) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,a,a,a,1p,g14.7)') &
&       'BCENE = 12 : sheath electron bc on ', bcchar(ib), &
&       boundary_location(ib), ' with transmission coefficient ', enepar&
&       (ib, 1)
        WRITE(*, '(a)') &
&       'Obsolete. Use drift-compatible BCENE = 15 instead'
      END IF
      DO ibc=1,mpg%bccvp(ib, 2)
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        IF (0.0_R8 .LT. mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%fne(ifc, &
&           0)+dv%fne(ifc, 1))) THEN
          max3 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%fne(ifc, 0)+dv%&
&           fne(ifc, 1))
        ELSE
          max3 = 0.0_R8
        END IF
        srw%she0(icv, 3) = srw%she0(icv, 3) - enepar(ib, 1)*max3/dv%ne(&
&         icv)
      END DO
    CASE (13) 
!
! -- BCENE=13 -- PRESCRIBE THE ELECTRON ENERGY FLUX PER UNIT AREA
!             -- PROPORTIONAL TO TEMPERATURE
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                          'BCENE = 13 : electron energy flux per area '&
&                                   //'proportional to temperature ', &
&                                   enepar(ib, 1), ' on ', bcchar(ib), &
&                                   boundary_location(ib)
      DO ibc=1,mpg%bccvp(ib, 2)
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        srw%she0(icv, 0) = enepar(ib, 1)*pl%te(icv)*geo%fcs(ifc)
        srw%she0(icv, 1) = 0.0_R8
      END DO
    CASE (14) 
!
! -- BCENE=14 -- leakage option for electron energy
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                'BCENE = 14 : electron energy leakage '&
&                                   , enepar(ib, 1), ' on ', bcchar(ib)&
&                                   , boundary_location(ib)
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        cs = SQRT(pz(icv1)/rz(icv1))
        srw%she0(icv1, 0) = geo%fcs(ifc)*cs*dv%ne(icv1)*fac_he_anom_bc*&
&         enepar(ib, 1)*enepar(ib, 2)*pl%po(icv1)*qe
        srw%she0(icv1, 3) = geo%fcs(ifc)*cs*fac_he_anom_bc*enepar(ib, 1)
        IF (switch%mdf_fhe .NE. 0) THEN
          srw%she0(icv1, 0) = srw%she0(icv1, 0) + mpg%bcfcor(mpg%bccvp(&
&           ib, 1)+ibc-1)*(dv%fhepsch(ifc, 0)+dv%fhepsch(ifc, 1))
          t0 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*2.5_R8*(geo%fcs(ifc)*&
&           geo%fcqalf(ifc, 0)*dv%vedia(ifc, 0)+geo%fcs(ifc)*geo%fcqalf(&
&           ifc, 1)*dv%vedia(ifc, 1))*0.5_R8*(dv%ne(icv1)+dv%ne(icv2))*&
&           0.5_R8*(pl%te(icv1)+pl%te(icv2))
          IF (0.0_R8 .LT. t0) THEN
            max4 = t0
          ELSE
            max4 = 0.0_R8
          END IF
          srw%she0(icv1, 0) = srw%she0(icv1, 0) + max4
          IF (0.0_R8 .GT. t0) THEN
            min3 = t0
          ELSE
            min3 = 0.0_R8
          END IF
          srw%she0(icv1, 1) = srw%she0(icv1, 1) + min3/pl%te(icv1)
        END IF
      END DO
    CASE (15) 
!
! -- BCENE=15 -- DRIFT-COMPATIBLE SHEATH CONDITION                      !srv 01.02.09 {
!srv 20.09.17 }
      IF (ncall_b2stbc_phys .EQ. 0) THEN
!srv 20.09.17 {
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENE = 15 (style = 0) : with GAMMAE =', gammae, ' on ', bcchar&
&       (ib), boundary_location(ib)
        WRITE(*, *) 'BCENE=15 - should have BCCON=14 for all ions'
        bccon14_is(ib) = .true.
        DO is=0,ns-1
          IF (.NOT.is_neutral(is)) bccon14_is(ib) = bccon14_is(ib) .AND.&
&             bccon(is, ib) .EQ. 14
        END DO
        IF (bccon14_is(ib)) WRITE(*, '(a,a,i3,a)') 'BCCON=14 HAS ', &
&                           'BEEN IMPOSED AT BOUNDARY ', ib, &
&                           ' FOR ALL IONS'
        IF (.NOT.bccon14_is(ib)) WRITE(*, '(a,a,i3,a)') 'BCCON=14 ', &
&                                'HAS NOT BEEN IMPOSED AT BOUNDARY ', ib&
&                                , ' FOR ALL IONS'
      END IF
!srv 01.02.09 }
!srv added accumulation in order to account twice b.c. for corner cells
      IF (bcene_15_style .EQ. 0) THEN
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                               'BCENE = 15 (style = 0) : with GAMMAE ='&
&                                     , gammae, ' on ', bcchar(ib), &
&                                     boundary_location(ib)
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          cs = SQRT(pz(icv1)/rz(icv1))
          t0 = dv%ne(icv1)
          t1 = 0.0_R8
          DO is=0,ns-1
            IF (.NOT.is_neutral(is) .AND. conpar(is, ib, 2) .GT. 0.0_R8&
&           ) t1 = t1 + co%dna0(icv1, is)/conpar(is, ib, 2)*rt%rza(icv1&
&               , is)*pl%na(icv1, is)
          END DO
          IF (geo%fcpbs(ifc) .GE. 0.) THEN
            abs1 = geo%fcpbs(ifc)
          ELSE
            abs1 = -geo%fcpbs(ifc)
          END IF
          y1 = abs1*t0*cs - dv%fch_p(ifc, 0)*mpg%bcfcor(mpg%bccvp(ib, 1)&
&           +ibc-1)/qe
          IF (0.0_R8 .LT. y1) THEN
            t0 = y1
          ELSE
            t0 = 0.0_R8
          END IF
          t1 = t1*geo%fcs(ifc)
!srv 27.02.13 }
          IF (switch%pot_eq .EQ. 1) THEN
!srv 27.02.13 {
!srv 11.03.09 {
!srv 19.04.13
!wdk to check: correct for gammae?
            srw%she0(icv1, 1) = srw%she0(icv1, 1) - (1.0_R8+gammae)/(&
&             1.0_R8-gammae)*t0 - fac_he_anom_bc*enepar(ib, 2)*t1
!srv 07.11.12
            srw%she0(icv1, 0) = srw%she0(icv1, 0) - qe*(pl%po(icv1)-&
&             potpar(ib, 2))*(t0+t1)
          ELSE
!srv 27.02.13
!srv 11.03.09 {
!srv 19.04.13
!wdk to check: correct for gammae?
            srw%she0(icv1, 1) = srw%she0(icv1, 1) - ((1.0_R8+gammae)/(&
&             1.0_R8-gammae)+switch%delpo)*t0 - (fac_he_anom_bc*enepar(&
&             ib, 2)+switch%delpo)*t1
          END IF
          IF (switch%mdf_fhe .NE. 0) THEN
            srw%she0(icv1, 0) = srw%she0(icv1, 0) + mpg%bcfcor(mpg%bccvp&
&             (ib, 1)+ibc-1)*(dv%fhepsch(ifc, 0)+dv%fhepsch(ifc, 1))
            t0 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*2.5_R8*(geo%fcs(ifc)&
&             *geo%fcqalf(ifc, 0)*dv%vedia(ifc, 0)+geo%fcs(ifc)*geo%&
&             fcqalf(ifc, 1)*dv%vedia(ifc, 1))*0.5_R8*(dv%ne(icv1)+dv%ne&
&             (icv2))*0.5_R8*(pl%te(icv1)+pl%te(icv2))
            IF (0.0_R8 .LT. t0) THEN
              max5 = t0
            ELSE
              max5 = 0.0_R8
            END IF
            srw%she0(icv1, 0) = srw%she0(icv1, 0) + max5
            IF (0.0_R8 .GT. t0) THEN
              min4 = t0
            ELSE
              min4 = 0.0_R8
            END IF
            srw%she0(icv1, 1) = srw%she0(icv1, 1) + min4/pl%te(icv1)
          END IF
        END DO
      ELSE IF (bcene_15_style .EQ. 1) THEN
!wdk    Todo: corrections for BCCON.ne.14
        IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, &
&                                     '(a,1p,g14.7,a,g14.7,a,a,a)') &
&                              'BCENE = 15 (style = 1) : with GAMMAE = '&
&                                     , gammae, ' and ENEPAR(IB,1) = ', &
&                                     enepar(ib, 1), ' (def = 0), on ', &
&                                     bcchar(ib), boundary_location(ib)
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          vte = SQRT(pl%te(icv1)/me)
          IF (geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3) .GE. &
&             0.) THEN
            wrk = geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3)
          ELSE
            wrk = -(geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3)&
&             )
          END IF
          IF (wrk .LT. geo%qalfmin) THEN
            IF (geo%fcs(ifc) .GE. 0.) THEN
              abs0 = geo%fcs(ifc)
            ELSE
              abs0 = -geo%fcs(ifc)
            END IF
            s1 = abs0*geo%qalfmax
          ELSE IF (geo%fcpbs(ifc) .GE. 0.) THEN
            s1 = geo%fcpbs(ifc)
          ELSE
            s1 = -geo%fcpbs(ifc)
          END IF
          t0 = dv%ne(icv1)
          t1 = 0.0_R8
          DO is=0,ns-1
            IF (.NOT.is_neutral(is) .AND. conpar(is, ib, 2) .GT. 0.0_R8&
&           ) t1 = t1 + co%dna0(icv1, is)/conpar(is, ib, 2)*rt%rza(icv1&
&               , is)*pl%na(icv1, is)
          END DO
          IF (-50.0_R8 .LT. -(qe*(pl%po(icv1)-potpar(ib, 2))/pl%te(icv1)&
&             )) THEN
            y2 = -(qe*(pl%po(icv1)-potpar(ib, 2))/pl%te(icv1))
          ELSE
            y2 = -50.0_R8
          END IF
          IF (0.0_R8 .GT. y2) THEN
            min5 = y2
          ELSE
            min5 = 0.0_R8
          END IF
!lkw 31.03.2023
          result10 = EXPU2(min5)
          t0 = s1*t0*SQRT(1.0_R8/(2.0_R8*pi))*vte*result10
          t1 = t1*geo%fcs(ifc)
          IF (switch%pot_eq .EQ. 1) THEN
!wdk to check: correct 2nd term for gammae?
            srw%she0(icv1, 1) = srw%she0(icv1, 1) - (1.0_R8+gammae+&
&             enepar(ib, 1)+switch%stab_coeff_sheath_te)*t0 - &
&             fac_he_anom_bc*enepar(ib, 2)*t1
!lkw 31.03.2023
!wdk to check: correct 2nd term for gammae?
            srw%she0(icv1, 0) = srw%she0(icv1, 0) - ((1.0_R8-gammae)*qe*&
&             (pl%po(icv1)-potpar(ib, 2))-switch%stab_coeff_sheath_te*pl&
&             %te(icv1))*t0 - qe*(pl%po(icv1)-potpar(ib, 2))*t1
            IF (switch%b2nppo_restr_po .NE. 0.0_R8 .AND. srw%she0(icv1, &
&               0) + srw%she0(icv1, 1)*pl%te(icv1) .GT. 0.0_R8) srw%she0&
&             (icv1, :) = 0.0_R8
          ELSE
            cs = SQRT(pz(icv1)/rz(icv1))
!srv 11.03.09 {
!wdk to check: correct for gammae?
            srw%she0(icv1, 1) = srw%she0(icv1, 1) - s1*dv%ne(icv1)*cs*(&
&             1.0_R8+gammae+enepar(ib, 1)+(1.0_R8-gammae)*switch%delpo) &
&             - (fac_he_anom_bc*enepar(ib, 2)+switch%delpo)*t1
          END IF
          IF (switch%mdf_fhe .NE. 0) THEN
            srw%she0(icv1, 0) = srw%she0(icv1, 0) + mpg%bcfcor(mpg%bccvp&
&             (ib, 1)+ibc-1)*(dv%fhepsch(ifc, 0)+dv%fhepsch(ifc, 1))
            t0 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*2.5_R8*(geo%fcs(ifc)&
&             *geo%fcqalf(ifc, 0)*dv%vedia(ifc, 0)+geo%fcs(ifc)*geo%&
&             fcqalf(ifc, 1)*dv%vedia(ifc, 1))*0.5_R8*(dv%ne(icv1)+dv%ne&
&             (icv2))*0.5_R8*(pl%te(icv1)+pl%te(icv2))
            IF (0.0_R8 .LT. t0) THEN
              max6 = t0
            ELSE
              max6 = 0.0_R8
            END IF
            srw%she0(icv1, 0) = srw%she0(icv1, 0) + max6
            IF (0.0_R8 .GT. t0) THEN
              min6 = t0
            ELSE
              min6 = 0.0_R8
            END IF
            srw%she0(icv1, 1) = srw%she0(icv1, 1) + min6/pl%te(icv1)
          END IF
        END DO
      ELSE
        CALL XERRAB('B2STBC -- BCENE=15, incorrect bcene_15_style value'&
&            )
      END IF
    CASE (16) 
!
! -- BCENE=16 -- Feedback boundary condition with constant temperature
!
!
      IF (switch%bcene_16_style .EQ. 0) THEN
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a)') &
&         'BCENE = 16 (style = 0) : '//&
&         'electron temperature feedback by flux ', enepar(ib, 1), &
&         ' with ', enepar(ib, 2), ' on ', bcchar(ib), boundary_location&
&         (ib)
          CALL XERTST(enepar(ib, 1) .NE. 0, 'faulty parameter enepar1')
        END IF
!       ..compute average temperature on boundary
        t0 = 0.0_R8
        t1 = 0.0_R8
!wdk Note on backwards compatibility: feedback now always on
!wdk flux through the boundary itself (no offset)
        totflux = 0.0_R8
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          t0 = t0 + geo%fcs(ifc)*dv%ne(icv1)
          t1 = t1 + geo%fcs(ifc)*dv%ne(icv1)*pl%te(icv1)
          totflux = totflux - (dv%fhe(ifc, 0)+dv%fhe(ifc, 1))*mpg%bcfcor&
&           (mpg%bccvp(ib, 1)+ibc-1)
        END DO
        t1 = t1/t0
        totpar = fac_he_anom_bc*enepar(ib, 1)
        IF (enepar(ib, 2) .GT. 0.0_R8) t3 = enepar(ib, 2)
        IF (enepar(ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref_te
        IF (totflux .GE. 0.) THEN
          x1 = totflux
        ELSE
          x1 = -totflux
        END IF
        IF (totpar .GE. 0.) THEN
          y3 = totpar
        ELSE
          y3 = -totpar
        END IF
        IF (x1 .LT. y3) THEN
          max7 = y3
        ELSE
          max7 = x1
        END IF
        t2 = (1.0_R8-t3*(totflux-totpar)/max7)*t1
        IF (switch%b2stbc_diagno .GE. 2) WRITE(*, '(a,1p,4(1x,e15.6))') &
&             'bcene=16: curr_flux, desired_flux, old/new temperature, '&
&                                        , totflux, totpar, t1/qe, t2/qe
!       ..impose temperature
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%she0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*t2
          srw%she0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
        END DO
      ELSE IF (switch%bcene_16_style .EQ. 1) THEN
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a)') 'BCENE = 16 (style = 1) : '//&
&         'Given integrated electron heat flux with constant Te'
!          write all boundaries with this type of boundary condition
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bcene(ibw) .EQ. bcene(ib)) THEN
              WRITE(*, '(a,a,a)') ' on ', bcchar(ibw), boundary_location&
&             (ibw)
              icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
              CALL XERTST(mpg%cvonclosedsurface(icv), &
&                   'BCENE = 16 only applicable to core boundaries !')
              CALL XERTST(enepar(ibw, 1) .NE. 0.0_R8, &
&                   'faulty parameter enepar1')
            END IF
          END DO
        END IF
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
!srv 16.02.12 }
          IF (.NOT.once_bcene) THEN
            IF (switch%use_astra .NE. 0) THEN
              CALL XERRAB(&
&                   'Compile with -DASTRA option to couple to ASTRA!')
            ELSE
              senepar = 0.0_R8
              DO ibw=ib,nbc
                IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') &
&                   .AND. bcene(ibw) .EQ. bcene(ib)) senepar = senepar +&
&                   enepar(ibw, 1)
              END DO
            END IF
            WRITE(*, *) 'BCENE=16: Summed value is ', senepar
            tes = 0.0_R8
            volsum = 0.0_R8
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bcene(ibw) .EQ. bcene(ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  tes = tes + pl%te(icv)*geo%cvvol(icv)
                  volsum = volsum + geo%cvvol(icv)
                END DO
              END IF
            END DO
            tes = tes/volsum
            totflux = 0.0_R8
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bcene(ibw) .EQ. bcene(ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                  IF (switch%mdf_fhe .NE. 0) THEN
                    totflux = totflux - mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc&
&                     -1)*(dv%fhe_mdf(ifc, 0)+dv%fhe_mdf(ifc, 1))
                    totflux = totflux - pl%te(icv)*dv%ne(icv)*geo%fcs(&
&                     ifc)*mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)*(dv%&
&                     vaecrb(ifc, 0, ns-1)*geo%fcqalf(ifc, 0)+dv%vaecrb(&
&                     ifc, 1, ns-1)*geo%fcqalf(ifc, 1))
                  ELSE
                    totflux = totflux - mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc&
&                     -1)*(dv%fhe(ifc, 0)+dv%fhe(ifc, 1))
                  END IF
                END DO
              END IF
            END DO
            IF (enepar(ib, 2) .GT. 0.0_R8) t3 = enepar(ib, 2)
            IF (enepar(ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref_te
            IF (totflux .GE. 0.) THEN
              x2 = totflux
            ELSE
              x2 = -totflux
            END IF
            IF (x2 .LT. senepar) THEN
              max8 = senepar
            ELSE
              max8 = x2
            END IF
            tes = tes*(1.0_R8-t3*(totflux-senepar)/max8)
            WRITE(*, '(3(a,es14.7))') ' TES=', tes/ev, ' totflux=', &
&           totflux, ' SENEPAR=', senepar
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bcene(ibw) .EQ. bcene(ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                  srw%she0(icv, 0) = vbig*ne00*tes*geo%fcs(ifc)
                  srw%she0(icv, 1) = -(vbig*ne00*geo%fcs(ifc))
                END DO
              END IF
            END DO
            once_bcene = .true.
          END IF
        ELSE
          CALL XERRAB('B2STBC -- BCENE=16, ONLY AVAILABLE FOR CORE!')
        END IF
      ELSE
        CALL XERRAB(' Incorrect style of boundary condition')
      END IF
    CASE (17) 
!
! -- BCENE=17 -- Feedback boundary condition with constant shared temperature
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a)') &
&       'BCENE = 17 : shared temperature feedback by flux ', enepar(ib, &
&       1), ' with ', enepar(ib, 2), ' on ', bcchar(ib), &
&       boundary_location(ib)
        CALL XERTST(enepar(ib, 1) .NE. 0, 'faulty parameter enepar1')
        CALL XERTST(enepar(ib, 2) .GT. 0, 'faulty parameter enepar2')
        CALL XERTST(bcene(ib) .EQ. bceni(ib), &
&             'both bcene and bceni should be set to 17')
        CALL XERTST(enipar(ib, 1) .NE. 0, 'faulty parameter enipar1')
        CALL XERTST(enipar(ib, 2) .GT. 0, 'faulty parameter enipar2')
      END IF
      IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
        totflux = 0.0_R8
        t0 = 0.0_R8
        weight = 0.0_R8
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
          totflux = totflux - (dv%fhe(ifc, 0)+dv%fhe(ifc, 1)+dv%fhi(ifc&
&           , 0)+dv%fhi(ifc, 1)+st_ext%fhi(ifc, 0)+st_ext%fhi(ifc, 1))*&
&           mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          IF (bc_type16_kinetic_energy .EQ. 1) THEN
            DO is=0,ns-1
              result10 = INTFACE_S(ifc, ncv, nfc, mpg%fccv, geo%fcvol, &
&               dv%kinrgy(1, is))
              totflux = totflux - (1.0_R8-switch%boris)*mpg%bcfcor(mpg%&
&               bccvp(ib, 1)+ibc-1)*(dv%fna(ifc, 0, is)+dv%fna(ifc, 1, &
&               is))*result10
            END DO
            DO is=0,st_ext%ns-1
              result10 = INTFACE_S(ifc, ncv, nfc, mpg%fccv, geo%fcvol, &
&               st_ext%ua(1, is))
              totflux = totflux - (1.0_R8-switch%boris)*mpg%bcfcor(mpg%&
&               bccvp(ib, 1)+ibc-1)*(st_ext%fa(ifc, 0, is)+st_ext%fa(ifc&
&               , 1, is))*0.5_R8*st_ext%am(is)*mp*result10**2
            END DO
          END IF
          t0 = t0 + (pl%te(icv)*dv%ne(icv)+pl%ti(icv)*dv%ni(icv, 0))*geo&
&           %cvvol(icv)
          weight = weight + (dv%ne(icv)+dv%ni(icv, 0))*geo%cvvol(icv)
        END DO
        t0 = t0/weight
        IF (switch%b2stbc_diagno .GE. 2) WRITE(*, *) 'Totflux :', &
&                                        totflux
        t1 = (1.0_R8-enepar(ib, 2)*(totflux*enepar(ib, 1)/(enepar(ib, 1)&
&         +enipar(ib, 1))-enepar(ib, 1))/enepar(ib, 1)-enipar(ib, 2)*(&
&         totflux*enipar(ib, 1)/(enepar(ib, 1)+enipar(ib, 1))-enipar(ib&
&         , 1))/enipar(ib, 1))*t0
        IF (switch%b2stbc_diagno .GE. 2) WRITE(*, *) &
&                                        'Old/New shared temp :', t0/qe&
&                                        , t1/qe
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
          srw%she0(icv, 0) = vbig*ne00*t1*geo%fcs(ifc)
          srw%she0(icv, 1) = -(vbig*ne00*geo%fcs(ifc))
          srw%shi0(icv, 0) = vbig*ne00*t1*geo%fcs(ifc)
          srw%shi0(icv, 1) = -(vbig*ne00*geo%fcs(ifc))
        END DO
      ELSE
        CALL XERRAB('B2STBC -- BCENE=17, NOT AVAILABLE FOR N,W,E')
      END IF
    CASE (18) 
!
! -- BCENE=18 -- FRACTIONAL DROP CONDITION (FOR EDGE2D COMPARISON)
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENE = 18 : electron temperature fractional drop ', enepar(ib&
&       , 1), ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enepar(ib, 1) .LT. 1.0_R8, &
&             'BCENE = 18, ENEPAR(,1) => 1')
      END IF
      DO ibc=1,mpg%bccvp(ib, 2)
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        t1 = (1.0_R8-enepar(ib, 1))*pl%te(icv2)
        srw%she0(icv1, 0) = vbig*ne00*t1*geo%fcs(ifc)
        srw%she0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (19) 
!
! -- BCENE=19 -- PRESCRIBE THE DECAY LENGTH FOR THE ELECTRON TEMPERATURE
!
      CALL XERRAB('b2stbc_phys -- BCENE = 19 not adapted for WG')
!
! -- BCENE=20 -- Feedback boundary condition with constant temperature
!
    CASE (20) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a)') &
&       'BCENE = 20 : electron temperature feedback by flux ', enepar(ib&
&       , 1), ' with ', enepar(ib, 2), ' on ', bcchar(ib), &
&       boundary_location(ib)
        CALL XERTST(enepar(ib, 1) .NE. 0, 'faulty parameter enepar1')
      END IF
      IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
        totflux = 0.0_R8
        t0 = 0.0_R8
        weight = 0.0_R8
        teave = 0.0_R8
        neave = 0.0_R8
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          totflux = totflux - mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%fhe&
&           (ifc, 0)+dv%fhe(ifc, 1))
          t0 = t0 + pl%te(icv1)*dv%ne(icv1)*geo%cvvol(icv1)
          weight = weight + dv%ne(icv1)*geo%cvvol(icv1)
          teave = teave + pl%te(icv2)*dv%ne(icv2)*geo%cvvol(icv2)
          neave = neave + dv%ne(icv2)*geo%cvvol(icv2)
        END DO
        t0 = t0/weight
        teave = teave/neave
        IF (switch%b2stbc_diagno .GE. 2) WRITE(*, *) 'Totflux :', &
&                                        totflux
        IF (enepar(ib, 2) .GT. 0.0_R8) t3 = enepar(ib, 2)
        IF (enepar(ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref_te
        t1 = (1.0_R8-t3*(totflux-enepar(ib, 1))/enepar(ib, 1))*t0
        IF (switch%b2stbc_diagno .GE. 2) WRITE(*, *) &
&                                        'Old/New electron temp :', t0/&
&                                        qe, t1/qe
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%she0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*t1*pl%te(icv2)/&
&           teave
          srw%she0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
        END DO
      ELSE
        CALL XERRAB('B2STBC -- BCENE=20, NOT AVAILABLE FOR N,W,E')
      END IF
    CASE (21) 
!
! -- BCENE=21 -- constant temperature scaled by temperature on the ring bc_type21_ref away
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a)') &
&       'BCENE = 21 : fixed electron temperature '//&
&       '(modified by nearby ring) ', enepar(ib, 1), ' with ', enepar(ib&
&       , 2), ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enepar(ib, 1) .NE. 0.0_R8, &
&             'faulty parameter enepar1')
      END IF
      IF ((bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'N') .OR. bcchar(ib)&
&         .EQ. 'A') THEN
        teave = 0.0_R8
        neave = 0.0_R8
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          teave = teave + pl%te(icv)*dv%ne(icv)*geo%cvvol(icv)
          neave = neave + dv%ne(icv)*geo%cvvol(icv)
        END DO
        teave = teave/neave
        IF (enepar(ib, 2) .GT. 0.0_R8) t3 = enepar(ib, 2)
        IF (enepar(ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref_te
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%she0(icv1, 0) = vbig*ne00*enepar(ib, 1)*ev*geo%fcs(ifc)*(&
&           1.0_R8-t3+t3*pl%te(icv2)/teave)
          srw%she0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
        END DO
      ELSE
        CALL XERRAB('B2STBC -- BCENE=21, NOT AVAILABLE FOR W,E')
      END IF
    CASE (22) 
!
! -- BCENE=22 -- RADIAL LEAKAGE CONDITION FOR THE ELECTRON TEMPERATURE   !srv 23.07.10 {
!                SPECIFIES A TEMPERATURE GRADIENT SUCH THAT THE DIFFUSIVE
!                FLUX IS SET TO BE EQUIVALENT TO A LEAKAGE VELOCITY, IN
!                UNITS OF THE ELECTRON THERMAL VELOCITY
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                   'BCENE = 22 : with ENEPAR(IB,1)= ', &
&                                   enepar(ib, 1), ' on ', bcchar(ib), &
&                                   boundary_location(ib)
!wdk    Notes:
!wdk     * need correction for misaligned grids -> t1
!wdk     * need to correct this BC for hybrid scheme
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        vte = SQRT(pl%te(icv1)/me)
        t0 = geo%fcqalf(ifc, 1)
        t1 = (geo%fchc(ifc, 1)+geo%fchc(ifc, 2))/geo%fcht(ifc)*geo%&
&         fcqbet(ifc, 0)
        srw%she0(icv1, 0) = vbig*ne00*ev*co%chce(ifc, 1)*(t0*pl%te(icv2)&
&         -mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*t1*(pl%te(mpg%fcvx(ifc, 2)&
&         )-pl%te(mpg%fcvx(ifc, 1))))
        srw%she0(icv1, 1) = -(vbig*ne00*ev*(co%chce(ifc, 1)*t0-enepar(ib&
&         , 1)*geo%fcs(ifc)*vte*dv%ne(icv1)))
      END DO
    CASE (23) 
!
!
! -- BCENE=23 -- Prescribe the value of the electron temperature, with poloidal
!                perturbation taken from flux tube just inside domain
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          CALL XERTST(mpg%cvonclosedsurface(icv), &
&               'BCENE=23 intended for core boundaries only!')
        END DO
        IF (switch%use_astra .NE. 0) enepar(ib, 1) = teb_astra*1.0e3_R8
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'specified electron temp. + perturbation', enepar(ib, 1), ' on '&
&       , bcchar(ib), boundary_location(ib)
        CALL XERTST(enepar(ib, 1) .GT. 0.0_R8, &
&             'BCENE = 23, ENEPAR(,1) !> 0')
      END IF
!     ..compute average temperature on core boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
        IF (mpg%cvonclosedsurface(icv1)) THEN
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            t0 = t0 + geo%cvvol(icv2)
            t1 = t1 + geo%cvvol(icv2)*pl%te(icv2)
          END DO
        END IF
      END DO
      t1 = t1/t0
!     ..impose temperature with perturbation
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%she0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*(pl%te(icv2)+enepar(&
&         ib, 1)*ev-t1)
        srw%she0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (24) 
!
! -- BCENE=24 -- Feedback on the total electron energy flux, by imposing a flux surface
!                averaged temperature, with poloidal perturbation taken from flux
!                tube just inside domain
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          CALL XERTST(mpg%cvonclosedsurface(icv1), &
&               'BCENE=24 intended for core boundaries only!')
        END DO
        WRITE(*, '(a,1p,g14.7,a,a,a)') 'specified electron heat flux', &
&       enepar(ib, 1), ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enepar(ib, 1) .GT. 0.0_R8, &
&             'BCENE = 24, ENEPAR(,1) !> 0')
      END IF
!     ..compute average temperature on core boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
      t2 = 0.0_R8
      totflux = 0.0_R8
      totpar = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
        IF (mpg%cvonclosedsurface(icv1)) THEN
          IF (bcene(ib0) .NE. 24) CALL XERRAB(&
&                                      'BCENE=24: incompatible core BCs'&
&                                      )
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            t0 = t0 + geo%cvvol(icv2)
            t1 = t1 + geo%cvvol(icv2)*pl%te(icv1)
            t2 = t2 + geo%cvvol(icv2)*pl%te(icv2)
            totflux = totflux - (dv%fhe(ifc, 0)+dv%fhe(ifc, 1))*mpg%&
&             bcfcor(mpg%bccvp(ib0, 1)+ibc0-1)
          END DO
          totpar = totpar + enepar(ib0, 1)
        END IF
      END DO
      totpar = fac_he_anom_bc*totpar
      t1 = t1/t0
      t2 = t2/t0
      IF (enepar(ib, 2) .GT. 0.0_R8) t3 = enepar(ib, 2)
      IF (enepar(ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref_te
      IF (totflux .GE. 0.) THEN
        x3 = totflux
      ELSE
        x3 = -totflux
      END IF
      IF (totpar .GE. 0.) THEN
        y4 = totpar
      ELSE
        y4 = -totpar
      END IF
      IF (x3 .LT. y4) THEN
        max9 = y4
      ELSE
        max9 = x3
      END IF
      t4 = (1.0_R8-t3*(totflux-totpar)/max9)*t1
!     ..impose temperature with perturbation
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%she0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*(pl%te(icv2)+t4-t2)
        srw%she0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE DEFAULT
!
      WRITE(*, *) bcene(ib)
      CALL XERRAB('BCENE out of bounds')
!
    END SELECT
!
    RETURN
  END SUBROUTINE B2STBC_PHYS_ENE

!  Differentiation of b2stbc_phys_eni in reverse (adjoint) mode (with options context noISIZE r8):
!   gradient     of useful results: conpar mompar enipar senipar
!                *(dv.fna) *(dv.fhi) *(dv.fhi_mdf) *(dv.fhipsch)
!                *(dv.fhm) *(dv.ne) *(dv.ni) *(dv.vadia) *(dv.vaecrb)
!                *(rt.rza) *(srw.shi0) *(srw.sna0) *(co.chci) *(co.hci0)
!                *(co.hcn0) *(co.dna0) *(pl.na) *(pl.ua) *(pl.te)
!                *(pl.ti) vbc rz csbc pz
!   with respect to varying inputs: conpar mompar enipar senipar
!                *(dv.fna) *(dv.fhi) *(dv.fhi_mdf) *(dv.fhipsch)
!                *(dv.fhm) *(dv.ne) *(dv.ni) *(dv.vadia) *(dv.vaecrb)
!                *(rt.rza) *(srw.shi0) *(srw.sna0) *(co.chci) *(co.hci0)
!                *(co.hcn0) *(co.dna0) *(pl.na) *(pl.ua) *(pl.te)
!                *(pl.ti) vbc rz csbc pz
!   Plus diff mem management of: dv.fna:in dv.fhi:in dv.fhi_mdf:in
!                dv.fhipsch:in dv.fhm:in dv.ne:in dv.ni:in dv.vadia:in
!                dv.vaecrb:in mpg.bcfcor:in geo.cvbb:in geo.fcs:in
!                geo.vxvol:in rt.rza:in srw.shi0:in srw.sna0:in
!                co.chci:in co.hci0:in co.hcn0:in co.dna0:in pl.na:in
!                pl.ua:in pl.te:in pl.ti:in
!
  SUBROUTINE B2STBC_PHYS_ENI_B(ib)
    IMPLICIT NONE
    INTEGER :: ib, ibw, ibc, ib0, ibc0, is
    INTEGER :: icv, icv1, icv2, ifc, ivx1, ivx2
    REAL(kind=r8) :: t0, t1, t2, t3, t4, dsh, vt, vbnd, niave, tiave, &
&   totpar, totflux, weight, cs, csb, wrk
    REAL(kind=r8) :: t0b, t1b, t2b, t3b, t4b, dshb, vtb, vbndb, niaveb, &
&   tiaveb, totparb, totfluxb, weightb, csb0, csbb
    REAL(kind=r8), EXTERNAL :: INTVERTEX_S_NODIFF
    LOGICAL :: decay_length_ok
    EXTERNAL XERRAB
    INTRINSIC MIN
    INTRINSIC NINT
    INTRINSIC SQRT
    INTRINSIC ABS
    INTRINSIC SIGN
    REAL(kind=r8) :: x1
    REAL(kind=r8) :: x1b
    REAL(kind=r8) :: y1
    REAL(kind=r8) :: y1b
    REAL(kind=r8) :: x2
    REAL(kind=r8) :: x2b
    REAL(kind=r8) :: y2
    REAL(kind=r8) :: y2b
    REAL(kind=r8) :: x3
    REAL(kind=r8) :: x3b
    REAL(kind=r8) :: x4
    REAL(kind=r8) :: x4b
    REAL(kind=r8) :: x5
    REAL(kind=r8) :: x5b
    REAL(kind=r8) :: x6
    REAL(kind=r8) :: x6b
    REAL(kind=r8) :: y3
    REAL(kind=r8) :: y3b
    REAL(r8) :: max1
    REAL(r8) :: max1b
    REAL(r8) :: min1
    REAL(r8) :: min1b
    REAL(r8) :: max2
    REAL(r8) :: max2b
    REAL(r8) :: min2
    REAL(r8) :: min2b
    REAL(r8) :: max3
    REAL(r8) :: max3b
    REAL(r8) :: max4
    REAL(r8) :: max4b
    REAL(r8) :: min3
    REAL(r8) :: min3b
    REAL(kind=r8) :: abs0
    REAL(r8) :: max5
    REAL(r8) :: max5b
    REAL(r8) :: min4
    REAL(r8) :: min4b
    REAL(kind=r8) :: max6
    REAL(kind=r8) :: max6b
    REAL(kind=r8) :: abs1
    REAL(kind=r8) :: abs2
    REAL(kind=r8) :: abs3
    REAL(kind=r8) :: abs4
    REAL(r8) :: max7
    REAL(r8) :: max7b
    REAL(r8) :: min5
    REAL(r8) :: min5b
    REAL(kind=r8) :: max8
    REAL(kind=r8) :: max8b
    REAL(kind=r8) :: max9
    REAL(kind=r8) :: max9b
    REAL(kind=r8) :: max10
    REAL(kind=r8) :: max10b
    REAL(kind=r8) :: max11
    REAL(kind=r8) :: max11b
    REAL(kind=r8) :: max12
    REAL(kind=r8) :: max12b
    REAL(kind=r8) :: abs5
    REAL(kind=r8) :: result10
    REAL(kind=r8) :: result10b
    REAL(kind=r8) :: result20
    REAL(kind=r8) :: result20b
    REAL(kind=r8) :: temp
    REAL(kind=r8) :: tempb
    REAL(kind=r8) :: temp0
    REAL(kind=r8) :: tempb0
    REAL(r8) :: temp1
    REAL(r8) :: tempb1
    REAL(r8) :: temp2
    REAL(kind=r8) :: temp3
    REAL(kind=r8) :: temp4
    REAL(r8) :: temp5
    REAL(r8) :: tempb2
    REAL(kind=r8) :: tempb3
    REAL(kind=r8) :: tempb4
    REAL(r8) :: tempb5
    REAL(kind=r8) :: temp6
    REAL(kind=r8) :: tempb6
    REAL(kind=r8) :: temp7
    REAL(kind=r8) :: tempb7
    INTEGER*4 :: branch
    INTEGER :: ad_to
    INTEGER :: ad_to0
    INTEGER :: ad_to1
    INTEGER :: ad_to2
    INTEGER :: ad_to3
    INTEGER :: ad_to4
    INTEGER :: ad_to5
    INTEGER :: ad_to6
    INTEGER :: ad_to7
    INTEGER :: ad_to8
    INTEGER :: ad_to9
    INTEGER :: ad_to10
    INTEGER :: ad_to11
!
! -- BOUNDARY CONDITIONS FOR ION ENERGY EQUATIONS --
!
    SELECT CASE  (bceni(ib)) 
    CASE (0) 

    CASE (1) 
!
!
! -- BCENI=1 -- PRESCRIBE THE VALUE OF THE ION TEMPERATURE
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        IF (bcchar(ib) .EQ. 'S' .AND. switch%use_astra .NE. 0) THEN
          CALL PUSHCONTROL2B(1)
        ELSE
          CALL PUSHCONTROL2B(2)
        END IF
      ELSE
        CALL PUSHCONTROL2B(0)
      END IF
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        srwb%shi0(icv1, 1) = 0.D0
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        eniparb(ib, 1) = eniparb(ib, 1) + vbig*ne00*geo%fcs(ifc)*ev*srwb&
&         %shi0(icv1, 0)
        srwb%shi0(icv1, 0) = 0.D0
      END DO
      CALL POPCONTROL2B(branch)
      IF (branch .NE. 0) THEN
        IF (branch .EQ. 1) eniparb(ib, 1) = 0.D0
      END IF
    CASE (2) 
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        srwb%shi0(icv1, 1) = 0.D0
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        tempb = vbig*ne00*geo%fcs(ifc)*srwb%shi0(icv1, 0)
        srwb%shi0(icv1, 0) = 0.D0
        eniparb(ib, 1) = eniparb(ib, 1) + ev*geo%fcqgam(ifc, 0)*(geo%&
&         fchc(ifc, 1)+geo%fchc(ifc, 2))*tempb
        tempb0 = -(mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*cor9*geo%fcqgam(&
&         ifc, 1)*(geo%fchc(ifc, 1)+geo%fchc(ifc, 2))*tempb/geo%fcht(ifc&
&         ))
        plb%ti(icv2) = plb%ti(icv2) + tempb
        t2b = tempb0
        t1b = -tempb0
        ivx2 = mpg%fcvx(ifc, 2)
        CALL INTVERTEX_S_B(ivx2, ncv, nvx, mpg, geo%vxvol, pl%ti, plb%ti&
&                    , t2b)
        ivx1 = mpg%fcvx(ifc, 1)
        CALL INTVERTEX_S_B(ivx1, ncv, nvx, mpg, geo%vxvol, pl%ti, plb%ti&
&                    , t1b)
      END DO
    CASE (3) 

    CASE (4) 
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        eniparb(ib, 2) = eniparb(ib, 2) - geo%fcs(ifc)*srwb%shi0(icv1, 1&
&         )/ev
        srwb%shi0(icv1, 1) = 0.D0
        tempb0 = geo%fcs(ifc)*srwb%shi0(icv1, 0)
        srwb%shi0(icv1, 0) = 0.D0
        eniparb(ib, 2) = eniparb(ib, 2) + enipar(ib, 1)*tempb0
        eniparb(ib, 1) = eniparb(ib, 1) + enipar(ib, 2)*tempb0
      END DO
    CASE (5) 
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        srwb%shi0(icv, 1) = 0.D0
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        eniparb(ib, 1) = eniparb(ib, 1) + geo%fcs(ifc)*srwb%shi0(icv, 0)
        srwb%shi0(icv, 0) = 0.D0
      END DO
    CASE (6) 

    CASE (7) 
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        srwb%shi0(icv1, 1) = 0.D0
        srwb%shi0(icv1, 0) = 0.D0
      END DO
    CASE (8) 
!
! -- BCENI=8 -- PRESCRIBE THE TOTAL ION HEAT FLUX WITH CONSTANT
!                 FLUX DENSITY
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
!srv 28.07.11
        IF (switch%use_astra .NE. 0) THEN
          CALL PUSHCONTROL2B(0)
        ELSE
          CALL PUSHCONTROL2B(1)
        END IF
      ELSE
        CALL PUSHCONTROL2B(2)
      END IF
      us = 0.0_R8
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        us = us + geo%fcs(ifc)
      END DO
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        CALL PUSHINTEGER4(icv1)
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        CALL PUSHINTEGER4(ifc)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        IF (switch%mdf_fhi .NE. 0) THEN
!wdk Correction now involves vedia instead of ExB velocity
!wdk This makes implementation equivalent to mdf_fhi = 0 option
          t0 = 0.0_R8
          DO is=0,ns-1
            t0 = t0 + mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*2.5_R8*(geo%fcs&
&             (ifc)*geo%fcqalf(ifc, 0)*dv%vadia(ifc, 0, is)+geo%fcs(ifc)&
&             *geo%fcqalf(ifc, 1)*dv%vadia(ifc, 1, is))*0.5_R8*(pl%na(&
&             icv1, is)+pl%na(icv2, is))*0.5_R8*(pl%ti(icv1)+pl%ti(icv2)&
&             )
          END DO
          IF (0.0_R8 .LT. t0) THEN
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHCONTROL1B(1)
          END IF
          IF (0.0_R8 .GT. t0) THEN
            CALL PUSHREAL8(min1, r8/8)
            min1 = t0
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHREAL8(min1, r8/8)
            min1 = 0.0_R8
            CALL PUSHCONTROL1B(1)
          END IF
          CALL PUSHCONTROL1B(1)
        ELSE
          CALL PUSHCONTROL1B(0)
        END IF
      END DO
      DO ibc=mpg%bccvp(ib, 2),1,-1
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) THEN
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          tempb2 = srwb%shi0(icv1, 1)/pl%ti(icv1)
          min1b = tempb2
          plb%ti(icv1) = plb%ti(icv1) - min1*tempb2/pl%ti(icv1)
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            CALL POPREAL8(min1, r8/8)
            t0b = min1b
          ELSE
            CALL POPREAL8(min1, r8/8)
            t0b = 0.D0
          END IF
          max1b = srwb%shi0(icv1, 0)
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) t0b = t0b + max1b
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          DO is=ns-1,0,-1
            temp1 = pl%ti(icv1) + pl%ti(icv2)
            temp2 = pl%na(icv1, is) + pl%na(icv2, is)
            temp3 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
            temp4 = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
            tempb0 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*0.5_R8**2*2.5_R8&
&             *t0b
            tempb = temp2*temp1*tempb0
            tempb2 = (temp3*dv%vadia(ifc, 0, is)+temp4*dv%vadia(ifc, 1, &
&             is))*tempb0
            plb%na(icv1, is) = plb%na(icv1, is) + temp1*tempb2
            plb%na(icv2, is) = plb%na(icv2, is) + temp1*tempb2
            plb%ti(icv1) = plb%ti(icv1) + temp2*tempb2
            plb%ti(icv2) = plb%ti(icv2) + temp2*tempb2
            dvb%vadia(ifc, 0, is) = dvb%vadia(ifc, 0, is) + temp3*tempb
            dvb%vadia(ifc, 1, is) = dvb%vadia(ifc, 1, is) + temp4*tempb
          END DO
          tempb1 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*srwb%shi0(icv1, 0)
          dvb%fhipsch(ifc, 0) = dvb%fhipsch(ifc, 0) + tempb1
          dvb%fhipsch(ifc, 1) = dvb%fhipsch(ifc, 1) + tempb1
        END IF
        srwb%shi0(icv1, 1) = 0.D0
        eniparb(ib, 1) = eniparb(ib, 1) + fac_he_anom_bc*geo%fcs(ifc)*&
&         srwb%shi0(icv1, 0)/us
        srwb%shi0(icv1, 0) = 0.D0
        CALL POPINTEGER4(ifc)
        CALL POPINTEGER4(icv1)
      END DO
      CALL POPCONTROL2B(branch)
      IF (branch .EQ. 0) eniparb(ib, 1) = 0.D0
    CASE (9) 
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        IF (switch%recycle_afn .EQ. 0 .OR. switch%tn_style .NE. 0) THEN
          CALL PUSHCONTROL1B(1)
        ELSE
          CALL PUSHCONTROL1B(0)
        END IF
        DO is=0,ns-1
          IF (((.NOT.is_neutral(is)) .OR. switch%tn_style .EQ. 0) .OR. (&
&             switch%tn_style .EQ. 2 .AND. NINT(zn(is)) .NE. 1)) THEN
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHCONTROL1B(1)
          END IF
        END DO
        IF (switch%mdf_fhi .NE. 0) THEN
          DO is=0,ns-1
            t0 = -(mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*1.5_R8*(geo%fcs(&
&             ifc)*geo%fcqalf(ifc, 0)*dv%vaecrb(ifc, 0, is)+geo%fcs(ifc)&
&             *geo%fcqalf(ifc, 1)*dv%vaecrb(ifc, 1, is))*0.5_R8*(pl%na(&
&             icv1, is)+pl%na(icv2, is))*0.5_R8*(pl%ti(icv1)+pl%ti(icv2)&
&             ))
            IF (0.0_R8 .LT. t0) THEN
              CALL PUSHCONTROL1B(0)
            ELSE
              CALL PUSHCONTROL1B(1)
            END IF
            IF (0.0_R8 .GT. t0) THEN
              CALL PUSHREAL8(min2, r8/8)
              min2 = t0
              CALL PUSHCONTROL1B(0)
            ELSE
              CALL PUSHREAL8(min2, r8/8)
              min2 = 0.0_R8
              CALL PUSHCONTROL1B(1)
            END IF
          END DO
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
      END DO
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          DO is=ns-1,0,-1
            tempb2 = srwb%shi0(icv1, 1)/pl%ti(icv1)
            min2b = tempb2
            plb%ti(icv1) = plb%ti(icv1) - min2*tempb2/pl%ti(icv1)
            CALL POPCONTROL1B(branch)
            IF (branch .EQ. 0) THEN
              CALL POPREAL8(min2, r8/8)
              t0b = min2b
            ELSE
              CALL POPREAL8(min2, r8/8)
              t0b = 0.D0
            END IF
            max2b = srwb%shi0(icv1, 0)
            CALL POPCONTROL1B(branch)
            IF (branch .EQ. 0) t0b = t0b + max2b
            temp5 = pl%ti(icv1) + pl%ti(icv2)
            temp2 = pl%na(icv1, is) + pl%na(icv2, is)
            temp0 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
            temp = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
            tempb3 = -(mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*0.5_R8**2*&
&             1.5_R8*t0b)
            tempb4 = temp2*temp5*tempb3
            tempb1 = (temp0*dv%vaecrb(ifc, 0, is)+temp*dv%vaecrb(ifc, 1&
&             , is))*tempb3
            plb%na(icv1, is) = plb%na(icv1, is) + temp5*tempb1
            plb%na(icv2, is) = plb%na(icv2, is) + temp5*tempb1
            plb%ti(icv1) = plb%ti(icv1) + temp2*tempb1
            plb%ti(icv2) = plb%ti(icv2) + temp2*tempb1
            dvb%vaecrb(ifc, 0, is) = dvb%vaecrb(ifc, 0, is) + temp0*&
&             tempb4
            dvb%vaecrb(ifc, 1, is) = dvb%vaecrb(ifc, 1, is) + temp*&
&             tempb4
          END DO
          tempb2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*srwb%shi0(icv1, 0)
          dvb%fhipsch(ifc, 0) = dvb%fhipsch(ifc, 0) + tempb2
          dvb%fhipsch(ifc, 1) = dvb%fhipsch(ifc, 1) + tempb2
        END IF
        DO is=ns-1,0,-1
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            plb%na(icv1, is) = plb%na(icv1, is) + srw%sna0(icv1, 1, is)*&
&             fac_he_anom*srwb%shi0(icv1, 1)
            srwb%sna0(icv1, 1, is) = srwb%sna0(icv1, 1, is) + pl%na(icv1&
&             , is)*fac_he_anom*srwb%shi0(icv1, 1)
            plb%ti(icv1) = plb%ti(icv1) + srw%sna0(icv1, 0, is)*&
&             fac_he_anom*srwb%shi0(icv1, 0)
            srwb%sna0(icv1, 0, is) = srwb%sna0(icv1, 0, is) + pl%ti(icv1&
&             )*fac_he_anom*srwb%shi0(icv1, 0)
          END IF
        END DO
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          sy = geo%fcs(ifc)
          tempb2 = -(sy*srwb%shi0(icv1, 1)/enipar(ib, 1))
          srwb%shi0(icv1, 1) = 0.D0
          cob%hci0(icv1) = cob%hci0(icv1) + tempb2
          cob%hcn0(icv1) = cob%hcn0(icv1) - tempb2
          eniparb(ib, 1) = eniparb(ib, 1) - (co%hci0(icv1)-co%hcn0(icv1)&
&           )*tempb2/enipar(ib, 1)
        ELSE
          sy = geo%fcs(ifc)
          tempb2 = -(sy*srwb%shi0(icv1, 1)/enipar(ib, 1))
          srwb%shi0(icv1, 1) = 0.D0
          cob%hci0(icv1) = cob%hci0(icv1) + tempb2
          eniparb(ib, 1) = eniparb(ib, 1) - co%hci0(icv1)*tempb2/enipar(&
&           ib, 1)
        END IF
        srwb%shi0(icv1, 0) = 0.D0
      END DO
    CASE (11, 10) 

    CASE (12) 
      DO ibc=1,mpg%bccvp(ib, 2)
        CALL PUSHINTEGER4(icv)
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        CALL PUSHINTEGER4(ifc)
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        DO is=0,ns-1
          IF (0.0_R8 .LT. mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%fna(ifc&
&             , 0, is)+dv%fna(ifc, 1, is))) THEN
            CALL PUSHREAL8(max3, r8/8)
            max3 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%fna(ifc, 0, is&
&             )+dv%fna(ifc, 1, is))
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHREAL8(max3, r8/8)
            max3 = 0.0_R8
            CALL PUSHCONTROL1B(1)
          END IF
        END DO
      END DO
      DO ibc=mpg%bccvp(ib, 2),1,-1
        DO is=ns-1,0,-1
          tempb3 = -(srwb%shi0(icv, 3)/dv%ni(icv, 0))
          eniparb(ib, 1) = eniparb(ib, 1) + max3*tempb3
          max3b = enipar(ib, 1)*tempb3
          dvb%ni(icv, 0) = dvb%ni(icv, 0) - enipar(ib, 1)*max3*tempb3/dv&
&           %ni(icv, 0)
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            CALL POPREAL8(max3, r8/8)
            tempb2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*max3b
            dvb%fna(ifc, 0, is) = dvb%fna(ifc, 0, is) + tempb2
            dvb%fna(ifc, 1, is) = dvb%fna(ifc, 1, is) + tempb2
          ELSE
            CALL POPREAL8(max3, r8/8)
          END IF
        END DO
        CALL POPINTEGER4(ifc)
        CALL POPINTEGER4(icv)
      END DO
    CASE (13) 
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        srwb%shi0(icv, 1) = 0.D0
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        tempb3 = geo%fcs(ifc)*srwb%shi0(icv, 0)
        srwb%shi0(icv, 0) = 0.D0
        eniparb(ib, 1) = eniparb(ib, 1) + pl%ti(icv)*tempb3
        plb%ti(icv) = plb%ti(icv) + enipar(ib, 1)*tempb3
      END DO
    CASE (14) 
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        CALL PUSHINTEGER4(icv1)
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        CALL PUSHINTEGER4(ifc)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        CALL PUSHREAL8(cs, r8/8)
        cs = SQRT(pz(icv1)/rz(icv1))
        IF (switch%mdf_fhi .NE. 0) THEN
          t0 = 0.0_R8
          DO is=0,ns-1
            t0 = t0 + mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*2.5_R8*(geo%fcs&
&             (ifc)*geo%fcqalf(ifc, 0)*dv%vadia(ifc, 0, is)+geo%fcs(ifc)&
&             *geo%fcqalf(ifc, 1)*dv%vadia(ifc, 1, is))*0.5_R8*(pl%na(&
&             icv1, is)+pl%na(icv2, is))*0.5_R8*(pl%ti(icv1)+pl%ti(icv2)&
&             )
          END DO
          IF (0.0_R8 .LT. t0) THEN
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHCONTROL1B(1)
          END IF
          IF (0.0_R8 .GT. t0) THEN
            CALL PUSHREAL8(min3, r8/8)
            min3 = t0
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHREAL8(min3, r8/8)
            min3 = 0.0_R8
            CALL PUSHCONTROL1B(1)
          END IF
          CALL PUSHCONTROL1B(1)
        ELSE
          CALL PUSHCONTROL1B(0)
        END IF
      END DO
      DO ibc=mpg%bccvp(ib, 2),1,-1
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) THEN
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          tempb2 = srwb%shi0(icv1, 1)/pl%ti(icv1)
          min3b = tempb2
          plb%ti(icv1) = plb%ti(icv1) - min3*tempb2/pl%ti(icv1)
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            CALL POPREAL8(min3, r8/8)
            t0b = min3b
          ELSE
            CALL POPREAL8(min3, r8/8)
            t0b = 0.D0
          END IF
          max4b = srwb%shi0(icv1, 0)
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) t0b = t0b + max4b
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          DO is=ns-1,0,-1
            temp5 = pl%ti(icv1) + pl%ti(icv2)
            temp2 = pl%na(icv1, is) + pl%na(icv2, is)
            temp0 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
            temp = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
            tempb3 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*0.5_R8**2*2.5_R8&
&             *t0b
            tempb4 = temp2*temp5*tempb3
            tempb1 = (temp0*dv%vadia(ifc, 0, is)+temp*dv%vadia(ifc, 1, &
&             is))*tempb3
            plb%na(icv1, is) = plb%na(icv1, is) + temp5*tempb1
            plb%na(icv2, is) = plb%na(icv2, is) + temp5*tempb1
            plb%ti(icv1) = plb%ti(icv1) + temp2*tempb1
            plb%ti(icv2) = plb%ti(icv2) + temp2*tempb1
            dvb%vadia(ifc, 0, is) = dvb%vadia(ifc, 0, is) + temp0*tempb4
            dvb%vadia(ifc, 1, is) = dvb%vadia(ifc, 1, is) + temp*tempb4
          END DO
          tempb2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*srwb%shi0(icv1, 0)
          dvb%fhipsch(ifc, 0) = dvb%fhipsch(ifc, 0) + tempb2
          dvb%fhipsch(ifc, 1) = dvb%fhipsch(ifc, 1) + tempb2
        END IF
        tempb3 = geo%fcs(ifc)*fac_he_anom_bc*srwb%shi0(icv1, 3)
        srwb%shi0(icv1, 3) = 0.D0
        csb0 = enipar(ib, 1)*tempb3
        eniparb(ib, 1) = eniparb(ib, 1) + cs*tempb3
        srwb%shi0(icv1, 0) = 0.D0
        CALL POPREAL8(cs, r8/8)
        temp4 = pz(icv1)/rz(icv1)
        IF (temp4 .EQ. 0.D0) THEN
          tempb3 = 0.D0
        ELSE
          tempb3 = csb0/(rz(icv1)*2.0*SQRT(temp4))
        END IF
        pzb(icv1) = pzb(icv1) + tempb3
        rzb(icv1) = rzb(icv1) - temp4*tempb3
        CALL POPINTEGER4(ifc)
        CALL POPINTEGER4(icv1)
      END DO
    CASE (15) 
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        CALL PUSHINTEGER4(icv1)
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        CALL PUSHINTEGER4(icv2)
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        CALL PUSHINTEGER4(ifc)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
!srv 15.02.26 {
        DO is=0,ns-1
          CALL PUSHREAL8ARRAY(csbc, r8*ncv*ns/8)
          CALL PUSHREAL8(cs, r8/8)
          CALL CSBC_IS(icv1, ib, is, cs)
          CALL PUSHREAL8ARRAY(vbc, r8*ncv*ns/8)
          CALL VBC_IS(ib, is, ibc, icv1, icv2, ifc, csbc(icv1, is), wrk)
!srv 15.02.26 }
        END DO
        CALL PUSHREAL8(cs, r8/8)
        cs = SQRT(pz(icv1)/rz(icv1))
        CALL PUSHREAL8(t0, r8/8)
        t0 = 0.0_R8
        CALL PUSHREAL8(t1, r8/8)
        t1 = 0.0_R8
        wrk = geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3)
        IF (bceni_15_style .EQ. 0) THEN
          IF (wrk .GE. 0.) THEN
            abs0 = wrk
          ELSE
            abs0 = -wrk
          END IF
          IF (abs0 .LT. geo%qalfmin) THEN
            IF (switch%mdf_fhi .NE. 0) THEN
              t0 = 0.0_R8
              DO is=0,ns-1
                t0 = t0 + mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*1.5_R8*(geo&
&                 %fcs(ifc)*geo%fcqalf(ifc, 0)*dv%vaecrb(ifc, 0, is)+geo&
&                 %fcs(ifc)*geo%fcqalf(ifc, 1)*dv%vaecrb(ifc, 1, is))*&
&                 0.5_R8*(pl%na(icv1, is)+pl%na(icv2, is))*0.5_R8*(pl%ti&
&                 (icv1)+pl%ti(icv2))
              END DO
              IF (0.0_R8 .LT. t0) THEN
                CALL PUSHCONTROL1B(0)
              ELSE
                CALL PUSHCONTROL1B(1)
              END IF
              IF (0.0_R8 .GT. t0) THEN
                CALL PUSHREAL8(min4, r8/8)
                min4 = t0
                CALL PUSHCONTROL1B(0)
              ELSE
                CALL PUSHREAL8(min4, r8/8)
                min4 = 0.0_R8
                CALL PUSHCONTROL1B(1)
              END IF
              CALL PUSHCONTROL2B(0)
            ELSE
              CALL PUSHCONTROL2B(1)
            END IF
          ELSE
            DO is=0,ns-1
              IF (is_neutral(is)) THEN
                CALL PUSHCONTROL2B(0)
              ELSE
                vbnd = (dv%vaecrb(ifc, 0, is)*geo%fcqalf(ifc, 0)+dv%&
&                 vaecrb(ifc, 1, is)*geo%fcqalf(ifc, 1))*mpg%bcfcor(mpg%&
&                 bccvp(ib, 1)+ibc-1)
                IF (wrk .GE. 0.) THEN
                  CALL PUSHREAL8(abs5, r8/8)
                  abs5 = wrk
                  CALL PUSHCONTROL1B(0)
                ELSE
                  CALL PUSHREAL8(abs5, r8/8)
                  abs5 = -wrk
                  CALL PUSHCONTROL1B(1)
                END IF
                x1 = csbc(icv1, is)*abs5
                y1 = vbc(icv1, is)*SIGN(1.0_R8, wrk) + vbnd
                IF (x1 .LT. y1) THEN
                  CALL PUSHREAL8(max6, r8/8)
                  max6 = y1
                  CALL PUSHCONTROL1B(0)
                ELSE
                  CALL PUSHREAL8(max6, r8/8)
                  max6 = x1
                  CALL PUSHCONTROL1B(1)
                END IF
                t0 = t0 + mompar(is, ib, 1)*pl%na(icv1, is)*geo%fcs(ifc)&
&                 *max6
                IF (conpar(is, ib, 2) .GT. 0.0_R8) THEN
                  t1 = t1 + co%dna0(icv1, is)/conpar(is, ib, 2)*pl%na(&
&                   icv1, is)
                  CALL PUSHCONTROL2B(2)
                ELSE
                  CALL PUSHCONTROL2B(1)
                END IF
              END IF
            END DO
            CALL PUSHCONTROL2B(2)
          END IF
        ELSE
!wdk sheath transmission factor consistent with truncated
!    Maxwellian distribution on Eirene side (NEMODS=7)
!    See Eirene manual for details.
          DO is=0,ns-1
            IF (.NOT.is_neutral(is)) THEN
              CALL PUSHREAL8(vt, r8/8)
              vt = SQRT(2.0_R8*pl%ti(icv1)/(am(is)*mp))
              IF (geo%fcqalf(ifc, 0) .GE. 0.) THEN
                CALL PUSHREAL8(abs1, r8/8)
                abs1 = geo%fcqalf(ifc, 0)
                CALL PUSHCONTROL1B(0)
              ELSE
                CALL PUSHREAL8(abs1, r8/8)
                abs1 = -geo%fcqalf(ifc, 0)
                CALL PUSHCONTROL1B(1)
              END IF
              CALL PUSHREAL8(result10, r8/8)
              result10 = PIT(icv1)
              CALL PUSHREAL8(t3, r8/8)
              t3 = result10*abs1*cs/vt
              IF (geo%fcqalf(ifc, 1) .GE. 0.) THEN
                CALL PUSHREAL8(abs2, r8/8)
                abs2 = geo%fcqalf(ifc, 1)
                CALL PUSHCONTROL1B(0)
              ELSE
                CALL PUSHREAL8(abs2, r8/8)
                abs2 = -geo%fcqalf(ifc, 1)
                CALL PUSHCONTROL1B(1)
              END IF
!WG_TODO correct for drift contributions!
              CALL PUSHREAL8(result10, r8/8)
              result10 = PIT(icv1)
              CALL PUSHREAL8(t4, r8/8)
              t4 = SQRT((result10*abs2*cs/vt)**2 + (geo%cvbb(icv1, 2)/&
&               geo%cvbb(icv1, 3)*cs/vt)**2)
!corrected for factor 3/2 in parallel convection
              CALL PUSHREAL8(result10, r8/8)
              result10 = SHEATH_G(t3)
              CALL PUSHREAL8(result20, r8/8)
              result20 = SHEATH_G(t3)
              dsh = 1.0_R8 + t3**2 + t4**2 + 0.5_R8*(result10-1.0_R8)/&
&               result20
              t0 = t0 + dsh*mompar(is, ib, 1)*pl%na(icv1, is)
              IF (conpar(is, ib, 2) .GT. 0.0_R8) THEN
                CALL PUSHCONTROL1B(0)
              ELSE
                CALL PUSHCONTROL1B(1)
              END IF
              CALL PUSHCONTROL1B(1)
            ELSE
              CALL PUSHCONTROL1B(0)
            END IF
          END DO
          IF (geo%fcpbs(ifc) .GE. 0.) THEN
            CALL PUSHREAL8(abs3, r8/8)
            abs3 = geo%fcpbs(ifc)
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHREAL8(abs3, r8/8)
            abs3 = -geo%fcpbs(ifc)
            CALL PUSHCONTROL1B(1)
          END IF
          IF (geo%fcpbs(ifc) .GE. 0.) THEN
            CALL PUSHREAL8(abs4, r8/8)
            abs4 = geo%fcpbs(ifc)
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHREAL8(abs4, r8/8)
            abs4 = -geo%fcpbs(ifc)
            CALL PUSHCONTROL1B(1)
          END IF
          CALL PUSHCONTROL2B(3)
        END IF
        IF (switch%mdf_fhi .NE. 0) THEN
          CALL PUSHREAL8(t0, r8/8)
          t0 = 0.0_R8
          DO is=0,ns-1
            t0 = t0 + mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*2.5_R8*(geo%fcs&
&             (ifc)*geo%fcqalf(ifc, 0)*dv%vadia(ifc, 0, is)+geo%fcs(ifc)&
&             *geo%fcqalf(ifc, 1)*dv%vadia(ifc, 1, is))*0.5_R8*(pl%na(&
&             icv1, is)+pl%na(icv2, is))*0.5_R8*(pl%ti(icv1)+pl%ti(icv2)&
&             )
          END DO
          IF (0.0_R8 .LT. t0) THEN
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHCONTROL1B(1)
          END IF
          IF (0.0_R8 .GT. t0) THEN
            CALL PUSHREAL8(min5, r8/8)
            min5 = t0
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHREAL8(min5, r8/8)
            min5 = 0.0_R8
            CALL PUSHCONTROL1B(1)
          END IF
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
      END DO
      DO ibc=mpg%bccvp(ib, 2),1,-1
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          tempb2 = srwb%shi0(icv1, 1)/pl%ti(icv1)
          min5b = tempb2
          plb%ti(icv1) = plb%ti(icv1) - min5*tempb2/pl%ti(icv1)
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            CALL POPREAL8(min5, r8/8)
            t0b = min5b
          ELSE
            CALL POPREAL8(min5, r8/8)
            t0b = 0.D0
          END IF
          max7b = srwb%shi0(icv1, 0)
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) t0b = t0b + max7b
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          DO is=ns-1,0,-1
            temp5 = pl%ti(icv1) + pl%ti(icv2)
            temp2 = pl%na(icv1, is) + pl%na(icv2, is)
            temp4 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
            temp3 = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
            tempb7 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*0.5_R8**2*2.5_R8&
&             *t0b
            tempb6 = temp2*temp5*tempb7
            tempb1 = (temp4*dv%vadia(ifc, 0, is)+temp3*dv%vadia(ifc, 1, &
&             is))*tempb7
            plb%na(icv1, is) = plb%na(icv1, is) + temp5*tempb1
            plb%na(icv2, is) = plb%na(icv2, is) + temp5*tempb1
            plb%ti(icv1) = plb%ti(icv1) + temp2*tempb1
            plb%ti(icv2) = plb%ti(icv2) + temp2*tempb1
            dvb%vadia(ifc, 0, is) = dvb%vadia(ifc, 0, is) + temp4*tempb6
            dvb%vadia(ifc, 1, is) = dvb%vadia(ifc, 1, is) + temp3*tempb6
          END DO
          CALL POPREAL8(t0, r8/8)
          tempb2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*srwb%shi0(icv1, 0)
          dvb%fhipsch(ifc, 0) = dvb%fhipsch(ifc, 0) + tempb2
          dvb%fhipsch(ifc, 1) = dvb%fhipsch(ifc, 1) + tempb2
        END IF
        CALL POPCONTROL2B(branch)
        IF (branch .LT. 2) THEN
          IF (branch .EQ. 0) THEN
            tempb2 = srwb%shi0(icv1, 1)/pl%ti(icv1)
            min4b = tempb2
            plb%ti(icv1) = plb%ti(icv1) - min4*tempb2/pl%ti(icv1)
            CALL POPCONTROL1B(branch)
            IF (branch .EQ. 0) THEN
              CALL POPREAL8(min4, r8/8)
              t0b = min4b
            ELSE
              CALL POPREAL8(min4, r8/8)
              t0b = 0.D0
            END IF
            max5b = srwb%shi0(icv1, 0)
            CALL POPCONTROL1B(branch)
            IF (branch .EQ. 0) t0b = t0b + max5b
            DO is=ns-1,0,-1
              temp5 = pl%ti(icv1) + pl%ti(icv2)
              temp2 = pl%na(icv1, is) + pl%na(icv2, is)
              temp0 = geo%fcs(ifc)*geo%fcqalf(ifc, 0)
              temp = geo%fcs(ifc)*geo%fcqalf(ifc, 1)
              tempb3 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*0.5_R8**2*&
&               1.5_R8*t0b
              tempb4 = temp2*temp5*tempb3
              tempb1 = (temp0*dv%vaecrb(ifc, 0, is)+temp*dv%vaecrb(ifc, &
&               1, is))*tempb3
              plb%na(icv1, is) = plb%na(icv1, is) + temp5*tempb1
              plb%na(icv2, is) = plb%na(icv2, is) + temp5*tempb1
              plb%ti(icv1) = plb%ti(icv1) + temp2*tempb1
              plb%ti(icv2) = plb%ti(icv2) + temp2*tempb1
              dvb%vaecrb(ifc, 0, is) = dvb%vaecrb(ifc, 0, is) + temp0*&
&               tempb4
              dvb%vaecrb(ifc, 1, is) = dvb%vaecrb(ifc, 1, is) + temp*&
&               tempb4
            END DO
            tempb2 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*srwb%shi0(icv1, &
&             0)
            dvb%fhipsch(ifc, 0) = dvb%fhipsch(ifc, 0) + tempb2
            dvb%fhipsch(ifc, 1) = dvb%fhipsch(ifc, 1) + tempb2
          END IF
          tempb3 = -(geo%fcs(ifc)*geo%qalfmax*1.5_R8*srwb%shi0(icv1, 1))
          srwb%shi0(icv1, 1) = 0.D0
          csb0 = dv%ni(icv1, 1)*tempb3
          dvb%ni(icv1, 1) = dvb%ni(icv1, 1) + cs*tempb3
          srwb%shi0(icv1, 0) = 0.D0
        ELSE IF (branch .EQ. 2) THEN
          tempb2 = switch%stab_coeff_sheath_ti*geo%fcs(ifc)*srwb%shi0(&
&           icv1, 0)
          tempb5 = pl%ti(icv1)*tempb2
          plb%ti(icv1) = plb%ti(icv1) + dv%ne(icv1)*cs*tempb2
          eniparb(ib, 1) = eniparb(ib, 1) - t0*srwb%shi0(icv1, 1)
          t0b = -(enipar(ib, 1)*srwb%shi0(icv1, 1))
          tempb2 = -(switch%stab_coeff_sheath_ti*geo%fcs(ifc)*srwb%shi0(&
&           icv1, 1))
          dvb%ne(icv1) = dvb%ne(icv1) + cs*tempb5 + cs*tempb2
          csb0 = dv%ne(icv1)*tempb5 + dv%ne(icv1)*tempb2
          tempb3 = -(fac_he_anom_bc*geo%fcs(ifc)*srwb%shi0(icv1, 1))
          eniparb(ib, 2) = eniparb(ib, 2) + t1*tempb3
          t1b = enipar(ib, 2)*tempb3
          wrk = geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3)
          DO is=ns-1,0,-1
            CALL POPCONTROL2B(branch)
            IF (branch .NE. 0) THEN
              IF (branch .NE. 1) THEN
                tempb2 = t1b/conpar(is, ib, 2)
                cob%dna0(icv1, is) = cob%dna0(icv1, is) + pl%na(icv1, is&
&                 )*tempb2
                plb%na(icv1, is) = plb%na(icv1, is) + co%dna0(icv1, is)*&
&                 tempb2
                conparb(is, ib, 2) = conparb(is, ib, 2) - co%dna0(icv1, &
&                 is)*pl%na(icv1, is)*tempb2/conpar(is, ib, 2)
              END IF
              tempb3 = geo%fcs(ifc)*t0b
              tempb4 = pl%na(icv1, is)*tempb3
              plb%na(icv1, is) = plb%na(icv1, is) + mompar(is, ib, 1)*&
&               max6*tempb3
              momparb(is, ib, 1) = momparb(is, ib, 1) + max6*tempb4
              max6b = mompar(is, ib, 1)*tempb4
              CALL POPCONTROL1B(branch)
              IF (branch .EQ. 0) THEN
                CALL POPREAL8(max6, r8/8)
                y1b = max6b
                x1b = 0.D0
              ELSE
                CALL POPREAL8(max6, r8/8)
                x1b = max6b
                y1b = 0.D0
              END IF
              vbcb(icv1, is) = vbcb(icv1, is) + SIGN(1.0_R8, wrk)*y1b
              vbndb = y1b
              csbcb(icv1, is) = csbcb(icv1, is) + abs5*x1b
              CALL POPCONTROL1B(branch)
              IF (branch .EQ. 0) THEN
                CALL POPREAL8(abs5, r8/8)
              ELSE
                CALL POPREAL8(abs5, r8/8)
              END IF
              tempb3 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*vbndb
              dvb%vaecrb(ifc, 0, is) = dvb%vaecrb(ifc, 0, is) + geo%&
&               fcqalf(ifc, 0)*tempb3
              dvb%vaecrb(ifc, 1, is) = dvb%vaecrb(ifc, 1, is) + geo%&
&               fcqalf(ifc, 1)*tempb3
            END IF
          END DO
        ELSE
          tempb7 = switch%stab_coeff_sheath_ti*abs4*srwb%shi0(icv1, 0)
          t0b = cs*tempb7
          csb0 = t0*tempb7
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            CALL POPREAL8(abs4, r8/8)
          ELSE
            CALL POPREAL8(abs4, r8/8)
          END IF
          tempb7 = -((switch%stab_coeff_sheath_ti+1.0_R8)*abs3*srwb%shi0&
&           (icv1, 1))
          t2b = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*srwb%shi0(icv1, 1)
          t1b = -(geo%fcs(ifc)*srwb%shi0(icv1, 1))
          t0b = t0b + cs*tempb7
          csb0 = csb0 + t0*tempb7
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            CALL POPREAL8(abs3, r8/8)
          ELSE
            CALL POPREAL8(abs3, r8/8)
          END IF
          DO is=ns-1,0,-1
            CALL POPCONTROL1B(branch)
            IF (branch .NE. 0) THEN
              dvb%fhm(ifc, 0, is) = dvb%fhm(ifc, 0, is) + t2b
              dvb%fhm(ifc, 1, is) = dvb%fhm(ifc, 1, is) + t2b
              CALL POPCONTROL1B(branch)
              IF (branch .EQ. 0) THEN
                temp5 = pl%na(icv1, is)/conpar(is, ib, 2)
                tempb7 = fac_he_anom_bc*t1b
                eniparb(ib, 2) = eniparb(ib, 2) + co%dna0(icv1, is)*&
&                 temp5*tempb7
                cob%dna0(icv1, is) = cob%dna0(icv1, is) + enipar(ib, 2)*&
&                 temp5*tempb7
                tempb2 = enipar(ib, 2)*co%dna0(icv1, is)*tempb7/conpar(&
&                 is, ib, 2)
                plb%na(icv1, is) = plb%na(icv1, is) + tempb2
                conparb(is, ib, 2) = conparb(is, ib, 2) - temp5*tempb2
              END IF
              dsh = 1.0_R8 + t3**2 + t4**2 + 0.5_R8*(result10-1.0_R8)/&
&               result20
              tempb7 = pl%na(icv1, is)*t0b
              plb%na(icv1, is) = plb%na(icv1, is) + dsh*mompar(is, ib, 1&
&               )*t0b
              dshb = mompar(is, ib, 1)*tempb7
              momparb(is, ib, 1) = momparb(is, ib, 1) + dsh*tempb7
              t3b = 2*t3*dshb
              t4b = 2*t4*dshb
              tempb7 = 0.5_R8*dshb/result20
              result10b = tempb7
              result20b = -((result10-1.0_R8)*tempb7/result20)
              CALL POPREAL8(result20, r8/8)
              CALL SHEATH_G_B(t3, t3b, result20b)
              CALL POPREAL8(result10, r8/8)
              CALL SHEATH_G_B(t3, t3b, result10b)
              CALL POPREAL8(t4, r8/8)
              temp4 = geo%cvbb(icv1, 3)*vt
              temp3 = cs/temp4
              temp0 = geo%cvbb(icv1, 2)*temp3
              temp = result10*abs2*cs/vt
              IF (temp**2 + temp0**2 .EQ. 0.D0) THEN
                tempb6 = 0.D0
              ELSE
                tempb6 = t4b/(2.0*SQRT(temp**2+temp0**2))
              END IF
              tempb7 = result10*abs2*2*temp*tempb6/vt
              tempb4 = geo%cvbb(icv1, 2)*2*temp0*tempb6/temp4
              csb0 = csb0 + tempb4 + tempb7
              vtb = -(geo%cvbb(icv1, 3)*temp3*tempb4) - cs*tempb7/vt
              CALL POPREAL8(result10, r8/8)
              CALL POPCONTROL1B(branch)
              IF (branch .EQ. 0) THEN
                CALL POPREAL8(abs2, r8/8)
              ELSE
                CALL POPREAL8(abs2, r8/8)
              END IF
              CALL POPREAL8(t3, r8/8)
              tempb3 = result10*abs1*t3b/vt
              csb0 = csb0 + tempb3
              vtb = vtb - cs*tempb3/vt
              CALL POPREAL8(result10, r8/8)
              CALL POPCONTROL1B(branch)
              IF (branch .EQ. 0) THEN
                CALL POPREAL8(abs1, r8/8)
              ELSE
                CALL POPREAL8(abs1, r8/8)
              END IF
              CALL POPREAL8(vt, r8/8)
              IF (.NOT.2.0_R8*(pl%ti(icv1)/(am(is)*mp)) .EQ. 0.D0) plb%&
&               ti(icv1) = plb%ti(icv1) + 2.0_R8*vtb/(am(is)*mp*2.0*SQRT&
&                 (2.0_R8*(pl%ti(icv1)/(am(is)*mp))))
            END IF
          END DO
        END IF
        CALL POPREAL8(t1, r8/8)
        CALL POPREAL8(t0, r8/8)
        CALL POPREAL8(cs, r8/8)
        temp4 = pz(icv1)/rz(icv1)
        IF (temp4 .EQ. 0.D0) THEN
          tempb3 = 0.D0
        ELSE
          tempb3 = csb0/(rz(icv1)*2.0*SQRT(temp4))
        END IF
        pzb(icv1) = pzb(icv1) + tempb3
        rzb(icv1) = rzb(icv1) - temp4*tempb3
        DO is=ns-1,0,-1
          CALL POPREAL8ARRAY(vbc, r8*ncv*ns/8)
          CALL VBC_IS_B(ib, is, ibc, icv1, icv2, ifc, csbc(icv1, is), &
&                 csbcb(icv1, is), wrk)
          CALL POPREAL8(cs, r8/8)
          CALL POPREAL8ARRAY(csbc, r8*ncv*ns/8)
          csb0 = 0.D0
          CALL CSBC_IS_B(icv1, ib, is, cs, csb0)
        END DO
        CALL POPINTEGER4(ifc)
        CALL POPINTEGER4(icv2)
        CALL POPINTEGER4(icv1)
      END DO
    CASE (16) 
!
! -- BCENI=16 -- Feedback boundary condition with constant temperature
!
!
      IF (switch%bceni_16_style .EQ. 0) THEN
!       ..compute average temperature on boundary
        t0 = 0.0_R8
        t1 = 0.0_R8
!wdk Note on backwards compatibility: feedback now always on
!wdk flux through the boundary itself (no offset)
        totflux = 0.0_R8
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          t0 = t0 + geo%fcs(ifc)*dv%ni(icv1, 0)
!wdk at the moment, totflux only contains ion/neutral heat flux;
!wdk bc_type16_kinetic_energy.eq.1 option not yet included
          t1 = t1 + geo%fcs(ifc)*dv%ni(icv1, 0)*pl%ti(icv1)
          totflux = totflux - (dv%fhi(ifc, 0)+dv%fhi(ifc, 1))*mpg%bcfcor&
&           (mpg%bccvp(ib, 1)+ibc-1)
        END DO
        CALL PUSHREAL8(t1, r8/8)
        t1 = t1/t0
        totpar = fac_he_anom_bc*enipar(ib, 1)
        IF (enipar(ib, 2) .GT. 0.0_R8) THEN
          t3 = enipar(ib, 2)
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        IF (enipar(ib, 2) .LE. 0.0_R8) THEN
          t3 = switch%b2stbc_bc_ref_ti
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        IF (totflux .GE. 0.) THEN
          x2 = totflux
          CALL PUSHCONTROL1B(0)
        ELSE
          x2 = -totflux
          CALL PUSHCONTROL1B(1)
        END IF
        IF (totpar .GE. 0.) THEN
          y2 = totpar
          CALL PUSHCONTROL1B(0)
        ELSE
          y2 = -totpar
          CALL PUSHCONTROL1B(1)
        END IF
        IF (x2 .LT. y2) THEN
          max8 = y2
          CALL PUSHCONTROL1B(0)
        ELSE
          max8 = x2
          CALL PUSHCONTROL1B(1)
        END IF
        t2b = 0.D0
        DO ibc=mpg%bccvp(ib, 2),1,-1
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          srwb%shi0(icv1, 1) = 0.D0
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          t2b = t2b + geo%fcs(ifc)*vbig*ne00*srwb%shi0(icv1, 0)
          srwb%shi0(icv1, 0) = 0.D0
        END DO
        temp7 = t3/max8
        tempb2 = t1*t2b
        t1b = (1.0_R8-(totflux-totpar)*temp7)*t2b
        totfluxb = -(temp7*tempb2)
        totparb = temp7*tempb2
        tempb7 = -((totflux-totpar)*tempb2/max8)
        t3b = tempb7
        max8b = -(temp7*tempb7)
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          y2b = max8b
          x2b = 0.D0
        ELSE
          x2b = max8b
          y2b = 0.D0
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          totparb = totparb + y2b
        ELSE
          totparb = totparb - y2b
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          totfluxb = totfluxb + x2b
        ELSE
          totfluxb = totfluxb - x2b
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) t3b = 0.D0
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) eniparb(ib, 2) = eniparb(ib, 2) + t3b
        eniparb(ib, 1) = eniparb(ib, 1) + fac_he_anom_bc*totparb
        CALL POPREAL8(t1, r8/8)
        t0b = -(t1*t1b/t0**2)
        t1b = t1b/t0
        DO ibc=mpg%bccvp(ib, 2),1,-1
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          tempb2 = -(mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*totfluxb)
          dvb%fhi(ifc, 0) = dvb%fhi(ifc, 0) + tempb2
          dvb%fhi(ifc, 1) = dvb%fhi(ifc, 1) + tempb2
          tempb2 = geo%fcs(ifc)*t1b
          dvb%ni(icv1, 0) = dvb%ni(icv1, 0) + pl%ti(icv1)*tempb2 + geo%&
&           fcs(ifc)*t0b
          plb%ti(icv1) = plb%ti(icv1) + dv%ni(icv1, 0)*tempb2
        END DO
      ELSE IF (switch%bceni_16_style .EQ. 1) THEN
!
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
!srv 16.02.12 }
          IF (.NOT.once_bceni) THEN
            IF (switch%use_astra .NE. 0) THEN
              CALL PUSHCONTROL1B(0)
            ELSE
              senipar = 0.0_R8
              DO ibw=ib,nbc
                IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') &
&                   .AND. bceni(ibw) .EQ. bceni(ib)) THEN
                  senipar = senipar + enipar(ibw, 1)
                  CALL PUSHCONTROL1B(1)
                ELSE
                  CALL PUSHCONTROL1B(0)
                END IF
              END DO
              CALL PUSHCONTROL1B(1)
            END IF
            tis = 0.0_R8
            nivs = 0.0_R8
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bceni(ibw) .EQ. bceni(ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  CALL PUSHINTEGER4(icv)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  tis = tis + pl%ti(icv)*dv%ni(icv, 0)*geo%cvvol(icv)
                  nivs = nivs + dv%ni(icv, 0)*geo%cvvol(icv)
                END DO
                CALL PUSHINTEGER4(ibc - 1)
                CALL PUSHCONTROL1B(1)
              ELSE
                CALL PUSHCONTROL1B(0)
              END IF
            END DO
            CALL PUSHREAL8(tis, r8/8)
            tis = tis/nivs
            totflux = 0.0_R8
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bceni(ibw) .EQ. bceni(ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  CALL PUSHINTEGER4(icv)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  CALL PUSHINTEGER4(ifc)
                  ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                  IF (switch%mdf_fhi .NE. 0) THEN
                    totflux = totflux - mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc&
&                     -1)*(dv%fhi_mdf(ifc, 0)+dv%fhi_mdf(ifc, 1))
                    DO is=0,ns-1
                      totflux = totflux - pl%ti(icv)*pl%na(icv, is)*geo%&
&                       fcs(ifc)*mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)*(dv&
&                       %vaecrb(ifc, 0, is)*geo%fcqalf(ifc, 0)+dv%vaecrb&
&                       (ifc, 1, is)*geo%fcqalf(ifc, 1))
                    END DO
                    CALL PUSHCONTROL1B(1)
                  ELSE
                    totflux = totflux - mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc&
&                     -1)*(dv%fhi(ifc, 0)+dv%fhi(ifc, 1))
                    CALL PUSHCONTROL1B(0)
                  END IF
                END DO
                CALL PUSHINTEGER4(ibc - 1)
                CALL PUSHCONTROL1B(1)
              ELSE
                CALL PUSHCONTROL1B(0)
              END IF
            END DO
            IF (enipar(ib, 2) .GT. 0.0_R8) THEN
              t3 = enipar(ib, 2)
              CALL PUSHCONTROL1B(0)
            ELSE
              CALL PUSHCONTROL1B(1)
            END IF
            IF (enipar(ib, 2) .LE. 0.0_R8) THEN
              t3 = switch%b2stbc_bc_ref_ti
              CALL PUSHCONTROL1B(0)
            ELSE
              CALL PUSHCONTROL1B(1)
            END IF
            IF (totflux .GE. 0.) THEN
              x3 = totflux
              CALL PUSHCONTROL1B(0)
            ELSE
              x3 = -totflux
              CALL PUSHCONTROL1B(1)
            END IF
            IF (x3 .LT. senipar) THEN
              max9 = senipar
              CALL PUSHCONTROL1B(0)
            ELSE
              max9 = x3
              CALL PUSHCONTROL1B(1)
            END IF
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bcene(ibw) .EQ. bcene(ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  CALL PUSHINTEGER4(icv)
                  CALL PUSHINTEGER4(ifc)
                END DO
                CALL PUSHINTEGER4(ibc - 1)
                CALL PUSHCONTROL1B(1)
              ELSE
                CALL PUSHCONTROL1B(0)
              END IF
            END DO
            tisb = 0.D0
            DO ibw=nbc,ib,-1
              CALL POPCONTROL1B(branch)
              IF (branch .NE. 0) THEN
                CALL POPINTEGER4(ad_to1)
                DO ibc=ad_to1,1,-1
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  srwb%shi0(icv, 1) = 0.D0
                  ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                  tisb = tisb + geo%fcs(ifc)*vbig*ne00*srwb%shi0(icv, 0)
                  srwb%shi0(icv, 0) = 0.D0
                  CALL POPINTEGER4(ifc)
                  CALL POPINTEGER4(icv)
                END DO
              END IF
            END DO
            temp7 = t3/max9
            tempb2 = tis*tisb
            tisb = (1.0_R8-(totflux-senipar)*temp7)*tisb
            totfluxb = -(temp7*tempb2)
            seniparb = seniparb + temp7*tempb2
            tempb7 = -((totflux-senipar)*tempb2/max9)
            t3b = tempb7
            max9b = -(temp7*tempb7)
            CALL POPCONTROL1B(branch)
            IF (branch .EQ. 0) THEN
              seniparb = seniparb + max9b
              x3b = 0.D0
            ELSE
              x3b = max9b
            END IF
            CALL POPCONTROL1B(branch)
            IF (branch .EQ. 0) THEN
              totfluxb = totfluxb + x3b
            ELSE
              totfluxb = totfluxb - x3b
            END IF
            CALL POPCONTROL1B(branch)
            IF (branch .EQ. 0) t3b = 0.D0
            CALL POPCONTROL1B(branch)
            IF (branch .EQ. 0) eniparb(ib, 2) = eniparb(ib, 2) + t3b
            DO ibw=nbc,ib,-1
              CALL POPCONTROL1B(branch)
              IF (branch .NE. 0) THEN
                CALL POPINTEGER4(ad_to0)
                DO ibc=ad_to0,1,-1
                  CALL POPCONTROL1B(branch)
                  IF (branch .EQ. 0) THEN
                    icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                    ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                    tempb2 = -(mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)*&
&                     totfluxb)
                    dvb%fhi(ifc, 0) = dvb%fhi(ifc, 0) + tempb2
                    dvb%fhi(ifc, 1) = dvb%fhi(ifc, 1) + tempb2
                  ELSE
                    DO is=ns-1,0,-1
                      tempb2 = -(geo%fcs(ifc)*mpg%bcfcor(mpg%bccvp(ibw, &
&                       1)+ibc-1)*totfluxb)
                      tempb5 = (geo%fcqalf(ifc, 0)*dv%vaecrb(ifc, 0, is)&
&                       +geo%fcqalf(ifc, 1)*dv%vaecrb(ifc, 1, is))*&
&                       tempb2
                      tempb7 = pl%ti(icv)*pl%na(icv, is)*tempb2
                      dvb%vaecrb(ifc, 0, is) = dvb%vaecrb(ifc, 0, is) + &
&                       geo%fcqalf(ifc, 0)*tempb7
                      dvb%vaecrb(ifc, 1, is) = dvb%vaecrb(ifc, 1, is) + &
&                       geo%fcqalf(ifc, 1)*tempb7
                      plb%ti(icv) = plb%ti(icv) + pl%na(icv, is)*tempb5
                      plb%na(icv, is) = plb%na(icv, is) + pl%ti(icv)*&
&                       tempb5
                    END DO
                    tempb2 = -(mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)*&
&                     totfluxb)
                    dvb%fhi_mdf(ifc, 0) = dvb%fhi_mdf(ifc, 0) + tempb2
                    dvb%fhi_mdf(ifc, 1) = dvb%fhi_mdf(ifc, 1) + tempb2
                  END IF
                  CALL POPINTEGER4(ifc)
                  CALL POPINTEGER4(icv)
                END DO
              END IF
            END DO
            CALL POPREAL8(tis, r8/8)
            nivsb = -(tis*tisb/nivs**2)
            tisb = tisb/nivs
            DO ibw=nbc,ib,-1
              CALL POPCONTROL1B(branch)
              IF (branch .NE. 0) THEN
                CALL POPINTEGER4(ad_to)
                DO ibc=ad_to,1,-1
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  tempb2 = geo%cvvol(icv)*tisb
                  dvb%ni(icv, 0) = dvb%ni(icv, 0) + geo%cvvol(icv)*nivsb&
&                   + pl%ti(icv)*tempb2
                  plb%ti(icv) = plb%ti(icv) + dv%ni(icv, 0)*tempb2
                  CALL POPINTEGER4(icv)
                END DO
              END IF
            END DO
            CALL POPCONTROL1B(branch)
            IF (branch .NE. 0) THEN
              DO ibw=nbc,ib,-1
                CALL POPCONTROL1B(branch)
                IF (branch .NE. 0) eniparb(ibw, 1) = eniparb(ibw, 1) + &
&                   seniparb
              END DO
              seniparb = 0.D0
            END IF
          END IF
        END IF
      END IF
    CASE (17) 

    CASE (18) 
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        srwb%shi0(icv1, 1) = 0.D0
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        t1b = geo%fcs(ifc)*vbig*ne00*srwb%shi0(icv1, 0)
        srwb%shi0(icv1, 0) = 0.D0
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
        eniparb(ib, 1) = eniparb(ib, 1) - pl%ti(icv2)*t1b
        plb%ti(icv2) = plb%ti(icv2) + (1.0_R8-enipar(ib, 1))*t1b
      END DO
    CASE (19) 

    CASE (20) 
      IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
        totflux = 0.0_R8
        t0 = 0.0_R8
        weight = 0.0_R8
        tiave = 0.0_R8
        niave = 0.0_R8
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          totflux = totflux - mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%fhi&
&           (ifc, 0)+dv%fhi(ifc, 1))
          t0 = t0 + pl%ti(icv1)*dv%ni(icv1, 0)*geo%cvvol(icv1)
          weight = weight + dv%ni(icv1, 0)*geo%cvvol(icv1)
          tiave = tiave + pl%ti(icv2)*dv%ni(icv2, 0)*geo%cvvol(icv2)
          niave = niave + dv%ni(icv2, 0)*geo%cvvol(icv2)
        END DO
        CALL PUSHREAL8(t0, r8/8)
        t0 = t0/weight
        CALL PUSHREAL8(tiave, r8/8)
        tiave = tiave/niave
        IF (enipar(ib, 2) .GT. 0.0_R8) THEN
          t3 = enipar(ib, 2)
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        IF (enipar(ib, 2) .LE. 0.0_R8) THEN
          t3 = switch%b2stbc_bc_ref_ti
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        t1 = (1.0_R8-t3*(totflux-enipar(ib, 1))/enipar(ib, 1))*t0
        t1b = 0.D0
        tiaveb = 0.D0
        DO ibc=mpg%bccvp(ib, 2),1,-1
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          srwb%shi0(icv1, 1) = 0.D0
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          tempb2 = vbig*ne00*geo%fcs(ifc)*srwb%shi0(icv1, 0)
          srwb%shi0(icv1, 0) = 0.D0
          plb%ti(icv2) = plb%ti(icv2) + t1*tempb2/tiave
          tempb7 = pl%ti(icv2)*tempb2/tiave
          t1b = t1b + tempb7
          tiaveb = tiaveb - t1*tempb7/tiave
        END DO
        temp7 = t3/enipar(ib, 1)
        tempb2 = t0*t1b
        t0b = (1.0_R8-(totflux-enipar(ib, 1))*temp7)*t1b
        totfluxb = -(temp7*tempb2)
        tempb7 = -((totflux-enipar(ib, 1))*tempb2/enipar(ib, 1))
        eniparb(ib, 1) = eniparb(ib, 1) + temp7*tempb2 - temp7*tempb7
        t3b = tempb7
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) t3b = 0.D0
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) eniparb(ib, 2) = eniparb(ib, 2) + t3b
        CALL POPREAL8(tiave, r8/8)
        niaveb = -(tiave*tiaveb/niave**2)
        tiaveb = tiaveb/niave
        CALL POPREAL8(t0, r8/8)
        weightb = -(t0*t0b/weight**2)
        t0b = t0b/weight
        DO ibc=mpg%bccvp(ib, 2),1,-1
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          tempb2 = geo%cvvol(icv2)*tiaveb
          dvb%ni(icv2, 0) = dvb%ni(icv2, 0) + geo%cvvol(icv2)*niaveb + &
&           pl%ti(icv2)*tempb2
          plb%ti(icv2) = plb%ti(icv2) + dv%ni(icv2, 0)*tempb2
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          tempb2 = geo%cvvol(icv1)*t0b
          dvb%ni(icv1, 0) = dvb%ni(icv1, 0) + geo%cvvol(icv1)*weightb + &
&           pl%ti(icv1)*tempb2
          plb%ti(icv1) = plb%ti(icv1) + dv%ni(icv1, 0)*tempb2
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          tempb2 = -(mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*totfluxb)
          dvb%fhi(ifc, 0) = dvb%fhi(ifc, 0) + tempb2
          dvb%fhi(ifc, 1) = dvb%fhi(ifc, 1) + tempb2
        END DO
      END IF
    CASE (21) 

    CASE (22) 
!wdk    Notes:
!wdk     * need correction for misaligned grids -> t1
!wdk     * need to correct this BC for hybrid scheme
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
! number of the guard cell face
        CALL PUSHREAL8(t2, r8/8)
        t2 = 0.0_R8
        DO is=0,ns-1
          IF (.NOT.is_neutral(is)) THEN
            CALL PUSHREAL8(csb, r8/8)
            csb = SQRT((rt%rza(icv1, is)*pl%te(icv1)+pl%ti(icv1))/(am(is&
&             )*mp))
            t2 = t2 + csb*pl%na(icv1, is)
            CALL PUSHCONTROL1B(1)
          ELSE
            CALL PUSHCONTROL1B(0)
          END IF
        END DO
      END DO
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        t0 = geo%fcqalf(ifc, 1)
        tempb7 = -(vbig*ne00*ev*srwb%shi0(icv1, 1))
        srwb%shi0(icv1, 1) = 0.D0
        tempb6 = -(geo%fcs(ifc)*tempb7)
        eniparb(ib, 1) = eniparb(ib, 1) + t2*tempb6
        t2b = enipar(ib, 1)*tempb6
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
        t1 = (geo%fchc(ifc, 1)+geo%fchc(ifc, 2))/geo%fcht(ifc)*geo%&
&         fcqbet(ifc, 0)
        temp7 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*t1
        tempb2 = vbig*ne00*ev*srwb%shi0(icv1, 0)
        cob%chci(ifc, 1) = cob%chci(ifc, 1) + t0*tempb7 + (t0*pl%ti(icv2&
&         )-temp7*(pl%ti(mpg%fcvx(ifc, 2))-pl%ti(mpg%fcvx(ifc, 1))))*&
&         tempb2
        srwb%shi0(icv1, 0) = 0.D0
        tempb6 = co%chci(ifc, 1)*tempb2
        plb%ti(icv2) = plb%ti(icv2) + t0*tempb6
        plb%ti(mpg%fcvx(ifc, 2)) = plb%ti(mpg%fcvx(ifc, 2)) - temp7*&
&         tempb6
        plb%ti(mpg%fcvx(ifc, 1)) = plb%ti(mpg%fcvx(ifc, 1)) + temp7*&
&         tempb6
        DO is=ns-1,0,-1
          CALL POPCONTROL1B(branch)
          IF (branch .NE. 0) THEN
            csbb = pl%na(icv1, is)*t2b
            plb%na(icv1, is) = plb%na(icv1, is) + csb*t2b
            CALL POPREAL8(csb, r8/8)
            IF ((rt%rza(icv1, is)*pl%te(icv1)+pl%ti(icv1))/(am(is)*mp) &
&               .EQ. 0.D0) THEN
              tempb2 = 0.D0
            ELSE
              tempb2 = csbb/(am(is)*mp*2.0*SQRT((rt%rza(icv1, is)*pl%te(&
&               icv1)+pl%ti(icv1))/(am(is)*mp)))
            END IF
            rtb%rza(icv1, is) = rtb%rza(icv1, is) + pl%te(icv1)*tempb2
            plb%te(icv1) = plb%te(icv1) + rt%rza(icv1, is)*tempb2
            plb%ti(icv1) = plb%ti(icv1) + tempb2
          END IF
        END DO
        CALL POPREAL8(t2, r8/8)
      END DO
    CASE (23) 
!
      IF (.NOT.once_bceni) THEN
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
! Volume                                     !lk 12.12.12 {
          t0 = 0.0_R8
! Poloidally volume-averaged ion temperature in the cell next to boundary
          t1 = 0.0_R8
! Poloidally volume-averaged electron density in the cell next to boundary
          t2 = 0.0_R8
! Poloidally volume-averaged electron density in the boundary cell
          t3 = 0.0_R8
          CALL PUSHINTEGER4(ibw)
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                t0 = t0 + geo%cvvol(icv2)
                t1 = t1 + pl%ti(icv2)*geo%cvvol(icv2)
                t2 = t2 + dv%ne(icv2)*geo%cvvol(icv2)
                t3 = t3 + dv%ne(icv1)*geo%cvvol(icv2)
              END DO
              CALL PUSHINTEGER4(ibc - 1)
              CALL PUSHCONTROL1B(1)
            ELSE
              CALL PUSHCONTROL1B(0)
            END IF
          END DO
          t1 = t1/t0
          t2 = t2/t0
          t3 = t3/t0
          DO ibw=ib,nbc
!lk 12.12.12 }
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                IF (mpg%cvonclosedsurface(icv2)) THEN
                  CALL PUSHCONTROL1B(1)
                ELSE
                  CALL PUSHCONTROL1B(0)
                END IF
              END DO
              CALL PUSHINTEGER4(ibc - 1)
              CALL PUSHCONTROL1B(1)
            ELSE
              CALL PUSHCONTROL1B(0)
            END IF
          END DO
          t1b = 0.D0
          t2b = 0.D0
          t3b = 0.D0
          DO ibw=nbc,ib,-1
            CALL POPCONTROL1B(branch)
            IF (branch .NE. 0) THEN
              CALL POPINTEGER4(ad_to3)
              DO ibc=ad_to3,1,-1
                CALL POPCONTROL1B(branch)
                IF (branch .NE. 0) THEN
                  icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  srwb%shi0(icv1, 1) = 0.D0
                  icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                  ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                  temp6 = ev*t3*enipar(ibw, 1)
                  temp4 = t1*t2
                  tempb7 = vbig*ne00*geo%fcs(ifc)*srwb%shi0(icv1, 0)
                  tempb2 = tempb7/temp6
                  plb%ti(icv2) = plb%ti(icv2) + temp4*tempb2
                  tempb3 = (pl%ti(icv2)-t1)*tempb2
                  t1b = t1b + t2*tempb3 - temp4*tempb2
                  tempb6 = -((pl%ti(icv2)-t1)*temp4*tempb2/temp6)
                  eniparb(ibw, 1) = eniparb(ibw, 1) + ev*tempb7 + ev*t3*&
&                   tempb6
                  t3b = t3b + ev*enipar(ibw, 1)*tempb6
                  t2b = t2b + t1*tempb3
                END IF
              END DO
            END IF
          END DO
          t3b = t3b/t0
          t2b = t2b/t0
          t1b = t1b/t0
          DO ibw=nbc,ib,-1
            CALL POPCONTROL1B(branch)
            IF (branch .NE. 0) THEN
              CALL POPINTEGER4(ad_to2)
              DO ibc=ad_to2,1,-1
                icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                dvb%ne(icv1) = dvb%ne(icv1) + geo%cvvol(icv2)*t3b
                dvb%ne(icv2) = dvb%ne(icv2) + geo%cvvol(icv2)*t2b
                plb%ti(icv2) = plb%ti(icv2) + geo%cvvol(icv2)*t1b
              END DO
            END IF
          END DO
          CALL POPINTEGER4(ibw)
        END IF
      END IF
    CASE (24) 
!srv 16.02.12 }
      IF (.NOT.once_bceni) THEN
        IF (switch%use_astra .NE. 0) THEN
          CALL PUSHCONTROL1B(0)
        ELSE
          senipar = 0.0_R8
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              senipar = senipar + enipar(ibw, 1)
              CALL PUSHCONTROL1B(1)
            ELSE
              CALL PUSHCONTROL1B(0)
            END IF
          END DO
          CALL PUSHCONTROL1B(1)
        END IF
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
! Poloidally density-averaged ion temperature in the boundary cell     !IYS 21.01.2016
          tis = 0.0_R8
          nivs = 0.0_R8
          totflux = 0.0_R8
! Volume                                     !lk 12.12.12 {
          t0 = 0.0_R8
! Poloidally volume-averaged ion temperature in the cell next to boundary
          t1 = 0.0_R8
! Poloidally volume-averaged electron density in the cell next to boundary
          t2 = 0.0_R8
! Poloidally volume-averaged electron density in the boundary cell
          t3 = 0.0_R8
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                CALL PUSHINTEGER4(icv1)
                icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                CALL PUSHINTEGER4(ifc)
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                t0 = t0 + geo%cvvol(icv2)
                t1 = t1 + pl%ti(icv2)*geo%cvvol(icv2)
                tis = tis + pl%ti(icv1)*dv%ni(icv1, 0)*geo%cvvol(icv2)
                nivs = nivs + dv%ni(icv1, 0)*geo%cvvol(icv2)
                t2 = t2 + dv%ne(icv2)*geo%cvvol(icv2)
                t3 = t3 + dv%ne(icv1)*geo%cvvol(icv2)
                IF (switch%mdf_fhi .NE. 0) THEN
                  totflux = totflux - mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1&
&                   )*(dv%fhi_mdf(ifc, 0)+dv%fhi_mdf(ifc, 1))
                  DO is=0,ns-1
                    totflux = totflux - pl%ti(icv1)*pl%na(icv1, is)*geo%&
&                     fcs(ifc)*mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)*(dv%&
&                     vaecrb(ifc, 0, is)*geo%fcqalf(ifc, 0)+dv%vaecrb(&
&                     ifc, 1, is)*geo%fcqalf(ifc, 1))
                  END DO
                  CALL PUSHCONTROL1B(1)
                ELSE
                  totflux = totflux - mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1&
&                   )*(dv%fhi(ifc, 0)+dv%fhi(ifc, 1))
                  CALL PUSHCONTROL1B(0)
                END IF
              END DO
              CALL PUSHINTEGER4(ibc - 1)
              CALL PUSHCONTROL1B(1)
            ELSE
              CALL PUSHCONTROL1B(0)
            END IF
          END DO
          CALL PUSHREAL8(tis, r8/8)
          tis = tis/nivs
          t1 = t1/t0
          t2 = t2/t0
          t3 = t3/t0
          IF (enipar(ib, 2) .GT. 0.0_R8) THEN
            t4 = enipar(ib, 2)
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHCONTROL1B(1)
          END IF
          IF (enipar(ib, 2) .LE. 0.0_R8) THEN
            t4 = switch%b2stbc_bc_ref_ti
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHCONTROL1B(1)
          END IF
          IF (totflux .GE. 0.) THEN
            x4 = totflux
            CALL PUSHCONTROL1B(0)
          ELSE
            x4 = -totflux
            CALL PUSHCONTROL1B(1)
          END IF
          IF (x4 .LT. senipar) THEN
            max10 = senipar
            CALL PUSHCONTROL1B(0)
          ELSE
            max10 = x4
            CALL PUSHCONTROL1B(1)
          END IF
          CALL PUSHREAL8(tis, r8/8)
          tis = tis*(1.0_R8-t4*(totflux-senipar)/max10)
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                CALL PUSHINTEGER4(icv1)
                CALL PUSHINTEGER4(ifc)
              END DO
              CALL PUSHINTEGER4(ibc - 1)
              CALL PUSHCONTROL1B(1)
            ELSE
              CALL PUSHCONTROL1B(0)
            END IF
          END DO
          tisb = 0.D0
          t1b = 0.D0
          t2b = 0.D0
          t3b = 0.D0
          DO ibw=nbc,ib,-1
            CALL POPCONTROL1B(branch)
            IF (branch .NE. 0) THEN
              CALL POPINTEGER4(ad_to5)
              DO ibc=ad_to5,1,-1
                icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                srwb%shi0(icv1, 1) = 0.D0
                icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                temp6 = t1*t2
                tempb7 = vbig*ne00*geo%fcs(ifc)*srwb%shi0(icv1, 0)
                srwb%shi0(icv1, 0) = 0.D0
                tempb2 = tempb7/(t3*tis)
                plb%ti(icv2) = plb%ti(icv2) + temp6*tempb2
                tempb6 = (pl%ti(icv2)-t1)*tempb2
                t1b = t1b + t2*tempb6 - temp6*tempb2
                tempb3 = -((pl%ti(icv2)-t1)*temp6*tempb2/(t3*tis))
                tisb = tisb + tempb7 + t3*tempb3
                t3b = t3b + tis*tempb3
                t2b = t2b + t1*tempb6
                CALL POPINTEGER4(ifc)
                CALL POPINTEGER4(icv1)
              END DO
            END IF
          END DO
          CALL POPREAL8(tis, r8/8)
          temp7 = t4/max10
          tempb2 = tis*tisb
          tisb = (1.0_R8-(totflux-senipar)*temp7)*tisb
          totfluxb = -(temp7*tempb2)
          seniparb = seniparb + temp7*tempb2
          tempb7 = -((totflux-senipar)*tempb2/max10)
          t4b = tempb7
          max10b = -(temp7*tempb7)
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            seniparb = seniparb + max10b
            x4b = 0.D0
          ELSE
            x4b = max10b
          END IF
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            totfluxb = totfluxb + x4b
          ELSE
            totfluxb = totfluxb - x4b
          END IF
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) t4b = 0.D0
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) eniparb(ib, 2) = eniparb(ib, 2) + t4b
          t3b = t3b/t0
          t2b = t2b/t0
          t1b = t1b/t0
          CALL POPREAL8(tis, r8/8)
          nivsb = -(tis*tisb/nivs**2)
          tisb = tisb/nivs
          DO ibw=nbc,ib,-1
            CALL POPCONTROL1B(branch)
            IF (branch .NE. 0) THEN
              CALL POPINTEGER4(ad_to4)
              DO ibc=ad_to4,1,-1
                CALL POPCONTROL1B(branch)
                IF (branch .EQ. 0) THEN
                  icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                  tempb2 = -(mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)*&
&                   totfluxb)
                  dvb%fhi(ifc, 0) = dvb%fhi(ifc, 0) + tempb2
                  dvb%fhi(ifc, 1) = dvb%fhi(ifc, 1) + tempb2
                ELSE
                  DO is=ns-1,0,-1
                    tempb2 = -(geo%fcs(ifc)*mpg%bcfcor(mpg%bccvp(ibw, 1)&
&                     +ibc-1)*totfluxb)
                    tempb5 = (geo%fcqalf(ifc, 0)*dv%vaecrb(ifc, 0, is)+&
&                     geo%fcqalf(ifc, 1)*dv%vaecrb(ifc, 1, is))*tempb2
                    tempb7 = pl%ti(icv1)*pl%na(icv1, is)*tempb2
                    dvb%vaecrb(ifc, 0, is) = dvb%vaecrb(ifc, 0, is) + &
&                     geo%fcqalf(ifc, 0)*tempb7
                    dvb%vaecrb(ifc, 1, is) = dvb%vaecrb(ifc, 1, is) + &
&                     geo%fcqalf(ifc, 1)*tempb7
                    plb%ti(icv1) = plb%ti(icv1) + pl%na(icv1, is)*tempb5
                    plb%na(icv1, is) = plb%na(icv1, is) + pl%ti(icv1)*&
&                     tempb5
                  END DO
                  tempb2 = -(mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)*&
&                   totfluxb)
                  dvb%fhi_mdf(ifc, 0) = dvb%fhi_mdf(ifc, 0) + tempb2
                  dvb%fhi_mdf(ifc, 1) = dvb%fhi_mdf(ifc, 1) + tempb2
                END IF
                icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                dvb%ne(icv1) = dvb%ne(icv1) + geo%cvvol(icv2)*t3b
                dvb%ne(icv2) = dvb%ne(icv2) + geo%cvvol(icv2)*t2b
                tempb2 = geo%cvvol(icv2)*tisb
                dvb%ni(icv1, 0) = dvb%ni(icv1, 0) + geo%cvvol(icv2)*&
&                 nivsb + pl%ti(icv1)*tempb2
                plb%ti(icv1) = plb%ti(icv1) + dv%ni(icv1, 0)*tempb2
                plb%ti(icv2) = plb%ti(icv2) + geo%cvvol(icv2)*t1b
                CALL POPINTEGER4(ifc)
                CALL POPINTEGER4(icv1)
              END DO
            END IF
          END DO
        END IF
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) THEN
          DO ibw=nbc,ib,-1
            CALL POPCONTROL1B(branch)
            IF (branch .NE. 0) eniparb(ibw, 1) = eniparb(ibw, 1) + &
&               seniparb
          END DO
          seniparb = 0.D0
        END IF
      END IF
    CASE (25) 
      tiave = 0.0_R8
      niave = 0.0_R8
      DO ibc=1,mpg%bccvp(ib, 2)
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
        tiave = tiave + pl%ti(icv)*dv%ni(icv, 0)*geo%cvvol(icv)
        niave = niave + dv%ni(icv, 0)*geo%cvvol(icv)
      END DO
      CALL PUSHREAL8(tiave, r8/8)
      tiave = tiave/niave
      IF (enipar(ib, 2) .GT. 0.0_R8) THEN
        t3 = enipar(ib, 2)
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHCONTROL1B(1)
      END IF
      IF (enipar(ib, 2) .LE. 0.0_R8) THEN
        t3 = switch%b2stbc_bc_ref_ti
        CALL PUSHCONTROL1B(1)
      ELSE
        CALL PUSHCONTROL1B(0)
      END IF
      t3b = 0.D0
      tiaveb = 0.D0
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        srwb%shi0(icv1, 1) = 0.D0
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp6 = t3/tiave
        tempb7 = vbig*ne00*ev*geo%fcs(ifc)*srwb%shi0(icv1, 0)
        srwb%shi0(icv1, 0) = 0.D0
        eniparb(ib, 1) = eniparb(ib, 1) + (pl%ti(icv2)*temp6-t3+1.0_R8)*&
&         tempb7
        tempb2 = enipar(ib, 1)*tempb7
        plb%ti(icv2) = plb%ti(icv2) + temp6*tempb2
        tempb6 = pl%ti(icv2)*tempb2/tiave
        t3b = t3b + tempb6 - tempb2
        tiaveb = tiaveb - temp6*tempb6
      END DO
      CALL POPCONTROL1B(branch)
      IF (branch .NE. 0) t3b = 0.D0
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) eniparb(ib, 2) = eniparb(ib, 2) + t3b
      CALL POPREAL8(tiave, r8/8)
      niaveb = -(tiave*tiaveb/niave**2)
      tiaveb = tiaveb/niave
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
        tempb2 = geo%cvvol(icv)*tiaveb
        dvb%ni(icv, 0) = dvb%ni(icv, 0) + geo%cvvol(icv)*niaveb + pl%ti(&
&         icv)*tempb2
        plb%ti(icv) = plb%ti(icv) + dv%ni(icv, 0)*tempb2
      END DO
    CASE (26) 
!
      IF (.NOT.once_bceni) THEN
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
! Volume                                     !lk 12.12.12 {
          t0 = 0.0_R8
! Poloidally volume-averaged ion temperature in the cell next to boundary
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                CALL PUSHINTEGER4(icv)
                icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                t0 = t0 + geo%cvvol(icv)
              END DO
              CALL PUSHINTEGER4(ibc - 1)
              CALL PUSHCONTROL1B(1)
            ELSE
              CALL PUSHCONTROL1B(0)
            END IF
          END DO
          DO ibw=ib,nbc
!lk 12.12.12 }
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                IF (mpg%cvonclosedsurface(icv2)) THEN
                  CALL PUSHCONTROL1B(1)
                ELSE
                  CALL PUSHCONTROL1B(0)
                END IF
              END DO
              CALL PUSHINTEGER4(ibc - 1)
              CALL PUSHCONTROL1B(1)
            ELSE
              CALL PUSHCONTROL1B(0)
            END IF
          END DO
          t1b = 0.D0
          DO ibw=nbc,ib,-1
            CALL POPCONTROL1B(branch)
            IF (branch .NE. 0) THEN
              CALL POPINTEGER4(ad_to7)
              DO ibc=ad_to7,1,-1
                CALL POPCONTROL1B(branch)
                IF (branch .NE. 0) THEN
                  icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  srwb%shi0(icv1, 1) = 0.D0
                  icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                  ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                  tempb7 = vbig*ne00*geo%fcs(ifc)*srwb%shi0(icv1, 0)
                  srwb%shi0(icv1, 0) = 0.D0
                  eniparb(ibw, 1) = eniparb(ibw, 1) + ev*tempb7
                  plb%ti(icv2) = plb%ti(icv2) + tempb7
                  t1b = t1b - tempb7
                END IF
              END DO
            END IF
          END DO
          t1b = t1b/t0
          DO ibw=nbc,ib,-1
            CALL POPCONTROL1B(branch)
            IF (branch .NE. 0) THEN
              CALL POPINTEGER4(ad_to6)
              DO ibc=ad_to6,1,-1
                icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                plb%ti(icv) = plb%ti(icv) + geo%cvvol(icv)*t1b
                CALL POPINTEGER4(icv)
              END DO
            END IF
          END DO
        END IF
      END IF
    CASE (27) 
      IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
!srv 16.02.12 }
        IF (.NOT.once_bceni) THEN
          IF (switch%use_astra .NE. 0) THEN
            CALL PUSHCONTROL1B(0)
          ELSE
            senipar = 0.0_R8
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bceni(ibw) .EQ. bceni(ib)) THEN
                senipar = senipar + enipar(ibw, 1)
                CALL PUSHCONTROL1B(1)
              ELSE
                CALL PUSHCONTROL1B(0)
              END IF
            END DO
            CALL PUSHCONTROL1B(1)
          END IF
! Poloidally density-averaged ion temperature in the boundary cell
          tis = 0.0_R8
          nivs = 0.0_R8
! Volume                                      !lk 12.12.12 {
          t0 = 0.0_R8
! Poloidally volume-averaged ion temperature in the cell next to boundary
! IYS 22.03.2017
          totflux = 0.0_R8
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                CALL PUSHINTEGER4(icv1)
                icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                CALL PUSHINTEGER4(ifc)
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                tis = tis + pl%ti(icv1)*dv%ni(icv1, 0)*geo%cvvol(icv2)
                nivs = nivs + dv%ni(icv1, 0)*geo%cvvol(icv2)
                t0 = t0 + geo%cvvol(icv2)
                IF (switch%mdf_fhi .NE. 0) THEN
                  totflux = totflux - mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1&
&                   )*(dv%fhi_mdf(ifc, 0)+dv%fhi_mdf(ifc, 1))
                  DO is=0,ns-1
                    totflux = totflux - pl%ti(icv1)*pl%na(icv1, is)*geo%&
&                     fcs(ifc)*mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)*(dv%&
&                     vaecrb(ifc, 0, is)*geo%fcqalf(ifc, 0)+dv%vaecrb(&
&                     ifc, 1, is)*geo%fcqalf(ifc, 1))
                  END DO
                  CALL PUSHCONTROL1B(1)
                ELSE
                  totflux = totflux - mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1&
&                   )*(dv%fhi(ifc, 0)+dv%fhi(ifc, 1))
                  CALL PUSHCONTROL1B(0)
                END IF
              END DO
              CALL PUSHINTEGER4(ibc - 1)
              CALL PUSHCONTROL1B(1)
            ELSE
              CALL PUSHCONTROL1B(0)
            END IF
          END DO
          CALL PUSHREAL8(tis, r8/8)
          tis = tis/nivs
          IF (enipar(ib, 2) .GT. 0.0_R8) THEN
            t3 = enipar(ib, 2)
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHCONTROL1B(1)
          END IF
          IF (enipar(ib, 2) .LE. 0.0_R8) THEN
            t3 = switch%b2stbc_bc_ref_ti
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHCONTROL1B(1)
          END IF
          IF (totflux .GE. 0.) THEN
            x5 = totflux
            CALL PUSHCONTROL1B(0)
          ELSE
            x5 = -totflux
            CALL PUSHCONTROL1B(1)
          END IF
          IF (x5 .LT. senipar) THEN
            max11 = senipar
            CALL PUSHCONTROL1B(0)
          ELSE
            max11 = x5
            CALL PUSHCONTROL1B(1)
          END IF
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                CALL PUSHINTEGER4(icv1)
                CALL PUSHINTEGER4(ifc)
              END DO
              CALL PUSHINTEGER4(ibc - 1)
              CALL PUSHCONTROL1B(1)
            ELSE
              CALL PUSHCONTROL1B(0)
            END IF
          END DO
          tisb = 0.D0
          t1b = 0.D0
          DO ibw=nbc,ib,-1
            CALL POPCONTROL1B(branch)
            IF (branch .NE. 0) THEN
              CALL POPINTEGER4(ad_to9)
              DO ibc=ad_to9,1,-1
                icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                srwb%shi0(icv1, 1) = 0.D0
                icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                tempb7 = vbig*ne00*geo%fcs(ifc)*srwb%shi0(icv1, 0)
                srwb%shi0(icv1, 0) = 0.D0
                tisb = tisb + tempb7
                plb%ti(icv2) = plb%ti(icv2) + tempb7
                t1b = t1b - tempb7
                CALL POPINTEGER4(ifc)
                CALL POPINTEGER4(icv1)
              END DO
            END IF
          END DO
          temp7 = t3/max11
          tempb2 = tis*tisb
          tisb = (1.0_R8-(totflux-senipar)*temp7)*tisb
          totfluxb = -(temp7*tempb2)
          seniparb = seniparb + temp7*tempb2
          tempb7 = -((totflux-senipar)*tempb2/max11)
          t3b = tempb7
          max11b = -(temp7*tempb7)
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            seniparb = seniparb + max11b
            x5b = 0.D0
          ELSE
            x5b = max11b
          END IF
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            totfluxb = totfluxb + x5b
          ELSE
            totfluxb = totfluxb - x5b
          END IF
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) t3b = 0.D0
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) eniparb(ib, 2) = eniparb(ib, 2) + t3b
          t1b = t1b/t0
          CALL POPREAL8(tis, r8/8)
          nivsb = -(tis*tisb/nivs**2)
          tisb = tisb/nivs
          DO ibw=nbc,ib,-1
            CALL POPCONTROL1B(branch)
            IF (branch .NE. 0) THEN
              CALL POPINTEGER4(ad_to8)
              DO ibc=ad_to8,1,-1
                CALL POPCONTROL1B(branch)
                IF (branch .EQ. 0) THEN
                  icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                  tempb2 = -(mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)*&
&                   totfluxb)
                  dvb%fhi(ifc, 0) = dvb%fhi(ifc, 0) + tempb2
                  dvb%fhi(ifc, 1) = dvb%fhi(ifc, 1) + tempb2
                ELSE
                  DO is=ns-1,0,-1
                    tempb2 = -(geo%fcs(ifc)*mpg%bcfcor(mpg%bccvp(ibw, 1)&
&                     +ibc-1)*totfluxb)
                    tempb5 = (geo%fcqalf(ifc, 0)*dv%vaecrb(ifc, 0, is)+&
&                     geo%fcqalf(ifc, 1)*dv%vaecrb(ifc, 1, is))*tempb2
                    tempb7 = pl%ti(icv1)*pl%na(icv1, is)*tempb2
                    dvb%vaecrb(ifc, 0, is) = dvb%vaecrb(ifc, 0, is) + &
&                     geo%fcqalf(ifc, 0)*tempb7
                    dvb%vaecrb(ifc, 1, is) = dvb%vaecrb(ifc, 1, is) + &
&                     geo%fcqalf(ifc, 1)*tempb7
                    plb%ti(icv1) = plb%ti(icv1) + pl%na(icv1, is)*tempb5
                    plb%na(icv1, is) = plb%na(icv1, is) + pl%ti(icv1)*&
&                     tempb5
                  END DO
                  tempb2 = -(mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)*&
&                   totfluxb)
                  dvb%fhi_mdf(ifc, 0) = dvb%fhi_mdf(ifc, 0) + tempb2
                  dvb%fhi_mdf(ifc, 1) = dvb%fhi_mdf(ifc, 1) + tempb2
                END IF
                icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                plb%ti(icv2) = plb%ti(icv2) + geo%cvvol(icv2)*t1b
                tempb2 = geo%cvvol(icv2)*tisb
                dvb%ni(icv1, 0) = dvb%ni(icv1, 0) + geo%cvvol(icv2)*&
&                 nivsb + pl%ti(icv1)*tempb2
                plb%ti(icv1) = plb%ti(icv1) + dv%ni(icv1, 0)*tempb2
                CALL POPINTEGER4(ifc)
                CALL POPINTEGER4(icv1)
              END DO
            END IF
          END DO
          CALL POPCONTROL1B(branch)
          IF (branch .NE. 0) THEN
            DO ibw=nbc,ib,-1
              CALL POPCONTROL1B(branch)
              IF (branch .NE. 0) eniparb(ibw, 1) = eniparb(ibw, 1) + &
&                 seniparb
            END DO
            seniparb = 0.D0
          END IF
        END IF
      END IF
    CASE (28) 
!
! -- BCENI=28 -- Prescribe the value of the ion temperature, with poloidal
!                perturbation taken from flux tube just inside domain
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        IF (switch%use_astra .NE. 0) THEN
          CALL PUSHCONTROL2B(0)
        ELSE
          CALL PUSHCONTROL2B(1)
        END IF
      ELSE
        CALL PUSHCONTROL2B(2)
      END IF
!     ..compute average temperature on core boundary
      t0 = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        CALL PUSHINTEGER4(icv1)
        icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
        IF (mpg%cvonclosedsurface(icv1)) THEN
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            t0 = t0 + geo%cvvol(icv2)
          END DO
          CALL PUSHINTEGER4(ibc0 - 1)
          CALL PUSHCONTROL1B(1)
        ELSE
          CALL PUSHCONTROL1B(0)
        END IF
      END DO
!     ..impose temperature with perturbation
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        CALL PUSHINTEGER4(icv1)
! number of the domain cell
! number of the guard cell face
      END DO
      t1b = 0.D0
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        srwb%shi0(icv1, 1) = 0.D0
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        tempb2 = vbig*ne00*geo%fcs(ifc)*srwb%shi0(icv1, 0)
        srwb%shi0(icv1, 0) = 0.D0
        plb%ti(icv2) = plb%ti(icv2) + tempb2
        eniparb(ib, 1) = eniparb(ib, 1) + ev*tempb2
        t1b = t1b - tempb2
        CALL POPINTEGER4(icv1)
      END DO
      t1b = t1b/t0
      DO ib0=nbc,1,-1
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) THEN
          CALL POPINTEGER4(ad_to10)
          DO ibc0=ad_to10,1,-1
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
            plb%ti(icv2) = plb%ti(icv2) + geo%cvvol(icv2)*t1b
          END DO
        END IF
        CALL POPINTEGER4(icv1)
      END DO
      CALL POPCONTROL2B(branch)
      IF (branch .EQ. 0) eniparb(ib, 1) = 0.D0
    CASE (29) 
!     ..compute average temperature on core boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
      totflux = 0.0_R8
      totpar = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        CALL PUSHINTEGER4(icv1)
        icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
        IF (mpg%cvonclosedsurface(icv1)) THEN
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            t0 = t0 + geo%cvvol(icv2)
            t1 = t1 + geo%cvvol(icv2)*pl%ti(icv1)
            totflux = totflux - (dv%fhi(ifc, 0)+dv%fhi(ifc, 1))*mpg%&
&             bcfcor(mpg%bccvp(ib0, 1)+ibc0-1)
          END DO
          CALL PUSHINTEGER4(ibc0 - 1)
          totpar = totpar + enipar(ib0, 1)
          CALL PUSHCONTROL1B(1)
        ELSE
          CALL PUSHCONTROL1B(0)
        END IF
      END DO
      totpar = fac_he_anom_bc*totpar
      t1 = t1/t0
      IF (enipar(ib, 2) .GT. 0.0_R8) THEN
        t3 = enipar(ib, 2)
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHCONTROL1B(1)
      END IF
      IF (enipar(ib, 2) .LE. 0.0_R8) THEN
        t3 = switch%b2stbc_bc_ref_ti
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHCONTROL1B(1)
      END IF
      IF (totflux .GE. 0.) THEN
        x6 = totflux
        CALL PUSHCONTROL1B(0)
      ELSE
        x6 = -totflux
        CALL PUSHCONTROL1B(1)
      END IF
      IF (totpar .GE. 0.) THEN
        y3 = totpar
        CALL PUSHCONTROL1B(0)
      ELSE
        y3 = -totpar
        CALL PUSHCONTROL1B(1)
      END IF
      IF (x6 .LT. y3) THEN
        max12 = y3
        CALL PUSHCONTROL1B(0)
      ELSE
        max12 = x6
        CALL PUSHCONTROL1B(1)
      END IF
!     ..impose temperature with perturbation
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        CALL PUSHINTEGER4(icv1)
! number of the domain cell
! number of the guard cell face
      END DO
      t2b = 0.D0
      t4b = 0.D0
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        srwb%shi0(icv1, 1) = 0.D0
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        tempb2 = vbig*ne00*geo%fcs(ifc)*srwb%shi0(icv1, 0)
        srwb%shi0(icv1, 0) = 0.D0
        plb%ti(icv2) = plb%ti(icv2) + tempb2
        t4b = t4b + tempb2
        t2b = t2b - tempb2
        CALL POPINTEGER4(icv1)
      END DO
      temp7 = t3/max12
      tempb2 = t1*t4b
      t1b = (1.0_R8-(totflux-totpar)*temp7)*t4b
      totfluxb = -(temp7*tempb2)
      totparb = temp7*tempb2
      tempb7 = -((totflux-totpar)*tempb2/max12)
      t3b = tempb7
      max12b = -(temp7*tempb7)
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        y3b = max12b
        x6b = 0.D0
      ELSE
        x6b = max12b
        y3b = 0.D0
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        totparb = totparb + y3b
      ELSE
        totparb = totparb - y3b
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        totfluxb = totfluxb + x6b
      ELSE
        totfluxb = totfluxb - x6b
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) t3b = 0.D0
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) eniparb(ib, 2) = eniparb(ib, 2) + t3b
      t2b = t2b/t0
      t1b = t1b/t0
      totparb = fac_he_anom_bc*totparb
      DO ib0=nbc,1,-1
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) THEN
          eniparb(ib0, 1) = eniparb(ib0, 1) + totparb
          CALL POPINTEGER4(ad_to11)
          DO ibc0=ad_to11,1,-1
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            tempb2 = -(mpg%bcfcor(mpg%bccvp(ib0, 1)+ibc0-1)*totfluxb)
            dvb%fhi(ifc, 0) = dvb%fhi(ifc, 0) + tempb2
            dvb%fhi(ifc, 1) = dvb%fhi(ifc, 1) + tempb2
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
            plb%ti(icv2) = plb%ti(icv2) + geo%cvvol(icv2)*t2b
            plb%ti(icv1) = plb%ti(icv1) + geo%cvvol(icv2)*t1b
          END DO
        END IF
        CALL POPINTEGER4(icv1)
      END DO
    END SELECT
  END SUBROUTINE B2STBC_PHYS_ENI_B

!
  SUBROUTINE B2STBC_PHYS_ENI(ib)
    IMPLICIT NONE
    INTEGER :: ib, ibw, ibc, ib0, ibc0, is
    INTEGER :: icv, icv1, icv2, ifc, ivx1, ivx2
    REAL(kind=r8) :: t0, t1, t2, t3, t4, dsh, vt, vbnd, niave, tiave, &
&   totpar, totflux, weight, cs, csb, wrk
    REAL(kind=r8), EXTERNAL :: INTVERTEX_S_NODIFF
    LOGICAL :: decay_length_ok
    EXTERNAL XERRAB
    INTRINSIC MIN
    INTRINSIC NINT
    INTRINSIC SQRT
    INTRINSIC ABS
    INTRINSIC SIGN
    REAL(kind=r8) :: x1
    REAL(kind=r8) :: y1
    REAL(kind=r8) :: x2
    REAL(kind=r8) :: y2
    REAL(kind=r8) :: x3
    REAL(kind=r8) :: x4
    REAL(kind=r8) :: x5
    REAL(kind=r8) :: x6
    REAL(kind=r8) :: y3
    REAL(r8) :: max1
    REAL(r8) :: min1
    REAL(r8) :: max2
    REAL(r8) :: min2
    REAL(r8) :: max3
    REAL(r8) :: max4
    REAL(r8) :: min3
    REAL(kind=r8) :: abs0
    REAL(r8) :: max5
    REAL(r8) :: min4
    REAL(kind=r8) :: max6
    REAL(kind=r8) :: abs1
    REAL(kind=r8) :: abs2
    REAL(kind=r8) :: abs3
    REAL(kind=r8) :: abs4
    REAL(r8) :: max7
    REAL(r8) :: min5
    REAL(kind=r8) :: max8
    REAL(kind=r8) :: max9
    REAL(kind=r8) :: max10
    REAL(kind=r8) :: max11
    REAL(kind=r8) :: max12
    REAL(kind=r8) :: abs5
    REAL(kind=r8) :: result10
    REAL(kind=r8) :: result20
!
! -- BOUNDARY CONDITIONS FOR ION ENERGY EQUATIONS --
!
    SELECT CASE  (bceni(ib)) 
    CASE (0) 

    CASE (1) 
!
!
! -- BCENI=1 -- PRESCRIBE THE VALUE OF THE ION TEMPERATURE
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        IF (bcchar(ib) .EQ. 'S' .AND. switch%use_astra .NE. 0) THEN
!srv 14.06.12
          enipar(ib, 1) = tib_astra*1.0e3_R8
        END IF
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENI =  1 : specified ion temperature ', enipar(ib, 1), ' on '&
&       , bcchar(ib), boundary_location(ib)
        CALL XERTST(enipar(ib, 1) .GT. 0.0_R8, &
&             'BCENI = 1, ENIPAR(,1) !> 0')
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%shi0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*enipar(ib, 1)*ev
        srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (2) 
!
! -- BCENI=2 -- PRESCRIBE THE GRADIENT OF THE ION TEMPERATURE
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                               'BCENI =  2 : ion temperature gradient '&
&                                   , enipar(ib, 1), ' on ', bcchar(ib)&
&                                   , boundary_location(ib)
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        ivx1 = mpg%fcvx(ifc, 1)
        ivx2 = mpg%fcvx(ifc, 2)
        t1 = INTVERTEX_S_NODIFF(ivx1, ncv, nvx, mpg, geo%vxvol, pl%ti)
        t2 = INTVERTEX_S_NODIFF(ivx2, ncv, nvx, mpg, geo%vxvol, pl%ti)
        srw%shi0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*(ev*enipar(ib, 1)*(&
&         geo%fchc(ifc, 1)+geo%fchc(ifc, 2))*geo%fcqgam(ifc, 0)-cor9*(t2&
&         -t1)*geo%fcqgam(ifc, 1)*(geo%fchc(ifc, 1)+geo%fchc(ifc, 2))/&
&         geo%fcht(ifc)*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)+pl%ti(icv2))
        srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (3) 
!
! -- BCENI=3 -- SHEATH CONDITIONS, ION ENERGY TRANSMISSION COEFFICIENT
!
      CALL XERRAB('b2stbc_phys -- BCENI = 3 not adapted for WG.'//&
&           ' Replace with drift-compatible BCENI = 15')
!
! -- BCENI=4 -- PRESCRIBE THE VALUE OF THE ION TEMPERATURE, WEAKLY
!                 A MIXED BOUNDARY CONDITION
!
    CASE (4) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENI =  4 : weak ion temperature ', enipar(ib, 1), ' on ', &
&       bcchar(ib), boundary_location(ib)
        CALL XERTST(enipar(ib, 1) .GT. 0.0_R8, &
&             'BCENI = 4, ENIPAR(,1) !> 0')
!srv 02.02.11
        CALL XERTST(enipar(ib, 2) .GT. 0.0_R8, &
&             'BCENI = 4, ENIPAR(,2) !> 0')
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%shi0(icv1, 0) = enipar(ib, 2)*geo%fcs(ifc)*enipar(ib, 1)
        srw%shi0(icv1, 1) = -(enipar(ib, 2)/ev*geo%fcs(ifc))
      END DO
    CASE (5) 
!
! -- BCENI=5 -- PRESCRIBE THE ION ENERGY FLUX PER UNIT AREA
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                               'BCENI =  5 : ion energy flux per area '&
&                                   , enipar(ib, 1), ' on ', bcchar(ib)&
&                                   , boundary_location(ib)
      DO ibc=1,mpg%bccvp(ib, 2)
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        srw%shi0(icv, 0) = enipar(ib, 1)*geo%fcs(ifc)
        srw%shi0(icv, 1) = 0.0_R8
      END DO
    CASE (6) 
!
! -- BCENI=6 -- PRESCRIBE THE TOTAL ION ENERGY FLUX FOR A
!                 CONSTANT ION TEMPERATURE
!
      CALL XERRAB('b2stbc_phys -- BCENI = 6 not adapted for WG')
!
! -- BCENI=7 -- PRESCRIBE THE ION TEMPERATURE PROFILE
!
    CASE (7) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
!srv 26.02.18 {
        WRITE(*, '(3a)') 'BCENI = 7 : specified ion temperature on ', &
&       bcchar(ib), boundary_location(ib)
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%shi0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*bv_ti(icv1)*ev
        srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (8) 
!
! -- BCENI=8 -- PRESCRIBE THE TOTAL ION HEAT FLUX WITH CONSTANT
!                 FLUX DENSITY
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
!srv 28.07.11
        IF (switch%use_astra .NE. 0) enipar(ib, 1) = fhib_astra
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENI =  8 : total ion energy flux', enipar(ib, 1), ' on ', &
&       bcchar(ib), boundary_location(ib)
      END IF
      us = 0.0_R8
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        us = us + geo%fcs(ifc)
      END DO
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%shi0(icv1, 0) = fac_he_anom_bc*enipar(ib, 1)/us*geo%fcs(ifc)
        srw%shi0(icv1, 1) = 0.0_R8
        IF (switch%mdf_fhi .NE. 0) THEN
!wdk Correction now involves vedia instead of ExB velocity
!wdk This makes implementation equivalent to mdf_fhi = 0 option
          srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + mpg%bcfcor(mpg%bccvp(&
&           ib, 1)+ibc-1)*(dv%fhipsch(ifc, 0)+dv%fhipsch(ifc, 1))
          t0 = 0.0_R8
          DO is=0,ns-1
            t0 = t0 + mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*2.5_R8*(geo%fcs&
&             (ifc)*geo%fcqalf(ifc, 0)*dv%vadia(ifc, 0, is)+geo%fcs(ifc)&
&             *geo%fcqalf(ifc, 1)*dv%vadia(ifc, 1, is))*0.5_R8*(pl%na(&
&             icv1, is)+pl%na(icv2, is))*0.5_R8*(pl%ti(icv1)+pl%ti(icv2)&
&             )
          END DO
          IF (0.0_R8 .LT. t0) THEN
            max1 = t0
          ELSE
            max1 = 0.0_R8
          END IF
          srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + max1
          IF (0.0_R8 .GT. t0) THEN
            min1 = t0
          ELSE
            min1 = 0.0_R8
          END IF
          srw%shi0(icv1, 1) = srw%shi0(icv1, 1) + min1/pl%ti(icv1)
        END IF
      END DO
    CASE (9) 
!
! -- BCENI=9 -- PRESCRIBE THE DECAY LENGTH FOR THE ION TEMPERATURE
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENI =  9 : ion temperature decay length ', enipar(ib, 1), &
&       ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enipar(ib, 1) .NE. 0.0_R8, &
&             'BCENI = 9, ENIPAR(,1) = 0')
        decay_length_ok = .true.
        DO is=0,ns-1
          decay_length_ok = decay_length_ok .AND. ((bccon(is, ib) .EQ. 9&
&           .OR. bccon(is, ib) .EQ. 0) .OR. (is_neutral(is) .AND. switch&
&           %use_eirene .EQ. 1))
          IF (bccon(is, ib) .EQ. 1) WRITE(0, *) &
&                      'Should use BCENI=19 in conjunction with BCCON=1'
        END DO
        IF (.NOT.decay_length_ok) THEN
          WRITE(0, *) 'Should use BCENI.EQ.9 together with BCCON=9'
          WRITE(*, *) 'Should use BCENI.EQ.9 together with BCCON=9'
!srv 21.09.12
          WRITE(*, '(1x,a)') &
&         'Please ensure that this boundary condition '//&
&         'is consistent with '//'the density boundary condition'
        END IF
      END IF
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        sy = geo%fcs(ifc)
        srw%shi0(icv1, 0) = 0.0_R8
        IF (switch%recycle_afn .EQ. 0 .OR. switch%tn_style .NE. 0) THEN
!! Note that
!! if tn_style=0: hci0 includes contributions from all ions and all fluid neutrals
!! if tn_style=1: hci0 includes contributions from ions only
!! if tn_style=2: hci0 includes contributions from all ions and non-hydrogenic neutrals
          srw%shi0(icv1, 1) = -(co%hci0(icv1)/enipar(ib, 1)*sy)
        ELSE
!! tn_style=0.and.recycle_afn=1 => take out hydrogenic atoms
          srw%shi0(icv1, 1) = -((co%hci0(icv1)-co%hcn0(icv1))/enipar(ib&
&           , 1)*sy)
        END IF
        DO is=0,ns-1
          IF (((.NOT.is_neutral(is)) .OR. switch%tn_style .EQ. 0) .OR. (&
&             switch%tn_style .EQ. 2 .AND. NINT(zn(is)) .NE. 1)) THEN
            srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + fac_he_anom*pl%ti(&
&             icv1)*srw%sna0(icv1, 0, is)
            srw%shi0(icv1, 1) = srw%shi0(icv1, 1) + fac_he_anom*pl%na(&
&             icv1, is)*srw%sna0(icv1, 1, is)
          END IF
!! end species loop

        END DO
        IF (switch%mdf_fhi .NE. 0) THEN
          srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + mpg%bcfcor(mpg%bccvp(&
&           ib, 1)+ibc-1)*(dv%fhipsch(ifc, 0)+dv%fhipsch(ifc, 1))
          DO is=0,ns-1
            t0 = -(mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*1.5_R8*(geo%fcs(&
&             ifc)*geo%fcqalf(ifc, 0)*dv%vaecrb(ifc, 0, is)+geo%fcs(ifc)&
&             *geo%fcqalf(ifc, 1)*dv%vaecrb(ifc, 1, is))*0.5_R8*(pl%na(&
&             icv1, is)+pl%na(icv2, is))*0.5_R8*(pl%ti(icv1)+pl%ti(icv2)&
&             ))
            IF (0.0_R8 .LT. t0) THEN
              max2 = t0
            ELSE
              max2 = 0.0_R8
            END IF
            srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + max2
            IF (0.0_R8 .GT. t0) THEN
              min2 = t0
            ELSE
              min2 = 0.0_R8
            END IF
            srw%shi0(icv1, 1) = srw%shi0(icv1, 1) + min2/pl%ti(icv1)
          END DO
        END IF
!! end boundary cell loop

      END DO
    CASE (10) 
!
! -- BCENI=10 -- Feedback option for core
!
      CALL XERRAB('b2stbc_phys -- BCENI = 10 not adapted for WG')
!
! -- BCENI=11 -- SHEATH CONDITIONS, ION ENERGY TRANSMISSION COEFFICIENT
!
    CASE (11) 
      CALL XERRAB('b2stbc_phys -- BCENI = 11 not adapted for WG')
!
! -- BCENI=12 -- SHEATH CONDITIONS, ION ENERGY TRANSMISSION COEFFICIENT
!
    CASE (12) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,a,a)') 'BCENI = 12 : sheath ion bc on ', bcchar(ib)&
&       , boundary_location(ib)
        WRITE(*, '(a)') &
&       'Obsolete. Use drift-compatible BCENI = 15 instead'
      END IF
      DO ibc=1,mpg%bccvp(ib, 2)
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        DO is=0,ns-1
          IF (0.0_R8 .LT. mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%fna(ifc&
&             , 0, is)+dv%fna(ifc, 1, is))) THEN
            max3 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%fna(ifc, 0, is&
&             )+dv%fna(ifc, 1, is))
          ELSE
            max3 = 0.0_R8
          END IF
          srw%shi0(icv, 3) = srw%shi0(icv, 3) - enipar(ib, 1)*max3/dv%ni&
&           (icv, 0)
        END DO
      END DO
    CASE (13) 
!
! -- BCENI=13 -- PRESCRIBE THE ION ENERGY FLUX PER UNIT AREA
!             -- PROPORTIONAL TO TEMPERATURE
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                               'BCENI = 13 : ion energy flux per area '&
&                                   //'proportional to temperature ', &
&                                   enipar(ib, 1), ' on ', bcchar(ib), &
&                                   boundary_location(ib)
      DO ibc=1,mpg%bccvp(ib, 2)
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        srw%shi0(icv, 0) = enipar(ib, 1)*pl%ti(icv)*geo%fcs(ifc)
        srw%shi0(icv, 1) = 0.0_R8
      END DO
    CASE (14) 
!
! -- BCENI=14 -- leakage option for ion energy
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                   'BCENI = 14 : ion energy leakage ', &
&                                   enipar(ib, 1), ' on ', bcchar(ib), &
&                                   boundary_location(ib)
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        cs = SQRT(pz(icv1)/rz(icv1))
        srw%shi0(icv1, 0) = 0.0_R8
        srw%shi0(icv1, 3) = geo%fcs(ifc)*cs*fac_he_anom_bc*enipar(ib, 1)
        IF (switch%mdf_fhi .NE. 0) THEN
          srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + mpg%bcfcor(mpg%bccvp(&
&           ib, 1)+ibc-1)*(dv%fhipsch(ifc, 0)+dv%fhipsch(ifc, 1))
          t0 = 0.0_R8
          DO is=0,ns-1
            t0 = t0 + mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*2.5_R8*(geo%fcs&
&             (ifc)*geo%fcqalf(ifc, 0)*dv%vadia(ifc, 0, is)+geo%fcs(ifc)&
&             *geo%fcqalf(ifc, 1)*dv%vadia(ifc, 1, is))*0.5_R8*(pl%na(&
&             icv1, is)+pl%na(icv2, is))*0.5_R8*(pl%ti(icv1)+pl%ti(icv2)&
&             )
          END DO
          IF (0.0_R8 .LT. t0) THEN
            max4 = t0
          ELSE
            max4 = 0.0_R8
          END IF
          srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + max4
          IF (0.0_R8 .GT. t0) THEN
            min3 = t0
          ELSE
            min3 = 0.0_R8
          END IF
          srw%shi0(icv1, 1) = srw%shi0(icv1, 1) + min3/pl%ti(icv1)
        END IF
      END DO
    CASE (15) 
!
! -- BCENI=15 -- DRIFT-COMPATIBLE SHEATH CONDITION                   !srv 01.02.09 {
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
!srv 20.09.17
        WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a)') &
&       'BCENI = 15 : drift-compatible sheath condition '//&
&       'for ion temperature with ENIPAR(IB,1) =', enipar(ib, 1), ' on '&
&       , bcchar(ib), boundary_location(ib)
        WRITE(*, *) 'BCENI=15 - should have BCCON=14 for all ions'
!srv 20.09.17
        CALL XERTST(enipar(ib, 1) .GT. 0.0_R8, &
&             'BCENI = 15, ENIPAR(IB,1) <= 0 not allowed!')
        IF (bceni_15_style .NE. 0) WRITE(*, *) 'bceni_15_style <> 0'
        bccon14_is(ib) = .true.
        DO is=0,ns-1
          IF (.NOT.is_neutral(is)) bccon14_is(ib) = bccon14_is(ib) .AND.&
&             bccon(is, ib) .EQ. 14
        END DO
        IF (bccon14_is(ib)) WRITE(*, '(a,a,i3,a)') 'BCCON=14 HAS ', &
&                           'BEEN IMPOSED AT BOUNDARY ', ib, &
&                           ' FOR ALL IONS'
        IF (.NOT.bccon14_is(ib)) THEN
          WRITE(*, '(a,a,i3,a)') 'BCCON=14 ', &
&         'HAS NOT BEEN IMPOSED AT BOUNDARY ', ib, ' FOR ALL IONS'
          IF (bceni_15_style .EQ. 0) CALL XERRAB(&
&                              'When BCENI=15 and bceni_15_style.eq.0, '&
&                                          //&
&                          'one must have BCCON=14 for all ion species!'&
&                                         )
        END IF
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
!srv 15.02.26 {
        DO is=0,ns-1
          CALL CSBC_IS(icv1, ib, is, cs)
          CALL VBC_IS(ib, is, ibc, icv1, icv2, ifc, csbc(icv1, is), wrk)
!srv 15.02.26 }
        END DO
        cs = SQRT(pz(icv1)/rz(icv1))
        t0 = 0.0_R8
        t1 = 0.0_R8
        t2 = 0.0_R8
        wrk = geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3)
        IF (bceni_15_style .EQ. 0) THEN
          IF (wrk .GE. 0.) THEN
            abs0 = wrk
          ELSE
            abs0 = -wrk
          END IF
          IF (abs0 .LT. geo%qalfmin) THEN
            srw%shi0(icv1, 0) = 0.0_R8
            srw%shi0(icv1, 1) = -(1.5_R8*geo%fcs(ifc)*geo%qalfmax*cs*dv%&
&             ni(icv1, 1))
            IF (switch%mdf_fhi .NE. 0) THEN
              srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + mpg%bcfcor(mpg%&
&               bccvp(ib, 1)+ibc-1)*(dv%fhipsch(ifc, 0)+dv%fhipsch(ifc, &
&               1))
              t0 = 0.0_R8
              DO is=0,ns-1
                t0 = t0 + mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*1.5_R8*(geo&
&                 %fcs(ifc)*geo%fcqalf(ifc, 0)*dv%vaecrb(ifc, 0, is)+geo&
&                 %fcs(ifc)*geo%fcqalf(ifc, 1)*dv%vaecrb(ifc, 1, is))*&
&                 0.5_R8*(pl%na(icv1, is)+pl%na(icv2, is))*0.5_R8*(pl%ti&
&                 (icv1)+pl%ti(icv2))
              END DO
              IF (0.0_R8 .LT. t0) THEN
                max5 = t0
              ELSE
                max5 = 0.0_R8
              END IF
              srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + max5
              IF (0.0_R8 .GT. t0) THEN
                min4 = t0
              ELSE
                min4 = 0.0_R8
              END IF
              srw%shi0(icv1, 1) = srw%shi0(icv1, 1) + min4/pl%ti(icv1)
            END IF
          ELSE
            DO is=0,ns-1
              IF (.NOT.is_neutral(is)) THEN
                vbnd = (dv%vaecrb(ifc, 0, is)*geo%fcqalf(ifc, 0)+dv%&
&                 vaecrb(ifc, 1, is)*geo%fcqalf(ifc, 1))*mpg%bcfcor(mpg%&
&                 bccvp(ib, 1)+ibc-1)
                IF (wrk .GE. 0.) THEN
                  abs5 = wrk
                ELSE
                  abs5 = -wrk
                END IF
                x1 = csbc(icv1, is)*abs5
                y1 = vbc(icv1, is)*SIGN(1.0_R8, wrk) + vbnd
                IF (x1 .LT. y1) THEN
                  max6 = y1
                ELSE
                  max6 = x1
                END IF
                t0 = t0 + mompar(is, ib, 1)*pl%na(icv1, is)*geo%fcs(ifc)&
&                 *max6
                IF (conpar(is, ib, 2) .GT. 0.0_R8) t1 = t1 + co%dna0(&
&                   icv1, is)/conpar(is, ib, 2)*pl%na(icv1, is)
              END IF
            END DO
            srw%shi0(icv1, 1) = srw%shi0(icv1, 1) - enipar(ib, 1)*t0 - &
&             switch%stab_coeff_sheath_ti*dv%ne(icv1)*cs*geo%fcs(ifc) - &
&             fac_he_anom_bc*enipar(ib, 2)*t1*geo%fcs(ifc)
            srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + switch%&
&             stab_coeff_sheath_ti*dv%ne(icv1)*cs*geo%fcs(ifc)*pl%ti(&
&             icv1)
          END IF
        ELSE
!wdk sheath transmission factor consistent with truncated
!    Maxwellian distribution on Eirene side (NEMODS=7)
!    See Eirene manual for details.
          DO is=0,ns-1
            IF (.NOT.is_neutral(is)) THEN
              vt = SQRT(2.0_R8*pl%ti(icv1)/(am(is)*mp))
              IF (geo%fcqalf(ifc, 0) .GE. 0.) THEN
                abs1 = geo%fcqalf(ifc, 0)
              ELSE
                abs1 = -geo%fcqalf(ifc, 0)
              END IF
              result10 = PIT(icv1)
              t3 = result10*abs1*cs/vt
              IF (geo%fcqalf(ifc, 1) .GE. 0.) THEN
                abs2 = geo%fcqalf(ifc, 1)
              ELSE
                abs2 = -geo%fcqalf(ifc, 1)
              END IF
!WG_TODO correct for drift contributions!
              result10 = PIT(icv1)
              t4 = SQRT((result10*abs2*cs/vt)**2 + (geo%cvbb(icv1, 2)/&
&               geo%cvbb(icv1, 3)*cs/vt)**2)
!corrected for factor 3/2 in parallel convection
              result10 = SHEATH_G(t3)
              result20 = SHEATH_G(t3)
              dsh = 1.0_R8 + t3**2 + t4**2 + 0.5_R8*(result10-1.0_R8)/&
&               result20
              t0 = t0 + dsh*mompar(is, ib, 1)*pl%na(icv1, is)
              IF (conpar(is, ib, 2) .GT. 0.0_R8) t1 = t1 + &
&                 fac_he_anom_bc*enipar(ib, 2)*co%dna0(icv1, is)/conpar(&
&                 is, ib, 2)*pl%na(icv1, is)
              t2 = t2 + dv%fhm(ifc, 0, is) + dv%fhm(ifc, 1, is)
            END IF
          END DO
          IF (geo%fcpbs(ifc) .GE. 0.) THEN
            abs3 = geo%fcpbs(ifc)
          ELSE
            abs3 = -geo%fcpbs(ifc)
          END IF
          srw%shi0(icv1, 1) = srw%shi0(icv1, 1) - (1.0_R8+switch%&
&           stab_coeff_sheath_ti)*t0*cs*abs3 - t1*geo%fcs(ifc) + t2*mpg%&
&           bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          IF (geo%fcpbs(ifc) .GE. 0.) THEN
            abs4 = geo%fcpbs(ifc)
          ELSE
            abs4 = -geo%fcpbs(ifc)
          END IF
          srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + switch%&
&           stab_coeff_sheath_ti*t0*cs*abs4
        END IF
        IF (switch%mdf_fhi .NE. 0) THEN
          srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + mpg%bcfcor(mpg%bccvp(&
&           ib, 1)+ibc-1)*(dv%fhipsch(ifc, 0)+dv%fhipsch(ifc, 1))
          t0 = 0.0_R8
          DO is=0,ns-1
            t0 = t0 + mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*2.5_R8*(geo%fcs&
&             (ifc)*geo%fcqalf(ifc, 0)*dv%vadia(ifc, 0, is)+geo%fcs(ifc)&
&             *geo%fcqalf(ifc, 1)*dv%vadia(ifc, 1, is))*0.5_R8*(pl%na(&
&             icv1, is)+pl%na(icv2, is))*0.5_R8*(pl%ti(icv1)+pl%ti(icv2)&
&             )
          END DO
          IF (0.0_R8 .LT. t0) THEN
            max7 = t0
          ELSE
            max7 = 0.0_R8
          END IF
          srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + max7
          IF (0.0_R8 .GT. t0) THEN
            min5 = t0
          ELSE
            min5 = 0.0_R8
          END IF
          srw%shi0(icv1, 1) = srw%shi0(icv1, 1) + min5/pl%ti(icv1)
        END IF
!wdk    Todo: corrections for BCCON.ne.14
!srv 01.02.09 }

      END DO
    CASE (16) 
!
! -- BCENI=16 -- Feedback boundary condition with constant temperature
!
!
      IF (switch%bceni_16_style .EQ. 0) THEN
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a)') &
&         'ion temperature feedback by flux ', enipar(ib, 1), ' with ', &
&         enipar(ib, 2), ' on ', bcchar(ib), boundary_location(ib)
          CALL XERTST(enipar(ib, 1) .NE. 0, 'faulty parameter enipar1')
        END IF
!       ..compute average temperature on boundary
        t0 = 0.0_R8
        t1 = 0.0_R8
!wdk Note on backwards compatibility: feedback now always on
!wdk flux through the boundary itself (no offset)
        totflux = 0.0_R8
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          t0 = t0 + geo%fcs(ifc)*dv%ni(icv1, 0)
!wdk at the moment, totflux only contains ion/neutral heat flux;
!wdk bc_type16_kinetic_energy.eq.1 option not yet included
          t1 = t1 + geo%fcs(ifc)*dv%ni(icv1, 0)*pl%ti(icv1)
          totflux = totflux - (dv%fhi(ifc, 0)+dv%fhi(ifc, 1))*mpg%bcfcor&
&           (mpg%bccvp(ib, 1)+ibc-1)
        END DO
        t1 = t1/t0
        totpar = fac_he_anom_bc*enipar(ib, 1)
        IF (enipar(ib, 2) .GT. 0.0_R8) t3 = enipar(ib, 2)
        IF (enipar(ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref_ti
        IF (totflux .GE. 0.) THEN
          x2 = totflux
        ELSE
          x2 = -totflux
        END IF
        IF (totpar .GE. 0.) THEN
          y2 = totpar
        ELSE
          y2 = -totpar
        END IF
        IF (x2 .LT. y2) THEN
          max8 = y2
        ELSE
          max8 = x2
        END IF
        t2 = (1.0_R8-t3*(totflux-totpar)/max8)*t1
        IF (switch%b2stbc_diagno .GE. 2) WRITE(*, '(a,1p,4(1x,e15.6))') &
&             'bceni=16: curr_flux, desired_flux, old/new temperature, '&
&                                        , totflux, totpar, t1/qe, t2/qe
!       ..impose temperature
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%shi0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*t2
          srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
        END DO
      ELSE IF (switch%bceni_16_style .EQ. 1) THEN
!
!srv 16.02.12 {
!
        IF (ncall_b2stbc_phys .EQ. 0) THEN
          WRITE(*, *) 'BCENI = 16 (style = 1) : '//&
&         'Given integrated ion heat flux with constant Ti '
!          write all boundaries with this type of boundary condition
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              WRITE(*, '(a,a,a)') ' on ', bcchar(ibw), boundary_location&
&             (ibw)
              icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
              CALL XERTST(mpg%cvonclosedsurface(icv), &
&                   'BCENI = 16 only applicable to core boundaries !')
              CALL XERTST(enipar(ibw, 1) .NE. 0, &
&                   'faulty parameter enipar1')
            END IF
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (&
&               ((bceni(ibw) .EQ. 23 .OR. bceni(ibw) .EQ. 24) .OR. bceni&
&               (ibw) .EQ. 26) .OR. bceni(ibw) .EQ. 27)) THEN
! IYS added BCENI= 26 and 27
              CALL XERRAB(&
&                   'BCENI types 16, 23, 24, 26 and 27 cannot be mixed!'&
&                  )
            END IF
          END DO
        END IF
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
!srv 16.02.12 }
          IF (.NOT.once_bceni) THEN
            IF (switch%use_astra .NE. 0) THEN
              CALL XERRAB(&
&                   'Compile with -DASTRA option to couple to ASTRA!')
            ELSE
              senipar = 0.0_R8
              DO ibw=ib,nbc
                IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') &
&                   .AND. bceni(ibw) .EQ. bceni(ib)) senipar = senipar +&
&                   enipar(ibw, 1)
              END DO
            END IF
            WRITE(*, *) 'BCENI=16: Summed value is ', senipar
            tis = 0.0_R8
            nivs = 0.0_R8
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bceni(ibw) .EQ. bceni(ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  tis = tis + pl%ti(icv)*dv%ni(icv, 0)*geo%cvvol(icv)
                  nivs = nivs + dv%ni(icv, 0)*geo%cvvol(icv)
                END DO
              END IF
            END DO
            tis = tis/nivs
            totflux = 0.0_R8
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bceni(ibw) .EQ. bceni(ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                  IF (switch%mdf_fhi .NE. 0) THEN
                    totflux = totflux - mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc&
&                     -1)*(dv%fhi_mdf(ifc, 0)+dv%fhi_mdf(ifc, 1))
                    DO is=0,ns-1
                      totflux = totflux - pl%ti(icv)*pl%na(icv, is)*geo%&
&                       fcs(ifc)*mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)*(dv&
&                       %vaecrb(ifc, 0, is)*geo%fcqalf(ifc, 0)+dv%vaecrb&
&                       (ifc, 1, is)*geo%fcqalf(ifc, 1))
                    END DO
                  ELSE
                    totflux = totflux - mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc&
&                     -1)*(dv%fhi(ifc, 0)+dv%fhi(ifc, 1))
                  END IF
                END DO
              END IF
            END DO
            IF (enipar(ib, 2) .GT. 0.0_R8) t3 = enipar(ib, 2)
            IF (enipar(ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref_ti
            IF (totflux .GE. 0.) THEN
              x3 = totflux
            ELSE
              x3 = -totflux
            END IF
            IF (x3 .LT. senipar) THEN
              max9 = senipar
            ELSE
              max9 = x3
            END IF
            tis = tis*(1.0_R8-t3*(totflux-senipar)/max9)
            WRITE(*, '(3(a,es14.7))') ' TIS=', tis/ev, ' totflux=', &
&           totflux, ' SENIPAR=', senipar
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bcene(ibw) .EQ. bcene(ib)) THEN
                DO ibc=1,mpg%bccvp(ibw, 2)
                  icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                  ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                  srw%shi0(icv, 0) = vbig*ne00*tis*geo%fcs(ifc)
                  srw%shi0(icv, 1) = -(vbig*ne00*geo%fcs(ifc))
                END DO
              END IF
            END DO
            once_bceni = .true.
          END IF
        ELSE
          CALL XERRAB('B2STBC -- BCENI=16, ONLY AVAILABLE FOR CORE!')
        END IF
      ELSE
        CALL XERRAB(' Incorrect style of boundary condition')
      END IF
    CASE (17) 
!
! -- BCENI=17 -- Feedback boundary condition with constant temperature
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a)') &
&       'BCENI = 17 : ion temperature feedback by flux ', enipar(ib, 1)&
&       , ' with ', enipar(ib, 2), ' on ', bcchar(ib), boundary_location&
&       (ib)
        CALL XERTST(enipar(ib, 1) .NE. 0, 'faulty parameter enipar1')
        CALL XERTST(enipar(ib, 2) .GT. 0, 'faulty parameter enipar2')
        CALL XERTST(bcene(ib) .EQ. bceni(ib), &
&             'both bcene and bceni should be set to 17')
        CALL XERTST(enepar(ib, 1) .NE. 0, 'faulty parameter enepar1')
        CALL XERTST(enepar(ib, 2) .GT. 0, 'faulty parameter enepar2')
      END IF
      IF (.NOT.(bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A')) THEN
! already handled when the electron heat bc was handled
! see label 2980
        CALL XERRAB('B2STBC -- BCENI=17, NOT AVAILABLE FOR N,W,E')
      END IF
    CASE (18) 
!
! -- BCENI=18 -- FRACTIONAL DROP CONDITION (FOR EDGE2D COMPARISON)
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCENI = 18 : ion temperature fractional drop', enipar(ib, 1), &
&       ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enipar(ib, 1) .LT. 1.0_R8, &
&             'BCENI = 18, ENIPAR(,1) => 1')
      END IF
      DO ibc=1,mpg%bccvp(ib, 2)
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        t1 = (1.0_R8-enipar(ib, 1))*pl%ti(icv2)
        srw%shi0(icv1, 0) = vbig*ne00*t1*geo%fcs(ifc)
        srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (19) 
!
! -- BCENI=19 -- PRESCRIBE THE DECAY LENGTH FOR THE ION TEMPERATURE
!
      CALL XERRAB('b2stbc_phys -- BCENI = 19 not adapted for WG')
!
! -- BCENI=20 -- Feedback boundary condition with constant temperature
!
    CASE (20) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a)') &
&       'BCENI = 20 : ion temperature feedback by flux (neo) ', enipar(&
&       ib, 1), ' with ', enipar(ib, 2), ' on ', bcchar(ib), &
&       boundary_location(ib)
        CALL XERTST(enipar(ib, 1) .NE. 0, 'faulty parameter enipar1')
      END IF
      IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
        totflux = 0.0_R8
        t0 = 0.0_R8
        weight = 0.0_R8
        tiave = 0.0_R8
        niave = 0.0_R8
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          totflux = totflux - mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%fhi&
&           (ifc, 0)+dv%fhi(ifc, 1))
          t0 = t0 + pl%ti(icv1)*dv%ni(icv1, 0)*geo%cvvol(icv1)
          weight = weight + dv%ni(icv1, 0)*geo%cvvol(icv1)
          tiave = tiave + pl%ti(icv2)*dv%ni(icv2, 0)*geo%cvvol(icv2)
          niave = niave + dv%ni(icv2, 0)*geo%cvvol(icv2)
        END DO
        t0 = t0/weight
        tiave = tiave/niave
        IF (switch%b2stbc_diagno .GE. 2) WRITE(*, *) 'Totflux :', &
&                                        totflux
        IF (enipar(ib, 2) .GT. 0.0_R8) t3 = enipar(ib, 2)
        IF (enipar(ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref_ti
        t1 = (1.0_R8-t3*(totflux-enipar(ib, 1))/enipar(ib, 1))*t0
        IF (switch%b2stbc_diagno .GE. 2) WRITE(*, *) &
&                                        'Old/New ion temp :', t0/qe, t1&
&                                        /qe
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%shi0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*t1*pl%ti(icv2)/&
&           tiave
          srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
        END DO
      ELSE
        CALL XERRAB('B2STBC -- BCENI=20, NOT AVAILABLE FOR N,W,E')
      END IF
    CASE (21) 
!
!! FIXME: Clash here with 5.0/5.1 BCENI=21 type
!xpb Careful here because of BC number clash
! From 5.0: starting at version 01.001.030
! -- BCCON=21 -- constant ion temperature scaled by ion temperature on the ring bc_type21_ref away
! has been moved up to next available number (BCENI=25)
!
! From 5.2, after version number 01.001.078:
! -- BCENI=21 -- from b2stbc_spb                                     !srv 01.02.09 {
!
      CALL XERRAB('b2stbc_phys -- BCENI = 21 not adapted for WG')
!
! -- BCENI=22 -- RADIAL LEAKAGE CONDITION FOR THE ION TEMPERATURE    !srv 23.07.10 {
!                SPECIFIES A TEMPERATURE GRADIENT SUCH THAT THE DIFFUSIVE
!                FLUX IS SET TO BE EQUIVALENT TO A LEAKAGE VELOCITY, IN
!                UNITS OF THE COLLECTIVE ION THERMAL VELOCITY
!
    CASE (22) 
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                   'BCENI = 22 : with ENIPAR(IB,1)= ', &
&                                   enipar(ib, 1), ' on ', bcchar(ib), &
&                                   boundary_location(ib)
!wdk    Notes:
!wdk     * need correction for misaligned grids -> t1
!wdk     * need to correct this BC for hybrid scheme
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        t0 = geo%fcqalf(ifc, 1)
        t1 = (geo%fchc(ifc, 1)+geo%fchc(ifc, 2))/geo%fcht(ifc)*geo%&
&         fcqbet(ifc, 0)
        t2 = 0.0_R8
        DO is=0,ns-1
          IF (.NOT.is_neutral(is)) THEN
            csb = SQRT((rt%rza(icv1, is)*pl%te(icv1)+pl%ti(icv1))/(am(is&
&             )*mp))
            t2 = t2 + csb*pl%na(icv1, is)
          END IF
        END DO
        srw%shi0(icv1, 0) = vbig*ne00*ev*co%chci(ifc, 1)*(t0*pl%ti(icv2)&
&         -mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*t1*(pl%ti(mpg%fcvx(ifc, 2)&
&         )-pl%ti(mpg%fcvx(ifc, 1))))
        srw%shi0(icv1, 1) = -(vbig*ne00*ev*(co%chci(ifc, 1)*t0-enipar(ib&
&         , 1)*geo%fcs(ifc)*t2))
!srv 23.07.10 }
      END DO
    CASE (23) 
!
! -- BCENI=23 -- PRESCRIBE THE POLOIDALLY AVERAGED VALUE OF THE ION TEMPERATURE
! AND INTRODUCE A POLOIDAL VARIATION AS CLOSE AS POSSIBLE TO NEOCLASSICAL SOLUTION.
! IT IS RECOMMENDED TO USE THIS BOUNDARY CONDITION TOGETHER WITH CORRESPONDING
! CONDITION ON ION DENSITY BCCON = 21,22,23
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7)') &
&       'BCENI = 23 : specified ion temperature ', enipar(ib, 1)
!          write all boundaries with this type of boundary condition
        DO ibw=ib,nbc
          IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&             bceni(ibw) .EQ. bceni(ib)) THEN
            WRITE(*, '(a,a,a)') ' on ', bcchar(ibw), boundary_location(&
&           ibw)
            icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
            CALL XERTST(mpg%cvonclosedsurface(icv), &
&                 'BCENI = 23 only applicable to core boundaries !')
            CALL XERTST(switch%use_astra .NE. 0 .OR. enipar(ib, 1) .EQ. &
&                 enipar(ibw, 1), &
&                 'BCENI = 23, inconsistent ENIPAR(,1) values!')
            IF (.NOT.((bccon(ismain, ib) .EQ. 21 .OR. bccon(ismain, ib) &
&               .EQ. 22) .OR. bccon(ismain, ib) .EQ. 23)) THEN
              WRITE(0, '(a,i3,a,i2,a)') 'Should use BCCON(', ismain, ','&
&             , ib, ').EQ.21,22,23 together with BCENI=23'
              WRITE(*, '(a,i3,a,i2,a)') 'Should use BCCON(', ismain, ','&
&             , ib, ').EQ.21,22,23 together with BCENI=23'
!srv 21.09.12
              WRITE(*, '(1x,a)') &
&             'Please ensure that this boundary condition '//&
&             'is consistent with '//&
&             'the ion density boundary condition'
            END IF
            IF (.NOT.(ns .EQ. 1 .OR. (ns .EQ. 2 .AND. is_neutral(0)))) &
&           THEN
              WRITE(0, *) &
&             'Use of BCENI=23 only meant for single-fluid runs!'
              WRITE(0, *) 'Use BCENI=26 instead!'
              WRITE(6, *) &
&             'Use of BCENI=23 only meant for single-fluid runs!'
              WRITE(6, *) 'Use BCENI=26 instead!'
            END IF
          END IF
          IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (((&
&             bceni(ibw) .EQ. 16 .OR. bceni(ibw) .EQ. 24) .OR. bceni(ibw&
&             ) .EQ. 26) .OR. bceni(ibw) .EQ. 27)) THEN
! IYS added BCENI= 26 and 27
            CALL XERRAB(&
&                 'BCENI types 16, 23, 24, 26 and 27 cannot be mixed!')
          END IF
        END DO
        CALL XERTST(switch%use_astra .NE. 0 .OR. enipar(ibw, 1) .GT. &
&             0.0_R8, 'BCENI = 23, ENIPAR(,1) !> 0')
      END IF
!
      IF (.NOT.once_bceni) THEN
        IF (switch%use_astra .NE. 0) CALL XERRAB(&
&                    'Compile with -DASTRA option to couple with ASTRA!'&
&                                         )
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
! Volume                                     !lk 12.12.12 {
          t0 = 0.0_R8
! Poloidally volume-averaged ion temperature in the cell next to boundary
          t1 = 0.0_R8
! Poloidally volume-averaged electron density in the cell next to boundary
          t2 = 0.0_R8
! Poloidally volume-averaged electron density in the boundary cell
          t3 = 0.0_R8
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                t0 = t0 + geo%cvvol(icv2)
                t1 = t1 + pl%ti(icv2)*geo%cvvol(icv2)
                t2 = t2 + dv%ne(icv2)*geo%cvvol(icv2)
                t3 = t3 + dv%ne(icv1)*geo%cvvol(icv2)
              END DO
            END IF
          END DO
          t1 = t1/t0
          t2 = t2/t0
          t3 = t3/t0
          DO ibw=ib,nbc
!lk 12.12.12 }
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                IF (mpg%cvonclosedsurface(icv2)) THEN
                  srw%shi0(icv1, 0) = srw%shi0(icv1, 0) + vbig*ne00*(&
&                   enipar(ibw, 1)*ev+(pl%ti(icv2)-t1)*t1*t2/t3/enipar(&
&                   ibw, 1)/ev)*geo%fcs(ifc)
                  srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
                END IF
              END DO
            END IF
          END DO
          once_bceni = .true.
        ELSE
          CALL XERRAB(&
&              'B2STBC -- BCENI=23 IS AVAILABLE FOR CORE BOUNDARY ONLY.'&
&              )
        END IF
      END IF
    CASE (24) 
!
! -- BCENI=24 -- Feedback boundary condition with prescribed total ion heat flux,
!                constant poloidally averaged ion temperature and a
!                poloidal variation as close as possible to neoclassical solution.
! IT IS RECOMMENDED TO USE THIS BOUNDARY CONDITION TOGETHER WITH CORRESPONDING
! CONDITION ON ION DENSITY BCCON = 21,22,23
!
!IYS 04.03.2013 {
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a)') 'BCENI = 24 : Given integrated ion heat flux', &
&       ' with constant Ti '
!          write all boundaries with this type of boundary condition
        DO ibw=ib,nbc
          IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&             bceni(ibw) .EQ. bceni(ib)) THEN
            WRITE(*, '(a,a,a)') ' on ', bcchar(ibw), boundary_location(&
&           ibw)
            icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
            CALL XERTST(mpg%cvonclosedsurface(icv), &
&                 'BCENI = 24 only applicable to core boundaries !')
            CALL XERTST(enipar(ibw, 1) .NE. 0, &
&                 'faulty parameter enipar1')
            IF (.NOT.((bccon(ismain, ib) .EQ. 21 .OR. bccon(ismain, ib) &
&               .EQ. 22) .OR. bccon(ismain, ib) .EQ. 23)) THEN
              WRITE(0, '(a,i3,a,i2,a)') 'Should use BCCON(', ismain, ','&
&             , ib, ').EQ.21,22,23 together with BCENI=24'
              WRITE(*, '(a,i3,a,i2,a)') 'Should use BCCON(', ismain, ','&
&             , ib, ').EQ.21,22,23 together with BCENI=24'
!srv 21.09.12
              WRITE(*, '(1x,a)') &
&             'Please ensure that this boundary condition '//&
&             'is consistent with '//&
&             'the ion density boundary condition'
            END IF
            IF (.NOT.(ns .EQ. 1 .OR. (ns .EQ. 2 .AND. is_neutral(0)))) &
&           THEN
              WRITE(0, *) &
&             'Use of BCENI=24 only meant for single-fluid runs!'
              WRITE(0, *) 'Use BCENI=27 instead!'
              WRITE(6, *) &
&             'Use of BCENI=24 only meant for single-fluid runs!'
              WRITE(6, *) 'Use BCENI=27 instead!'
            END IF
          END IF
          IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (((&
&             bceni(ibw) .EQ. 16 .OR. bceni(ibw) .EQ. 23) .OR. bceni(ibw&
&             ) .EQ. 26) .OR. bceni(ibw) .EQ. 27)) THEN
! IYS added BCENI= 26 and 27
            CALL XERRAB(&
&                 'BCENI types 16, 23, 24, 26 and 27 cannot be mixed!')
          END IF
        END DO
      END IF
!srv 16.02.12 }
      IF (.NOT.once_bceni) THEN
        IF (switch%use_astra .NE. 0) THEN
          CALL XERRAB(&
&               'Compile with -DASTRA option to couple with ASTRA!')
        ELSE
          senipar = 0.0_R8
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) senipar = senipar + enipar(&
&               ibw, 1)
          END DO
        END IF
        WRITE(*, *) 'BCENI=24: Summed value is ', senipar
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
! Poloidally density-averaged ion temperature in the boundary cell     !IYS 21.01.2016
          tis = 0.0_R8
          nivs = 0.0_R8
          totflux = 0.0_R8
! Volume                                     !lk 12.12.12 {
          t0 = 0.0_R8
! Poloidally volume-averaged ion temperature in the cell next to boundary
          t1 = 0.0_R8
! Poloidally volume-averaged electron density in the cell next to boundary
          t2 = 0.0_R8
! Poloidally volume-averaged electron density in the boundary cell
          t3 = 0.0_R8
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                t0 = t0 + geo%cvvol(icv2)
                t1 = t1 + pl%ti(icv2)*geo%cvvol(icv2)
                tis = tis + pl%ti(icv1)*dv%ni(icv1, 0)*geo%cvvol(icv2)
                nivs = nivs + dv%ni(icv1, 0)*geo%cvvol(icv2)
                t2 = t2 + dv%ne(icv2)*geo%cvvol(icv2)
                t3 = t3 + dv%ne(icv1)*geo%cvvol(icv2)
                IF (switch%mdf_fhi .NE. 0) THEN
                  totflux = totflux - mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1&
&                   )*(dv%fhi_mdf(ifc, 0)+dv%fhi_mdf(ifc, 1))
                  DO is=0,ns-1
                    totflux = totflux - pl%ti(icv1)*pl%na(icv1, is)*geo%&
&                     fcs(ifc)*mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)*(dv%&
&                     vaecrb(ifc, 0, is)*geo%fcqalf(ifc, 0)+dv%vaecrb(&
&                     ifc, 1, is)*geo%fcqalf(ifc, 1))
                  END DO
                ELSE
                  totflux = totflux - mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1&
&                   )*(dv%fhi(ifc, 0)+dv%fhi(ifc, 1))
                END IF
              END DO
            END IF
          END DO
          tis = tis/nivs
          t1 = t1/t0
          t2 = t2/t0
          t3 = t3/t0
          IF (enipar(ib, 2) .GT. 0.0_R8) t4 = enipar(ib, 2)
          IF (enipar(ib, 2) .LE. 0.0_R8) t4 = switch%b2stbc_bc_ref_ti
          IF (totflux .GE. 0.) THEN
            x4 = totflux
          ELSE
            x4 = -totflux
          END IF
          IF (x4 .LT. senipar) THEN
            max10 = senipar
          ELSE
            max10 = x4
          END IF
          tis = tis*(1.0_R8-t4*(totflux-senipar)/max10)
          WRITE(*, '(3(a,es14.7))') ' TIS=', tis/ev, ' totflux=', &
&         totflux, ' SENIPAR=', senipar
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                srw%shi0(icv1, 0) = vbig*ne00*(tis+(pl%ti(icv2)-t1)*t1*&
&                 t2/t3/tis)*geo%fcs(ifc)
                srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
              END DO
            END IF
          END DO
          once_bceni = .true.
        ELSE
          CALL XERRAB('B2STBC -- BCENI=24 IS AVAILABLE FOR CORE ONLY')
        END IF
      END IF
    CASE (25) 
!
! -- BCENI=25 -- constant ion temperature scaled by inner ring
! was BCENI=21 in 5.0/5.1
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a)') &
&       'BCENI = 25 : fixed ion temperature '//&
&       '(modified by nearby ring) ', enipar(ib, 1), ' with ', enipar(ib&
&       , 2), ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enipar(ib, 1) .NE. 0.0_R8, &
&             'faulty parameter enipar1')
      END IF
      tiave = 0.0_R8
      niave = 0.0_R8
      DO ibc=1,mpg%bccvp(ib, 2)
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
        tiave = tiave + pl%ti(icv)*dv%ni(icv, 0)*geo%cvvol(icv)
        niave = niave + dv%ni(icv, 0)*geo%cvvol(icv)
      END DO
      tiave = tiave/niave
      IF (enipar(ib, 2) .GT. 0.0_R8) t3 = enipar(ib, 2)
      IF (enipar(ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref_ti
      DO ibc=1,mpg%bccvp(ib, 2)
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%shi0(icv1, 0) = vbig*ne00*enipar(ib, 1)*ev*geo%fcs(ifc)*(&
&         1.0_R8-t3+t3*pl%ti(icv2)/tiave)
        srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (26) 
!
! -- BCENI=26 -- PRESCRIBE THE POLOIDALLY AVERAGED VALUE OF THE ION TEMPERATURE
! AND INTRODUCE A POLOIDAL VARIATION IN A SIMPLIFIED MANNER.
! THIS BOUNDARY CONDITION IS SUITABLE FOR ANY PLASMA COMPOSITION (i.e. when BCENI=23 fails).
! IT IS RECOMMENDED TO USE THIS BOUNDARY CONDITION TOGETHER WITH CORRESPONDING
! CONDITION ON ION DENSITY BCCON = 25,26,27
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7)') &
&       'BCENI = 26 : specified ion temperature ', enipar(ib, 1)
!         write all boundaries with this type of boundary condition
        DO ibw=ib,nbc
          IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&             bceni(ibw) .EQ. bceni(ib)) THEN
            WRITE(*, '(a,a,a)') ' on ', bcchar(ibw), boundary_location(&
&           ibw)
            icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
            CALL XERTST(mpg%cvonclosedsurface(icv), &
&                 'BCENI = 26 only applicable to core boundaries !')
            CALL XERTST(switch%use_astra .NE. 0 .OR. enipar(ibw, 1) .GT.&
&                 0.0_R8, 'BCENI = 26, ENIPAR(,1) !> 0')
            CALL XERTST(switch%use_astra .NE. 0 .OR. enipar(ib, 1) .EQ. &
&                 enipar(ibw, 1), &
&                 'BCENI = 26, inconsistent ENIPAR(,1) values!')
          END IF
          IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (((&
&             bceni(ibw) .EQ. 16 .OR. bceni(ibw) .EQ. 23) .OR. bceni(ibw&
&             ) .EQ. 24) .OR. bceni(ibw) .EQ. 27)) THEN
! IYS added BCENI= 26 and 27
            CALL XERRAB(&
&                 'BCENI types 16, 23, 24, 26 and 27 cannot be mixed!')
          END IF
        END DO
      END IF
!
      IF (.NOT.once_bceni) THEN
        IF (switch%use_astra .NE. 0) CALL XERRAB(&
&                    'Compile with -DASTRA option to couple with ASTRA!'&
&                                         )
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
! Volume                                     !lk 12.12.12 {
          t0 = 0.0_R8
! Poloidally volume-averaged ion temperature in the cell next to boundary
          t1 = 0.0_R8
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                t0 = t0 + geo%cvvol(icv)
                t1 = t1 + pl%ti(icv)*geo%cvvol(icv)
              END DO
            END IF
          END DO
          t1 = t1/t0
          DO ibw=ib,nbc
!lk 12.12.12 }
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                IF (mpg%cvonclosedsurface(icv2)) THEN
                  srw%shi0(icv1, 0) = vbig*ne00*(enipar(ibw, 1)*ev+(pl%&
&                   ti(icv2)-t1))*geo%fcs(ifc)
                  srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
                END IF
              END DO
            END IF
          END DO
          once_bceni = .true.
        ELSE
          CALL XERRAB(&
&              'B2STBC -- BCENI=26 IS AVAILABLE FOR CORE BOUNDARY ONLY.'&
&              )
        END IF
      END IF
    CASE (27) 
!
! -- BCENI=27 -- Feedback boundary condition with prescribed total ion heat flux,
!                constant poloidally averaged ion temperature and a
!                poloidal variation in a simplified manner.
! THIS BOUNDARY CONDITION IS SUITABLE FOR ANY PLASMA COMPOSITION (i.e. when BCENI=24 fails).
! IT IS RECOMMENDED TO USE THIS BOUNDARY CONDITION TOGETHER WITH CORRESPONDING
! CONDITION ON ION DENSITY BCCON = 25,26,27
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, *) 'BCENI = 27 : Given integrated ion heat flux', &
&       ' with constant Ti '
!         write all boundaries with this type of boundary condition
        DO ibw=ib,nbc
          IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&             bceni(ibw) .EQ. bceni(ib)) THEN
            WRITE(*, '(a,a,a)') ' on ', bcchar(ibw), boundary_location(&
&           ibw)
            icv = mpg%bccv(mpg%bccvp(ibw, 1), 2)
            CALL XERTST(mpg%cvonclosedsurface(icv), &
&                 'BCENI = 27 only applicable to core boundaries !')
            CALL XERTST(enipar(ibw, 1) .NE. 0, &
&                 'faulty parameter enipar1')
          END IF
          IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. (((&
&             bceni(ibw) .EQ. 16 .OR. bceni(ibw) .EQ. 23) .OR. bceni(ibw&
&             ) .EQ. 24) .OR. bceni(ibw) .EQ. 26)) THEN
! IYS added BCENI= 26 and 27
            CALL XERRAB(&
&                 'BCENI types 16, 23, 24, 26 and 27 cannot be mixed!')
          END IF
        END DO
      END IF
      IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
!srv 16.02.12 }
        IF (.NOT.once_bceni) THEN
          IF (switch%use_astra .NE. 0) THEN
            CALL XERRAB(&
&                 'Compile with -DASTRA option to couple with ASTRA!')
          ELSE
            senipar = 0.0_R8
            DO ibw=ib,nbc
              IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND.&
&                 bceni(ibw) .EQ. bceni(ib)) senipar = senipar + enipar(&
&                 ibw, 1)
            END DO
          END IF
          WRITE(*, *) 'BCENI=27: Summed value is ', senipar
! Poloidally density-averaged ion temperature in the boundary cell
          tis = 0.0_R8
          nivs = 0.0_R8
! Volume                                      !lk 12.12.12 {
          t0 = 0.0_R8
! Poloidally volume-averaged ion temperature in the cell next to boundary
          t1 = 0.0_R8
! IYS 22.03.2017
          totflux = 0.0_R8
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                tis = tis + pl%ti(icv1)*dv%ni(icv1, 0)*geo%cvvol(icv2)
                nivs = nivs + dv%ni(icv1, 0)*geo%cvvol(icv2)
                t0 = t0 + geo%cvvol(icv2)
                t1 = t1 + pl%ti(icv2)*geo%cvvol(icv2)
                IF (switch%mdf_fhi .NE. 0) THEN
                  totflux = totflux - mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1&
&                   )*(dv%fhi_mdf(ifc, 0)+dv%fhi_mdf(ifc, 1))
                  DO is=0,ns-1
                    totflux = totflux - pl%ti(icv1)*pl%na(icv1, is)*geo%&
&                     fcs(ifc)*mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1)*(dv%&
&                     vaecrb(ifc, 0, is)*geo%fcqalf(ifc, 0)+dv%vaecrb(&
&                     ifc, 1, is)*geo%fcqalf(ifc, 1))
                  END DO
                ELSE
                  totflux = totflux - mpg%bcfcor(mpg%bccvp(ibw, 1)+ibc-1&
&                   )*(dv%fhi(ifc, 0)+dv%fhi(ifc, 1))
                END IF
              END DO
            END IF
          END DO
          tis = tis/nivs
          t1 = t1/t0
          IF (enipar(ib, 2) .GT. 0.0_R8) t3 = enipar(ib, 2)
          IF (enipar(ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref_ti
          IF (totflux .GE. 0.) THEN
            x5 = totflux
          ELSE
            x5 = -totflux
          END IF
          IF (x5 .LT. senipar) THEN
            max11 = senipar
          ELSE
            max11 = x5
          END IF
          tis = tis*(1.0_R8-t3*(totflux-senipar)/max11)
          WRITE(*, '(3(a,es14.7))') ' TIS=', tis/ev, ' totflux=', &
&         totflux, ' SENIPAR=', senipar
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bceni(ibw) .EQ. bceni(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv1 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                icv2 = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 2)
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                srw%shi0(icv1, 0) = vbig*ne00*(tis+(pl%ti(icv2)-t1))*geo&
&                 %fcs(ifc)
                srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
              END DO
            END IF
          END DO
          once_bceni = .true.
        END IF
      ELSE
        CALL XERRAB('B2STBC -- BCENI=27 IS AVAILABLE FOR CORE ONLY')
      END IF
    CASE (28) 
!
! -- BCENI=28 -- Prescribe the value of the ion temperature, with poloidal
!                perturbation taken from flux tube just inside domain
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          CALL XERTST(mpg%cvonclosedsurface(icv1), &
&               'BCENI=28 intended for core boundaries only!')
        END DO
        IF (switch%use_astra .NE. 0) enipar(ib, 1) = teb_astra*1.0e3_R8
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'specified ion temperature + perturbation', enipar(ib, 1), &
&       ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enipar(ib, 1) .GT. 0.0_R8, &
&             'BCENI = 28, ENIPAR(,1) !> 0')
      END IF
!     ..compute average temperature on core boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
        IF (mpg%cvonclosedsurface(icv1)) THEN
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            t0 = t0 + geo%cvvol(icv2)
            t1 = t1 + geo%cvvol(icv2)*pl%ti(icv2)
          END DO
        END IF
      END DO
      t1 = t1/t0
!     ..impose temperature with perturbation
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%shi0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*(pl%ti(icv2)+enipar(&
&         ib, 1)*ev-t1)
        srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (29) 
!
! -- BCENI=29 -- Feedback on the total ion energy flux, by imposing a flux surface
!                averaged temperature, with poloidal perturbation taken from flux
!                tube just inside domain
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          CALL XERTST(mpg%cvonclosedsurface(icv1), &
&               'BCENI=29 intended for core boundaries only!')
        END DO
        WRITE(*, '(a,1p,g14.7,a,a,a)') 'specified ion heat flux', enipar&
&       (ib, 1), ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enipar(ib, 1) .GT. 0.0_R8, &
&             'BCENI = 29, ENIPAR(,1) !> 0')
      END IF
!     ..compute average temperature on core boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
      t2 = 0.0_R8
      totflux = 0.0_R8
      totpar = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
        IF (mpg%cvonclosedsurface(icv1)) THEN
          IF (bceni(ib0) .NE. 29) CALL XERRAB(&
&                                      'BCENI=29: incompatible core BCs'&
&                                      )
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            t0 = t0 + geo%cvvol(icv2)
            t1 = t1 + geo%cvvol(icv2)*pl%ti(icv1)
            t2 = t2 + geo%cvvol(icv2)*pl%ti(icv2)
            totflux = totflux - (dv%fhi(ifc, 0)+dv%fhi(ifc, 1))*mpg%&
&             bcfcor(mpg%bccvp(ib0, 1)+ibc0-1)
          END DO
          totpar = totpar + enipar(ib0, 1)
        END IF
      END DO
      totpar = fac_he_anom_bc*totpar
      t1 = t1/t0
      t2 = t2/t0
      IF (enipar(ib, 2) .GT. 0.0_R8) t3 = enipar(ib, 2)
      IF (enipar(ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref_ti
      IF (totflux .GE. 0.) THEN
        x6 = totflux
      ELSE
        x6 = -totflux
      END IF
      IF (totpar .GE. 0.) THEN
        y3 = totpar
      ELSE
        y3 = -totpar
      END IF
      IF (x6 .LT. y3) THEN
        max12 = y3
      ELSE
        max12 = x6
      END IF
      t4 = (1.0_R8-t3*(totflux-totpar)/max12)*t1
!     ..impose temperature with perturbation
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%shi0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*(pl%ti(icv2)+t4-t2)
        srw%shi0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE DEFAULT
!
      WRITE(*, *) bceni(ib)
      CALL XERRAB('BCENI out of bounds')
!
    END SELECT
!
    RETURN
  END SUBROUTINE B2STBC_PHYS_ENI

!  Differentiation of b2stbc_phys_pot in reverse (adjoint) mode (with options context noISIZE r8):
!   gradient     of useful results: mompar potpar scurpar prev_cur_delta
!                po_prev po_curr coeff_16 pos *(dv.fch) *(dv.fchdia)
!                *(dv.fchin) *(dv.fchvispar) *(dv.fchvisper) *(dv.fchvisq)
!                *(dv.fchinert) *(dv.fchviskt) *(dv.ne) *(dv.vaecrb)
!                *(rt.rza) *(srw.sch0) *(co.sig0) *(pl.na) *(pl.ua)
!                *(pl.po) *(pl.te) *(pl.ti) naua2average vbc rz
!                csbc pzaverage pz
!   with respect to varying inputs: mompar potpar scurpar prev_cur_delta
!                po_prev po_curr coeff_16 pos *(dv.fch) *(dv.fchdia)
!                *(dv.fchin) *(dv.fchvispar) *(dv.fchvisper) *(dv.fchvisq)
!                *(dv.fchinert) *(dv.fchviskt) *(dv.ne) *(dv.vaecrb)
!                *(rt.rza) *(srw.sch0) *(co.sig0) *(pl.na) *(pl.ua)
!                *(pl.po) *(pl.te) *(pl.ti) naua2average vbc rz
!                csbc pzaverage pz
!   Plus diff mem management of: dv.fch:in dv.fchdia:in dv.fchin:in
!                dv.fchvispar:in dv.fchvisper:in dv.fchvisq:in
!                dv.fchinert:in dv.fchviskt:in dv.ne:in dv.vaecrb:in
!                dv.facdrift:in mpg.bcfcor:in geo.vxvol:in rt.rza:in
!                srw.sch0:in co.sig0:in pl.na:in pl.ua:in pl.po:in
!                pl.te:in pl.ti:in
!
  SUBROUTINE B2STBC_PHYS_POT_B(ib)
    IMPLICIT NONE
    INTEGER :: ib, ib0, ibc, ibc0, ibw, is
    INTEGER :: icv, icv1, icv2, ifc, ivx1, ivx2
    REAL(kind=r8) :: cs, vte, vbnd, s1, fche, fchi, t0, t1, t2, t3, t4, &
&   neave, poave, totpar, totflux, wrk, seec, fchy_dia, fchy_inertia
    REAL(kind=r8) :: csb, vteb, vbndb, fcheb, fchib, t0b, t1b, t2b, t3b&
&   , t4b, neaveb, poaveb, totparb, totfluxb, fchy_diab, fchy_inertiab
    REAL(kind=r8), EXTERNAL :: INTVERTEX_S_NODIFF
    EXTERNAL XERRAB
    INTRINSIC SQRT
    INTRINSIC ABS
    INTRINSIC SIGN
    INTRINSIC MIN
    INTRINSIC MOD
    REAL(kind=r8) :: x1
    REAL(kind=r8) :: x1b
    REAL(kind=r8) :: y1
    REAL(kind=r8) :: y1b
    REAL(kind=r8) :: y2
    REAL(kind=r8) :: x2
    REAL(kind=r8) :: x2b
    REAL(kind=r8) :: x3
    REAL(kind=r8) :: x3b
    REAL(kind=r8) :: y3
    REAL(kind=r8) :: y3b
    REAL(kind=r8) :: x4
    REAL(kind=r8) :: x4b
    REAL(kind=r8) :: y4
    REAL(kind=r8) :: y4b
    REAL(kind=r8) :: x5
    REAL(kind=r8) :: x5b
    REAL(kind=r8) :: y5
    REAL(kind=r8) :: y5b
    REAL(r8) :: y6
    REAL(r8) :: y6b
    REAL(kind=r8) :: abs0
    REAL(kind=r8) :: max1
    REAL(kind=r8) :: max1b
    REAL(kind=r8) :: abs1
    REAL(kind=r8) :: max2
    REAL(kind=r8) :: max2b
    REAL(kind=r8) :: abs2
    REAL(kind=r8) :: max3
    REAL(kind=r8) :: max3b
    REAL(kind=r8) :: max4
    REAL(kind=r8) :: max4b
    REAL(kind=r8) :: abs3
    REAL(kind=r8) :: max5
    REAL(kind=r8) :: max5b
    REAL(kind=r8) :: max6
    REAL(kind=r8) :: max6b
    REAL(kind=r8) :: abs4
    REAL(r8) :: min1
    REAL(r8) :: min1b
    REAL(kind=r8) :: abs5
    REAL(kind=r8) :: result10
    REAL(kind=r8) :: result10b
    REAL(kind=r8) :: result11
    REAL(kind=r8) :: temp
    REAL(kind=r8) :: tempb
    REAL(kind=r8) :: temp0
    REAL(kind=r8) :: tempb0
    REAL(r8) :: tempb1
    INTEGER*4 :: branch
    INTEGER :: ad_to
    INTEGER :: ad_to0
    INTEGER :: ad_to1
    INTEGER :: ad_to2
    INTEGER :: ad_to3
    INTEGER :: ad_to4
    INTEGER :: ad_to5
!
! -- BOUNDARY CONDITIONS FOR POTENTIAL EQUATION --
!
    SELECT CASE  (bcpot(ib)) 
    CASE (0) 

    CASE (1) 
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        srwb%sch0(icv1, 1) = 0.D0
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        potparb(ib, 1) = potparb(ib, 1) + pbig*geo%fcs(ifc)*srwb%sch0(&
&         icv1, 0)
        srwb%sch0(icv1, 0) = 0.D0
      END DO
    CASE (2) 
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        srwb%sch0(icv1, 1) = 0.D0
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        tempb = pbig*geo%fcs(ifc)*srwb%sch0(icv1, 0)
        srwb%sch0(icv1, 0) = 0.D0
        potparb(ib, 1) = potparb(ib, 1) + geo%fcqgam(ifc, 0)*(geo%fchc(&
&         ifc, 1)+geo%fchc(ifc, 2))*tempb
        tempb0 = -(mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*cor9*geo%fcqgam(&
&         ifc, 1)*(geo%fchc(ifc, 1)+geo%fchc(ifc, 2))*tempb/geo%fcht(ifc&
&         ))
        plb%po(icv2) = plb%po(icv2) + tempb
        t2b = tempb0
        t1b = -tempb0
        ivx2 = mpg%fcvx(ifc, 2)
        CALL INTVERTEX_S_B(ivx2, ncv, nvx, mpg, geo%vxvol, pl%po, plb%po&
&                    , t2b)
        ivx1 = mpg%fcvx(ifc, 1)
        CALL INTVERTEX_S_B(ivx1, ncv, nvx, mpg, geo%vxvol, pl%po, plb%po&
&                    , t1b)
      END DO
    CASE (3) 

    CASE (4) 
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        potparb(ib, 2) = potparb(ib, 2) - geo%fcs(ifc)*srwb%sch0(icv1, 1&
&         )
        srwb%sch0(icv1, 1) = 0.D0
        tempb0 = geo%fcs(ifc)*srwb%sch0(icv1, 0)
        srwb%sch0(icv1, 0) = 0.D0
        potparb(ib, 2) = potparb(ib, 2) + potpar(ib, 1)*tempb0
        potparb(ib, 1) = potparb(ib, 1) + potpar(ib, 2)*tempb0
      END DO
    CASE (5) 
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        srwb%sch0(icv, 1) = 0.D0
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        potparb(ib, 1) = potparb(ib, 1) + geo%fcs(ifc)*srwb%sch0(icv, 0)
        srwb%sch0(icv, 0) = 0.D0
      END DO
    CASE (6) 

    CASE (7) 
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        srwb%sch0(icv1, 1) = 0.D0
        srwb%sch0(icv1, 0) = 0.D0
      END DO
    CASE (8) 
      us = 0.0_R8
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        us = us + geo%fcs(ifc)
      END DO
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        srwb%sch0(icv1, 1) = 0.D0
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        potparb(ib, 1) = potparb(ib, 1) + geo%fcs(ifc)*srwb%sch0(icv1, 0&
&         )/us
        srwb%sch0(icv1, 0) = 0.D0
      END DO
    CASE (9) 
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        temp0 = qe*potpar(ib, 1)
        temp = temp0*dv%ne(icv)
        tempb1 = -(geo%fcs(ifc)*srwb%sch0(icv, 1)/temp)
        srwb%sch0(icv, 1) = 0.D0
        cob%sig0(ifc) = cob%sig0(ifc) + tempb1
        tempb = -(co%sig0(ifc)*tempb1/temp)
        potparb(ib, 1) = potparb(ib, 1) + qe*dv%ne(icv)*tempb
        dvb%ne(icv) = dvb%ne(icv) + temp0*tempb
        srwb%sch0(icv, 0) = 0.D0
      END DO
    CASE (10) 

    CASE (11) 
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        ivx1 = mpg%fcvx(ifc, 1)
        ivx2 = mpg%fcvx(ifc, 2)
!srv 15.02.26 {
        DO is=0,ns-1
          CALL PUSHREAL8ARRAY(csbc, r8*ncv*ns/8)
          CALL CSBC_IS(icv1, ib, is, cs)
          CALL PUSHREAL8ARRAY(vbc, r8*ncv*ns/8)
          CALL VBC_IS(ib, is, ibc, icv1, icv2, ifc, csbc(icv1, is), wrk)
!srv 15.02.26 }
        END DO
        CALL PUSHREAL8(vte, r8/8)
        vte = SQRT(pl%te(icv1)/me)
        t0 = 0.0_R8
        wrk = geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3)
        IF (wrk .GE. 0.) THEN
          abs0 = wrk
        ELSE
          abs0 = -wrk
        END IF
        IF (abs0 .LT. geo%qalfmin) THEN
          CALL PUSHCONTROL1B(0)
        ELSE
          s1 = geo%fcs(ifc)
          DO is=0,ns-1
            IF (is_neutral(is)) THEN
              CALL PUSHCONTROL1B(0)
            ELSE
              vbnd = (dv%vaecrb(ifc, 0, is)*geo%fcqalf(ifc, 0)+dv%vaecrb&
&               (ifc, 1, is)*geo%fcqalf(ifc, 1))*mpg%bcfcor(mpg%bccvp(ib&
&               , 1)+ibc-1)
              IF (wrk .GE. 0.) THEN
                CALL PUSHREAL8(abs4, r8/8)
                abs4 = wrk
                CALL PUSHCONTROL1B(0)
              ELSE
                CALL PUSHREAL8(abs4, r8/8)
                abs4 = -wrk
                CALL PUSHCONTROL1B(1)
              END IF
              x1 = csbc(icv1, is)*abs4
              y1 = vbc(icv1, is)*SIGN(1.0_R8, wrk) + vbnd
              IF (x1 .LT. y1) THEN
                CALL PUSHREAL8(max1, r8/8)
                max1 = y1
                CALL PUSHCONTROL1B(0)
              ELSE
                CALL PUSHREAL8(max1, r8/8)
                max1 = x1
                CALL PUSHCONTROL1B(1)
              END IF
              t0 = t0 + rt%rza(icv1, is)*mompar(is, ib, 1)*s1*max1*pl%na&
&               (icv1, is)
              CALL PUSHCONTROL1B(1)
            END IF
          END DO
          fchi = qe*t0
          IF (wrk .GE. 0.) THEN
            CALL PUSHREAL8(abs1, r8/8)
            abs1 = wrk
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHREAL8(abs1, r8/8)
            abs1 = -wrk
            CALL PUSHCONTROL1B(1)
          END IF
          IF (-50.0_R8 .LT. -(qe*(pl%po(icv1)-potpar(ib, 2))/pl%te(icv1)&
&             )) THEN
            y6 = -(qe*(pl%po(icv1)-potpar(ib, 2))/pl%te(icv1))
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHCONTROL1B(1)
            y6 = -50.0_R8
          END IF
          IF (0.0_R8 .GT. y6) THEN
            CALL PUSHREAL8(min1, r8/8)
            min1 = y6
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHREAL8(min1, r8/8)
            min1 = 0.0_R8
            CALL PUSHCONTROL1B(1)
          END IF
!lkw 31.03.2023
          CALL PUSHBOOLEAN(b2mod_math_initialised)
          CALL PUSHREAL8(cutlo, r8/8)
          CALL PUSHREAL8(cutll, r8/8)
          CALL PUSHREAL8(result10, r8/8)
          result10 = EXPU2(min1)
          fche = SQRT(1/(2*pi))*qe*dv%ne(icv1)*vte*s1*abs1*result10
          seec = gammae
          IF (fchi .LT. (1.0_R8-seec)*fche) THEN
            CALL PUSHREAL8(max2, r8/8)
            max2 = (1.0_R8-seec)*fche
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHREAL8(max2, r8/8)
            max2 = fchi
            CALL PUSHCONTROL1B(1)
          END IF
          CALL PUSHCONTROL1B(1)
        END IF
      END DO
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          srwb%sch0(icv1, 1) = 0.D0
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          tempb1 = pbig*geo%fcs(ifc)*srwb%sch0(icv1, 0)
          srwb%sch0(icv1, 0) = 0.D0
          plb%po(icv2) = plb%po(icv2) + tempb1
          tempb0 = -(mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*cor9*geo%fcqgam(&
&           ifc, 1)*(geo%fchc(ifc, 1)+geo%fchc(ifc, 2))*tempb1/geo%fcht(&
&           ifc))
          t2b = tempb0
          t1b = -tempb0
          ivx2 = mpg%fcvx(ifc, 2)
          CALL INTVERTEX_S_B(ivx2, ncv, nvx, mpg, geo%vxvol, pl%po, plb%&
&                      po, t2b)
          ivx1 = mpg%fcvx(ifc, 1)
          CALL INTVERTEX_S_B(ivx1, ncv, nvx, mpg, geo%vxvol, pl%po, plb%&
&                      po, t1b)
          vteb = 0.D0
        ELSE
          t0b = -srwb%sch0(icv1, 1)
          srwb%sch0(icv1, 1) = 0.D0
          t0 = max2*qe/pl%te(icv1)
          seec = gammae
          fcheb = (1.0_R8-seec)*srwb%sch0(icv1, 0)
          fchib = -srwb%sch0(icv1, 0)
          t0b = t0b + pl%po(icv1)*srwb%sch0(icv1, 0)
          plb%po(icv1) = plb%po(icv1) + t0*srwb%sch0(icv1, 0)
          srwb%sch0(icv1, 0) = 0.D0
          tempb0 = qe*t0b/pl%te(icv1)
          max2b = tempb0
          plb%te(icv1) = plb%te(icv1) - max2*tempb0/pl%te(icv1)
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            CALL POPREAL8(max2, r8/8)
            fcheb = fcheb + (1.0_R8-seec)*max2b
          ELSE
            CALL POPREAL8(max2, r8/8)
            fchib = fchib + max2b
          END IF
          s1 = geo%fcs(ifc)
          tempb1 = qe*s1*abs1*SQRT(1.0/(2*pi))*fcheb
          dvb%ne(icv1) = dvb%ne(icv1) + vte*result10*tempb1
          tempb0 = dv%ne(icv1)*tempb1
          vteb = result10*tempb0
          result10b = vte*tempb0
          CALL POPREAL8(result10, r8/8)
          CALL POPREAL8(cutll, r8/8)
          CALL POPREAL8(cutlo, r8/8)
          CALL POPBOOLEAN(b2mod_math_initialised)
          CALL EXPU2_B(min1, min1b, result10b)
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            CALL POPREAL8(min1, r8/8)
            y6b = min1b
          ELSE
            CALL POPREAL8(min1, r8/8)
            y6b = 0.D0
          END IF
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            tempb1 = -(qe*y6b/pl%te(icv1))
            plb%po(icv1) = plb%po(icv1) + tempb1
            potparb(ib, 2) = potparb(ib, 2) - tempb1
            plb%te(icv1) = plb%te(icv1) - (pl%po(icv1)-potpar(ib, 2))*&
&             tempb1/pl%te(icv1)
          END IF
          wrk = geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3)
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            CALL POPREAL8(abs1, r8/8)
          ELSE
            CALL POPREAL8(abs1, r8/8)
          END IF
          t0b = qe*fchib
          DO is=ns-1,0,-1
            CALL POPCONTROL1B(branch)
            IF (branch .NE. 0) THEN
              tempb1 = mompar(is, ib, 1)*pl%na(icv1, is)*s1*t0b
              tempb0 = rt%rza(icv1, is)*max1*s1*t0b
              momparb(is, ib, 1) = momparb(is, ib, 1) + pl%na(icv1, is)*&
&               tempb0
              plb%na(icv1, is) = plb%na(icv1, is) + mompar(is, ib, 1)*&
&               tempb0
              rtb%rza(icv1, is) = rtb%rza(icv1, is) + max1*tempb1
              max1b = rt%rza(icv1, is)*tempb1
              CALL POPCONTROL1B(branch)
              IF (branch .EQ. 0) THEN
                CALL POPREAL8(max1, r8/8)
                y1b = max1b
                x1b = 0.D0
              ELSE
                CALL POPREAL8(max1, r8/8)
                x1b = max1b
                y1b = 0.D0
              END IF
              vbcb(icv1, is) = vbcb(icv1, is) + SIGN(1.0_R8, wrk)*y1b
              vbndb = y1b
              csbcb(icv1, is) = csbcb(icv1, is) + abs4*x1b
              CALL POPCONTROL1B(branch)
              IF (branch .EQ. 0) THEN
                CALL POPREAL8(abs4, r8/8)
              ELSE
                CALL POPREAL8(abs4, r8/8)
              END IF
              tempb0 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*vbndb
              dvb%vaecrb(ifc, 0, is) = dvb%vaecrb(ifc, 0, is) + geo%&
&               fcqalf(ifc, 0)*tempb0
              dvb%vaecrb(ifc, 1, is) = dvb%vaecrb(ifc, 1, is) + geo%&
&               fcqalf(ifc, 1)*tempb0
            END IF
          END DO
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
        END IF
        CALL POPREAL8(vte, r8/8)
        IF (.NOT.pl%te(icv1)/me .EQ. 0.D0) plb%te(icv1) = plb%te(icv1) +&
&           vteb/(me*2.0*SQRT(pl%te(icv1)/me))
        DO is=ns-1,0,-1
          CALL POPREAL8ARRAY(vbc, r8*ncv*ns/8)
          CALL VBC_IS_B(ib, is, ibc, icv1, icv2, ifc, csbc(icv1, is), &
&                 csbcb(icv1, is), wrk)
          CALL POPREAL8ARRAY(csbc, r8*ncv*ns/8)
          csb = 0.D0
          CALL CSBC_IS_B(icv1, ib, is, cs, csb)
        END DO
      END DO
    CASE (12) 
      result11 = MAXVAL(dv%facdrift)
      IF (result11 .NE. 0.0_R8) THEN
!       ..compute the source
        IF (bcpot_12_style .EQ. -1) THEN
!wdk with <fcBb(:,2)>
! loop over number of cells in the boundary
          DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
            CALL PUSHINTEGER4(icv1)
! number of the guard cell face
            DO is=0,ns-1
              IF (.NOT.is_neutral(is)) THEN
                CALL PUSHCONTROL1B(1)
              ELSE
                CALL PUSHCONTROL1B(0)
              END IF
            END DO
          END DO
          DO ibc=mpg%bccvp(ib, 2),1,-1
            icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
            fchy_inertiab = -srwb%sch0(icv1, 0)
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            DO is=ns-1,0,-1
              CALL POPCONTROL1B(branch)
              IF (branch .NE. 0) naua2averageb(is) = naua2averageb(is) -&
&                 am(is)*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*mp*bzaverage&
&                 *geo%fcqalf(ifc, 1)*switch%b2stbc_phm1*0.5_R8*geo%fcs(&
&                 ifc)*dv%facdrift(ifc)*gonedbsq(ifc, 0)*fchy_inertiab
            END DO
            fchy_diab = -srwb%sch0(icv1, 0)
            pzaverageb = pzaverageb - dv%facdrift(ifc)*mpg%bcfcor(mpg%&
&             bccvp(ib, 1)+ibc-1)*switch%b2stbc_phm0*bzaverage*geo%&
&             fcqalf(ifc, 1)*gonedbsq(ifc, 0)*geo%fcs(ifc)*fchy_diab
            CALL POPINTEGER4(icv1)
          END DO
        ELSE IF (bcpot_12_style .EQ. 0) THEN
! loop over number of cells in the boundary
          DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
            CALL PUSHINTEGER4(icv1)
! number of the guard cell face
!wdk now uses fcBb(iFc,2) instead of <fcBb(:,2)>
            DO is=0,ns-1
              IF (.NOT.is_neutral(is)) THEN
                CALL PUSHCONTROL1B(1)
              ELSE
                CALL PUSHCONTROL1B(0)
              END IF
            END DO
          END DO
          DO ibc=mpg%bccvp(ib, 2),1,-1
            icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
            fchy_inertiab = -srwb%sch0(icv1, 0)
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            DO is=ns-1,0,-1
              CALL POPCONTROL1B(branch)
              IF (branch .NE. 0) naua2averageb(is) = naua2averageb(is) -&
&                 dv%facdrift(ifc)*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*am&
&                 (is)*mp*geo%fcqalf(ifc, 1)*switch%b2stbc_phm1*0.5_R8*&
&                 geo%fcbb(ifc, 2)*gonedbsq(ifc, 0)*geo%fcs(ifc)*&
&                 fchy_inertiab
            END DO
            fchy_diab = -srwb%sch0(icv1, 0)
            pzaverageb = pzaverageb - switch%b2stbc_phm0*geo%fcqalf(ifc&
&             , 1)*geo%fcbb(ifc, 2)*geo%fcs(ifc)*mpg%bcfcor(mpg%bccvp(ib&
&             , 1)+ibc-1)*dv%facdrift(ifc)*gonedbsq(ifc, 0)*fchy_diab
            CALL POPINTEGER4(icv1)
          END DO
        ELSE IF (bcpot_12_style .EQ. 1) THEN
!wdk experimental - use fchdia / fchinert as computed
! loop over number of cells in the boundary
          DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
            CALL PUSHINTEGER4(icv1)
! number of the guard cell face
!wdk now uses fcBb(iFc,2) instead of <fcBb(:,2)>
          END DO
          DO ibc=mpg%bccvp(ib, 2),1,-1
            icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
            fchy_inertiab = -srwb%sch0(icv1, 0)
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            tempb1 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*fchy_inertiab
            dvb%fchinert(ifc, 0) = dvb%fchinert(ifc, 0) + tempb1
            dvb%fchinert(ifc, 1) = dvb%fchinert(ifc, 1) + tempb1
            fchy_diab = -srwb%sch0(icv1, 0)
            tempb1 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*fchy_diab
            dvb%fchdia(ifc, 0) = dvb%fchdia(ifc, 0) + tempb1
            dvb%fchdia(ifc, 1) = dvb%fchdia(ifc, 1) + tempb1
            CALL POPINTEGER4(icv1)
          END DO
        ELSE IF (bcpot_12_style .EQ. 2) THEN
!wdk experimental - find constant potential (with
!    perturbation taken from flux tube just inside
!    domain) such that total current through core
!    is sum of dia + inert currents
!     ..compute average potential on core boundary
          t0 = 0.0_R8
          t1 = 0.0_R8
          totflux = 0.0_R8
          totpar = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
          DO ib0=1,nbc
            CALL PUSHINTEGER4(icv1)
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
            IF (mpg%cvonclosedsurface(icv1)) THEN
! loop over number of cells in the boundary
              DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
                icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
                icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                t0 = t0 + geo%cvvol(icv2)
                t1 = t1 + geo%cvvol(icv2)*pl%po(icv1)
                totflux = totflux - mpg%bcfcor(mpg%bccvp(ib0, 1)+ibc0-1)&
&                 *(dv%fch(ifc, 0)+dv%fch(ifc, 1))
                totpar = totpar - mpg%bcfcor(mpg%bccvp(ib0, 1)+ibc0-1)*(&
&                 dv%fchdia(ifc, 0)+dv%fchdia(ifc, 1)+dv%fchinert(ifc, 0&
&                 )+dv%fchinert(ifc, 1))
              END DO
              CALL PUSHINTEGER4(ibc0 - 1)
              CALL PUSHCONTROL1B(1)
            ELSE
              CALL PUSHCONTROL1B(0)
            END IF
          END DO
          t1 = t1/t0
          IF (potpar(ib, 2) .GT. 0.0_R8) THEN
            t3 = potpar(ib, 2)
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHCONTROL1B(1)
          END IF
          IF (potpar(ib, 2) .LE. 0.0_R8) THEN
            t3 = switch%b2stbc_bc_ref_te
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHCONTROL1B(1)
          END IF
          IF (totflux .GE. 0.) THEN
            x2 = totflux
            CALL PUSHCONTROL1B(0)
          ELSE
            x2 = -totflux
            CALL PUSHCONTROL1B(1)
          END IF
          IF (x2 .LT. totpar) THEN
            IF (totpar .LT. 1.0e-10_R8) THEN
              CALL PUSHCONTROL2B(0)
              max3 = 1.0e-10_R8
            ELSE
              max3 = totpar
              CALL PUSHCONTROL2B(1)
            END IF
          ELSE IF (x2 .LT. 1.0e-10_R8) THEN
            max3 = 1.0e-10_R8
            CALL PUSHCONTROL2B(2)
          ELSE
            max3 = x2
            CALL PUSHCONTROL2B(3)
          END IF
!       ..impose potential with perturbation
! loop over number of cells in the boundary
          DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
            CALL PUSHINTEGER4(icv1)
! number of the domain cell
! number of the guard cell face
          END DO
          t2b = 0.D0
          t4b = 0.D0
          DO ibc=mpg%bccvp(ib, 2),1,-1
            icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
            srwb%sch0(icv1, 1) = 0.D0
            icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            tempb1 = pbig*geo%fcs(ifc)*srwb%sch0(icv1, 0)
            srwb%sch0(icv1, 0) = 0.D0
            plb%po(icv2) = plb%po(icv2) + tempb1
            t4b = t4b + tempb1
            t2b = t2b - tempb1
            CALL POPINTEGER4(icv1)
          END DO
          temp0 = t3/max3
          tempb1 = t1*t4b
          t1b = (1.0_R8-(totflux-totpar)*temp0)*t4b
          totfluxb = -(temp0*tempb1)
          totparb = temp0*tempb1
          tempb0 = -((totflux-totpar)*tempb1/max3)
          t3b = tempb0
          max3b = -(temp0*tempb0)
          CALL POPCONTROL2B(branch)
          IF (branch .LT. 2) THEN
            IF (branch .NE. 0) totparb = totparb + max3b
            x2b = 0.D0
          ELSE IF (branch .EQ. 2) THEN
            x2b = 0.D0
          ELSE
            x2b = max3b
          END IF
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            totfluxb = totfluxb + x2b
          ELSE
            totfluxb = totfluxb - x2b
          END IF
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) t3b = 0.D0
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) potparb(ib, 2) = potparb(ib, 2) + t3b
          t2b = t2b/t0
          t1b = t1b/t0
          DO ib0=nbc,1,-1
            CALL POPCONTROL1B(branch)
            IF (branch .NE. 0) THEN
              CALL POPINTEGER4(ad_to)
              DO ibc0=ad_to,1,-1
                icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                tempb1 = -(mpg%bcfcor(mpg%bccvp(ib0, 1)+ibc0-1)*totparb)
                dvb%fchdia(ifc, 0) = dvb%fchdia(ifc, 0) + tempb1
                dvb%fchdia(ifc, 1) = dvb%fchdia(ifc, 1) + tempb1
                dvb%fchinert(ifc, 0) = dvb%fchinert(ifc, 0) + tempb1
                dvb%fchinert(ifc, 1) = dvb%fchinert(ifc, 1) + tempb1
                tempb1 = -(mpg%bcfcor(mpg%bccvp(ib0, 1)+ibc0-1)*totfluxb&
&                 )
                dvb%fch(ifc, 0) = dvb%fch(ifc, 0) + tempb1
                dvb%fch(ifc, 1) = dvb%fch(ifc, 1) + tempb1
                icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
                plb%po(icv2) = plb%po(icv2) + geo%cvvol(icv2)*t2b
                plb%po(icv1) = plb%po(icv1) + geo%cvvol(icv2)*t1b
              END DO
            END IF
            CALL POPINTEGER4(icv1)
          END DO
        END IF
      END IF
    CASE (13) 
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        CALL PUSHINTEGER4(icv1)
! number of the guard cell face
!srv 03.03.15 }
      END DO
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        tempb1 = -(mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*srwb%sch0(icv1, 0)&
&         )
        dvb%fchdia(ifc, 0) = dvb%fchdia(ifc, 0) + tempb1
        dvb%fchdia(ifc, 1) = dvb%fchdia(ifc, 1) + tempb1
        dvb%fchin(ifc, 0) = dvb%fchin(ifc, 0) + tempb1
        dvb%fchin(ifc, 1) = dvb%fchin(ifc, 1) + tempb1
        dvb%fchvispar(ifc, 0) = dvb%fchvispar(ifc, 0) + tempb1
        dvb%fchvispar(ifc, 1) = dvb%fchvispar(ifc, 1) + tempb1
        dvb%fchvisq(ifc, 0) = dvb%fchvisq(ifc, 0) + tempb1
        dvb%fchvisq(ifc, 1) = dvb%fchvisq(ifc, 1) + tempb1
        dvb%fchviskt(ifc, 0) = dvb%fchviskt(ifc, 0) + tempb1
        dvb%fchviskt(ifc, 1) = dvb%fchviskt(ifc, 1) + tempb1
        dvb%fchvisper(ifc, 0) = dvb%fchvisper(ifc, 0) + tempb1
        dvb%fchvisper(ifc, 1) = dvb%fchvisper(ifc, 1) + tempb1
        dvb%fchinert(ifc, 0) = dvb%fchinert(ifc, 0) + tempb1
        dvb%fchinert(ifc, 1) = dvb%fchinert(ifc, 1) + tempb1
        CALL POPINTEGER4(icv1)
      END DO
    CASE (14) 
      us = 0.0_R8
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        us = us + geo%fcs(ifc)
      END DO
      t0b = 0.D0
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        srwb%sch0(icv1, 1) = 0.D0
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        tempb0 = geo%fcs(ifc)*srwb%sch0(icv1, 0)/us
        tempb1 = -(mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*srwb%sch0(icv1, 0)&
&         )
        srwb%sch0(icv1, 0) = 0.D0
        dvb%fch(ifc, 0) = dvb%fch(ifc, 0) + tempb1
        dvb%fch(ifc, 1) = dvb%fch(ifc, 1) + tempb1
        t0b = t0b + tempb0
        potparb(ib, 1) = potparb(ib, 1) - tempb0
      END DO
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        tempb1 = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*t0b
        dvb%fch(ifc, 0) = dvb%fch(ifc, 0) + tempb1
        dvb%fch(ifc, 1) = dvb%fch(ifc, 1) + tempb1
      END DO
    CASE (15) 
!     ..compute average potential on boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
      totflux = 0.0_R8
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        t0 = t0 + geo%fcs(ifc)
        t1 = t1 + geo%fcs(ifc)*pl%po(icv1)
        totflux = totflux - (dv%fch(ifc, 0)+dv%fch(ifc, 1))*mpg%bcfcor(&
&         mpg%bccvp(ib, 1)+ibc-1)
      END DO
      t1 = t1/t0
      totpar = potpar(ib, 1)
      IF (potpar(ib, 2) .GT. 0.0_R8) THEN
        t3 = potpar(ib, 2)
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHCONTROL1B(1)
      END IF
      IF (potpar(ib, 2) .LE. 0.0_R8) THEN
        t3 = switch%b2stbc_bc_ref_te
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHCONTROL1B(1)
      END IF
      IF (totflux .GE. 0.) THEN
        x3 = totflux
        CALL PUSHCONTROL1B(0)
      ELSE
        x3 = -totflux
        CALL PUSHCONTROL1B(1)
      END IF
      IF (totpar .GE. 0.) THEN
        y3 = totpar
        CALL PUSHCONTROL1B(0)
      ELSE
        y3 = -totpar
        CALL PUSHCONTROL1B(1)
      END IF
      IF (x3 .LT. y3) THEN
        IF (y3 .LT. 1.0_R8) THEN
          max4 = 1.0_R8
          CALL PUSHCONTROL2B(0)
        ELSE
          max4 = y3
          CALL PUSHCONTROL2B(1)
        END IF
      ELSE IF (x3 .LT. 1.0_R8) THEN
        max4 = 1.0_R8
        CALL PUSHCONTROL2B(2)
      ELSE
        max4 = x3
        CALL PUSHCONTROL2B(3)
      END IF
      t2b = 0.D0
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        srwb%sch0(icv1, 1) = 0.D0
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        t2b = t2b + pbig*geo%fcs(ifc)*srwb%sch0(icv1, 0)
        srwb%sch0(icv1, 0) = 0.D0
      END DO
      temp0 = t3/max4
      tempb1 = t1*t2b
      t1b = (1.0_R8-(totflux-totpar)*temp0)*t2b
      totfluxb = -(temp0*tempb1)
      totparb = temp0*tempb1
      tempb0 = -((totflux-totpar)*tempb1/max4)
      t3b = tempb0
      max4b = -(temp0*tempb0)
      CALL POPCONTROL2B(branch)
      IF (branch .LT. 2) THEN
        IF (branch .EQ. 0) THEN
          y3b = 0.D0
        ELSE
          y3b = max4b
        END IF
        x3b = 0.D0
      ELSE
        IF (branch .EQ. 2) THEN
          x3b = 0.D0
        ELSE
          x3b = max4b
        END IF
        y3b = 0.D0
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        totparb = totparb + y3b
      ELSE
        totparb = totparb - y3b
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        totfluxb = totfluxb + x3b
      ELSE
        totfluxb = totfluxb - x3b
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) t3b = 0.D0
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) potparb(ib, 2) = potparb(ib, 2) + t3b
      potparb(ib, 1) = potparb(ib, 1) + totparb
      t1b = t1b/t0
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        tempb1 = -(mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*totfluxb)
        dvb%fch(ifc, 0) = dvb%fch(ifc, 0) + tempb1
        dvb%fch(ifc, 1) = dvb%fch(ifc, 1) + tempb1
        plb%po(icv1) = plb%po(icv1) + geo%fcs(ifc)*t1b
      END DO
    CASE (16) 
!
! -- BCPOT=16 -- Feedback boundary condition with constant potential    !Solovyev 22.03.14 !srv 29.09.15
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
! add smth about #ifdef ASTRA here
! Init variables for BCPOT=16                                  { Solovyev 01.05.14
! square of delta between desired and calculated current
! previous value of upper value
        prev_cur_delta = 0.0_R8
! step of approximation (set after 1st iteration)
        coeff_16 = 1.0_R8
!************************************************************* } Solovyev 01.05.14
        scurpar = 0.0_R8
        DO ibw=ib,nbc
          IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&             bcpot(ibw) .EQ. bcpot(ib)) THEN
            scurpar = scurpar + potpar(ibw, 1)
            CALL PUSHCONTROL1B(1)
          ELSE
            CALL PUSHCONTROL1B(0)
          END IF
        END DO
!srv 29.09.15
        pos = 0.0_R8
        vs = 0.0_R8
        DO ibw=ib,nbc
          IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&             bcpot(ibw) .EQ. bcpot(ib)) THEN
            DO ibc=1,mpg%bccvp(ibw, 2)
              icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
              pos = pos + pl%po(icv)*geo%cvvol(icv)
              vs = vs + geo%cvvol(icv)
            END DO
            CALL PUSHINTEGER4(ibc - 1)
            CALL PUSHCONTROL1B(1)
          ELSE
            CALL PUSHCONTROL1B(0)
          END IF
        END DO
!srv 29.09.15 }
        pos = pos/vs
        po_prev = pos
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHCONTROL1B(1)
      END IF
!srv 29.09.15 }
      IF (.NOT.once_bcpot) THEN
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
          totflux = 0.0_R8
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bcpot(ibw) .EQ. bcpot(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                CALL PUSHINTEGER4(ifc)
                ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                totflux = totflux - mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(&
&                 dv%fch(ifc, 0)+dv%fch(ifc, 1))
              END DO
              CALL PUSHINTEGER4(ibc - 1)
              CALL PUSHCONTROL1B(1)
            ELSE
              CALL PUSHCONTROL1B(0)
            END IF
          END DO
! The implementation is based on one step of Newton method
! { Solovyev 03.05.14
          cur_delta = totflux - scurpar
! } Solovyev 03.05.14
          IF (ncall_b2stbc_phys .EQ. 0) THEN
            CALL PUSHCONTROL2B(0)
          ELSE
!Solovyev 23.05.14
            IF (ncall_b2stbc_phys .EQ. 1) THEN
! Solovyev 23.05.14
!srv 29.09.15
              po_curr = 0.0_R8
              CALL PUSHREAL8(vs, r8/8)
              vs = 0.0_R8
              DO ibw=ib,nbc
                IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') &
&                   .AND. bcene(ibw) .EQ. bcene(ib)) THEN
                  DO ibc=1,mpg%bccvp(ibw, 2)
                    CALL PUSHINTEGER4(icv)
                    icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                    CALL PUSHINTEGER4(ifc)
                    ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                    po_curr = po_curr + pl%po(icv)*geo%cvvol(icv)
                    vs = vs + geo%cvvol(icv)
                  END DO
                  CALL PUSHINTEGER4(ibc - 1)
                  CALL PUSHCONTROL1B(1)
                ELSE
                  CALL PUSHCONTROL1B(0)
                END IF
              END DO
!srv 29.09.15 }
              po_curr = po_curr/vs
              CALL PUSHCONTROL1B(0)
            ELSE
              CALL PUSHCONTROL1B(1)
            END IF
! Solovyev 23.05.14
            IF (MOD(ncall_b2stbc_phys, bcpot_16_step) .EQ. 0) THEN
              IF (cur_delta - prev_cur_delta .GE. 0.) THEN
                abs3 = cur_delta - prev_cur_delta
              ELSE
                abs3 = -(cur_delta-prev_cur_delta)
              END IF
!Solovyev 23.05.14
              IF (abs3 .GT. 1.0e-20_R8) THEN
!{ Solovyev 24.05.14
                coeff_16 = (po_prev-po_curr)/(cur_delta-prev_cur_delta)
                CALL PUSHCONTROL1B(0)
              ELSE
                CALL PUSHCONTROL1B(1)
              END IF
              CALL PUSHCONTROL2B(1)
            ELSE
              CALL PUSHCONTROL2B(2)
            END IF
          END IF
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bcpot(ibw) .EQ. bcpot(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                CALL PUSHINTEGER4(icv)
!Solovyev 27.04.14
!Solovyev 27.04.14
              END DO
              CALL PUSHINTEGER4(ibc - 1)
              CALL PUSHCONTROL1B(1)
            ELSE
              CALL PUSHCONTROL1B(0)
            END IF
          END DO
          DO ibw=nbc,ib,-1
            CALL POPCONTROL1B(branch)
            IF (branch .NE. 0) THEN
              CALL POPINTEGER4(ad_to3)
              DO ibc=ad_to3,1,-1
                icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                srwb%sch0(icv, 1) = 0.D0
                posb = posb + pbig*geo%fcs(ifc)*srwb%sch0(icv, 0)
                srwb%sch0(icv, 0) = 0.D0
                CALL POPINTEGER4(icv)
              END DO
            END IF
          END DO
          CALL POPCONTROL2B(branch)
          IF (branch .EQ. 0) THEN
            cur_deltab = prev_cur_deltab
            prev_cur_deltab = 0.D0
          ELSE
            IF (branch .EQ. 1) THEN
              posb = posb + po_currb
              po_currb = po_prevb + posb
              po_stepb = posb
              cur_deltab = prev_cur_deltab + coeff_16*po_stepb
              coeff_16b = coeff_16b + cur_delta*po_stepb
              CALL POPCONTROL1B(branch)
              IF (branch .EQ. 0) THEN
                tempb0 = coeff_16b/(cur_delta-prev_cur_delta)
                po_prevb = tempb0
                po_currb = po_currb - tempb0
                tempb = -((po_prev-po_curr)*tempb0/(cur_delta-&
&                 prev_cur_delta))
                cur_deltab = cur_deltab + tempb
                prev_cur_deltab = -tempb
                coeff_16b = 0.D0
              ELSE
                prev_cur_deltab = 0.D0
                po_prevb = 0.D0
              END IF
              posb = 0.D0
            ELSE
              cur_deltab = 0.D0
            END IF
            CALL POPCONTROL1B(branch)
            IF (branch .EQ. 0) THEN
              po_currb = po_currb/vs
              DO ibw=nbc,ib,-1
                CALL POPCONTROL1B(branch)
                IF (branch .NE. 0) THEN
                  CALL POPINTEGER4(ad_to2)
                  DO ibc=ad_to2,1,-1
                    plb%po(icv) = plb%po(icv) + geo%cvvol(icv)*po_currb
                    CALL POPINTEGER4(ifc)
                    CALL POPINTEGER4(icv)
                  END DO
                END IF
              END DO
              CALL POPREAL8(vs, r8/8)
              po_currb = 0.D0
            END IF
          END IF
          totfluxb = cur_deltab
          scurparb = scurparb - cur_deltab
          DO ibw=nbc,ib,-1
            CALL POPCONTROL1B(branch)
            IF (branch .NE. 0) THEN
              CALL POPINTEGER4(ad_to1)
              DO ibc=ad_to1,1,-1
                tempb1 = -(mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*totfluxb)
                dvb%fch(ifc, 0) = dvb%fch(ifc, 0) + tempb1
                dvb%fch(ifc, 1) = dvb%fch(ifc, 1) + tempb1
                CALL POPINTEGER4(ifc)
              END DO
            END IF
          END DO
        END IF
 100    CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          posb = posb + po_prevb
          posb = posb/vs
          DO ibw=nbc,ib,-1
            CALL POPCONTROL1B(branch)
            IF (branch .NE. 0) THEN
              CALL POPINTEGER4(ad_to0)
              DO ibc=ad_to0,1,-1
                icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                plb%po(icv) = plb%po(icv) + geo%cvvol(icv)*posb
              END DO
            END IF
          END DO
          DO ibw=nbc,ib,-1
            CALL POPCONTROL1B(branch)
            IF (branch .NE. 0) potparb(ibw, 1) = potparb(ibw, 1) + &
&               scurparb
          END DO
          scurparb = 0.D0
          prev_cur_deltab = 0.D0
          po_prevb = 0.D0
          coeff_16b = 0.D0
          posb = 0.D0
        END IF
      ELSE
        GOTO 100
      END IF
    CASE (17) 
!     ..compute average potential on boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
      t2 = 0.0_R8
      totflux = 0.0_R8
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the plasma cell
        CALL PUSHINTEGER4(icv2)
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        CALL PUSHINTEGER4(ifc)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        t0 = t0 + geo%fcs(ifc)
        t1 = t2 + geo%fcs(ifc)*pl%po(icv2)
        totflux = totflux - (dv%fch(ifc, 0)+dv%fch(ifc, 1))*mpg%bcfcor(&
&         mpg%bccvp(ib, 1)+ibc-1)
      END DO
      t1 = t1/t0
      totpar = potpar(ib, 1)
      IF (potpar(ib, 2) .GT. 0.0_R8) THEN
        t3 = potpar(ib, 2)
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHCONTROL1B(1)
      END IF
      IF (potpar(ib, 2) .LE. 0.0_R8) THEN
        t3 = switch%b2stbc_bc_ref_te
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHCONTROL1B(1)
      END IF
      IF (totflux .GE. 0.) THEN
        x4 = totflux
        CALL PUSHCONTROL1B(0)
      ELSE
        x4 = -totflux
        CALL PUSHCONTROL1B(1)
      END IF
      IF (totpar .GE. 0.) THEN
        y4 = totpar
        CALL PUSHCONTROL1B(0)
      ELSE
        y4 = -totpar
        CALL PUSHCONTROL1B(1)
      END IF
      IF (x4 .LT. y4) THEN
        IF (y4 .LT. 1.0_R8) THEN
          max5 = 1.0_R8
          CALL PUSHCONTROL2B(0)
        ELSE
          max5 = y4
          CALL PUSHCONTROL2B(1)
        END IF
      ELSE IF (x4 .LT. 1.0_R8) THEN
        max5 = 1.0_R8
        CALL PUSHCONTROL2B(2)
      ELSE
        max5 = x4
        CALL PUSHCONTROL2B(3)
      END IF
!     ..impose potential
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
! number of the domain cell
        CALL PUSHINTEGER4(icv2)
! number of the guard cell face
        CALL PUSHINTEGER4(ifc)
      END DO
      t4b = 0.D0
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        srwb%sch0(icv1, 1) = 0.D0
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        tempb1 = pbig*geo%fcs(ifc)*srwb%sch0(icv1, 0)
        srwb%sch0(icv1, 0) = 0.D0
        plb%po(icv2) = plb%po(icv2) + tempb1
        t4b = t4b + tempb1
        CALL POPINTEGER4(ifc)
        CALL POPINTEGER4(icv2)
      END DO
      temp0 = t3/max5
      tempb1 = t1*t4b
      t1b = (1.0_R8-(totflux-totpar)*temp0)*t4b
      totfluxb = -(temp0*tempb1)
      totparb = temp0*tempb1
      tempb0 = -((totflux-totpar)*tempb1/max5)
      t3b = tempb0
      max5b = -(temp0*tempb0)
      CALL POPCONTROL2B(branch)
      IF (branch .LT. 2) THEN
        IF (branch .EQ. 0) THEN
          y4b = 0.D0
        ELSE
          y4b = max5b
        END IF
        x4b = 0.D0
      ELSE
        IF (branch .EQ. 2) THEN
          x4b = 0.D0
        ELSE
          x4b = max5b
        END IF
        y4b = 0.D0
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        totparb = totparb + y4b
      ELSE
        totparb = totparb - y4b
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        totfluxb = totfluxb + x4b
      ELSE
        totfluxb = totfluxb - x4b
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) t3b = 0.D0
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) potparb(ib, 2) = potparb(ib, 2) + t3b
      potparb(ib, 1) = potparb(ib, 1) + totparb
      t1b = t1b/t0
      DO ibc=mpg%bccvp(ib, 2),1,-1
        tempb1 = -(mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*totfluxb)
        dvb%fch(ifc, 0) = dvb%fch(ifc, 0) + tempb1
        dvb%fch(ifc, 1) = dvb%fch(ifc, 1) + tempb1
        plb%po(icv2) = plb%po(icv2) + geo%fcs(ifc)*t1b
        CALL POPINTEGER4(ifc)
        CALL POPINTEGER4(icv2)
        t1b = 0.D0
      END DO
    CASE (20, 19, 18) 

    CASE (21) 
      IF ((bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'N') .OR. bcchar(ib)&
&         .EQ. 'A') THEN
        poave = 0.0_R8
        neave = 0.0_R8
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          poave = poave + pl%po(icv)*dv%ne(icv)*geo%cvvol(icv)
          neave = neave + dv%ne(icv)*geo%cvvol(icv)
        END DO
        CALL PUSHREAL8(poave, r8/8)
        poave = poave/neave
        IF (potpar(ib, 2) .GT. 0.0_R8) THEN
          t3 = potpar(ib, 2)
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHCONTROL1B(1)
        END IF
        IF (potpar(ib, 2) .LE. 0.0_R8) THEN
          t3 = switch%b2stbc_bc_ref_te
          CALL PUSHCONTROL1B(1)
        ELSE
          CALL PUSHCONTROL1B(0)
        END IF
        poaveb = 0.D0
        t3b = 0.D0
        DO ibc=mpg%bccvp(ib, 2),1,-1
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          srwb%sch0(icv, 1) = 0.D0
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          temp = t3/poave
          tempb0 = vbig*geo%fcs(ifc)*srwb%sch0(icv, 0)
          srwb%sch0(icv, 0) = 0.D0
          potparb(ib, 1) = potparb(ib, 1) + (pl%po(icv)*temp-t3+1.0_R8)*&
&           tempb0
          tempb1 = potpar(ib, 1)*tempb0
          plb%po(icv) = plb%po(icv) + temp*tempb1
          tempb = pl%po(icv)*tempb1/poave
          t3b = t3b + tempb - tempb1
          poaveb = poaveb - temp*tempb
        END DO
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) t3b = 0.D0
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) potparb(ib, 2) = potparb(ib, 2) + t3b
        CALL POPREAL8(poave, r8/8)
        neaveb = -(poave*poaveb/neave**2)
        poaveb = poaveb/neave
        DO ibc=mpg%bccvp(ib, 2),1,-1
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          tempb1 = geo%cvvol(icv)*poaveb
          dvb%ne(icv) = dvb%ne(icv) + geo%cvvol(icv)*neaveb + pl%po(icv)&
&           *tempb1
          plb%po(icv) = plb%po(icv) + dv%ne(icv)*tempb1
        END DO
      END IF
    CASE (22) 
!     ..compute average potential on core boundary
      t0 = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        CALL PUSHINTEGER4(icv1)
        icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
        IF (mpg%cvonclosedsurface(icv1)) THEN
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            t0 = t0 + geo%cvvol(icv2)
          END DO
          CALL PUSHINTEGER4(ibc0 - 1)
          CALL PUSHCONTROL1B(1)
        ELSE
          CALL PUSHCONTROL1B(0)
        END IF
      END DO
!     ..impose potential with perturbation
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        CALL PUSHINTEGER4(icv1)
! number of the domain cell
! number of the guard cell face
      END DO
      t1b = 0.D0
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        srwb%sch0(icv1, 1) = 0.D0
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        tempb1 = pbig*geo%fcs(ifc)*srwb%sch0(icv1, 0)
        srwb%sch0(icv1, 0) = 0.D0
        plb%po(icv2) = plb%po(icv2) + tempb1
        potparb(ib, 1) = potparb(ib, 1) + tempb1
        t1b = t1b - tempb1
        CALL POPINTEGER4(icv1)
      END DO
      t1b = t1b/t0
      DO ib0=nbc,1,-1
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) THEN
          CALL POPINTEGER4(ad_to4)
          DO ibc0=ad_to4,1,-1
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
            plb%po(icv2) = plb%po(icv2) + geo%cvvol(icv2)*t1b
          END DO
        END IF
        CALL POPINTEGER4(icv1)
      END DO
    CASE (23) 
!     ..compute average potential on core boundary
      t0 = 0.0_R8
!lkw
      t4 = 0.0_R8
      totflux = 0.0_R8
      totpar = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        CALL PUSHINTEGER4(icv1)
        icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
        IF (mpg%cvonclosedsurface(icv1)) THEN
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            t0 = t0 + geo%cvvol(icv2)
! lkw 10.09.2022{
            t4 = t4 + geo%cvvol(icv2)*pl%ti(icv2)/qe
            totflux = totflux - (dv%fch(ifc, 0)+dv%fch(ifc, 1))*mpg%&
&             bcfcor(mpg%bccvp(ib0, 1)+ibc0-1)
          END DO
          CALL PUSHINTEGER4(ibc0 - 1)
          totpar = totpar + potpar(ib0, 1)
          CALL PUSHCONTROL1B(1)
        ELSE
          CALL PUSHCONTROL1B(0)
        END IF
      END DO
      t4 = t4/t0
      IF (potpar(ib, 2) .GT. 0.0_R8) THEN
        t3 = potpar(ib, 2)
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHCONTROL1B(1)
        t3 = switch%b2stbc_bc_ref_te
      END IF
      IF (totflux .GE. 0.) THEN
        x5 = totflux
        CALL PUSHCONTROL1B(0)
      ELSE
        x5 = -totflux
        CALL PUSHCONTROL1B(1)
      END IF
      IF (totpar .GE. 0.) THEN
        y5 = totpar
        CALL PUSHCONTROL1B(0)
      ELSE
        y5 = -totpar
        CALL PUSHCONTROL1B(1)
      END IF
      IF (x5 .LT. y5) THEN
        IF (y5 .LT. 1.0e-10_R8) THEN
          max6 = 1.0e-10_R8
          CALL PUSHCONTROL2B(0)
        ELSE
          max6 = y5
          CALL PUSHCONTROL2B(1)
        END IF
      ELSE IF (x5 .LT. 1.0e-10_R8) THEN
        max6 = 1.0e-10_R8
        CALL PUSHCONTROL2B(2)
      ELSE
        max6 = x5
        CALL PUSHCONTROL2B(3)
      END IF
!
!     ..impose potential with perturbation
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        CALL PUSHINTEGER4(icv1)
! number of the domain cell
! number of the guard cell face
      END DO
      t2b = 0.D0
      t4b = 0.D0
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        srwb%sch0(icv1, 1) = 0.D0
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        tempb1 = pbig*geo%fcs(ifc)*srwb%sch0(icv1, 0)
        srwb%sch0(icv1, 0) = 0.D0
        plb%po(icv2) = plb%po(icv2) + tempb1
        t4b = t4b + tempb1
        t2b = t2b - tempb1
        CALL POPINTEGER4(icv1)
      END DO
      temp0 = (totflux-totpar)/max6
      t1b = t4b
      t3b = -(t4*temp0*t4b)
      tempb0 = -(t4*t3*t4b/max6)
      t4b = -(t3*temp0*t4b)
      totfluxb = tempb0
      totparb = -tempb0
      max6b = -(temp0*tempb0)
      CALL POPCONTROL2B(branch)
      IF (branch .LT. 2) THEN
        IF (branch .EQ. 0) THEN
          y5b = 0.D0
        ELSE
          y5b = max6b
        END IF
        x5b = 0.D0
      ELSE
        IF (branch .EQ. 2) THEN
          x5b = 0.D0
        ELSE
          x5b = max6b
        END IF
        y5b = 0.D0
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        totparb = totparb + y5b
      ELSE
        totparb = totparb - y5b
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        totfluxb = totfluxb + x5b
      ELSE
        totfluxb = totfluxb - x5b
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) potparb(ib, 2) = potparb(ib, 2) + t3b
      t4b = t4b/t0
      t2b = t2b/t0
      t1b = t1b/t0
      DO ib0=nbc,1,-1
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) THEN
          potparb(ib0, 1) = potparb(ib0, 1) + totparb
          CALL POPINTEGER4(ad_to5)
          DO ibc0=ad_to5,1,-1
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            tempb1 = -(mpg%bcfcor(mpg%bccvp(ib0, 1)+ibc0-1)*totfluxb)
            dvb%fch(ifc, 0) = dvb%fch(ifc, 0) + tempb1
            dvb%fch(ifc, 1) = dvb%fch(ifc, 1) + tempb1
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
            plb%ti(icv2) = plb%ti(icv2) + geo%cvvol(icv2)*t4b/qe
            plb%po(icv2) = plb%po(icv2) + geo%cvvol(icv2)*t2b
            plb%po(icv1) = plb%po(icv1) + geo%cvvol(icv2)*t1b
          END DO
        END IF
        CALL POPINTEGER4(icv1)
      END DO
    END SELECT
  END SUBROUTINE B2STBC_PHYS_POT_B

!
  SUBROUTINE B2STBC_PHYS_POT(ib)
    IMPLICIT NONE
    INTEGER :: ib, ib0, ibc, ibc0, ibw, is
    INTEGER :: icv, icv1, icv2, ifc, ivx1, ivx2
    REAL(kind=r8) :: cs, vte, vbnd, s1, fche, fchi, t0, t1, t2, t3, t4, &
&   neave, poave, totpar, totflux, wrk, seec, fchy_dia, fchy_inertia
    REAL(kind=r8), EXTERNAL :: INTVERTEX_S_NODIFF
    EXTERNAL XERRAB
    INTRINSIC SQRT
    INTRINSIC ABS
    INTRINSIC SIGN
    INTRINSIC MIN
    INTRINSIC MOD
    REAL(kind=r8) :: x1
    REAL(kind=r8) :: y1
    REAL(kind=r8) :: y2
    REAL(kind=r8) :: x2
    REAL(kind=r8) :: x3
    REAL(kind=r8) :: y3
    REAL(kind=r8) :: x4
    REAL(kind=r8) :: y4
    REAL(kind=r8) :: x5
    REAL(kind=r8) :: y5
    REAL(r8) :: y6
    REAL(kind=r8) :: abs0
    REAL(kind=r8) :: max1
    REAL(kind=r8) :: abs1
    REAL(kind=r8) :: max2
    REAL(kind=r8) :: abs2
    REAL(kind=r8) :: max3
    REAL(kind=r8) :: max4
    REAL(kind=r8) :: abs3
    REAL(kind=r8) :: max5
    REAL(kind=r8) :: max6
    REAL(kind=r8) :: abs4
    REAL(r8) :: min1
    REAL(kind=r8) :: abs5
    REAL(kind=r8) :: result10
    REAL(kind=r8) :: result11
!
! -- BOUNDARY CONDITIONS FOR POTENTIAL EQUATION --
!
    SELECT CASE  (bcpot(ib)) 
    CASE (0) 

    CASE (1) 
!
!
! -- BCPOT=1 -- PRESCRIBE THE VALUE OF THE POTENTIAL
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                   'BCPOT =  1 : specified potential '&
&                                   , potpar(ib, 1), ' on ', bcchar(ib)&
&                                   , boundary_location(ib)
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%sch0(icv1, 0) = pbig*geo%fcs(ifc)*potpar(ib, 1)
        srw%sch0(icv1, 1) = -(pbig*geo%fcs(ifc))
      END DO
    CASE (2) 
!
! -- BCPOT=2 -- PRESCRIBE THE GRADIENT OF THE POTENTIAL
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                   'BCPOT =  2 : potential gradient ', &
&                                   potpar(ib, 1), ' on ', bcchar(ib), &
&                                   boundary_location(ib)
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        ivx1 = mpg%fcvx(ifc, 1)
        ivx2 = mpg%fcvx(ifc, 2)
        t1 = INTVERTEX_S_NODIFF(ivx1, ncv, nvx, mpg, geo%vxvol, pl%po)
        t2 = INTVERTEX_S_NODIFF(ivx2, ncv, nvx, mpg, geo%vxvol, pl%po)
        srw%sch0(icv1, 0) = pbig*geo%fcs(ifc)*(potpar(ib, 1)*(geo%fchc(&
&         ifc, 1)+geo%fchc(ifc, 2))*geo%fcqgam(ifc, 0)-cor9*(t2-t1)*geo%&
&         fcqgam(ifc, 1)*(geo%fchc(ifc, 1)+geo%fchc(ifc, 2))/geo%fcht(&
&         ifc)*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)+pl%po(icv2))
        srw%sch0(icv1, 1) = -(pbig*geo%fcs(ifc))
      END DO
    CASE (3) 
!
! -- BCPOT=3 -- SHEATH CONDITIONS, ELECTRON ENERGY TRANSMISSION
!
      CALL XERRAB('b2stbc_phys -- BCPOT = 3 not adapted for WG.'//&
&           ' Replace with drift-compatible BCPOT = 11')
!
! -- BCPOT=4 -- PRESCRIBE THE VALUE OF THE POTENTIAL,
!                 WEAKLY A MIXED BOUNDARY CONDITION
!
    CASE (4) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') 'BCPOT =  4 : weak potential ', &
&       potpar(ib, 1), ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(potpar(ib, 2) .GT. 0.0_R8, &
&             'BCPOT = 4, POTPAR(,2) !> 0')
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%sch0(icv1, 0) = potpar(ib, 2)*geo%fcs(ifc)*potpar(ib, 1)
        srw%sch0(icv1, 1) = -(potpar(ib, 2)*geo%fcs(ifc))
      END DO
    CASE (5) 
!
! -- BCPOT=5 -- PRESCRIBE THE CURRENT FLUX DENSITY PER UNIT AREA
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                          'BCPOT =  5 : current flux density per area '&
&                                   , potpar(ib, 1), ' on ', bcchar(ib)&
&                                   , boundary_location(ib)
      DO ibc=1,mpg%bccvp(ib, 2)
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        srw%sch0(icv, 0) = potpar(ib, 1)*geo%fcs(ifc)
        srw%sch0(icv, 1) = 0.0_R8
      END DO
    CASE (6) 
!
! -- BCPOT=6 -- PRESCRIBE THE TOTAL CURRENT FLUX DENSITY FOR A
!                 CONSTANT POTENTIAL
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                             'BCPOT =  6 : total current flux density '&
&                                   , potpar(ib, 1), &
&                                   ' with const potential on ', bcchar(&
&                                   ib), boundary_location(ib)
      CALL XERRAB('B2STBC -- BCPOT=6, NOT YET AVAILABLE')
!
! -- BCPOT=7 -- PRESCRIBE THE GIVEN PROFILE OF POTENTIAL
!
    CASE (7) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
!srv 26.02.18 {
        WRITE(*, '(3a)') 'BCPOT = 7 : specified potential on ', bcchar(&
&       ib), boundary_location(ib)
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%sch0(icv1, 0) = pbig*geo%fcs(ifc)*bv_po(icv1)
        srw%sch0(icv1, 1) = -(pbig*geo%fcs(ifc))
      END DO
    CASE (8) 
!
! -- BCPOT=8 -- PRESCRIBE THE TOTAL ELECTRON CURRENT WITH CONSTANT
!                 FLUX DENSITY
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                   'BCPOT =  8 : total current ', &
&                                   potpar(ib, 1), ' on ', bcchar(ib), &
&                                   boundary_location(ib)
      us = 0.0_R8
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        us = us + geo%fcs(ifc)
      END DO
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%sch0(icv1, 0) = potpar(ib, 1)/us*geo%fcs(ifc)
        srw%sch0(icv1, 1) = 0.0_R8
      END DO
    CASE (9) 
!
! -- BCPOT=9 -- PRESCRIBE THE DECAY LENGTH FOR
!                 THE POTENTIAL
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCPOT =  9 : potential decay length ', potpar(ib, 1), ' on ', &
&       bcchar(ib), boundary_location(ib)
        CALL XERTST(potpar(ib, 1) .NE. 0.0_R8, &
&             'BCPOT = 9, POTPAR(,1) = 0')
      END IF
      DO ibc=1,mpg%bccvp(ib, 2)
        icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
        srw%sch0(icv, 0) = 0.0_R8
        srw%sch0(icv, 1) = -(co%sig0(ifc)/potpar(ib, 1)*geo%fcs(ifc)/qe/&
&         dv%ne(icv))
      END DO
    CASE (10) 
!
! -- BCPOT=10 -- Feedback option for core
!                NOT YET TESTED!!!!!!!!!
!
      CALL XERRAB('b2stbc_phys -- BCPOT = 10 not adapted for WG')
!
! -- BCPOT=11 -- SHEATH CONDITION, CURRENT CONTINUITY                !srv 01.02.09 {
!
    CASE (11) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,a,1p,g14.7,a,g14.7,a,a,a)') &
&       'BCPOT = 11 : sheath potential current continuity bc', &
&       ' with POTPAR(IB,2) =', potpar(ib, 2), ' gammae =', gammae, &
&       ' on ', bcchar(ib), boundary_location(ib)
        DO is=0,ns-1
          IF (.NOT.is_neutral(is)) CALL XERTST(bccon(is, ib) .EQ. 14, &
&                                        'When BCPOT=11, '//&
&                          'one must have BCCON=14 for all ion species!'&
&                                       )
        END DO
      END IF
!srv 15.02.26
      conv_bcpot11 = .true.
!srv 15.02.26
      mrs = 0.0_R8
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        ivx1 = mpg%fcvx(ifc, 1)
        ivx2 = mpg%fcvx(ifc, 2)
!srv 15.02.26 {
        DO is=0,ns-1
          CALL CSBC_IS(icv1, ib, is, cs)
          CALL VBC_IS(ib, is, ibc, icv1, icv2, ifc, csbc(icv1, is), wrk)
!srv 15.02.26 }
        END DO
        vte = SQRT(pl%te(icv1)/me)
        t0 = 0.0_R8
        wrk = geo%fcqalf(ifc, 0)*geo%fcbb(ifc, 0)/geo%fcbb(ifc, 3)
        IF (wrk .GE. 0.) THEN
          abs0 = wrk
        ELSE
          abs0 = -wrk
        END IF
        IF (abs0 .LT. geo%qalfmin) THEN
          t1 = INTVERTEX_S_NODIFF(ivx1, ncv, nvx, mpg, geo%vxvol, pl%po)
          t2 = INTVERTEX_S_NODIFF(ivx2, ncv, nvx, mpg, geo%vxvol, pl%po)
          srw%sch0(icv1, 0) = pbig*geo%fcs(ifc)*(-(cor9*(t2-t1)*geo%&
&           fcqgam(ifc, 1)*(geo%fchc(ifc, 1)+geo%fchc(ifc, 2))/geo%fcht(&
&           ifc)*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1))+pl%po(icv2))
          srw%sch0(icv1, 1) = -(pbig*geo%fcs(ifc))
        ELSE
          s1 = geo%fcs(ifc)
          DO is=0,ns-1
            IF (.NOT.is_neutral(is)) THEN
              vbnd = (dv%vaecrb(ifc, 0, is)*geo%fcqalf(ifc, 0)+dv%vaecrb&
&               (ifc, 1, is)*geo%fcqalf(ifc, 1))*mpg%bcfcor(mpg%bccvp(ib&
&               , 1)+ibc-1)
              IF (wrk .GE. 0.) THEN
                abs4 = wrk
              ELSE
                abs4 = -wrk
              END IF
              x1 = csbc(icv1, is)*abs4
              y1 = vbc(icv1, is)*SIGN(1.0_R8, wrk) + vbnd
              IF (x1 .LT. y1) THEN
                max1 = y1
              ELSE
                max1 = x1
              END IF
              t0 = t0 + rt%rza(icv1, is)*mompar(is, ib, 1)*s1*max1*pl%na&
&               (icv1, is)
            END IF
          END DO
          fchi = qe*t0
          IF (wrk .GE. 0.) THEN
            abs1 = wrk
          ELSE
            abs1 = -wrk
          END IF
          IF (-50.0_R8 .LT. -(qe*(pl%po(icv1)-potpar(ib, 2))/pl%te(icv1)&
&             )) THEN
            y6 = -(qe*(pl%po(icv1)-potpar(ib, 2))/pl%te(icv1))
          ELSE
            y6 = -50.0_R8
          END IF
          IF (0.0_R8 .GT. y6) THEN
            min1 = y6
          ELSE
            min1 = 0.0_R8
          END IF
!lkw 31.03.2023
          result10 = EXPU2(min1)
          fche = SQRT(1/(2*pi))*qe*dv%ne(icv1)*vte*s1*abs1*result10
          seec = gammae
          IF (fchi .LT. (1.0_R8-seec)*fche) THEN
            max2 = (1.0_R8-seec)*fche
          ELSE
            max2 = fchi
          END IF
          t0 = max2*qe/pl%te(icv1)
!    ..compute charge source
          srw%sch0(icv1, 0) = (1.0_R8-seec)*fche - fchi + t0*pl%po(icv1)
          srw%sch0(icv1, 1) = -t0
!    ..compute the maximum difference between the left and right sides of the boundary condition
!srv 15.02.26 {
          fch_sch = srw%sch0(icv1, 0) + srw%sch0(icv1, 1)*pl%po(icv1)
          fch_bnd = dv%fch(ifc, 0) + dv%fch(ifc, 1)
          IF (mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1) .GT. 0.0_R8) fch_bnd = &
&             -fch_bnd
          res_bcpot11 = fch_sch - fch_bnd
          IF (res_bcpot11 .GE. 0.) THEN
            abs2 = res_bcpot11
          ELSE
            abs2 = -res_bcpot11
          END IF
          IF (fch_bnd .GE. 0.) THEN
            abs5 = fch_bnd
          ELSE
            abs5 = -fch_bnd
          END IF
          IF (abs2 .GE. abs5*switch%bcpot11_epsr + switch%bcpot11_epsa) &
&           conv_bcpot11 = .false.
          IF (res_bcpot11 .GE. 0.) THEN
            y2 = res_bcpot11
          ELSE
            y2 = -res_bcpot11
          END IF
          IF (mrs .LT. y2) THEN
            mrs = y2
          ELSE
            mrs = mrs
          END IF
        END IF
!wdk Todo: seecmodel
        wrong_flow = .false.
      END DO
    CASE (12) 
!
! -- BCPOT=12 -- Test condition for south core region ! Solovyev 07.04.14   !srv 03.03.15 {
! code here is a part of code from 50000 for istyle_cur_contr_on_S_and_N.eq.1
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,a,a,a,a)') 'BCPOT = 12 : Adding contributions ', &
&       'from diamagnetic and inertial currents ', 'on ', bcchar(ib), &
&       boundary_location(ib)
        IF (switch%istyle_cur_contr_on_s_and_n .EQ. 0 .OR. switch%&
&           istyle_cur_contr_on_s_and_n .EQ. 1) THEN
          WRITE(*, *) ' BCPOT=12 cannot be used when ', &
&         'istyle_cur_contr_on_S_and_N = 0 or 1'
          CALL XERRAB('faulty parameter istyle_cur_contr_on_S_and_N !')
        ELSE
          DO ibc=1,mpg%bccvp(ib, 2)
            icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
            CALL XERTST(mpg%cvonclosedsurface(icv1), &
&                 'BCPOT=12 intended for core boundaries only!')
          END DO
        END IF
      END IF
      result11 = MAXVAL(dv%facdrift)
      IF (result11 .NE. 0.0_R8) THEN
!       ..compute the source
        IF (bcpot_12_style .EQ. -1) THEN
!wdk with <fcBb(:,2)>
! loop over number of cells in the boundary
          DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            fchy_dia = -(mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*switch%&
&             b2stbc_phm0*pzaverage*dv%facdrift(ifc)*bzaverage*gonedbsq(&
&             ifc, 0)*geo%fcs(ifc)*geo%fcqalf(ifc, 1))
            srw%sch0(icv1, 0) = srw%sch0(icv1, 0) - fchy_dia
            fchy_inertia = 0.0_R8
            DO is=0,ns-1
              IF (.NOT.is_neutral(is)) fchy_inertia = fchy_inertia - mpg&
&                 %bcfcor(mpg%bccvp(ib, 1)+ibc-1)*switch%b2stbc_phm1*&
&                 0.5_R8*am(is)*mp*naua2average(is)*dv%facdrift(ifc)*&
&                 bzaverage*gonedbsq(ifc, 0)*geo%fcs(ifc)*geo%fcqalf(ifc&
&                 , 1)
            END DO
            srw%sch0(icv1, 0) = srw%sch0(icv1, 0) - fchy_inertia
          END DO
        ELSE IF (bcpot_12_style .EQ. 0) THEN
! loop over number of cells in the boundary
          DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
!wdk now uses fcBb(iFc,2) instead of <fcBb(:,2)>
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            fchy_dia = -(mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*switch%&
&             b2stbc_phm0*pzaverage*dv%facdrift(ifc)*geo%fcbb(ifc, 2)*&
&             gonedbsq(ifc, 0)*geo%fcs(ifc)*geo%fcqalf(ifc, 1))
            srw%sch0(icv1, 0) = srw%sch0(icv1, 0) - fchy_dia
            fchy_inertia = 0.0_R8
            DO is=0,ns-1
              IF (.NOT.is_neutral(is)) fchy_inertia = fchy_inertia - mpg&
&                 %bcfcor(mpg%bccvp(ib, 1)+ibc-1)*switch%b2stbc_phm1*&
&                 0.5_R8*am(is)*mp*naua2average(is)*dv%facdrift(ifc)*geo&
&                 %fcbb(ifc, 2)*gonedbsq(ifc, 0)*geo%fcs(ifc)*geo%fcqalf&
&                 (ifc, 1)
            END DO
            srw%sch0(icv1, 0) = srw%sch0(icv1, 0) - fchy_inertia
          END DO
        ELSE IF (bcpot_12_style .EQ. 1) THEN
!wdk experimental - use fchdia / fchinert as computed
! loop over number of cells in the boundary
          DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
!wdk now uses fcBb(iFc,2) instead of <fcBb(:,2)>
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            fchy_dia = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%fchdia(ifc&
&             , 0)+dv%fchdia(ifc, 1))
            srw%sch0(icv1, 0) = srw%sch0(icv1, 0) - fchy_dia
            fchy_inertia = mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%&
&             fchinert(ifc, 0)+dv%fchinert(ifc, 1))
            srw%sch0(icv1, 0) = srw%sch0(icv1, 0) - fchy_inertia
          END DO
        ELSE IF (bcpot_12_style .EQ. 2) THEN
!wdk experimental - find constant potential (with
!    perturbation taken from flux tube just inside
!    domain) such that total current through core
!    is sum of dia + inert currents
!     ..compute average potential on core boundary
          t0 = 0.0_R8
          t1 = 0.0_R8
          t2 = 0.0_R8
          totflux = 0.0_R8
          totpar = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
          DO ib0=1,nbc
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
            IF (mpg%cvonclosedsurface(icv1)) THEN
              IF (bcpot(ib0) .NE. 12) CALL XERRAB(&
&                                      'BCPOT=12: incompatible core BCs'&
&                                          )
! loop over number of cells in the boundary
              DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
                icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
                icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
                ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
                t0 = t0 + geo%cvvol(icv2)
                t1 = t1 + geo%cvvol(icv2)*pl%po(icv1)
                t2 = t2 + geo%cvvol(icv2)*pl%po(icv2)
                totflux = totflux - mpg%bcfcor(mpg%bccvp(ib0, 1)+ibc0-1)&
&                 *(dv%fch(ifc, 0)+dv%fch(ifc, 1))
                totpar = totpar - mpg%bcfcor(mpg%bccvp(ib0, 1)+ibc0-1)*(&
&                 dv%fchdia(ifc, 0)+dv%fchdia(ifc, 1)+dv%fchinert(ifc, 0&
&                 )+dv%fchinert(ifc, 1))
              END DO
            END IF
          END DO
          t1 = t1/t0
          t2 = t2/t0
          IF (potpar(ib, 2) .GT. 0.0_R8) t3 = potpar(ib, 2)
          IF (potpar(ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref_te
          IF (totflux .GE. 0.) THEN
            x2 = totflux
          ELSE
            x2 = -totflux
          END IF
          IF (x2 .LT. totpar) THEN
            IF (totpar .LT. 1.0e-10_R8) THEN
              max3 = 1.0e-10_R8
            ELSE
              max3 = totpar
            END IF
          ELSE IF (x2 .LT. 1.0e-10_R8) THEN
            max3 = 1.0e-10_R8
          ELSE
            max3 = x2
          END IF
          t4 = (1.0_R8-t3*(totflux-totpar)/max3)*t1
!       ..impose potential with perturbation
! loop over number of cells in the boundary
          DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            srw%sch0(icv1, 0) = pbig*geo%fcs(ifc)*(pl%po(icv2)+t4-t2)
            srw%sch0(icv1, 1) = -(pbig*geo%fcs(ifc))
          END DO
        ELSE
          CALL XERRAB('wrong value bcpot_12_style')
        END IF
      END IF
    CASE (13) 
!
! -- BCPOT=13 -- Test condition for south private & north regions ! Solovyev 07.04.14
! code here is a part of code from 50000 for istyle_cur_contr_on_S_and_N.eq.1
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,a,a,a,a)') 'Adding contributions ', &
&       'from all currents ', 'on ', bcchar(ib), boundary_location(ib)
        IF (switch%istyle_cur_contr_on_s_and_n .EQ. 0 .OR. switch%&
&           istyle_cur_contr_on_s_and_n .EQ. 1) THEN
          WRITE(*, *) ' BCPOT=13 cannot be used when ', &
&         'istyle_cur_contr_on_S_and_N = 0 or 1'
          CALL XERRAB('faulty parameter istyle_cur_contr_on_S_and_N !')
        ELSE
          DO ibc=1,mpg%bccvp(ib, 2)
            icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
            CALL XERTST(.NOT.mpg%cvonclosedsurface(icv1), &
&                 'BCPOT=13 not intended for core boundaries!')
          END DO
        END IF
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%sch0(icv1, 0) = srw%sch0(icv1, 0) - mpg%bcfcor(mpg%bccvp(ib&
&         , 1)+ibc-1)*(dv%fchdia(ifc, 0)+dv%fchdia(ifc, 1)+dv%fchin(ifc&
&         , 0)+dv%fchin(ifc, 1)+dv%fchvispar(ifc, 0)+dv%fchvispar(ifc, 1&
&         )+dv%fchvisq(ifc, 0)+dv%fchvisq(ifc, 1)+dv%fchviskt(ifc, 0)+dv&
&         %fchviskt(ifc, 1)+dv%fchvisper(ifc, 0)+dv%fchvisper(ifc, 1)+dv&
&         %fchinert(ifc, 0)+dv%fchinert(ifc, 1))
!srv 03.03.15 }
      END DO
    CASE (14) 
!
! -- BCPOT=14 -- PRESCRIBE THE TOTAL CURRENT WITHOUT IMPOSING A
!                 SPECIFIC PROFILE. FOLLOW PROFILE OF 1st RING INSIDE.
!wdk    Intended use: core boundary, total PF boundary,...
!wdk    For testing purposes, use with care!
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                'BCPOT = 14 : specified total current '&
&                                   , potpar(ib, 1), ' on ', bcchar(ib)&
&                                   , boundary_location(ib)
      us = 0.0_R8
      t0 = 0.0_R8
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        us = us + geo%fcs(ifc)
        t0 = t0 + mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%fch(ifc, 0)+dv%&
&         fch(ifc, 1))
      END DO
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%sch0(icv1, 0) = -(mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(dv%fch&
&         (ifc, 0)+dv%fch(ifc, 1))) + (t0-potpar(ib, 1))/us*geo%fcs(ifc)
        srw%sch0(icv1, 1) = 0.0_R8
      END DO
    CASE (15) 
!
! -- BCPOT=15 -- Feedback boundary condition on total current with constant potential
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                          'BCPOT = 15 : zero net anomalous current on '&
&                                   , bcchar(ib), boundary_location(ib)
!     ..compute average potential on boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
      totflux = 0.0_R8
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        t0 = t0 + geo%fcs(ifc)
        t1 = t1 + geo%fcs(ifc)*pl%po(icv1)
        totflux = totflux - (dv%fch(ifc, 0)+dv%fch(ifc, 1))*mpg%bcfcor(&
&         mpg%bccvp(ib, 1)+ibc-1)
      END DO
      t1 = t1/t0
      totpar = potpar(ib, 1)
      IF (potpar(ib, 2) .GT. 0.0_R8) t3 = potpar(ib, 2)
      IF (potpar(ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref_te
      IF (totflux .GE. 0.) THEN
        x3 = totflux
      ELSE
        x3 = -totflux
      END IF
      IF (totpar .GE. 0.) THEN
        y3 = totpar
      ELSE
        y3 = -totpar
      END IF
      IF (x3 .LT. y3) THEN
        IF (y3 .LT. 1.0_R8) THEN
          max4 = 1.0_R8
        ELSE
          max4 = y3
        END IF
      ELSE IF (x3 .LT. 1.0_R8) THEN
        max4 = 1.0_R8
      ELSE
        max4 = x3
      END IF
      t2 = (1.0_R8-t3*(totflux-totpar)/max4)*t1
      IF (switch%b2stbc_diagno .GE. 2) WRITE(*, '(a,1p,4(1x,e15.6))') &
&               'bcpot=15: curr_flux, desired_flux, old/new potential, '&
&                                      , totflux, totpar, t1, t2
!     ..impose potential
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%sch0(icv1, 0) = pbig*geo%fcs(ifc)*t2
        srw%sch0(icv1, 1) = -(pbig*geo%fcs(ifc))
      END DO
    CASE (16) 
!
! -- BCPOT=16 -- Feedback boundary condition with constant potential    !Solovyev 22.03.14 !srv 29.09.15
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,a,a)') &
&       'BCPOT = 16 : electric potential feedback by current on ', &
&       bcchar(ib), boundary_location(ib)
! add smth about #ifdef ASTRA here
! Init variables for BCPOT=16                                  { Solovyev 01.05.14
! square of delta between desired and calculated current
        cur_delta = 0.0_R8
! previous value of upper value
        prev_cur_delta = 0.0_R8
! step of approximation (set after 1st iteration)
        po_step = 0.0_R8
        coeff_16 = 1.0_R8
!************************************************************* } Solovyev 01.05.14
        scurpar = 0.0_R8
        DO ibw=ib,nbc
          IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&             bcpot(ibw) .EQ. bcpot(ib)) scurpar = scurpar + potpar(ibw&
&             , 1)
        END DO
        WRITE(*, *) 'SCURPAR = ', scurpar
!srv 29.09.15
        pos = 0.0_R8
        vs = 0.0_R8
        DO ibw=ib,nbc
          IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&             bcpot(ibw) .EQ. bcpot(ib)) THEN
            DO ibc=1,mpg%bccvp(ibw, 2)
              icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
              pos = pos + pl%po(icv)*geo%cvvol(icv)
              vs = vs + geo%cvvol(icv)
            END DO
          END IF
        END DO
!srv 29.09.15 }
        pos = pos/vs
        po_prev = pos
        WRITE(*, *) 'POS at 0 = ', pos
      END IF
!srv 29.09.15 }
      IF (.NOT.once_bcpot) THEN
        IF (bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'A') THEN
          totflux = 0.0_R8
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bcpot(ibw) .EQ. bcpot(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                totflux = totflux - mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*(&
&                 dv%fch(ifc, 0)+dv%fch(ifc, 1))
              END DO
            END IF
          END DO
! The implementation is based on one step of Newton method
! { Solovyev 03.05.14
          cur_delta = totflux - scurpar
! } Solovyev 03.05.14
          IF (ncall_b2stbc_phys .EQ. 0) THEN
            WRITE(*, *) '# Newton'
! previous value of upper value
            prev_cur_delta = cur_delta
          ELSE
!Solovyev 23.05.14
            IF (ncall_b2stbc_phys .EQ. 1) THEN
! Solovyev 23.05.14
!srv 29.09.15
              po_curr = 0.0_R8
              vs = 0.0_R8
              DO ibw=ib,nbc
                IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') &
&                   .AND. bcene(ibw) .EQ. bcene(ib)) THEN
                  DO ibc=1,mpg%bccvp(ibw, 2)
                    icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
                    ifc = mpg%cvfc(mpg%cvfcp(icv, 1))
                    po_curr = po_curr + pl%po(icv)*geo%cvvol(icv)
                    vs = vs + geo%cvvol(icv)
                  END DO
                END IF
              END DO
!srv 29.09.15 }
              po_curr = po_curr/vs
            END IF
! Solovyev 23.05.14
            IF (MOD(ncall_b2stbc_phys, bcpot_16_step) .EQ. 0) THEN
              IF (cur_delta - prev_cur_delta .GE. 0.) THEN
                abs3 = cur_delta - prev_cur_delta
              ELSE
                abs3 = -(cur_delta-prev_cur_delta)
              END IF
!Solovyev 23.05.14
              IF (abs3 .GT. 1.0e-20_R8) THEN
!{ Solovyev 24.05.14
                coeff_16 = (po_prev-po_curr)/(cur_delta-prev_cur_delta)
              END IF
!} Solovyev 24.05.14
              po_step = coeff_16*cur_delta
              pos = po_curr + po_step
              prev_cur_delta = cur_delta
              po_prev = po_curr
              po_curr = pos
            END IF
          END IF
! end of implementation
!Solovyev 29.04.14 - test output to b2fdebug
          WRITE(*, *) 'ncall, totflux, POS', ncall_b2stbc_phys, totflux&
&         , pos
          DO ibw=ib,nbc
            IF ((bcchar(ibw) .EQ. 'S' .OR. bcchar(ibw) .EQ. 'A') .AND. &
&               bcpot(ibw) .EQ. bcpot(ib)) THEN
              DO ibc=1,mpg%bccvp(ibw, 2)
                icv = mpg%bccv(mpg%bccvp(ibw, 1)+ibc-1, 1)
!Solovyev 27.04.14
                srw%sch0(icv, 0) = pbig*pos*geo%fcs(ifc)
!Solovyev 27.04.14
                srw%sch0(icv, 1) = -(pbig*geo%fcs(ifc))
              END DO
            END IF
          END DO
          once_bcpot = .true.
        ELSE
          CALL XERRAB('B2STBC -- BCPOT=16, NOT AVAILABLE FOR N,W,E')
        END IF
      END IF
    CASE (17) 
!
! -- BCPOT=17 -- Feedback boundary condition on total current, imposing potential,
!                with same profile as neighbouring flux tube
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                   'BCPOT = 17 : imposed current on ', &
&                                   bcchar(ib), boundary_location(ib)
!     ..compute average potential on boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
      t2 = 0.0_R8
      totflux = 0.0_R8
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the plasma cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        t0 = t0 + geo%fcs(ifc)
        t1 = t1 + geo%fcs(ifc)*pl%po(icv1)
        t1 = t2 + geo%fcs(ifc)*pl%po(icv2)
        totflux = totflux - (dv%fch(ifc, 0)+dv%fch(ifc, 1))*mpg%bcfcor(&
&         mpg%bccvp(ib, 1)+ibc-1)
      END DO
      t1 = t1/t0
      t2 = t2/t0
      totpar = potpar(ib, 1)
      IF (potpar(ib, 2) .GT. 0.0_R8) t3 = potpar(ib, 2)
      IF (potpar(ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref_te
      IF (totflux .GE. 0.) THEN
        x4 = totflux
      ELSE
        x4 = -totflux
      END IF
      IF (totpar .GE. 0.) THEN
        y4 = totpar
      ELSE
        y4 = -totpar
      END IF
      IF (x4 .LT. y4) THEN
        IF (y4 .LT. 1.0_R8) THEN
          max5 = 1.0_R8
        ELSE
          max5 = y4
        END IF
      ELSE IF (x4 .LT. 1.0_R8) THEN
        max5 = 1.0_R8
      ELSE
        max5 = x4
      END IF
      t4 = (1.0_R8-t3*(totflux-totpar)/max5)*t1
      IF (switch%b2stbc_diagno .GE. 2) WRITE(*, '(a,1p,4(1x,e15.6))') &
&               'bcpot=17: curr_flux, desired_flux, old/new potential, '&
&                                      , totflux, totpar, t1, t4
!     ..impose potential
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%sch0(icv1, 0) = pbig*geo%fcs(ifc)*(pl%po(icv2)+t4-t2)
        srw%sch0(icv1, 1) = -(pbig*geo%fcs(ifc))
      END DO
    CASE (18) 
!
! -- BCPOT=18 -- Nothing implemented
!
      CALL XERRAB('B2STBC -- BCPOT=18, NOT AVAILABLE FOR S,N,W,E')
!
! -- BCPOT=19 -- Nothing implemented
!
    CASE (19) 
      CALL XERRAB('B2STBC -- BCPOT=19, NOT AVAILABLE FOR S,N,W,E')
!
! -- BCPOT=20 -- Nothing implemented
!
    CASE (20) 
      CALL XERRAB('B2STBC -- BCPOT=20, NOT AVAILABLE FOR S,N,W,E')
!
! -- BCPOT=21 -- constant potential scaled by potential on the ring bc_type21_ref away
!
    CASE (21) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,g14.7,a,a,a)') &
&       'BCPOT = 21 : fixed potential (modified by nearby ring) ', &
&       potpar(ib, 1), ' with ', potpar(ib, 2), ' on ', bcchar(ib), &
&       boundary_location(ib)
        CALL XERTST(potpar(ib, 2) .GT. 0.0_R8, &
&             'faulty parameter potpar2')
      END IF
      IF ((bcchar(ib) .EQ. 'S' .OR. bcchar(ib) .EQ. 'N') .OR. bcchar(ib)&
&         .EQ. 'A') THEN
        poave = 0.0_R8
        neave = 0.0_R8
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          poave = poave + pl%po(icv)*dv%ne(icv)*geo%cvvol(icv)
          neave = neave + dv%ne(icv)*geo%cvvol(icv)
        END DO
        poave = poave/neave
        IF (potpar(ib, 2) .GT. 0.0_R8) t3 = potpar(ib, 2)
        IF (potpar(ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref_te
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%sch0(icv, 0) = vbig*potpar(ib, 1)*geo%fcs(ifc)*(1.0_R8-t3+&
&           t3*pl%po(icv)/poave)
          srw%sch0(icv, 1) = -(vbig*geo%fcs(ifc))
        END DO
      ELSE
        CALL XERRAB('B2STBC -- BCPOT=21, NOT AVAILABLE FOR W,E')
      END IF
    CASE (22) 
!
! -- BCPOT=22 -- Prescribe the value of the potential, with perturbation taken
!                from first flux tube in the domain
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCPOT = 22 : specified potential ', potpar(ib, 1), ' on ', &
&       bcchar(ib), boundary_location(ib)
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          CALL XERTST(mpg%cvonclosedsurface(icv1), &
&               'BCPOT=22 intended for core boundaries only!')
        END DO
      END IF
!     ..compute average potential on core boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
        IF (mpg%cvonclosedsurface(icv1)) THEN
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            t0 = t0 + geo%cvvol(icv2)
            t1 = t1 + geo%cvvol(icv2)*pl%po(icv2)
          END DO
        END IF
      END DO
      t1 = t1/t0
!     ..impose potential with perturbation
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%sch0(icv1, 0) = pbig*geo%fcs(ifc)*(pl%po(icv2)+potpar(ib, 1)&
&         -t1)
        srw%sch0(icv1, 1) = -(pbig*geo%fcs(ifc))
      END DO
    CASE (23) 
!
! -- BCPOT=23 -- Feedback on the total current for the South core boundary, by imposing a flux surface
!                averaged potential, with poloidal perturbation taken from flux
!                tube just inside domain. The feedback is scaled with the ion temperature.
!               POTPAR(,,1) specifies the desired integral current through flux surfaces(A).
!               POTPAR(,,2) is the strength of the feedback
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'BCPOT = 23 : specified potential ', potpar(ib, 1), ' on ', &
&       bcchar(ib), boundary_location(ib)
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          CALL XERTST(mpg%cvonclosedsurface(icv1), &
&               'BCPOT=23 intended for core boundaries only!')
        END DO
      END IF
!     ..compute average potential on core boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
      t2 = 0.0_R8
!lkw
      t4 = 0.0_R8
      totflux = 0.0_R8
      totpar = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv1 = mpg%bccv(mpg%bccvp(ib0, 1), 1)
        IF (mpg%cvonclosedsurface(icv1)) THEN
          IF (bcpot(ib0) .NE. 23) CALL XERRAB(&
&                                      'BCPOT=23: incompatible core BCs'&
&                                      )
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            t0 = t0 + geo%cvvol(icv2)
            t1 = t1 + geo%cvvol(icv2)*pl%po(icv1)
            t2 = t2 + geo%cvvol(icv2)*pl%po(icv2)
! lkw 10.09.2022{
            t4 = t4 + geo%cvvol(icv2)*pl%ti(icv2)/qe
            totflux = totflux - (dv%fch(ifc, 0)+dv%fch(ifc, 1))*mpg%&
&             bcfcor(mpg%bccvp(ib0, 1)+ibc0-1)
          END DO
          totpar = totpar + potpar(ib0, 1)
        END IF
      END DO
      t1 = t1/t0
      t2 = t2/t0
      t4 = t4/t0
      IF (potpar(ib, 2) .GT. 0.0_R8) THEN
        t3 = potpar(ib, 2)
      ELSE
        t3 = switch%b2stbc_bc_ref_te
      END IF
      IF (totflux .GE. 0.) THEN
        x5 = totflux
      ELSE
        x5 = -totflux
      END IF
      IF (totpar .GE. 0.) THEN
        y5 = totpar
      ELSE
        y5 = -totpar
      END IF
      IF (x5 .LT. y5) THEN
        IF (y5 .LT. 1.0e-10_R8) THEN
          max6 = 1.0e-10_R8
        ELSE
          max6 = y5
        END IF
      ELSE IF (x5 .LT. 1.0e-10_R8) THEN
        max6 = 1.0e-10_R8
      ELSE
        max6 = x5
      END IF
! lkw 10.09.2022}
      t4 = t1 - t4*t3*(totflux-totpar)/max6
!
!     ..impose potential with perturbation
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%sch0(icv1, 0) = pbig*geo%fcs(ifc)*(pl%po(icv2)+t4-t2)
        srw%sch0(icv1, 1) = -(pbig*geo%fcs(ifc))
      END DO
    CASE DEFAULT
!
      WRITE(*, *) bcpot(ib)
      CALL XERRAB('BCPOT out of bounds')
    END SELECT
!
!
    RETURN
  END SUBROUTINE B2STBC_PHYS_POT

!  Differentiation of b2stbc_phys_enk in reverse (adjoint) mode (with options context noISIZE r8):
!   gradient     of useful results: conpar mompar enkpar *(dv.fna)
!                *(dv.fhe) *(dv.fhi) *(dv.fkt) *(dv.ni) *(srw.skt0)
!                switch.b2tfhi_fflokt *(co.dna0) *(pl.na) *(pl.kt)
!                rz pz
!   with respect to varying inputs: conpar mompar enkpar *(dv.fna)
!                *(dv.fhe) *(dv.fhi) *(dv.fkt) *(dv.ni) *(srw.skt0)
!                switch.b2tfhi_fflokt *(co.dna0) *(pl.na) *(pl.kt)
!                rz pz
!   Plus diff mem management of: dv.fna:in dv.fhe:in dv.fhi:in
!                dv.fkt:in dv.ni:in mpg.bcfcor:in geo.vxvol:in
!                srw.skt0:in co.dna0:in pl.na:in pl.kt:in
!
  SUBROUTINE B2STBC_PHYS_ENK_B(ib)
    IMPLICIT NONE
!
! -- BCENK=17 -- Feedback on turb. kin. energy flux, by imposing a flux surface
!                averaged kt, with poloidal perturbation taken from flux
!                tube just inside domain
!
!
! -- BCENK=7 -- Prescribe the total flux of kt, following the
!               profile of fna
!
    INTEGER :: ib, ibc, ib0, ibc0, is
    INTEGER :: icv, icv1, icv2, ifc, ivx1, ivx2
    REAL(kind=r8) :: cs, t0, t1, t2, t3, t4, totpar, totflux
    REAL(kind=r8) :: csb, t0b, t1b, t2b, t3b, t4b, totparb, totfluxb
    REAL(kind=r8), EXTERNAL :: INTVERTEX_S_NODIFF
    EXTERNAL XERRAB
    INTRINSIC SQRT
    INTRINSIC ABS
    REAL(kind=r8) :: x1
    REAL(kind=r8) :: x1b
    REAL(kind=r8) :: abs0
    REAL(kind=r8) :: max1
    REAL(kind=r8) :: max1b
    REAL(kind=r8) :: tempb
    REAL(kind=r8) :: temp
    REAL(kind=r8) :: tempb0
    REAL(r8) :: tempb1
    REAL(r8) :: tempb2
    REAL(kind=r8) :: temp0
    REAL(kind=r8) :: tempb3
    INTEGER :: ad_to
    INTEGER*4 :: branch
    INTEGER :: ad_to0
    INTEGER :: ad_to1
    INTEGER :: ad_to2
!
! -- BOUNDARY CONDITIONS FOR TURBULENT KINETIC ENERGY EQUATION --
!
    SELECT CASE  (bcenk(ib)) 
    CASE (0) 

    CASE (1) 
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        srwb%skt0(icv1, 1) = 0.D0
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        enkparb(ib, 1) = enkparb(ib, 1) + vbig*ne00*geo%fcs(ifc)*ev*srwb&
&         %skt0(icv1, 0)
        srwb%skt0(icv1, 0) = 0.D0
      END DO
    CASE (2) 
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        srwb%skt0(icv1, 1) = 0.D0
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        tempb = vbig*ne00*geo%fcs(ifc)*srwb%skt0(icv1, 0)
        srwb%skt0(icv1, 0) = 0.D0
        enkparb(ib, 1) = enkparb(ib, 1) + ev*geo%fcqgam(ifc, 0)*(geo%&
&         fchc(ifc, 1)+geo%fchc(ifc, 2))*tempb
        tempb0 = -(mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*cor9*geo%fcqgam(&
&         ifc, 1)*(geo%fchc(ifc, 1)+geo%fchc(ifc, 2))*tempb/geo%fcht(ifc&
&         ))
        plb%kt(icv2) = plb%kt(icv2) + tempb
        t2b = tempb0
        t1b = -tempb0
        ivx2 = mpg%fcvx(ifc, 2)
        CALL INTVERTEX_S_B(ivx2, ncv, nvx, mpg, geo%vxvol, pl%kt, plb%kt&
&                    , t2b)
        ivx1 = mpg%fcvx(ifc, 1)
        CALL INTVERTEX_S_B(ivx1, ncv, nvx, mpg, geo%vxvol, pl%kt, plb%kt&
&                    , t1b)
      END DO
    CASE (5, 4, 3) 

    CASE (6) 
!     ..compute total ion+electron heat flux, and total kt flux
      totflux = 0.0_R8
      totpar = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        CALL PUSHINTEGER4(icv)
        icv = mpg%bccv(mpg%bccvp(ib0, 1), 2)
        IF (mpg%cvonclosedsurface(icv)) THEN
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            totflux = totflux - (dv%fhe(ifc, 0)+dv%fhe(ifc, 1)+dv%fhi(&
&             ifc, 0)+dv%fhi(ifc, 1))*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          END DO
          CALL PUSHINTEGER4(ibc0 - 1)
          totpar = totpar + enkpar(ib0, 1)
          CALL PUSHCONTROL1B(1)
        ELSE
          CALL PUSHCONTROL1B(0)
        END IF
      END DO
      CALL PUSHINTEGER4(ibc)
      totfluxb = 0.D0
      totparb = 0.D0
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        srwb%skt0(icv1, 1) = 0.D0
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        tempb1 = -(mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*srwb%skt0(icv1, 0)&
&         )
        srwb%skt0(icv1, 0) = 0.D0
        tempb2 = totpar*tempb1/totflux
        tempb0 = (dv%fhe(ifc, 0)+dv%fhe(ifc, 1)+dv%fhi(ifc, 0)+dv%fhi(&
&         ifc, 1))*tempb1/totflux
        totparb = totparb + tempb0
        totfluxb = totfluxb - totpar*tempb0/totflux
        dvb%fhe(ifc, 0) = dvb%fhe(ifc, 0) + tempb2
        dvb%fhe(ifc, 1) = dvb%fhe(ifc, 1) + tempb2
        dvb%fhi(ifc, 0) = dvb%fhi(ifc, 0) + tempb2
        dvb%fhi(ifc, 1) = dvb%fhi(ifc, 1) + tempb2
      END DO
      CALL POPINTEGER4(ibc)
      DO ib0=nbc,1,-1
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) THEN
          enkparb(ib0, 1) = enkparb(ib0, 1) + totparb
          CALL POPINTEGER4(ad_to)
          DO ibc0=ad_to,1,-1
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            tempb1 = -(mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*totfluxb)
            dvb%fhe(ifc, 0) = dvb%fhe(ifc, 0) + tempb1
            dvb%fhe(ifc, 1) = dvb%fhe(ifc, 1) + tempb1
            dvb%fhi(ifc, 0) = dvb%fhi(ifc, 0) + tempb1
            dvb%fhi(ifc, 1) = dvb%fhi(ifc, 1) + tempb1
          END DO
        END IF
        CALL POPINTEGER4(icv)
      END DO
    CASE (7) 
!     ..compute total particle flux, and total kt flux
      totflux = 0.0_R8
      totpar = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        CALL PUSHINTEGER4(icv)
        icv = mpg%bccv(mpg%bccvp(ib0, 1), 2)
        IF (mpg%cvonclosedsurface(icv)) THEN
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            totflux = totflux - (dv%fna(ifc, 0, ismain)+dv%fna(ifc, 1, &
&             ismain))*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          END DO
          CALL PUSHINTEGER4(ibc0 - 1)
          totpar = totpar + enkpar(ib0, 1)
          CALL PUSHCONTROL1B(1)
        ELSE
          CALL PUSHCONTROL1B(0)
        END IF
      END DO
      CALL PUSHINTEGER4(ibc)
      totfluxb = 0.D0
      totparb = 0.D0
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        srwb%skt0(icv1, 1) = 0.D0
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        temp = totpar/totflux
        tempb2 = -(mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*srwb%skt0(icv1, 0)&
&         )
        srwb%skt0(icv1, 0) = 0.D0
        dvb%fna(ifc, 0, ismain) = dvb%fna(ifc, 0, ismain) + temp*tempb2
        dvb%fna(ifc, 1, ismain) = dvb%fna(ifc, 1, ismain) + temp*tempb2
        tempb0 = (dv%fna(ifc, 0, ismain)+dv%fna(ifc, 1, ismain))*tempb2/&
&         totflux
        totparb = totparb + tempb0
        totfluxb = totfluxb - temp*tempb0
      END DO
      CALL POPINTEGER4(ibc)
      DO ib0=nbc,1,-1
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) THEN
          enkparb(ib0, 1) = enkparb(ib0, 1) + totparb
          CALL POPINTEGER4(ad_to0)
          DO ibc0=ad_to0,1,-1
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            tempb2 = -(mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*totfluxb)
            dvb%fna(ifc, 0, ismain) = dvb%fna(ifc, 0, ismain) + tempb2
            dvb%fna(ifc, 1, ismain) = dvb%fna(ifc, 1, ismain) + tempb2
          END DO
        END IF
        CALL POPINTEGER4(icv)
      END DO
    CASE (8) 
      us = 0.0_R8
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        us = us + geo%fcs(ifc)
      END DO
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        srwb%skt0(icv1, 1) = 0.D0
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        enkparb(ib, 1) = enkparb(ib, 1) + geo%fcs(ifc)*srwb%skt0(icv1, 0&
&         )/us
        srwb%skt0(icv1, 0) = 0.D0
      END DO
    CASE (13, 12, 11, 10, 9) 

    CASE (14) 
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
! number of the guard cell face
        CALL PUSHREAL8(cs, r8/8)
        cs = SQRT(pz(icv1)/rz(icv1))
      END DO
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        tempb0 = geo%fcs(ifc)*srwb%skt0(icv1, 3)
        srwb%skt0(icv1, 3) = 0.D0
        csb = enkpar(ib, 1)*tempb0
        enkparb(ib, 1) = enkparb(ib, 1) + cs*tempb0
        srwb%skt0(icv1, 0) = 0.D0
        CALL POPREAL8(cs, r8/8)
        temp = pz(icv1)/rz(icv1)
        IF (temp .EQ. 0.D0) THEN
          tempb0 = 0.D0
        ELSE
          tempb0 = csb/(rz(icv1)*2.0*SQRT(temp))
        END IF
        pzb(icv1) = pzb(icv1) + tempb0
        rzb(icv1) = rzb(icv1) - temp*tempb0
      END DO
    CASE (15) 
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        CALL PUSHREAL8(cs, r8/8)
        cs = SQRT(pz(icv1)/rz(icv1))
        CALL PUSHREAL8(t0, r8/8)
        t0 = 0.0_R8
        CALL PUSHREAL8(t1, r8/8)
        t1 = 0.0_R8
        DO is=0,ns-1
          IF (.NOT.is_neutral(is)) THEN
            t0 = t0 + mompar(is, ib, 1)*pl%na(icv1, is)
            IF (conpar(is, ib, 2) .GT. 0.0_R8) THEN
              t1 = t1 + co%dna0(icv1, is)/conpar(is, ib, 2)*pl%na(icv1, &
&               is)
              CALL PUSHCONTROL2B(2)
            ELSE
              CALL PUSHCONTROL2B(1)
            END IF
          ELSE
            CALL PUSHCONTROL2B(0)
          END IF
        END DO
        IF (geo%fcpbs(ifc) .GE. 0.) THEN
          CALL PUSHREAL8(abs0, r8/8)
          abs0 = geo%fcpbs(ifc)
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHREAL8(abs0, r8/8)
          abs0 = -geo%fcpbs(ifc)
          CALL PUSHCONTROL1B(1)
        END IF
      END DO
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        tempb0 = -(t0*cs*abs0*srwb%skt0(icv1, 1))
        tempb = -(enkpar(ib, 1)*(switch%b2tfhi_fflokt+1.0_R8)*abs0*srwb%&
&         skt0(icv1, 1))
        tempb3 = -(geo%fcs(ifc)*srwb%skt0(icv1, 1))
        enkparb(ib, 2) = enkparb(ib, 2) + t1*tempb3
        t1b = enkpar(ib, 2)*tempb3
        t0b = cs*tempb
        csb = t0*tempb
        enkparb(ib, 1) = enkparb(ib, 1) + (switch%b2tfhi_fflokt+1.0_R8)*&
&         tempb0
        switchb%b2tfhi_fflokt = switchb%b2tfhi_fflokt + enkpar(ib, 1)*&
&         tempb0
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          CALL POPREAL8(abs0, r8/8)
        ELSE
          CALL POPREAL8(abs0, r8/8)
        END IF
        DO is=ns-1,0,-1
          CALL POPCONTROL2B(branch)
          IF (branch .NE. 0) THEN
            IF (branch .NE. 1) THEN
              tempb2 = t1b/conpar(is, ib, 2)
              cob%dna0(icv1, is) = cob%dna0(icv1, is) + pl%na(icv1, is)*&
&               tempb2
              plb%na(icv1, is) = plb%na(icv1, is) + co%dna0(icv1, is)*&
&               tempb2
              conparb(is, ib, 2) = conparb(is, ib, 2) - co%dna0(icv1, is&
&               )*pl%na(icv1, is)*tempb2/conpar(is, ib, 2)
            END IF
            momparb(is, ib, 1) = momparb(is, ib, 1) + pl%na(icv1, is)*&
&             t0b
            plb%na(icv1, is) = plb%na(icv1, is) + mompar(is, ib, 1)*t0b
          END IF
        END DO
        CALL POPREAL8(t1, r8/8)
        CALL POPREAL8(t0, r8/8)
        CALL POPREAL8(cs, r8/8)
        temp = pz(icv1)/rz(icv1)
        IF (temp .EQ. 0.D0) THEN
          tempb0 = 0.D0
        ELSE
          tempb0 = csb/(rz(icv1)*2.0*SQRT(temp))
        END IF
        pzb(icv1) = pzb(icv1) + tempb0
        rzb(icv1) = rzb(icv1) - temp*tempb0
      END DO
    CASE (16) 
!     ..compute average kt on core boundary
      t0 = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        CALL PUSHINTEGER4(icv)
        icv = mpg%bccv(mpg%bccvp(ib0, 1), 2)
        IF (mpg%cvonclosedsurface(icv)) THEN
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            t0 = t0 + geo%cvvol(icv2)
          END DO
          CALL PUSHINTEGER4(ibc0 - 1)
          CALL PUSHCONTROL1B(1)
        ELSE
          CALL PUSHCONTROL1B(0)
        END IF
      END DO
      t1b = 0.D0
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        srwb%skt0(icv1, 1) = 0.D0
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        tempb2 = vbig*ne00*geo%fcs(ifc)*srwb%skt0(icv1, 0)
        srwb%skt0(icv1, 0) = 0.D0
        plb%kt(icv2) = plb%kt(icv2) + tempb2
        enkparb(ib, 1) = enkparb(ib, 1) + ev*tempb2
        t1b = t1b - tempb2
      END DO
      t1b = t1b/t0
      DO ib0=nbc,1,-1
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) THEN
          CALL POPINTEGER4(ad_to1)
          DO ibc0=ad_to1,1,-1
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
            plb%kt(icv2) = plb%kt(icv2) + geo%cvvol(icv2)*t1b
          END DO
        END IF
        CALL POPINTEGER4(icv)
      END DO
    CASE (17) 
!     ..compute average kt on core boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
      t2 = 0.0_R8
      totflux = 0.0_R8
      totpar = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        CALL PUSHINTEGER4(icv)
        icv = mpg%bccv(mpg%bccvp(ib0, 1), 2)
        IF (mpg%cvonclosedsurface(icv)) THEN
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            t0 = t0 + geo%cvvol(icv2)*dv%ni(icv1, 0)
            t1 = t1 + geo%cvvol(icv2)*dv%ni(icv1, 0)*pl%kt(icv1)
            t2 = t2 + geo%cvvol(icv2)*dv%ni(icv2, 0)*pl%kt(icv2)
            totflux = totflux - (dv%fkt(ifc, 0)+dv%fkt(ifc, 1))*mpg%&
&             bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          END DO
          CALL PUSHINTEGER4(ibc0 - 1)
          totpar = totpar + enkpar(ib0, 1)
          CALL PUSHCONTROL1B(1)
        ELSE
          CALL PUSHCONTROL1B(0)
        END IF
      END DO
      CALL PUSHREAL8(t1, r8/8)
      t1 = t1/t0
      IF (enkpar(ib, 2) .GT. 0.0_R8) THEN
        t3 = enkpar(ib, 2)
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHCONTROL1B(1)
      END IF
      IF (enkpar(ib, 2) .LE. 0.0_R8) THEN
        t3 = switch%b2stbc_bc_ref_ti
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHCONTROL1B(1)
      END IF
      IF (totflux .GE. 0.) THEN
        x1 = totflux
        CALL PUSHCONTROL1B(0)
      ELSE
        x1 = -totflux
        CALL PUSHCONTROL1B(1)
      END IF
      IF (x1 .LT. totpar) THEN
        max1 = totpar
        CALL PUSHCONTROL1B(0)
      ELSE
        max1 = x1
        CALL PUSHCONTROL1B(1)
      END IF
      IF (bcenk_17_style .EQ. 0) THEN
        CALL PUSHINTEGER4(ibc)
        t2b = 0.D0
        t4b = 0.D0
        DO ibc=mpg%bccvp(ib, 2),1,-1
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          srwb%skt0(icv1, 1) = 0.D0
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          tempb2 = vbig*ne00*geo%fcs(ifc)*srwb%skt0(icv1, 0)
          srwb%skt0(icv1, 0) = 0.D0
          plb%kt(icv2) = plb%kt(icv2) + tempb2
          t4b = t4b + tempb2
          t2b = t2b - tempb2
        END DO
        CALL POPINTEGER4(ibc)
      ELSE
        CALL PUSHINTEGER4(ibc)
        t4b = 0.D0
        DO ibc=mpg%bccvp(ib, 2),1,-1
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
          srwb%skt0(icv1, 1) = 0.D0
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          t4b = t4b + geo%fcs(ifc)*vbig*ne00*srwb%skt0(icv1, 0)
          srwb%skt0(icv1, 0) = 0.D0
        END DO
        CALL POPINTEGER4(ibc)
        t2b = 0.D0
      END IF
      temp0 = t3/max1
      tempb2 = t1*t4b
      t1b = (1.0_R8-(totflux-totpar)*temp0)*t4b
      totfluxb = -(temp0*tempb2)
      totparb = temp0*tempb2
      tempb3 = -((totflux-totpar)*tempb2/max1)
      t3b = tempb3
      max1b = -(temp0*tempb3)
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        totparb = totparb + max1b
        x1b = 0.D0
      ELSE
        x1b = max1b
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        totfluxb = totfluxb + x1b
      ELSE
        totfluxb = totfluxb - x1b
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) t3b = 0.D0
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) enkparb(ib, 2) = enkparb(ib, 2) + t3b
      CALL POPREAL8(t1, r8/8)
      t0b = -(t2*t2b/t0**2) - t1*t1b/t0**2
      t2b = t2b/t0
      t1b = t1b/t0
      DO ib0=nbc,1,-1
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) THEN
          enkparb(ib0, 1) = enkparb(ib0, 1) + totparb
          CALL POPINTEGER4(ad_to2)
          DO ibc0=ad_to2,1,-1
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            tempb2 = -(mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*totfluxb)
            dvb%fkt(ifc, 0) = dvb%fkt(ifc, 0) + tempb2
            dvb%fkt(ifc, 1) = dvb%fkt(ifc, 1) + tempb2
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
            tempb2 = geo%cvvol(icv2)*t2b
            dvb%ni(icv2, 0) = dvb%ni(icv2, 0) + pl%kt(icv2)*tempb2
            plb%kt(icv2) = plb%kt(icv2) + dv%ni(icv2, 0)*tempb2
            tempb2 = geo%cvvol(icv2)*t1b
            dvb%ni(icv1, 0) = dvb%ni(icv1, 0) + pl%kt(icv1)*tempb2 + geo&
&             %cvvol(icv2)*t0b
            plb%kt(icv1) = plb%kt(icv1) + dv%ni(icv1, 0)*tempb2
          END DO
        END IF
        CALL POPINTEGER4(icv)
      END DO
    END SELECT
  END SUBROUTINE B2STBC_PHYS_ENK_B

!
  SUBROUTINE B2STBC_PHYS_ENK(ib)
    IMPLICIT NONE
    INTEGER :: ib, ibc, ib0, ibc0, is
    INTEGER :: icv, icv1, icv2, ifc, ivx1, ivx2
    REAL(kind=r8) :: cs, t0, t1, t2, t3, t4, totpar, totflux
    REAL(kind=r8), EXTERNAL :: INTVERTEX_S_NODIFF
    EXTERNAL XERRAB
    INTRINSIC SQRT
    INTRINSIC ABS
    REAL(kind=r8) :: x1
    REAL(kind=r8) :: abs0
    REAL(kind=r8) :: max1
!
! -- BOUNDARY CONDITIONS FOR TURBULENT KINETIC ENERGY EQUATION --
!
    SELECT CASE  (bcenk(ib)) 
    CASE (0) 
!
!
! -- BCENK=1 -- PRESCRIBE THE VALUE OF KT
!

    CASE (1) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') 'specified kt ', enkpar(ib, 1), &
&       ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enkpar(ib, 1) .GT. 0.0_R8, &
&             'BCENK = 1, ENKPAR(,1) !> 0')
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%skt0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*enkpar(ib, 1)*ev
        srw%skt0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (2) 
!
! -- BCENK=2 -- PRESCRIBE THE GRADIENT OF THE TURB. KIN. ENERGY
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                   'turb. kin. en. gradient ', enkpar(&
&                                   ib, 1), ' on ', bcchar(ib), &
&                                   boundary_location(ib)
!wdk    Note: specifies the gradient in the outward normal direction
!wdk    Tmp: in "connector" direction - ok for orthogonal grids
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        ivx1 = mpg%fcvx(ifc, 1)
        ivx2 = mpg%fcvx(ifc, 2)
        t1 = INTVERTEX_S_NODIFF(ivx1, ncv, nvx, mpg, geo%vxvol, pl%kt)
        t2 = INTVERTEX_S_NODIFF(ivx2, ncv, nvx, mpg, geo%vxvol, pl%kt)
        srw%skt0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*(ev*enkpar(ib, 1)*(&
&         geo%fchc(ifc, 1)+geo%fchc(ifc, 2))*geo%fcqgam(ifc, 0)-cor9*(t2&
&         -t1)*geo%fcqgam(ifc, 1)*(geo%fchc(ifc, 1)+geo%fchc(ifc, 2))/&
&         geo%fcht(ifc)*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)+pl%kt(icv2))
        srw%skt0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (3) 
!
! -- BCENK=3 -- not implemented
!
      CALL XERRAB('B2STBC -- BCENK=3, NOT AVAILABLE')
!
! -- BCENK=4 -- not implemented
!
    CASE (4) 
      CALL XERRAB('B2STBC -- BCENK=4, NOT AVAILABLE')
!
! -- BCENK=5 -- not implemented
!
    CASE (5) 
      CALL XERRAB('B2STBC -- BCENK=5, NOT AVAILABLE')
!
! -- BCENK=6 -- Prescribe the total flux of kt, following the
!               profile of fhi + fhe
!
    CASE (6) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          CALL XERTST(mpg%cvonclosedsurface(icv), &
&               'BCENK=6 intended for core boundaries only!')
        END DO
        WRITE(*, '(a,1p,g14.7,a,a,a)') 'turb. kin. energy flux ', enkpar&
&       (ib, 1), ' on ', bcchar(ib), boundary_location(ib)
      END IF
!     ..compute total ion+electron heat flux, and total kt flux
      totflux = 0.0_R8
      totpar = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv = mpg%bccv(mpg%bccvp(ib0, 1), 2)
        IF (mpg%cvonclosedsurface(icv)) THEN
          IF (bcenk(ib0) .NE. 6) CALL XERRAB(&
&                                      'BCENK=6: incompatible core BCs')
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            totflux = totflux - (dv%fhe(ifc, 0)+dv%fhe(ifc, 1)+dv%fhi(&
&             ifc, 0)+dv%fhi(ifc, 1))*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          END DO
          totpar = totpar + enkpar(ib0, 1)
        END IF
      END DO
!     ..impose the flux
      WRITE(*, *) 'BCENK=6, totflux = ', totflux, ', totpar = ', totpar
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        cs = SQRT(pz(icv1)/rz(icv1))
        srw%skt0(icv1, 0) = -(totpar/totflux*(dv%fhe(ifc, 0)+dv%fhe(ifc&
&         , 1)+dv%fhi(ifc, 0)+dv%fhi(ifc, 1))*mpg%bcfcor(mpg%bccvp(ib, 1&
&         )+ibc-1))
        srw%skt0(icv1, 1) = 0.0_R8
      END DO
    CASE (7) 
!
! -- BCENK=7 -- Prescribe the total flux of kt, following the
!               profile of fna
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          CALL XERTST(mpg%cvonclosedsurface(icv), &
&               'BCENK=7 intended for core boundaries only!')
        END DO
        WRITE(*, '(a,1p,g14.7,a,a,a)') 'turb. kin. energy flux ', enkpar&
&       (ib, 1), ' on ', bcchar(ib), boundary_location(ib)
      END IF
!     ..compute total particle flux, and total kt flux
      totflux = 0.0_R8
      totpar = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv = mpg%bccv(mpg%bccvp(ib0, 1), 2)
        IF (mpg%cvonclosedsurface(icv)) THEN
          IF (bcenk(ib0) .NE. 7) CALL XERRAB(&
&                                      'BCENK=7: incompatible core BCs')
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            totflux = totflux - (dv%fna(ifc, 0, ismain)+dv%fna(ifc, 1, &
&             ismain))*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          END DO
          totpar = totpar + enkpar(ib0, 1)
        END IF
      END DO
!     ..impose the flux
      WRITE(*, *) 'BCENK=7, totflux = ', totflux, ', totpar = ', totpar
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        cs = SQRT(pz(icv1)/rz(icv1))
        srw%skt0(icv1, 0) = -(totpar/totflux*(dv%fna(ifc, 0, ismain)+dv%&
&         fna(ifc, 1, ismain))*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1))
        srw%skt0(icv1, 1) = 0.0_R8
      END DO
    CASE (8) 
!
! -- BCENK=8 -- PRESCRIBE THE TOTAL FLUX OF KT WITH CONSTANT
!               FLUX DENSITY
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                   'total turb. kin. energy flux ', &
&                                   enkpar(ib, 1), ' on ', bcchar(ib), &
&                                   boundary_location(ib)
      us = 0.0_R8
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        us = us + geo%fcs(ifc)
      END DO
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%skt0(icv1, 0) = enkpar(ib, 1)/us*geo%fcs(ifc)
        srw%skt0(icv1, 1) = 0.0_R8
      END DO
    CASE (9) 
!
! -- BCENK=9 -- not implemented
!
      CALL XERRAB('B2STBC -- BCENK=9, NOT AVAILABLE')
!
! -- BCENK=10 -- not implemented
!
    CASE (10) 
      CALL XERRAB('B2STBC -- BCENK=10, NOT AVAILABLE')
!
! -- BCENK=11 -- not implemented
!
    CASE (11) 
      CALL XERRAB('B2STBC -- BCENK=11, NOT AVAILABLE')
!
! -- BCENK=12 -- not implemented
!
    CASE (12) 
      CALL XERRAB('B2STBC -- BCENK=12, NOT AVAILABLE')
!
! -- BCENK=13 -- not implemented
!
    CASE (13) 
      CALL XERRAB('B2STBC -- BCENK=13, NOT AVAILABLE')
!
! -- BCENK=14 -- Leakage option for turbulent kinetic energy
    CASE (14) 
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                   'turb. kin. energy leakage ', enkpar&
&                                   (ib, 1), ' on ', bcchar(ib), &
&                                   boundary_location(ib)
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        cs = SQRT(pz(icv1)/rz(icv1))
        srw%skt0(icv1, 0) = 0.0_R8
        srw%skt0(icv1, 3) = geo%fcs(ifc)*cs*enkpar(ib, 1)
      END DO
    CASE (15) 
!
! -- BCENK=15 -- Sheath transmission factor
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, *) 'BCENK=15 - should have BCCON=14 for all ions'
        bccon14_is(ib) = .true.
        DO is=0,ns-1
          IF (.NOT.is_neutral(is)) bccon14_is(ib) = bccon14_is(ib) .AND.&
&             bccon(is, ib) .EQ. 14
        END DO
        IF (bccon14_is(ib)) WRITE(*, '(a,a,i3,a)') 'BCCON=14 HAS ', &
&                           'BEEN IMPOSED AT BOUNDARY', ib, &
&                           ' FOR ALL IONS'
        IF (.NOT.bccon14_is(ib)) WRITE(*, '(a,a,i3,a)') 'BCCON=14 ', &
&                                'HAS NOT BEEN IMPOSED AT BOUNDARY', ib&
&                                , ' FOR ALL IONS'
!srv 20.09.17
        CALL XERTST(enkpar(ib, 1) .GT. 0.0_R8, &
&             'BCENK = 15, ENKPAR(I,,1) <= 0 not allowed!')
!srv 20.09.17
        WRITE(*, '(a,a,1p,g14.7,a,a,a)') &
&       'sheath transmission factor BC for turb. kin. energy', &
&       ' with ENKPAR(IB,1) =', enkpar(ib, 1), ' on ', bcchar(ib), &
&       boundary_location(ib)
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        cs = SQRT(pz(icv1)/rz(icv1))
        t0 = 0.0_R8
        t1 = 0.0_R8
        DO is=0,ns-1
          IF (.NOT.is_neutral(is)) THEN
            t0 = t0 + mompar(is, ib, 1)*pl%na(icv1, is)
            IF (conpar(is, ib, 2) .GT. 0.0_R8) t1 = t1 + co%dna0(icv1, &
&               is)/conpar(is, ib, 2)*pl%na(icv1, is)
          END IF
        END DO
        IF (geo%fcpbs(ifc) .GE. 0.) THEN
          abs0 = geo%fcpbs(ifc)
        ELSE
          abs0 = -geo%fcpbs(ifc)
        END IF
        srw%skt0(icv1, 1) = srw%skt0(icv1, 1) - enkpar(ib, 1)*t0*cs*abs0&
&         *(1.0_R8+switch%b2tfhi_fflokt) - enkpar(ib, 2)*t1*geo%fcs(ifc)
!wdk    Todo: corrections for BCCON.ne.14
      END DO
    CASE (16) 
!
! -- BCENK=16 -- Prescribe the value of the turb. kin. energy, with poloidal
!                perturbation taken from flux tube just inside domain
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          CALL XERTST(mpg%cvonclosedsurface(icv), &
&               'BCENK=16 intended for core boundaries only!')
        END DO
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'specified turb. kin. energy + perturbation', enkpar(ib, 1), &
&       ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enkpar(ib, 1) .GT. 0.0_R8, &
&             'BCENK = 16, ENKPAR(,1) !> 0')
      END IF
!     ..compute average kt on core boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv = mpg%bccv(mpg%bccvp(ib0, 1), 2)
        IF (mpg%cvonclosedsurface(icv)) THEN
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            t0 = t0 + geo%cvvol(icv2)
            t1 = t1 + geo%cvvol(icv2)*pl%kt(icv2)
          END DO
        END IF
      END DO
      t1 = t1/t0
!     ..impose kt with perturbation
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%skt0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*(pl%kt(icv2)+enkpar(&
&         ib, 1)*ev-t1)
        srw%skt0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (17) 
!
! -- BCENK=17 -- Feedback on turb. kin. energy flux, by imposing a flux surface
!                averaged kt, with poloidal perturbation taken from flux
!                tube just inside domain
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        DO ibc=1,mpg%bccvp(ib, 2)
          icv = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          CALL XERTST(mpg%cvonclosedsurface(icv), &
&               'BCENK=17 intended for core boundaries only!')
        END DO
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'specified turb. kin. energy flux ', enkpar(ib, 1), ' on ', &
&       bcchar(ib), boundary_location(ib)
        CALL XERTST(enkpar(ib, 1) .GT. 0.0_R8, &
&             'BCENK = 17, ENKPAR(,1) !> 0')
      END IF
!     ..compute average kt on core boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
      t2 = 0.0_R8
      totflux = 0.0_R8
      totpar = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv = mpg%bccv(mpg%bccvp(ib0, 1), 2)
        IF (mpg%cvonclosedsurface(icv)) THEN
          IF (bcenk(ib0) .NE. 17) CALL XERRAB(&
&                                      'BCENK=17: incompatible core BCs'&
&                                      )
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            t0 = t0 + geo%cvvol(icv2)*dv%ni(icv1, 0)
            t1 = t1 + geo%cvvol(icv2)*dv%ni(icv1, 0)*pl%kt(icv1)
            t2 = t2 + geo%cvvol(icv2)*dv%ni(icv2, 0)*pl%kt(icv2)
            totflux = totflux - (dv%fkt(ifc, 0)+dv%fkt(ifc, 1))*mpg%&
&             bcfcor(mpg%bccvp(ib, 1)+ibc-1)
          END DO
          totpar = totpar + enkpar(ib0, 1)
        END IF
      END DO
      t1 = t1/t0
      t2 = t2/t0
      IF (enkpar(ib, 2) .GT. 0.0_R8) t3 = enkpar(ib, 2)
      IF (enkpar(ib, 2) .LE. 0.0_R8) t3 = switch%b2stbc_bc_ref_ti
      IF (totflux .GE. 0.) THEN
        x1 = totflux
      ELSE
        x1 = -totflux
      END IF
      IF (x1 .LT. totpar) THEN
        max1 = totpar
      ELSE
        max1 = x1
      END IF
      t4 = (1.0_R8-t3*(totflux-totpar)/max1)*t1
      IF (bcenk_17_style .EQ. 0) THEN
!       ..impose kt with perturbation
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%skt0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*(pl%kt(icv2)+t4-t2)
          srw%skt0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
        END DO
      ELSE
!       ..impose kt w/o perturbation
! loop over number of cells in the boundary
        DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
          icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
          ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
          srw%skt0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*t4
          srw%skt0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
        END DO
      END IF
    CASE DEFAULT
!
      WRITE(*, *) bcenk(ib)
      CALL XERRAB('BCENK out of bounds')
!
    END SELECT
!
    RETURN
  END SUBROUTINE B2STBC_PHYS_ENK

!  Differentiation of b2stbc_phys_enz in reverse (adjoint) mode (with options context noISIZE r8):
!   gradient     of useful results: conpar mompar *(srw.szt0) switch.b2tfhi_fflozt
!                *(co.dna0) *(pl.na) *(pl.zt) rz pz
!   with respect to varying inputs: conpar mompar *(srw.szt0) switch.b2tfhi_fflozt
!                *(co.dna0) *(pl.na) *(pl.zt) rz pz
!   Plus diff mem management of: mpg.bcfcor:in geo.vxvol:in srw.szt0:in
!                co.dna0:in pl.na:in pl.zt:in
!
  SUBROUTINE B2STBC_PHYS_ENZ_B(ib)
    IMPLICIT NONE
    INTEGER :: ib, ibc, ib0, ibc0, is
    INTEGER :: icv, icv1, icv2, ifc, ivx1, ivx2
    REAL(kind=r8) :: cs, t0, t1, t2
    REAL(kind=r8) :: csb, t0b, t1b, t2b
    REAL(kind=r8), EXTERNAL :: INTVERTEX_S_NODIFF
    EXTERNAL XERRAB
    INTRINSIC SQRT
    INTRINSIC ABS
    REAL(kind=r8) :: abs0
    REAL(kind=r8) :: tempb
    REAL(kind=r8) :: temp
    REAL(kind=r8) :: tempb0
    REAL(r8) :: tempb1
    INTEGER*4 :: branch
    INTEGER :: ad_to
!
! -- BOUNDARY CONDITIONS FOR TURBULENT ENSTROPHY EQUATION --
!
    SELECT CASE  (bcenz(ib)) 
    CASE (0) 

    CASE (1) 
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        srwb%szt0(icv1, 1) = 0.D0
        srwb%szt0(icv1, 0) = 0.D0
      END DO
    CASE (2) 
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        srwb%szt0(icv1, 1) = 0.D0
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        tempb = vbig*ne00*geo%fcs(ifc)*srwb%szt0(icv1, 0)
        srwb%szt0(icv1, 0) = 0.D0
        plb%zt(icv2) = plb%zt(icv2) + tempb
        tempb0 = -(mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)*cor9*geo%fcqgam(&
&         ifc, 1)*(geo%fchc(ifc, 1)+geo%fchc(ifc, 2))*tempb/geo%fcht(ifc&
&         ))
        t2b = tempb0
        t1b = -tempb0
        ivx2 = mpg%fcvx(ifc, 2)
        CALL INTVERTEX_S_B(ivx2, ncv, nvx, mpg, geo%vxvol, pl%zt, plb%zt&
&                    , t2b)
        ivx1 = mpg%fcvx(ifc, 1)
        CALL INTVERTEX_S_B(ivx1, ncv, nvx, mpg, geo%vxvol, pl%zt, plb%zt&
&                    , t1b)
      END DO
    CASE (13, 12, 11, 10, 9, 8, 7, 6, 5, 4, 3) 

    CASE (14) 
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        csb = geo%fcs(ifc)*enzpar(ib, 1)*srwb%szt0(icv1, 3)
        srwb%szt0(icv1, 3) = 0.D0
        srwb%szt0(icv1, 0) = 0.D0
        temp = pz(icv1)/rz(icv1)
        IF (temp .EQ. 0.D0) THEN
          tempb0 = 0.D0
        ELSE
          tempb0 = csb/(rz(icv1)*2.0*SQRT(temp))
        END IF
        pzb(icv1) = pzb(icv1) + tempb0
        rzb(icv1) = rzb(icv1) - temp*tempb0
      END DO
    CASE (15) 
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        CALL PUSHREAL8(cs, r8/8)
        cs = SQRT(pz(icv1)/rz(icv1))
        CALL PUSHREAL8(t0, r8/8)
        t0 = 0.0_R8
        DO is=0,ns-1
          IF (.NOT.is_neutral(is)) THEN
            t0 = t0 + mompar(is, ib, 1)*pl%na(icv1, is)
            IF (conpar(is, ib, 2) .GT. 0.0_R8) THEN
              CALL PUSHCONTROL2B(2)
            ELSE
              CALL PUSHCONTROL2B(1)
            END IF
          ELSE
            CALL PUSHCONTROL2B(0)
          END IF
        END DO
        IF (geo%fcpbs(ifc) .GE. 0.) THEN
          CALL PUSHREAL8(abs0, r8/8)
          abs0 = geo%fcpbs(ifc)
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHREAL8(abs0, r8/8)
          abs0 = -geo%fcpbs(ifc)
          CALL PUSHCONTROL1B(1)
        END IF
      END DO
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        tempb0 = -(enzpar(ib, 1)*abs0*srwb%szt0(icv1, 1))
        t1b = -(enzpar(ib, 2)*geo%fcs(ifc)*srwb%szt0(icv1, 1))
        t0b = cs*(switch%b2tfhi_fflozt+1.0_R8)*tempb0
        csb = t0*(switch%b2tfhi_fflozt+1.0_R8)*tempb0
        switchb%b2tfhi_fflozt = switchb%b2tfhi_fflozt + t0*cs*tempb0
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          CALL POPREAL8(abs0, r8/8)
        ELSE
          CALL POPREAL8(abs0, r8/8)
        END IF
        DO is=ns-1,0,-1
          CALL POPCONTROL2B(branch)
          IF (branch .NE. 0) THEN
            IF (branch .NE. 1) THEN
              tempb1 = t1b/conpar(is, ib, 2)
              cob%dna0(icv1, is) = cob%dna0(icv1, is) + pl%na(icv1, is)*&
&               tempb1
              plb%na(icv1, is) = plb%na(icv1, is) + co%dna0(icv1, is)*&
&               tempb1
              conparb(is, ib, 2) = conparb(is, ib, 2) - co%dna0(icv1, is&
&               )*pl%na(icv1, is)*tempb1/conpar(is, ib, 2)
            END IF
            momparb(is, ib, 1) = momparb(is, ib, 1) + pl%na(icv1, is)*&
&             t0b
            plb%na(icv1, is) = plb%na(icv1, is) + mompar(is, ib, 1)*t0b
          END IF
        END DO
        CALL POPREAL8(t0, r8/8)
        CALL POPREAL8(cs, r8/8)
        temp = pz(icv1)/rz(icv1)
        IF (temp .EQ. 0.D0) THEN
          tempb0 = 0.D0
        ELSE
          tempb0 = csb/(rz(icv1)*2.0*SQRT(temp))
        END IF
        pzb(icv1) = pzb(icv1) + tempb0
        rzb(icv1) = rzb(icv1) - temp*tempb0
      END DO
    CASE (16) 
!     ..compute average zt on core boundary
      t0 = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv = mpg%bccv(mpg%bccvp(ib0, 1), 2)
        IF (mpg%cvonclosedsurface(icv)) THEN
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            t0 = t0 + geo%cvvol(icv2)
          END DO
          CALL PUSHINTEGER4(ibc0 - 1)
          CALL PUSHCONTROL1B(1)
        ELSE
          CALL PUSHCONTROL1B(0)
        END IF
      END DO
!     ..impose zt with perturbation
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        CALL PUSHINTEGER4(icv1)
! number of the domain cell
! number of the guard cell face
      END DO
      t1b = 0.D0
      DO ibc=mpg%bccvp(ib, 2),1,-1
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
        srwb%szt0(icv1, 1) = 0.D0
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        tempb0 = vbig*ne00*geo%fcs(ifc)*srwb%szt0(icv1, 0)
        srwb%szt0(icv1, 0) = 0.D0
        plb%zt(icv2) = plb%zt(icv2) + tempb0
        t1b = t1b - tempb0
        CALL POPINTEGER4(icv1)
      END DO
      t1b = t1b/t0
      DO ib0=nbc,1,-1
        CALL POPCONTROL1B(branch)
        IF (branch .NE. 0) THEN
          CALL POPINTEGER4(ad_to)
          DO ibc0=ad_to,1,-1
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
            plb%zt(icv2) = plb%zt(icv2) + geo%cvvol(icv2)*t1b
          END DO
        END IF
      END DO
    END SELECT
  END SUBROUTINE B2STBC_PHYS_ENZ_B

!
  SUBROUTINE B2STBC_PHYS_ENZ(ib)
    IMPLICIT NONE
    INTEGER :: ib, ibc, ib0, ibc0, is
    INTEGER :: icv, icv1, icv2, ifc, ivx1, ivx2
    REAL(kind=r8) :: cs, t0, t1, t2
    REAL(kind=r8), EXTERNAL :: INTVERTEX_S_NODIFF
    EXTERNAL XERRAB
    INTRINSIC SQRT
    INTRINSIC ABS
    REAL(kind=r8) :: abs0
!
! -- BOUNDARY CONDITIONS FOR TURBULENT ENSTROPHY EQUATION --
!
    SELECT CASE  (bcenz(ib)) 
    CASE (0) 
!
!
! -- BCENZ=1 -- PRESCRIBE THE VALUE OF ZT
!

    CASE (1) 
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, '(a,1p,g14.7,a,a,a)') 'specified zt ', enzpar(ib, 1), &
&       ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enzpar(ib, 1) .GE. 0.0_R8, &
&             'BCENZ = 1, ENZPAR(,1) !> 0')
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%szt0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*enzpar(ib, 1)*ev
        srw%szt0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (2) 
!
! -- BCENZ=2 -- PRESCRIBE THE GRADIENT OF THE TURB. ENSTROPHY
!
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                   'turb. enstr. gradient ', enzpar(ib&
&                                   , 1), ' on ', bcchar(ib), &
&                                   boundary_location(ib)
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        ivx1 = mpg%fcvx(ifc, 1)
        ivx2 = mpg%fcvx(ifc, 2)
        t1 = INTVERTEX_S_NODIFF(ivx1, ncv, nvx, mpg, geo%vxvol, pl%zt)
        t2 = INTVERTEX_S_NODIFF(ivx2, ncv, nvx, mpg, geo%vxvol, pl%zt)
        srw%szt0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*(ev*enzpar(ib, 1)*(&
&         geo%fchc(ifc, 1)+geo%fchc(ifc, 2))*geo%fcqgam(ifc, 0)-cor9*(t2&
&         -t1)*geo%fcqgam(ifc, 1)*(geo%fchc(ifc, 1)+geo%fchc(ifc, 2))/&
&         geo%fcht(ifc)*mpg%bcfcor(mpg%bccvp(ib, 1)+ibc-1)+pl%zt(icv2))
        srw%szt0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE (3) 
!
! -- BCENZ=3 -- not implemented
!
      CALL XERRAB('B2STBC -- BCENZ=3, NOT AVAILABLE')
!
! -- BCENZ=4 -- not implemented
!
    CASE (4) 
      CALL XERRAB('B2STBC -- BCENZ=4, NOT AVAILABLE')
!
! -- BCENZ=5 -- not implemented
!
    CASE (5) 
      CALL XERRAB('B2STBC -- BCENZ=5, NOT AVAILABLE')
!
! -- BCENZ=6 -- Prescribe the total flux of kt, following the
!               profile of fhi + fhe
!
    CASE (6) 
      CALL XERRAB('B2STBC -- BCENZ=6, NOT AVAILABLE')
!
! -- BCENZ=7 -- Prescribe the total flux of kt, following the
!               profile of fna
!
    CASE (7) 
      CALL XERRAB('B2STBC -- BCENZ=7, NOT AVAILABLE')
!
! -- BCENZ=8 -- PRESCRIBE THE TOTAL FLUX OF KT WITH CONSTANT
!               FLUX DENSITY
!
    CASE (8) 
      CALL XERRAB('B2STBC -- BCENZ=8, NOT AVAILABLE')
!
! -- BCENZ=9 -- not implemented
!
    CASE (9) 
      CALL XERRAB('B2STBC -- BCENZ=9, NOT AVAILABLE')
!
! -- BCENZ=10 -- not implemented
!
    CASE (10) 
      CALL XERRAB('B2STBC -- BCENZ=10, NOT AVAILABLE')
!
! -- BCENZ=11 -- not implemented
!
    CASE (11) 
      CALL XERRAB('B2STBC -- BCENZ=11, NOT AVAILABLE')
!
! -- BCENZ=12 -- not implemented
!
    CASE (12) 
      CALL XERRAB('B2STBC -- BCENZ=12, NOT AVAILABLE')
!
! -- BCENZ=13 -- not implemented
!
    CASE (13) 
      CALL XERRAB('B2STBC -- BCENZ=13, NOT AVAILABLE')
!
! -- BCENZ=14 -- Leakage option for turbulent enstrophy
!
    CASE (14) 
      IF (ncall_b2stbc_phys .EQ. 0) WRITE(*, '(a,1p,g14.7,a,a,a)') &
&                                   'turb. enstrophy leakage ', enzpar(&
&                                   ib, 1), ' on ', bcchar(ib), &
&                                   boundary_location(ib)
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        cs = SQRT(pz(icv1)/rz(icv1))
        srw%szt0(icv1, 0) = 0.0_R8
        srw%szt0(icv1, 3) = geo%fcs(ifc)*cs*enzpar(ib, 1)
      END DO
    CASE (15) 
!
! -- BCENZ=15 -- Sheath transmission factor
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        WRITE(*, *) 'BCENZ=15 - should have BCCON=14 for all ions'
        bccon14_is(ib) = .true.
        DO is=0,ns-1
          IF (.NOT.is_neutral(is)) bccon14_is(ib) = bccon14_is(ib) .AND.&
&             bccon(is, ib) .EQ. 14
        END DO
        IF (bccon14_is(ib)) WRITE(*, '(a,a,i3,a)') 'BCCON=14 HAS ', &
&                           'BEEN IMPOSED AT BOUNDARY', ib, &
&                           ' FOR ALL IONS'
        IF (.NOT.bccon14_is(ib)) WRITE(*, '(a,a,i3,a)') 'BCCON=14 ', &
&                                'HAS NOT BEEN IMPOSED AT BOUNDARY', ib&
&                                , ' FOR ALL IONS'
!srv 20.09.17
        CALL XERTST(enkpar(ib, 1) .GT. 0.0_R8, &
&             'BCENZ = 15, ENZPAR(I,,1) <= 0 not allowed!')
!srv 20.09.17
        WRITE(*, '(a,a,1p,g14.7,a,a,a)') &
&       'BCENZ=15: sheath transmission factor BC for ', &
&       'turb. enstrophy with ENZPAR(IB,1) =', enzpar(ib, 1), ' on ', &
&       bcchar(ib), boundary_location(ib)
      END IF
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the corresponding domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        cs = SQRT(pz(icv1)/rz(icv1))
        t0 = 0.0_R8
        t1 = 0.0_R8
        DO is=0,ns-1
          IF (.NOT.is_neutral(is)) THEN
            t0 = t0 + mompar(is, ib, 1)*pl%na(icv1, is)
            IF (conpar(is, ib, 2) .GT. 0.0_R8) t1 = t1 + co%dna0(icv1, &
&               is)/conpar(is, ib, 2)*pl%na(icv1, is)
          END IF
        END DO
        IF (geo%fcpbs(ifc) .GE. 0.) THEN
          abs0 = geo%fcpbs(ifc)
        ELSE
          abs0 = -geo%fcpbs(ifc)
        END IF
        srw%szt0(icv1, 1) = srw%szt0(icv1, 1) - enzpar(ib, 1)*t0*cs*abs0&
&         *(1.0_R8+switch%b2tfhi_fflozt) - enzpar(ib, 2)*t1*geo%fcs(ifc)
!wdk    Todo: corrections for BCCON.ne.14
      END DO
    CASE (16) 
!
! -- BCENZ=16 -- Prescribe the value of the turb. enstropy, with poloidal
!                perturbation taken from flux tube just inside domain
!
      IF (ncall_b2stbc_phys .EQ. 0) THEN
        DO ibc=1,mpg%bccvp(ib, 2)
          icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
          CALL XERTST(mpg%cvonclosedsurface(icv1), &
&               'BCENZ=16 intended for core boundaries only!')
        END DO
        WRITE(*, '(a,1p,g14.7,a,a,a)') &
&       'specified turb. enstrophy + perturbation', enzpar(ib, 1), &
&       ' on ', bcchar(ib), boundary_location(ib)
        CALL XERTST(enzpar(ib, 1) .GT. 0.0_R8, &
&             'BCENZ = 16, ENZPAR(,1) !> 0')
      END IF
!     ..compute average zt on core boundary
      t0 = 0.0_R8
      t1 = 0.0_R8
! identify core boundaries; assume all core boundaries
! form single flux surface
! implicit assumption at the moment: first ring in the
! core is a 'structured grid' ring with quad cells
      DO ib0=1,nbc
        icv = mpg%bccv(mpg%bccvp(ib0, 1), 2)
        IF (mpg%cvonclosedsurface(icv)) THEN
! loop over number of cells in the boundary
          DO ibc0=1,mpg%bccvp(ib0, 2)
! number of the guard cell
            icv1 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 1)
! number of the domain cell
            icv2 = mpg%bccv(mpg%bccvp(ib0, 1)+ibc0-1, 2)
! number of the guard cell face
            ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
            t0 = t0 + geo%cvvol(icv2)
            t1 = t1 + geo%cvvol(icv2)*pl%zt(icv2)
          END DO
        END IF
      END DO
      t1 = t1/t0
!     ..impose zt with perturbation
! loop over number of cells in the boundary
      DO ibc=1,mpg%bccvp(ib, 2)
! number of the guard cell
        icv1 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 1)
! number of the domain cell
        icv2 = mpg%bccv(mpg%bccvp(ib, 1)+ibc-1, 2)
! number of the guard cell face
        ifc = mpg%cvfc(mpg%cvfcp(icv1, 1))
        srw%szt0(icv1, 0) = vbig*ne00*geo%fcs(ifc)*(pl%zt(icv2)+enzpar(&
&         ib, 1)*ev-t1)
        srw%szt0(icv1, 1) = -(vbig*ne00*geo%fcs(ifc))
      END DO
    CASE DEFAULT
!
      WRITE(*, *) bcenz(ib)
      CALL XERRAB('BCENZ out of bounds')
!
    END SELECT
!
    RETURN
  END SUBROUTINE B2STBC_PHYS_ENZ

!  Differentiation of sheath_g in reverse (adjoint) mode (with options context noISIZE r8):
!   gradient     of useful results: t0 sheath_g
!   with respect to varying inputs: t0
!
  SUBROUTINE SHEATH_G_B(t0, t0b, sheath_gb)
    USE B2MOD_TYPES
    IMPLICIT NONE
    REAL(kind=r8) :: sheath_g, t0
    REAL(kind=r8) :: sheath_gb, t0b
    INTRINSIC SQRT, ERF, EXP
    EXTERNAL ERF_B
    REAL(kind=r8) :: result10
    REAL(kind=r8) :: result10b
    REAL(kind=r8) :: tempb
    REAL(kind=r8) :: tempb0
!
    result10 = ERF(t0)
!
    tempb = SQRT(pi)*sheath_gb
    tempb0 = EXP(t0**2)*tempb
    t0b = t0b + 2*t0**2*EXP(t0**2)*(result10+1)*tempb + (result10+1)*&
&     tempb0
    result10b = t0*tempb0
    CALL ERF_B(t0, t0b, result10b)
  END SUBROUTINE SHEATH_G_B

!
  FUNCTION SHEATH_G(t0)
    USE B2MOD_TYPES
    IMPLICIT NONE
    REAL(kind=r8) :: sheath_g, t0
    INTRINSIC SQRT, ERF, EXP
    REAL(kind=r8) :: result10
!
    result10 = ERF(t0)
    sheath_g = 1.0_R8 + SQRT(pi)*t0*(1+result10)*EXP(t0**2)
!
    RETURN
  END FUNCTION SHEATH_G

!
  FUNCTION PIT(icv)
    IMPLICIT NONE
    INTEGER, INTENT(IN) :: icv
    REAL(kind=r8) :: pit
    INTRINSIC ABS
    REAL(kind=r8) :: abs0
    IF (geo%cvbb(icv, 0) .GE. 0.) THEN
      abs0 = geo%cvbb(icv, 0)
    ELSE
      abs0 = -geo%cvbb(icv, 0)
    END IF
!
    pit = abs0/geo%cvbb(icv, 3)
!
    RETURN
  END FUNCTION PIT

!
!-----------------------------------------------------------------------
!.specification
  FUNCTION BCINT(fun, nx, ny, il, ib)
    USE B2MOD_TYPES
    USE B2MOD_GEO_DIFF
    USE B2MOD_INDIRECT_DIFF
    USE B2MOD_BOUNDARY_NAMELIST_DIFF
    IMPLICIT NONE
!   ..output result (undefined upon entry)
    REAL(kind=r8) :: bcint
!   ..input arguments (unchanged on exit)
    INTEGER :: nx, ny, il, ib
    REAL(kind=r8) :: fun(-1:nx, -1:ny)
!
!-----------------------------------------------------------------------
!.documentation
!
!  1. purpose
!
!     BCINT provides interpolated face-centred values for cell-centred
!     quantities (array fun), for use in boundary conditions.
!     The interpolation is done according to distance away from the
!     cell face. The boundary index is ib, and the cell index along
!     the boundary is il.
!
!
!-----------------------------------------------------------------------
!.declarations
!
!   ..procedures
    EXTERNAL XERTST, XERRAB
    REAL(kind=r8) :: result10
    REAL(kind=r8) :: result20
    REAL(kind=r8) :: result3
    REAL(kind=r8) :: result4
!
!-----------------------------------------------------------------------
!.computation
!
! ..preliminaries
!  ..test input parameters
    CALL XERTST(0 .LE. nx .AND. 0 .LE. ny, 'faulty parameter nx, ny')
    CALL XERTST(0 .LT. ib .AND. nbc .GE. ib, 'faulty parameter ib')
    CALL XERTST(1 .LE. il .AND. bc_list_size(ib) .GE. il, &
&         'faulty parameter il')
!
! ..main computation
    IF (bcchar(ib) .EQ. 'S') THEN
      result10 = HY1(topix(bc_list_x(il, ib), bc_list_y(il, ib)), topiy(&
&       bc_list_x(il, ib), bc_list_y(il, ib)))
      result20 = HY1(bc_list_x(il, ib), bc_list_y(il, ib))
      result3 = HY1(bc_list_x(il, ib), bc_list_y(il, ib))
      result4 = HY1(topix(bc_list_x(il, ib), bc_list_y(il, ib)), topiy(&
&       bc_list_x(il, ib), bc_list_y(il, ib)))
      bcint = (fun(bc_list_x(il, ib), bc_list_y(il, ib))*result10+fun(&
&       topix(bc_list_x(il, ib), bc_list_y(il, ib)), topiy(bc_list_x(il&
&       , ib), bc_list_y(il, ib)))*result20)/(result3+result4)
    ELSE IF (bcchar(ib) .EQ. 'N') THEN
      result10 = HY1(bottomix(bc_list_x(il, ib), bc_list_y(il, ib)), &
&       bottomiy(bc_list_x(il, ib), bc_list_y(il, ib)))
      result20 = HY1(bc_list_x(il, ib), bc_list_y(il, ib))
      result3 = HY1(bc_list_x(il, ib), bc_list_y(il, ib))
      result4 = HY1(bottomix(bc_list_x(il, ib), bc_list_y(il, ib)), &
&       bottomiy(bc_list_x(il, ib), bc_list_y(il, ib)))
      bcint = (fun(bc_list_x(il, ib), bc_list_y(il, ib))*result10+fun(&
&       bottomix(bc_list_x(il, ib), bc_list_y(il, ib)), bottomiy(&
&       bc_list_x(il, ib), bc_list_y(il, ib)))*result20)/(result3+&
&       result4)
    ELSE IF (bcchar(ib) .EQ. 'E') THEN
      bcint = (fun(bc_list_x(il, ib), bc_list_y(il, ib))*hx(leftix(&
&       bc_list_x(il, ib), bc_list_y(il, ib)), leftiy(bc_list_x(il, ib)&
&       , bc_list_y(il, ib)))+fun(leftix(bc_list_x(il, ib), bc_list_y(il&
&       , ib)), leftiy(bc_list_x(il, ib), bc_list_y(il, ib)))*hx(&
&       bc_list_x(il, ib), bc_list_y(il, ib)))/(hx(bc_list_x(il, ib), &
&       bc_list_y(il, ib))+hx(leftix(bc_list_x(il, ib), bc_list_y(il, ib&
&       )), leftiy(bc_list_x(il, ib), bc_list_y(il, ib))))
    ELSE IF (bcchar(ib) .EQ. 'W') THEN
      bcint = (fun(bc_list_x(il, ib), bc_list_y(il, ib))*hx(rightix(&
&       bc_list_x(il, ib), bc_list_y(il, ib)), rightiy(bc_list_x(il, ib)&
&       , bc_list_y(il, ib)))+fun(rightix(bc_list_x(il, ib), bc_list_y(&
&       il, ib)), rightiy(bc_list_x(il, ib), bc_list_y(il, ib)))*hx(&
&       bc_list_x(il, ib), bc_list_y(il, ib)))/(hx(bc_list_x(il, ib), &
&       bc_list_y(il, ib))+hx(rightix(bc_list_x(il, ib), bc_list_y(il, &
&       ib)), rightiy(bc_list_x(il, ib), bc_list_y(il, ib))))
    ELSE
      CALL XERRAB('bcint : Unknown orientation!')
    END IF
!
! ..return
    RETURN
!
!-----------------------------------------------------------------------
!.end bcint
!
  END FUNCTION BCINT

END SUBROUTINE B2STBC_PHYS_B

